import { HandleBillingWebhook } from '../usecases/HandleBillingWebhook'
import { AuthAccountMiddleware } from '@auth/middlewares'

export const HandleBillingWebhookControllerInputSchema = z
	.object({
		params: z.object({
			platform: z.enum(BillingPlatform),
		}),
		query: z.object({
			signature: z.string().optional(),
		}),
		body: z.record(z.string(), z.unknown()),
	})
	.example([
		{
			params: { platform: BillingPlatform.KIWIFY },
			query: { signature: 'a1b2c3...' },
			body: {
				webhook_event_type: 'order_approved',
				order_id: 'order_001',
				subscription_id: 'kiwify_sub_001',
			},
		},
	])

export const HandleBillingWebhookControllerOutputSchema = z.void()

/**
 * The single billing-webhook entry point. Path-param `platform` routes to the
 * right verifier + mapper via their factories; everything else lives in the body.
 *
 * The whole inbound request (`request.raw`) is handed to the use case so the
 * verifier can HMAC the exact bytes Kiwify sent (read off `request.text()`),
 * rather than a re-stringified body. The body/query schema below stays for the
 * OpenAPI contract; the handler reads the raw request, not the parsed fields.
 */
@injectable()
export class HandleBillingWebhookController extends Controller<
	typeof HandleBillingWebhookControllerInputSchema,
	typeof HandleBillingWebhookControllerOutputSchema
> {
	readonly path = '/billing/webhooks/:platform'
	readonly method = 'post' as const
	readonly description = 'Ingest a billing-provider webhook (e.g. Kiwify order_approved). Returns 202 on accept or idempotent re-delivery.'
	readonly inputSchema = HandleBillingWebhookControllerInputSchema
	readonly outputSchema = HandleBillingWebhookControllerOutputSchema

	override skipMiddlewares = [AuthAccountMiddleware]

	constructor(private handleBillingWebhook: HandleBillingWebhook) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.handleBillingWebhook.execute({
			platform: request.params.platform,
			rawRequest: request.raw,
		})
		return { status: HttpStatusCode.ACCEPTED, data: undefined }
	}
}

