	readonly method = 'patch' as const
	readonly description = "Change a store member's role (C18 ChangeMemberRole; LAST_OWNER guarded)"
	readonly inputSchema = ChangeMemberRoleControllerInputSchema
	readonly outputSchema = ChangeMemberRoleControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER])]

