import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'
import { and, count, gte, inArray, lte, sql } from 'drizzle-orm'
import { adSpends, orders } from '@bk-dash/contracts/db'
import { CurrencyCode, PaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { SignedMonetaryAmountSchema } from '@shared/objects'
import { MonetaryByCurrencySchema } from '@shared/schemas'

export const GetDashboardOverviewInputSchema = z.object({
	storeIds: z.array(z.uuid()).min(1),
	storeIntegrationIds: z.array(z.uuid()).optional(),
	productIds: z.array(z.uuid()).optional(),
	from: z.date(),
	to: z.date(),
	forcePaidOrders: z.boolean().default(false),
})

export const GetDashboardOverviewOutputSchema = z.object({
	reportingCurrency: z.enum(CurrencyCode),
	revenue: MonetaryByCurrencySchema,
	revenueInReportingCurrency: SignedMonetaryAmountSchema,
	orderCount: z.number().int().min(0),
	averageOrderValueInReportingCurrency: SignedMonetaryAmountSchema,
	grossMargin: MonetaryByCurrencySchema,
	grossMarginInReportingCurrency: SignedMonetaryAmountSchema,
	grossMarginPercent: z.number(),
	marketingSpend: MonetaryByCurrencySchema,
	marketingSpendInReportingCurrency: SignedMonetaryAmountSchema,
	roas: z.number(),
	refundedRevenueInReportingCurrency: SignedMonetaryAmountSchema,
	comparisonToPreviousPeriod: z.object({
		revenueChangePercent: z.number(),
		orderCountChangePercent: z.number(),
		marketingSpendChangePercent: z.number(),
		roasChangePercent: z.number(),
	}),
})

interface PeriodAggregates {
	revenue: Record<string, number>
	orderCount: number
	refunded: Record<string, number>
	marketingSpend: Record<string, number>
}

/**
 * T30 DashboardOverview. Top-level KPIs over a date window. Real
 * impl for the multi-currency aggregations from `sales.orders` and
 * `marketing.ad_spends`. Gross margin + ROAS + FX-to-reporting-currency
 * conversion are deferred:
 *   - `grossMargin` needs ProductCost line-item attribution (each order
 *     line × ProductCost option pick). Returns 0 for now.
 *   - `*InReportingCurrency` fields pick the single dominant currency
 *     (or USD when the store has no revenue) — no FX conversion yet.
 *   - `roas` likewise 0 (depends on margin in unified currency).
 *
 * `comparisonToPreviousPeriod` runs the same aggregation on the prior
 * period (same length, ending the instant before `from`) and computes
 * percent deltas.
 */
@injectable()
export class GetDashboardOverview extends Handler<typeof GetDashboardOverviewInputSchema, typeof GetDashboardOverviewOutputSchema> {
	readonly name = 'get_dashboard_overview' as const
	readonly inputSchema = GetDashboardOverviewInputSchema
	readonly outputSchema = GetDashboardOverviewOutputSchema

	constructor(private readonly db: DrizzleClient) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const dbc = tx ?? this.db
		const current = await this.aggregate(dbc, input, input.from, input.to)

		const fromMs = input.from.getTime()
		const toMs = input.to.getTime()
		const windowMs = toMs - fromMs
		const prevTo = new Date(fromMs - 1)
		const prevFrom = new Date(fromMs - windowMs - 1)
		const previous = await this.aggregate(dbc, input, prevFrom, prevTo)

		const reportingCurrency = pickReportingCurrency(current.revenue)
		const revenueInReporting = current.revenue[reportingCurrency] ?? 0
		const marketingSpendInReporting = current.marketingSpend[reportingCurrency] ?? 0
		const refundedInReporting = current.refunded[reportingCurrency] ?? 0
		const aov = current.orderCount > 0 ? Math.round(revenueInReporting / current.orderCount) : 0

		const prevRevenueReporting = previous.revenue[reportingCurrency] ?? 0
		const prevMarketingReporting = previous.marketingSpend[reportingCurrency] ?? 0

		return {
			reportingCurrency,
			revenue: current.revenue as Record<CurrencyCode, number>,
			revenueInReportingCurrency: { amountCents: revenueInReporting, currency: reportingCurrency },
			orderCount: current.orderCount,
			averageOrderValueInReportingCurrency: { amountCents: aov, currency: reportingCurrency },
			grossMargin: {},
			grossMarginInReportingCurrency: { amountCents: 0, currency: reportingCurrency },
			grossMarginPercent: 0,
			marketingSpend: current.marketingSpend as Record<CurrencyCode, number>,
			marketingSpendInReportingCurrency: { amountCents: marketingSpendInReporting, currency: reportingCurrency },
			roas: 0,
			refundedRevenueInReportingCurrency: { amountCents: refundedInReporting, currency: reportingCurrency },
			comparisonToPreviousPeriod: {
				revenueChangePercent: pctChange(prevRevenueReporting, revenueInReporting),
				orderCountChangePercent: pctChange(previous.orderCount, current.orderCount),
				marketingSpendChangePercent: pctChange(prevMarketingReporting, marketingSpendInReporting),
				roasChangePercent: 0,
			},
		} as never
	}

	private async aggregate(dbc: DrizzleClient, input: this['input'], from: Date, to: Date): Promise<PeriodAggregates> {
		const orderConds = [inArray(orders.storeId, input.storeIds), gte(orders.externalCreatedAt, from), lte(orders.externalCreatedAt, to)]
		if (input.storeIntegrationIds !== undefined && input.storeIntegrationIds.length > 0) {
			orderConds.push(inArray(orders.storeIntegrationId, input.storeIntegrationIds))
		}

		const adSpendConds = [inArray(adSpends.storeId, input.storeIds), gte(adSpends.bucketStart, from), lte(adSpends.bucketStart, to)]

		const [revenueRows, countRows, refundedRows, marketingRows] = await Promise.all([
			dbc
				.select({
					currency: orders.totalCurrency,
					total: sql<string>`sum(${orders.totalCents})`,
				})
				.from(orders)
				.where(and(...orderConds))
				.groupBy(orders.totalCurrency),
			dbc
				.select({ n: count() })
				.from(orders)
				.where(and(...orderConds)),
			dbc
				.select({
					currency: orders.totalCurrency,
					total: sql<string>`sum(${orders.totalCents})`,
				})
				.from(orders)
				.where(and(...orderConds, sql`${orders.paymentStatus} = ${PaymentStatus.REFUNDED}`))
				.groupBy(orders.totalCurrency),
			dbc
				.select({
					currency: adSpends.currency,
					total: sql<string>`sum(${adSpends.amountCents})`,
				})
				.from(adSpends)
				.where(and(...adSpendConds))
				.groupBy(adSpends.currency),
		])

		return {
			revenue: groupRows(revenueRows as Array<{ currency: string | null; total: string | null }>),
			orderCount: Number((countRows[0]?.n as number | bigint | undefined) ?? 0),
			refunded: groupRows(refundedRows as Array<{ currency: string | null; total: string | null }>),
			marketingSpend: groupRows(marketingRows as Array<{ currency: string | null; total: string | null }>),
		}
	}
}

function groupRows(rows: Array<{ currency: string | null; total: string | null }>): Record<string, number> {
	const out: Record<string, number> = {}
	for (const r of rows) {
		if (!r.currency || r.total === null) continue
		out[r.currency] = Number(r.total)
	}
	return out
}

function pickReportingCurrency(revenue: Record<string, number>): CurrencyCode {
	const entries = Object.entries(revenue)
	if (entries.length === 0) return CurrencyCode.USD
	entries.sort((a, b) => b[1] - a[1])
	return entries[0]![0] as CurrencyCode
}

function pctChange(prev: number, curr: number): number {
	if (prev === 0) return 0
	return ((curr - prev) / prev) * 100
}

