	readonly path = '/goals'
	readonly method = 'get' as const
	readonly description = 'List Store revenue/profit goals'
	readonly inputSchema = GetGoalsControllerInputSchema
	readonly outputSchema = GetGoalsControllerOutputSchema

	override middlewares = [RequireStoreMember]

	constructor(private query: GetGoals) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.query.execute({ storeId: request.ctx.membership.storeId })
		return { status: HttpStatusCode.OK, data }
	}
}

