import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { PixelEventType } from '@bk-dash/contracts-typescript/wire/enums'
import { faker } from '@shared/testing/mock'

export const GetFunnelInputSchema = z.object({})

const FunnelStepSchema = z.object({ count: z.number(), rate: z.number() })

export const GetFunnelOutputSchema = z.object({
	hasPixel: z.boolean(),
	base: z.number(),
	steps: z.record(z.nativeEnum(PixelEventType), FunnelStepSchema),
})

/** MOCK. Pixel funnel steps for the dashboard. Faker fixtures. */
@injectable()
export class GetFunnel extends Handler<typeof GetFunnelInputSchema, typeof GetFunnelOutputSchema> {
	readonly name = 'get_funnel' as const
	readonly inputSchema = GetFunnelInputSchema
	readonly outputSchema = GetFunnelOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		const base = faker.number.int({ min: 1000, max: 10000 })
		return {
			hasPixel: true,
			base,
			steps: {
				[PixelEventType.PAGE_VIEWED]: { count: base, rate: 1 },
				[PixelEventType.PRODUCT_VIEWED]: { count: Math.floor(base * 0.6), rate: 0.6 },
				[PixelEventType.PRODUCT_ADDED_TO_CART]: { count: Math.floor(base * 0.25), rate: 0.25 },
				[PixelEventType.CHECKOUT_STARTED]: { count: Math.floor(base * 0.1), rate: 0.1 },
				[PixelEventType.CHECKOUT_COMPLETED]: { count: Math.floor(base * 0.04), rate: 0.04 },
			},
		}
	}
}
