import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { faker, mockId, mockSeries, pick } from '@shared/testing/mock'
import { StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'

export const ListIntegrationsBffInputSchema = z.object({
	category: z.string().optional(),
	search: z.string().optional(),
	page: z.number().optional(),
	pageSize: z.number().optional(),
})

const CredentialKind = ['domain', 'gateway', 'apiKey', 'apiSecret', 'token'] as const

const IntegrationStatus = ['connected', 'disconnected', 'error'] as const

const CredentialFieldSchema = z.object({
	id: z.string(),
	kind: z.enum(CredentialKind),
	value: z.string(),
	secret: z.boolean(),
})

const IntegrationItemSchema = z.object({
	id: z.string(),
	provider: z.string(),
	category: z.enum(StoreIntegrationType),
	name: z.string(),
	logoUrl: z.url(),
	status: z.enum(IntegrationStatus),
	summary: z.object({
		domain: z.string().nullable(),
		gateway: z.string().nullable(),
	}),
	credentials: z.array(CredentialFieldSchema),
})

export const ListIntegrationsBffOutputSchema = z.paginatedResponse({
	id: z.string(),
	provider: z.string(),
	category: z.enum(StoreIntegrationType),
	name: z.string(),
	logoUrl: z.url(),
	status: z.enum(IntegrationStatus),
	summary: z.object({
		domain: z.string().nullable(),
		gateway: z.string().nullable(),
	}),
	credentials: z.array(CredentialFieldSchema),
})

/** MOCK. List integrations for the integrations settings screen (BFF). Faker fixtures. */
@injectable()
export class ListIntegrationsBff extends Handler<typeof ListIntegrationsBffInputSchema, typeof ListIntegrationsBffOutputSchema> {
	readonly name = 'list_integrations_bff' as const
	readonly inputSchema = ListIntegrationsBffInputSchema
	readonly outputSchema = ListIntegrationsBffOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		const items = mockSeries(4, () => {
			const status = pick(IntegrationStatus)
			const domain = `${faker.internet.domainWord()}.myshopify.com`
			return {
				id: mockId(),
				provider: pick(['shopify', 'yampi', 'cartpanda', 'appmax']),
				category: pick([StoreIntegrationType.SALES_CHANNEL, StoreIntegrationType.CHECKOUT, StoreIntegrationType.PAYMENT_GATEWAY]),
				name: faker.company.name(),
				logoUrl: faker.image.url(),
				status,
				summary: {
					domain: status !== 'disconnected' ? domain : null,
					gateway: status !== 'disconnected' ? 'Shopify Payments' : null,
				},
				credentials: status === 'connected'
					? [
						{ id: mockId(), kind: 'domain' as const, value: domain, secret: false },
						{ id: mockId(), kind: 'apiKey' as const, value: '••••••••••••••••', secret: true },
					]
					: [],
			}
		})
		return { items, total: items.length, totalPages: 1 }
	}
}
