export const PatchOrderPaymentMethodInputSchema = z.object({
	id: z.uuid(),
	paymentMethod: z.enum(PaymentMethod),
})

export const PatchOrderPaymentMethodOutputSchema = z.object({
	order: OrderSchema,
})

const STATUSES = Object.values(PaymentStatus) as [PaymentStatus, ...PaymentStatus[]]

/** MOCK. Update a single order's payment method and return the updated order. */
@injectable()
export class PatchOrderPaymentMethod extends Handler<typeof PatchOrderPaymentMethodInputSchema, typeof PatchOrderPaymentMethodOutputSchema> {
	readonly name = 'patch_order_payment_method' as const
	readonly inputSchema = PatchOrderPaymentMethodInputSchema
	readonly outputSchema = PatchOrderPaymentMethodOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		const revenueCents = faker.number.int({ min: 5_000, max: 500_000 })
		const productCostCents = faker.number.int({ min: 1_000, max: revenueCents })
		const shippingCents = faker.number.int({ min: 0, max: 5_000 })
		const feesCents = faker.number.int({ min: 0, max: 5_000 })
		const taxesCents = faker.number.int({ min: 0, max: 5_000 })
		const profitCents = revenueCents - productCostCents - shippingCents - feesCents - taxesCents
		const currency: CurrencyCode = CurrencyCode.BRL
		return {
			order: {
				id: input.id,
				code: `BK-${faker.number.int({ min: 10000, max: 99999 })}`,
				date: mockIsoDate(),
				currency,
				products: [{ name: faker.commerce.productName(), imageUrl: faker.image.url() }],
				paymentMethod: input.paymentMethod,
				status: pick(STATUSES),
				revenue: { amountCents: revenueCents, currency },
				productCost: { amountCents: productCostCents, currency },
				shipping: { amountCents: shippingCents, currency },
				fees: { amountCents: feesCents, currency },
				taxes: { amountCents: taxesCents, currency },
				profit: { amountCents: profitCents, currency },
