import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { CurrencyCode, MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { ProfileAlertSchema } from '@shared/schemas'
import { faker, mockId, mockIsoDate } from '@shared/testing/mock'

export const GetStoreInfoInputSchema = z.object({})

export const GetStoreInfoOutputSchema = z.object({
	current: z.object({
		id: z.string().nullable(),
		name: z.string(),
		currency: z.enum(CurrencyCode),
		updatedAt: z.iso.datetime({ offset: true }),
	}),
	stores: z.array(
		z.object({
			id: z.string(),
			name: z.string(),
			currency: z.enum(CurrencyCode),
		}),
	),
	alerts: z.array(ProfileAlertSchema),
})

/** MOCK. Store identity + multi-store list + alerts. Faker fixtures. */
@injectable()
export class GetStoreInfo extends Handler<typeof GetStoreInfoInputSchema, typeof GetStoreInfoOutputSchema> {
	readonly name = 'get_store_info' as const
	readonly inputSchema = GetStoreInfoInputSchema
	readonly outputSchema = GetStoreInfoOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		const storeId1 = mockId()
		const storeId2 = mockId()
		return {
			current: {
				id: storeId1,
				name: faker.company.name(),
				currency: CurrencyCode.BRL,
				updatedAt: mockIsoDate(),
			},
			stores: [
				{ id: storeId1, name: faker.company.name(), currency: CurrencyCode.BRL },
				{ id: storeId2, name: faker.company.name(), currency: CurrencyCode.USD },
			],
			alerts: [
				{
					kind: 'reconnectProfile',
					id: mockId(),
					platform: MarketingPlatform.FACEBOOK,
					profileId: mockId(),
					displayName: faker.person.fullName(),
				},
			],
		}
	}
}

