	cost: z.number(),
	shipping: z.number(),
	currency: z.enum(CurrencyCode),
	startDate: z.string().nullable(),
	endDate: z.string().nullable(),
})

export const ListProductVariantCostsOutputSchema = z.object({
	total: z.number().int().nonnegative(),
	page: z.number().int().positive(),
	limit: z.number().int().positive(),
	items: z.array(
		z.object({
			product: z.object({
				id: z.string(),
				title: z.string(),
				imageUrl: z.string().nullable(),
			}),
			variant: z.object({
				id: z.string(),
				name: z.string(),
				latestCost: VariantCostSchema.nullable(),
			}),
		}),
	),
})

/** MOCK. List variants and their latest cost for a product. Faker fixtures. */
@injectable()
export class ListProductVariantCosts extends Handler<typeof ListProductVariantCostsInputSchema, typeof ListProductVariantCostsOutputSchema> {
	readonly name = 'list_product_variant_costs' as const
	readonly inputSchema = ListProductVariantCostsInputSchema
	readonly outputSchema = ListProductVariantCostsOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		const productTitle = faker.company.name()
		const productImageUrl = faker.image.url()
		const items = mockSeries(input.limit ?? 20, (i) => ({
			product: {
				id: input.productId,
				title: productTitle,
				imageUrl: productImageUrl,
			},
			variant: {
				id: mockId(),
				name: `US - W ${6 + i * 0.5}`,
				latestCost: faker.datatype.boolean()
					? {
							id: mockId(),
							cost: mockMoney(),
							shipping: mockMoney(),
							currency: CurrencyCode.USD,
							startDate: null,
							endDate: null,
						}
					: null,
			},
		}))
		return { total: 24, page: input.page ?? 1, limit: input.limit ?? 20, items }
	}
}
