import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import type { z as ZInfer } from 'zod'
import { SignedMonetaryAmountSchema } from '@shared/objects'
import { faker, mockId, mockSeries, mockIsoDate, pick } from '@shared/testing/mock'
import { PaymentStatus, PaymentMethod, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

// ---------------------------------------------------------------------------
// Canonical order sub-schemas
// ---------------------------------------------------------------------------

export const OrderProductSchema = z.object({
	name: z.string(),
	imageUrl: z.string().nullable(),
})

/** Canonical order shape returned by all /sales/orders* read endpoints. */
export const OrderSchema = z.object({
	id: z.uuid(),
	code: z.string(),
	date: z.iso.datetime({ offset: true }),
	currency: z.enum(CurrencyCode),
	products: z.array(OrderProductSchema),
	paymentMethod: z.enum(PaymentMethod),
	status: z.enum(PaymentStatus),
	revenue: SignedMonetaryAmountSchema,
	productCost: SignedMonetaryAmountSchema,
	shipping: SignedMonetaryAmountSchema,
	fees: SignedMonetaryAmountSchema,
	taxes: SignedMonetaryAmountSchema,
	profit: SignedMonetaryAmountSchema,
})

// ---------------------------------------------------------------------------
// Use case
// ---------------------------------------------------------------------------

export const ListOrdersInputSchema = z.object({
	page: z.number().int().min(1).optional().default(1),
	limit: z.number().int().min(1).max(100).optional().default(20),
	search: z.string().optional(),
	sortBy: z.enum(['code', 'date', 'revenue', 'profit']).optional(),
	sortOrder: z.enum(['ASC', 'DESC']).optional(),
	paymentStatus: z.array(z.enum(PaymentStatus)).optional(),
	paymentMethod: z.array(z.enum(PaymentMethod)).optional(),
	startDate: z.string().optional(),
	endDate: z.string().optional(),
})

export const ListOrdersOutputSchema = z.object({
	items: z.array(OrderSchema),
	total: z.number().int(),
	page: z.number().int(),
	limit: z.number().int(),
})

const STATUSES = Object.values(PaymentStatus) as [PaymentStatus, ...PaymentStatus[]]
const METHODS = Object.values(PaymentMethod) as [PaymentMethod, ...PaymentMethod[]]

const mockMoneyCents = (): number => faker.number.int({ min: 0, max: 10_000_00 })

const mockOrder = (): z.infer<typeof OrderSchema> => {
	const revenueCents = faker.number.int({ min: 5_000, max: 500_000 })
	const productCostCents = faker.number.int({ min: 1_000, max: revenueCents })
	const shippingCents = faker.number.int({ min: 0, max: 5_000 })
	const feesCents = faker.number.int({ min: 0, max: 5_000 })
	const taxesCents = faker.number.int({ min: 0, max: 5_000 })
	const profitCents = revenueCents - productCostCents - shippingCents - feesCents - taxesCents
	const currency: CurrencyCode = faker.helpers.arrayElement([CurrencyCode.BRL, CurrencyCode.USD])
	return {
		id: mockId(),
		code: `BK-${faker.number.int({ min: 10000, max: 99999 })}`,
		date: mockIsoDate(),
		currency,
		products: mockSeries(faker.number.int({ min: 1, max: 3 }), () => ({
			name: faker.commerce.productName(),
			imageUrl: faker.datatype.boolean() ? faker.image.url() : null,
		})),
		paymentMethod: pick(METHODS),
		status: pick(STATUSES),
		revenue: { amountCents: revenueCents, currency },
		productCost: { amountCents: productCostCents, currency },
		shipping: { amountCents: shippingCents, currency },
		fees: { amountCents: feesCents, currency },
		taxes: { amountCents: taxesCents, currency },
		profit: { amountCents: profitCents, currency },
	}
}

/** MOCK. Paginated list of orders with financial columns. Faker fixtures. */
@injectable()
export class ListOrders extends Handler<typeof ListOrdersInputSchema, typeof ListOrdersOutputSchema> {
	readonly name = 'list_orders' as const
	readonly inputSchema = ListOrdersInputSchema
	readonly outputSchema = ListOrdersOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		const total = 1079
		const page = input.page ?? 1
		const limit = input.limit ?? 20
		return {
			items: mockSeries(Math.min(limit, 10), () => mockOrder()),
			total,
			page,
			limit,
		}
	}
}

