import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { faker, mockId, mockSeries, mockIsoDate, pick } from '@shared/testing/mock'
import { PaymentStatus, PaymentMethod, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { SignedMonetaryAmountSchema } from '@shared/objects'
import { OrderSchema } from './ListOrders'

export const PatchOrderStatusInputSchema = z.object({
	id: z.uuid(),
	status: z.enum(PaymentStatus),
})

export const PatchOrderStatusOutputSchema = z.object({
	order: OrderSchema,
})

const METHODS = Object.values(PaymentMethod) as [PaymentMethod, ...PaymentMethod[]]

const mockPatchedOrder = (id: string, status: PaymentStatus): z.infer<typeof OrderSchema> => {
	const revenueCents = faker.number.int({ min: 5_000, max: 500_000 })
	const productCostCents = faker.number.int({ min: 1_000, max: revenueCents })
	const shippingCents = faker.number.int({ min: 0, max: 5_000 })
	const feesCents = faker.number.int({ min: 0, max: 5_000 })
	const taxesCents = faker.number.int({ min: 0, max: 5_000 })
	const profitCents = revenueCents - productCostCents - shippingCents - feesCents - taxesCents
	const currency: CurrencyCode = CurrencyCode.BRL
	return {
		id,
		code: `BK-${faker.number.int({ min: 10000, max: 99999 })}`,
		date: mockIsoDate(),
		currency,
		products: [{ name: faker.commerce.productName(), imageUrl: faker.image.url() }],
		paymentMethod: pick(METHODS),
		status,
		revenue: { amountCents: revenueCents, currency },
		productCost: { amountCents: productCostCents, currency },
		shipping: { amountCents: shippingCents, currency },
		fees: { amountCents: feesCents, currency },
		taxes: { amountCents: taxesCents, currency },
		profit: { amountCents: profitCents, currency },
