import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { SignedMonetaryAmountSchema } from '@shared/objects'
import { faker, mockIsoDate, pick } from '@shared/testing/mock'
import { PaymentStatus, PaymentMethod } from '@bk-dash/contracts-typescript/wire/enums'
import { OrderSchema } from './ListOrders'

export const PatchOrderProductCostItemSchema = z.object({
	productName: z.string(),
	value: SignedMonetaryAmountSchema,
})

export const PatchOrderProductCostInputSchema = z.object({
	id: z.uuid(),
	items: z.array(PatchOrderProductCostItemSchema).min(1),
})

export const PatchOrderProductCostOutputSchema = z.object({
	order: OrderSchema,
})

const STATUSES = Object.values(PaymentStatus) as [PaymentStatus, ...PaymentStatus[]]
const METHODS = Object.values(PaymentMethod) as [PaymentMethod, ...PaymentMethod[]]

/** MOCK. Update per-product cost items on an order; profit recalculated server-side. */
@injectable()
export class PatchOrderProductCost extends Handler<typeof PatchOrderProductCostInputSchema, typeof PatchOrderProductCostOutputSchema> {
	readonly name = 'patch_order_product_cost' as const
	readonly inputSchema = PatchOrderProductCostInputSchema
	readonly outputSchema = PatchOrderProductCostOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		const firstItem = input.items[0]
		const currency: CurrencyCode = firstItem?.value.currency ?? CurrencyCode.BRL
		const productCostCents = input.items.reduce((sum, item) => sum + item.value.amountCents, 0)
		const revenueCents = faker.number.int({ min: productCostCents + 1_000, max: productCostCents + 500_000 })
		const shippingCents = faker.number.int({ min: 0, max: 5_000 })
		const feesCents = faker.number.int({ min: 0, max: 5_000 })
		const taxesCents = faker.number.int({ min: 0, max: 5_000 })
		const profitCents = revenueCents - productCostCents - shippingCents - feesCents - taxesCents
		return {
			order: {
				id: input.id,
				code: `BK-${faker.number.int({ min: 10000, max: 99999 })}`,
				date: mockIsoDate(),
				currency: currency as typeof currency,
				products: input.items.map(item => ({ name: item.productName, imageUrl: faker.image.url() })),
				paymentMethod: pick(METHODS),
				status: pick(STATUSES),
				revenue: { amountCents: revenueCents, currency: currency as typeof currency },
				productCost: { amountCents: productCostCents, currency: currency as typeof currency },
				shipping: { amountCents: shippingCents, currency: currency as typeof currency },
				fees: { amountCents: feesCents, currency: currency as typeof currency },
				taxes: { amountCents: taxesCents, currency: currency as typeof currency },
				profit: { amountCents: profitCents, currency: currency as typeof currency },
			},
		}
	}
}

