export const GetMultiStoreDashboardInputSchema = z.object({
	startDate: z.string().optional(),
	endDate: z.string().optional(),
})

const DashboardDetailsSchema = z.object({
	fees: FeesBreakdownSchema,
	ads: AdsBreakdownSchema,
	productCost: ProductCostBreakdownSchema,
	chargeback: ChargebackBreakdownSchema,
	refund: MetricSchema,
	taxes: TaxesBreakdownSchema,
	operational: OperationalCostsSchema,
})

export const GetMultiStoreDashboardOutputSchema = z.object({
	kpis: ConsolidatedKpisSchema,
	perStore: PerStoreKpisSchema,
	details: DashboardDetailsSchema,
})

const mockCurrencyMetric = () => ({
	value: { BRL: faker.number.float({ min: 0, max: 100_000, fractionDigits: 2 }) },
	deltaPct: faker.datatype.boolean() ? faker.number.float({ min: -1, max: 1, fractionDigits: 2 }) : null,
})

/** MOCK. Multi-store consolidated dashboard KPIs. Faker fixtures. */
@injectable()
export class GetMultiStoreDashboard extends Handler<typeof GetMultiStoreDashboardInputSchema, typeof GetMultiStoreDashboardOutputSchema> {
	readonly name = 'get_multi_store_dashboard' as const
	readonly inputSchema = GetMultiStoreDashboardInputSchema
	readonly outputSchema = GetMultiStoreDashboardOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		const m = mockMetric
		const cm = mockCurrencyMetric
		const storeId = mockId()
		return {
			kpis: {
				revenue: cm(),
				profit: cm(),
				margin: m(),
				orders: m(),
				averageTicket: cm(),
				unitsSold: m(),
				costs: {
					total: cm(),
					segments: {
						marketing: cm(),
						product: cm(),
						shipping: cm(),
						fees: cm(),
						refund: cm(),
						chargeback: cm(),
						taxes: cm(),
						operational: cm(),
					},
				},
			},
			perStore: {
				[storeId]: {
					revenue: m(),
					profit: m(),
					margin: m(),
					orders: m(),
					averageTicket: m(),
					unitsSold: m(),
					costs: {
						total: m(),
						segments: {
							marketing: m(),
							product: m(),
							shipping: m(),
							fees: m(),
							refund: m(),
							chargeback: m(),
							taxes: m(),
							operational: m(),
						},
					},
				},
			},
			details: {
				fees: {
					gateway: { total: m(), segments: { variable: m(), fixed: m() } },
					checkout: m(),
					chargeback: m(),
				},
				ads: {
					total: m(),
					byPlatform: { total: m(), segments: { FACEBOOK: m(), GOOGLE: m(), TIKTOK: m(), INSTAGRAM: m(), UNKNOWN: m() } },
					byType: { total: m(), segments: { auto: m(), manual: m() } },
