import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'
import { and, gte, inArray, lte, sql } from 'drizzle-orm'
import { orders } from '@bk-dash/contracts/db'
import { AnalyticsFrequency, ChartType } from '@analytics/enums'

export const GetChartInputSchema = z.object({
	chartType: z.enum(ChartType),
	storeIds: z.array(z.uuid()).min(1),
	storeIntegrationIds: z.array(z.uuid()).optional(),
	productIds: z.array(z.uuid()).optional(),
	from: z.date(),
	to: z.date(),
	frequency: z.enum(AnalyticsFrequency),
	forcePaidOrders: z.boolean().default(false),
})

export const GetChartOutputSchema = z.object({
	chartType: z.enum(ChartType),
	series: z.array(
		z.object({
			label: z.string(),
			points: z.array(z.object({ x: z.string(), y: z.number() })),
		}),
	),
})

/**
 * T31 Chart. Single controller, discriminated by chartType.
 *
 * Implemented chart types:
 *   - REVENUE: time-series of total order revenue bucketed by the
 *     requested frequency (date_trunc on externalCreatedAt).
 *
 * Other chartTypes return empty series for now — the per-shape
 * aggregator lands in a follow-up:
 *   - REVENUE_PER_SHIFT, SALES_PER_HOUR: need shift table / hour-of-day
 *   - SALES_PER_WEEKDAY: extract(dow) grouping
 *   - SALES_PER_REGION: shipping_address->>'region' grouping
 */
@injectable()
export class GetChart extends Handler<typeof GetChartInputSchema, typeof GetChartOutputSchema> {
	readonly name = 'get_chart' as const
	readonly inputSchema = GetChartInputSchema
	readonly outputSchema = GetChartOutputSchema

	constructor(private readonly db: DrizzleClient) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		if (input.chartType !== ChartType.REVENUE) {
			return { chartType: input.chartType, series: [] }
		}

		const dbc = tx ?? this.db
		const conds = [
			inArray(orders.storeId, input.storeIds),
			gte(orders.externalCreatedAt, input.from),
			lte(orders.externalCreatedAt, input.to),
		]

		if (input.storeIntegrationIds !== undefined && input.storeIntegrationIds.length > 0) {
			conds.push(inArray(orders.storeIntegrationId, input.storeIntegrationIds))
		}

		const truncUnit = bucketUnit(input.frequency as AnalyticsFrequency)
		// date_trunc's first arg must be a literal — sql.raw inlines after the
		// bucketUnit() switch has validated truncUnit comes from a closed set.
		const bucket = sql<string>`to_char(date_trunc(${sql.raw(`'${truncUnit}'`)}, ${orders.externalCreatedAt}), 'YYYY-MM-DD"T"HH24:MI:SS"Z"')`

