import { OrderOverrideFieldsSchema } from '../objects/OrderOverrideFields'
import { UpdateOrderOverride, UpdateOrderOverrideOutputSchema } from '../usecases/UpdateOrderOverride'

export const UpdateOrderOverrideControllerInputSchema = z.object({
