import { ApiProperty } from "@nestjs/swagger";
import { Platform } from "@shared/types/enum";
import { IsEnum, IsOptional, IsString } from "class-validator";

export enum TreeLevel {
	PLATFORM = "platform",
	ACCOUNT_INFO = "accountInfo",
	BUSINESS_ACCOUNT = "businessAccount",
	AD_ACCOUNT = "adAccount",
	CAMPAIGN = "campaign",
}

export class GetIntegrationSetCampaignsQuery {
	@ApiProperty({
		description:
			"Search term to filter the tree structure. Used in combination with treeLevel to determine which level to filter.",
		example: "labubu",
		required: false,
	})
	@IsOptional()
	@IsString()
	search: string | null = null;

	@ApiProperty({
		description:
			"Defines which level of the tree structure to apply the search filter. When combined with search, only branches that contain matching items at this level will be returned.",
		enum: TreeLevel,
		example: TreeLevel.CAMPAIGN,
		examples: {
			accountInfo: {
				description:
					"Filter by account info names - removes branches that don't contain account info matching the search term",
				value: TreeLevel.ACCOUNT_INFO,
			},
			adAccount: {
				description:
					"Filter by ad account names - removes branches that don't contain ad accounts matching the search term",
				value: TreeLevel.AD_ACCOUNT,
			},
			businessAccount: {
				description:
					"Filter by business account names - removes branches that don't contain business accounts matching the search term",
				value: TreeLevel.BUSINESS_ACCOUNT,
			},
			campaign: {
				description:
					"Filter by campaign names - removes branches that don't contain campaigns matching the search term",
				value: TreeLevel.CAMPAIGN,
			},
			platform: {
				description: "Filter by platform names - removes platforms that don't match the search term",
				value: TreeLevel.PLATFORM,
			},
		},
		required: false,
	})
	@IsOptional()
	@IsEnum(TreeLevel)
	treeLevel: TreeLevel | null = null;
}

export class IntegrationSetCampaignsDto {
	@ApiProperty({
		additionalProperties: {
			description: "Social Media Platform data",
			type: "object",
		},
		description:
			"Hierarchical tree structure of marketing campaigns organized by platform -> account info -> business account -> ad account -> campaigns",
		required: false,
		type: "object",
	})
	campaignsTree: Record<string, SocialMedia> = {};
}

class SocialMedia {
	@ApiProperty({
		description: "Platform name (e.g., Facebook, Google, TikTok)",
	})
	name: Platform = Platform.UNKNOWN;

	@ApiProperty({ description: "Unique platform identifier" })
	id: string | null = null;

	@ApiProperty({
		additionalProperties: { type: "object" },
		description: "Collection of account information objects organized by account ID",
		type: "object",
	})
	accountInfo: Record<string, AccountInfo> = {};
}

class AccountInfo {
	@ApiProperty({ description: "Account display name" })
	name: string | null = null;

	@ApiProperty({ description: "Unique account identifier" })
	id: string | null = null;

	@ApiProperty({ description: "Whether the account is currently active" })
	isActive: boolean | null = null;

	@ApiProperty({
		additionalProperties: { type: "object" },
		description: "Collection of business accounts organized by business account ID",
		type: "object",
	})
	businessAccounts: Record<string, BusinessAccount> = {};
}

class BusinessAccount {
	@ApiProperty({ description: "Business account name" })
	name: string | null = null;

	@ApiProperty({ description: "Unique business account identifier" })
	id: string | null = null;

	@ApiProperty({
		description: "Whether the business account is currently active",
	})
	isActive: boolean | null = null;

	@ApiProperty({
		additionalProperties: { type: "object" },
		description: "Collection of advertising accounts organized by ad account ID",
		type: "object",
	})
	adAccounts: Record<string, AdAccount> = {};
}

class AdAccount {
	@ApiProperty({ description: "Ad account name" })
	name: string | null = null;

	@ApiProperty({ description: "Unique ad account identifier" })
	id: string | null = null;

	@ApiProperty({ description: "Whether the ad account is currently active" })
	isActive: boolean | null = null;

	@ApiProperty({
		additionalProperties: { type: "object" },
		description: "Collection of marketing campaigns organized by campaign ID",
		type: "object",
	})
	campaigns: Record<string, Campaign> = {};
}

class Campaign {
	@ApiProperty({ description: "Campaign name" })
	name: string | null = null;

	@ApiProperty({ description: "Unique campaign identifier" })
	id: string | null = null;

	@ApiProperty({ description: "Whether the campaign is currently active" })
	isActive: boolean | null = null;
}

