import { UUID } from "node:crypto";
import { Auth, Public } from "@decorators";
import {
	Body,
	Controller,
	Delete,
	Get,
	HttpCode,
	HttpStatus,
	Param,
	Patch,
	Post,
	Query,
} from "@nestjs/common";
import { ApiCookieAuth, ApiOperation, ApiQuery, ApiResponse, ApiTags } from "@nestjs/swagger";
import { NewWorkerService } from "@shared/services/NewWorker";
import { AuthData } from "@shared/types";
import { IntegrationSetHasMarketingPlatform, MarketingPlatformAdAccount } from "sql";
import { AddMarketingPlatformDto } from "./dto/addMarketingPlatform.dto";
import { BindCampaignsBodyDto, BindCampaignsDto } from "./dto/bindCampaigns.dto";
import { DeleteMarketingPlatformAccountDto } from "./dto/deleteMarketingPlatformAccount.dto";
import { GetIntegrationSetCampaignsQuery, IntegrationSetCampaignsDto } from "./dto/getCampaignsTree.dto";
import {
	GetMarketingPlatformAccountsSummaryQueryDto,
	PaginatedMarketingPlatformAccountsSummaryDto,
} from "./dto/getMarketingPlatformAccountSummary.dto";
import { MarketingUpdateQueryDto } from "./dto/marketingUpdateQuery.dto";
import { UnbindCampaignsBodyDto, UnbindCampaignsDto } from "./dto/unbindCampaigns.dto";
import { IntegrationSetMarketingPlatformsService } from "./integrationSetMarketingPlatforms.service";
import { AuthGenericAccountDto } from "./submodules/dto/authGenericAccount.dto";
import { PatchMarketingPlatformAdAccountDto } from "./submodules/dto/patchMarketingPlatformAdAccount.dto";

@ApiTags("Integration Sets - Marketing Platforms")
@ApiCookieAuth()
@Controller("integrationSets/marketingPlatforms")
export class IntegrationSetMarketingPlatformsController {
	constructor(
		private readonly integrationSetMarketingPlatformsService: IntegrationSetMarketingPlatformsService,
		readonly newWorkerService: NewWorkerService,
	) {}

	@ApiOperation({
		description:
			"Retrieve all marketing platform integrations for the current integration set including Facebook/Meta, Google Ads, TikTok, and their associated ad accounts.",
		summary: "Get Marketing Platform Integrations",
	})
	@ApiQuery({
		description: "Filter by specific platform name (facebook, google, tiktok)",
		name: "platform",
		required: false,
	})
	@ApiResponse({
		description: "Marketing platforms retrieved successfully",
		status: 200,
	})
	@ApiResponse({
		description: "Unauthorized - Invalid or missing authentication token",
		status: 401,
	})
	@Get()
	async getMarketingPlatforms(
		@Auth()
		{
			credentials: {
				current: { integrationSetId },
			},
		}: AuthData,
		@Query("platform") platform: string,
	): Promise<{
		marketingPlatforms: Partial<IntegrationSetHasMarketingPlatform>[];
	}> {
		const marketingPlatforms = await this.integrationSetMarketingPlatformsService.getByIntegrationSet(
			integrationSetId,
			platform,
		);

		return { marketingPlatforms };
	}

	@ApiResponse({ description: "Não autorizado.", status: 401 })
	@ApiResponse({
		description: "Plataforma de marketing adicionada.",
		status: 200,
	})
	@HttpCode(HttpStatus.OK)
	@Public()
	@Post()
	async addMarketingPlatform(
		@Body() body: AddMarketingPlatformDto,
	): Promise<Partial<IntegrationSetHasMarketingPlatform>> {
		const { integrationSetId } = body;

		return this.integrationSetMarketingPlatformsService.addMarketingPlatformWorkerSync(
			integrationSetId,
			body,
		);
	}

	@Get("/marketingUpdate/:profileId")
	public async marketingUpdateByProfile(
		@Auth() { credentials }: AuthData,
		@Param("profileId") _profileId: string,
		@Query("days") _days?: string,
	): Promise<any> {
		const integrationSetId = credentials.current.integrationSetId as UUID;
		const [result] = await this.newWorkerService.marketingUpdate([integrationSetId]);
		const nextProcessing = new Date(Date.now() + 5 * 60 * 1000);
		return { nextProcessing, status: result.status };
	}

	@Get("/marketingUpdate")
	public async marketingUpdate(
		@Auth() { credentials }: AuthData,
		@Query() query: MarketingUpdateQueryDto,
	): Promise<any> {
		const integrationSetId = credentials.current.integrationSetId as UUID;
		const now = new Date();
		const startDate = query.startDate ?? new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000);
		const endDate = query.endDate ?? now;
		const [result] = await this.newWorkerService.marketingUpdate([integrationSetId], {
			endDate: endDate.toISOString(),
			startDate: startDate.toISOString(),
		});
		const nextProcessing = new Date(Date.now() + 5 * 60 * 1000);
		return { nextProcessing, status: result.status };
	}

	@Get("/:platform")
	async getMarketingPlatformAccountsSummary(
		@Auth()
		{
			credentials: {
				current: { integrationSetId },
			},
		}: AuthData,
		@Param("platform") platform: string,
		@Query() params: GetMarketingPlatformAccountsSummaryQueryDto,
	): Promise<PaginatedMarketingPlatformAccountsSummaryDto> {
		const limit: number = params.limit;
		const page: number = params.page;
		const search: string | null = params.search;
		const startTime: Date = params.startDate;
		const endTime: Date = params.endDate;

		return this.integrationSetMarketingPlatformsService.getMarketingPlatformAccountsSummary(
			integrationSetId,
			platform,
			limit,
			page,
			search,
			startTime,
			endTime,
		);
	}

	@ApiOperation({
		description:
			"Retrieve campaigns tree structure starting from social media platforms down to ad accounts with campaigns. " +
			"Supports advanced filtering by tree level and search terms to return only relevant branches. " +
			"The tree structure follows: Platform -> Account Info -> Business Account -> Ad Account -> Campaigns.",
		summary: "Get Marketing Campaigns Tree with Advanced Filtering",
	})
	@ApiQuery({
		description: "Search term to filter the tree structure. Case-insensitive substring matching.",
		example: "labubu",
		name: "search",
		required: false,
	})
	@ApiQuery({
		description:
			"Specifies which level of the tree to apply the search filter. Only branches containing matches at this level will be returned.",
		enum: ["platform", "accountInfo", "businessAccount", "adAccount", "campaign"],
		examples: {
			adAccount: {
				description:
					"Filter by ad account names - only returns branches with ad accounts matching the search term",
				value: "adAccount",
			},
			campaign: {
				description:
					"Filter by campaign names - only returns branches with campaigns matching the search term",
				value: "campaign",
			},
		},
		name: "treeLevel",
		required: false,
	})
	@ApiResponse({
		description: "Campaigns tree retrieved successfully with applied filters",
		status: 200,
		type: IntegrationSetCampaignsDto,
	})
	@ApiResponse({
		description: "Unauthorized - Invalid or missing authentication token",
		status: 401,
	})
	@ApiResponse({
		description: "Forbidden - Integration set not found",
		status: 403,
	})
	@Get("/campaigns")
	async getCampaigns(
		@Auth()
		{
			credentials: {
				current: { integrationSetId },
			},
		}: AuthData,
		@Query() query: GetIntegrationSetCampaignsQuery,
	): Promise<IntegrationSetCampaignsDto> {
		const campaignsTree = await this.integrationSetMarketingPlatformsService.getCampaignsTree(
			integrationSetId,
			query.search,
			query.treeLevel,
		);

		return {
			campaignsTree,
		};
	}

	@ApiOperation({
		description:
			"Bind marketing campaigns to a specific product. This endpoint ensures only one product can be linked per campaign, " +
			"preventing conflicts in campaign-product associations. Before binding, it validates that no campaign already has a product linked.",
		summary: "Bind Campaigns to Product",
	})
	@ApiResponse({
		description: "Campaigns successfully bound to product",
		status: 200,
		type: BindCampaignsDto,
	})
	@ApiResponse({
		description: "Unauthorized - Invalid or missing authentication token",
		status: 401,
	})
	@ApiResponse({
		description: "Forbidden - Integration set not found",
		status: 403,
	})
	@ApiResponse({
		description: "Not Found - One or more campaigns not found",
		status: 404,
	})
	@ApiResponse({
		description: "Conflict - One or more campaigns already have products bound",
		status: 409,
	})
	@Post("/campaigns/bind")
	async bindCampaigns(
		@Auth()
		{
			credentials: {
				current: { integrationSetId },
			},
		}: AuthData,
		@Body() body: BindCampaignsBodyDto,
	): Promise<BindCampaignsDto> {
		const boundCampaigns = await this.integrationSetMarketingPlatformsService.bindCampaigns(
			integrationSetId,
			body.campaigns,
			body.productId,
		);

		return {
			boundCampaigns,
		};
	}

	@ApiOperation({
		description:
			"Unbind marketing campaigns from their associated products. This endpoint removes all product bindings " +
			"from the specified campaigns, making them available for binding to other products.",
		summary: "Unbind Campaigns from Products",
	})
	@ApiResponse({
		description: "Campaigns successfully unbound from products",
		status: 200,
		type: UnbindCampaignsDto,
	})
	@ApiResponse({
		description: "Unauthorized - Invalid or missing authentication token",
		status: 401,
	})
	@ApiResponse({
		description: "Forbidden - Integration set not found",
		status: 403,
	})
	@ApiResponse({
		description: "Not Found - One or more campaigns not found",
		status: 404,
	})
	@Post("/campaigns/unbind")
	async unbindCampaigns(
		@Auth()
		{
			credentials: {
				current: { integrationSetId },
			},
		}: AuthData,
		@Body() body: UnbindCampaignsBodyDto,
	): Promise<UnbindCampaignsDto> {
		const unboundCampaigns = await this.integrationSetMarketingPlatformsService.unbindCampaigns(
			integrationSetId,
			body.campaigns,
		);

		return {
			unboundCampaigns,
		};
	}

	@Patch("adAccount/:id")
	async patchAdAccountMarketingPlatform(
		@Param("id") id: string,
		@Body()
		patchMarketingPlatformAdAccount: PatchMarketingPlatformAdAccountDto,
	): Promise<Partial<MarketingPlatformAdAccount>> {
		return this.integrationSetMarketingPlatformsService.patchAdAccount(id, patchMarketingPlatformAdAccount);
	}

	@ApiOperation({
		description:
			"Desativa todas as contas de anúncio de um perfil de marketing específico usando updateMany. Retorna a quantidade de contas desativadas.",
		summary: "Desativar Todas as Contas de Anúncio de um Perfil",
	})
	@ApiResponse({
		description: "Contas de anúncio desativadas com sucesso",
		schema: {
			properties: {
				count: {
					description: "Quantidade de contas desativadas",
					type: "number",
				},
			},
			type: "object",
		},
		status: 200,
	})
	@ApiResponse({
		description: "Unauthorized - Invalid or missing authentication token",
		status: 401,
	})
	@Patch("adAccount/profile/:integrationSetHasMarketingPlatformId/deactivate-all")
	async deactivateAllAdAccountsByProfile(
		@Param("integrationSetHasMarketingPlatformId")
		integrationSetHasMarketingPlatformId: string,
	): Promise<{ count: number }> {
		return this.integrationSetMarketingPlatformsService.deactivateAllAdAccountsByProfile(
			integrationSetHasMarketingPlatformId,
		);
	}

	@ApiOperation({
		description:
			"Ativa todas as contas de anúncio de um perfil de marketing específico usando updateMany. Retorna a quantidade de contas ativadas.",
		summary: "Ativar Todas as Contas de Anúncio de um Perfil",
	})
	@ApiResponse({
		description: "Contas de anúncio ativadas com sucesso",
		schema: {
			properties: {
				count: {
					description: "Quantidade de contas ativadas",
					type: "number",
				},
			},
			type: "object",
		},
		status: 200,
	})
	@ApiResponse({
		description: "Unauthorized - Invalid or missing authentication token",
		status: 401,
	})
	@Patch("adAccount/profile/:integrationSetHasMarketingPlatformId/activate-all")
	async activateAllAdAccountsByProfile(
		@Param("integrationSetHasMarketingPlatformId")
		integrationSetHasMarketingPlatformId: string,
	): Promise<{ count: number }> {
		return this.integrationSetMarketingPlatformsService.activateAllAdAccountsByProfile(
			integrationSetHasMarketingPlatformId,
		);
	}

	@Delete()
	async deleteMarketingPlatforms(@Query() query: DeleteMarketingPlatformAccountDto): Promise<Partial<void>> {
		return this.integrationSetMarketingPlatformsService.deactivateMany(query.ids);
	}

	@Delete(":id")
	async deleteMarketingPlatform(
		@Param("id") id: string,
	): Promise<Partial<IntegrationSetHasMarketingPlatform>> {
		return this.integrationSetMarketingPlatformsService.deactivate(id);
	}

	@Get("auth/:id")
	async getMarketingPlatformCredentials(@Param("id") id: string): Promise<AuthGenericAccountDto> {
		return this.integrationSetMarketingPlatformsService.getCredentials(id);
	}
}

