	@IsOptional()
	@IsString()
	search?: string;

	@ApiPropertyOptional({ type: [ProductCostType] })
	@IsOptional()
	@TransformToArray()
	@IsEnum(ProductCostType, { each: true })
	type?: ProductCostType[];

	@IsOptional()
	@TransformToArray()
	@IsArray()
	@Type(() => String)
	variantIds?: string[];
}

