enum Country {
	BRAZIL = "Brasil",
	COLOMBIA = "Colombia",
	MEXICO = "Mexico",
	ITALY = "Italy",
	GERMANY = "Germany",
	CANADA = "Canada",
	USA = "United States",
	FRANCE = "France",
	UK = "United Kingdom",
	JAPAN = "Japan",
	CHINA = "China",
	INDIA = "India",
	AUSTRALIA = "Australia",
}

export default class CountrySymbolMapper {
	private static countryMap: Record<string, Country> = {
		AU: Country.AUSTRALIA,
		BR: Country.BRAZIL,
		CA: Country.CANADA,
		CN: Country.CHINA,
		CO: Country.COLOMBIA,
		DE: Country.GERMANY,
		FR: Country.FRANCE,
		GB: Country.UK,
		IN: Country.INDIA,
		IT: Country.ITALY,
		JP: Country.JAPAN,
		MX: Country.MEXICO,
		UK: Country.UK,
		US: Country.USA,
	};

	static convert(symbol: string): Country {
		const upperSymbol = symbol.toUpperCase();
		const country = CountrySymbolMapper.countryMap[upperSymbol];

		if (!country) {
			throw new Error(`Unknown country symbol: ${symbol}`);
		}

		return country;
	}

	static extractSymbol(text: string): string {
		const symbols = Object.keys(CountrySymbolMapper.countryMap);

		for (const symbol of symbols) {
			if (text.includes(symbol)) {
				return symbol;
			}
		}

		throw new Error("No country symbol found in the provided text");
	}
}

