import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { GetGoals, GetGoalsOutputSchema } from '../usecases/GetGoals'

export const GetGoalsControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), membership: z.object({ storeId: z.uuid() }) }),
})

export const GetGoalsControllerOutputSchema = GetGoalsOutputSchema

