import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { OrderOverrideFieldsSchema } from '../objects/OrderOverrideFields'
import { UpdateOrderOverride, UpdateOrderOverrideOutputSchema } from '../usecases/UpdateOrderOverride'

export const UpdateOrderOverrideControllerInputSchema = z.object({
	ctx: z.object({
		user: z.object({ id: z.string() }),
		membership: z.object({ storeId: z.uuid() }),
	}),
	params: z.object({
		orderId: z.uuid(),
	}),
	body: z.object({
		storeIntegrationExternalId: z.string().min(1),
		patch: OrderOverrideFieldsSchema,
	}),
})

export const UpdateOrderOverrideControllerOutputSchema = UpdateOrderOverrideOutputSchema

@injectable()
export class UpdateOrderOverrideController extends Controller<
	typeof UpdateOrderOverrideControllerInputSchema,
	typeof UpdateOrderOverrideControllerOutputSchema
> {
	readonly path = '/orders/:orderId/override'
	readonly method = 'patch' as const
	readonly description = 'Update typed override fields on an Order (C26 UpdateOrderOverride)'
	readonly inputSchema = UpdateOrderOverrideControllerInputSchema
	readonly outputSchema = UpdateOrderOverrideControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: UpdateOrderOverride) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.membership.storeId,
			orderId: request.params.orderId,
			storeIntegrationExternalId: request.body.storeIntegrationExternalId,
			patch: request.body.patch,
		})
		return { status: HttpStatusCode.OK, data }
	}
