import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, PaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import { UpdateOrderOverride } from './UpdateOrderOverride'
import { OrderOverrideRepository } from '../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderOverriddenEvent } from '../events'

const STORE = testId('store', '1')
const ORDER_A = testId('order', 'a')
const ORDER_B = testId('order', 'b')
const EXT_A = 'shop-a.myshopify.com'
const EXT_B = 'shop-b.myshopify.com'
const USER_1 = testId('user', '1')
const USER_2 = testId('user', '2')

describe('UpdateOrderOverride (C26)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateOrderOverride
	let repo: OrderOverrideRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateOrderOverride)
		repo = testBed.resolve(OrderOverrideRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readOverriddenEvents() {
		return testBed.resolve(DomainEventRepository).findByType(OrderOverriddenEvent)
	}

	it('creates a fresh override on first call + emits with all fields as changed', async () => {
		const out = await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: {
				paymentStatus: PaymentStatus.PAID,
				revenue: new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }),
			},
		})

		expect(out.orderOverrideId).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findByPin(ORDER_A, EXT_A)
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(saved?.fields.revenue).toEqual(new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }))

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.orderId).toBe(ORDER_A)
		expect(emitted[0]!.payload.storeIntegrationExternalId).toBe(EXT_A)
		expect(emitted[0]!.payload.entity.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(emitted[0]!.payload.entity.fields.revenue).toEqual({ amountCents: 10_000, currency: CurrencyCode.USD })
	})

	it('merges patch into existing override + emits only the changed keys', async () => {
		// first call: set paymentStatus + revenue
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: {
				paymentStatus: PaymentStatus.PAID,
				revenue: new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }),
			},
		})

		// second call by a different user: change paymentStatus + add fees (revenue unchanged)
		await useCase.execute({
			userId: USER_2,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: {
				paymentStatus: PaymentStatus.REFUNDED,
				fees: new MonetaryAmount({ amountCents: 250, currency: CurrencyCode.USD }),
			},
		})

		const saved = await repo.findByPin(ORDER_A, EXT_A)
		// revenue preserved, paymentStatus updated, fees added
		expect(saved?.fields.revenue).toEqual(new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }))
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(saved?.fields.fees).toEqual(new MonetaryAmount({ amountCents: 250, currency: CurrencyCode.USD }))

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(2)
		expect(emitted[1]!.payload.entity.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(emitted[1]!.payload.entity.fields.fees).toEqual({ amountCents: 250, currency: CurrencyCode.USD })
	})

	it('is a no-op + emits no event when the patch matches existing fields', async () => {
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PAID },
		})

		const beforeId = (await repo.findByPin(ORDER_A, EXT_A))!.id.value

		const out = await useCase.execute({
			userId: USER_2,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PAID }, // same value
		})

		expect(out.orderOverrideId).toBe(beforeId)
		const saved = await repo.findByPin(ORDER_A, EXT_A)
		// fields unchanged — paymentStatus still PAID from the first call.
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.PAID)

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(1) // only the first create's event
	})

	it('discriminates by (orderId, storeIntegrationExternalId) — independent overrides per shop', async () => {
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PAID },
		})
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_B,
			patch: { paymentStatus: PaymentStatus.REFUNDED },
		})
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_B,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PENDING },
		})

		const oa = await repo.findByPin(ORDER_A, EXT_A)
		const ob = await repo.findByPin(ORDER_A, EXT_B)
		const oc = await repo.findByPin(ORDER_B, EXT_A)
		expect(oa?.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(ob?.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(oc?.fields.paymentStatus).toBe(PaymentStatus.PENDING)
		expect(oa?.id.value).not.toBe(ob?.id.value)

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(3)
	})
})

