import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'
import { and, count, desc, eq, inArray, isNull, sql } from 'drizzle-orm'
import { productCosts } from '@bk-dash/contracts/db'
import { CurrencyCode, ProductCostType } from '@bk-dash/contracts-typescript/wire/enums'
import type { ProductCostOption } from '../entities/ProductCost'

export const GetProductCostsListInputSchema = z.object({
	storeId: z.uuid(),
	storeIntegrationIds: z.array(z.uuid()).optional(),
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(200).default(50),
})

export const GetProductCostsListOutputSchema = z.object({
	total: z.number().int().min(0),
	items: z.array(
		z.object({
			productCostId: z.uuid(),
			storeIntegrationId: z.uuid(),
			productId: z.uuid().nullable(),
			costType: z.enum(ProductCostType),
			displayName: z.string().nullable(),
			summary: z.object({
				currencies: z.array(z.enum(CurrencyCode)),
				optionsCount: z.number().int(),
			}),
		}),
	),
})

/**
 * T18 ProductCostsList. Read-projection over non-deleted ProductCosts scoped
 * to a Store, optionally narrowed by storeIntegrationIds. Summary collapses
 * each row's options[] to (currencies dedup, optionsCount) so the list view
 * stays cheap regardless of how many options each cost carries.
 *
 * Direct-Drizzle BFF query — no entity rehydration, mirrors the sibling
 * GetProductsList pattern.
 */
@injectable()
export class GetProductCostsList extends Handler<typeof GetProductCostsListInputSchema, typeof GetProductCostsListOutputSchema> {
	readonly name = 'get_product_costs_list' as const
	readonly inputSchema = GetProductCostsListInputSchema
	readonly outputSchema = GetProductCostsListOutputSchema

	constructor(private readonly db: DrizzleClient) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const dbc = tx ?? this.db

		const filters = [eq(productCosts.storeId, input.storeId), isNull(productCosts.deletedAt)] as ReturnType<typeof eq>[]
		if (input.storeIntegrationIds !== undefined && input.storeIntegrationIds.length > 0) {
			filters.push(inArray(productCosts.storeIntegrationId, input.storeIntegrationIds) as any)
		}
		const where = and(...filters)

		const offset = Math.max(0, (input.page - 1) * input.limit)

		const [items, totalRows] = await Promise.all([
			dbc
				.select({
					id: productCosts.id,
					storeIntegrationId: productCosts.storeIntegrationId,
					productId: productCosts.productId,
					costType: productCosts.costType,
					displayName: productCosts.displayName,
					options: productCosts.options,
				})
				.from(productCosts)
				.where(where ?? sql`true`)
				.orderBy(desc(productCosts.createdAt))
				.limit(input.limit)
				.offset(offset),
			dbc
				.select({ value: count() })
				.from(productCosts)
				.where(where ?? sql`true`),
		])

		return {
			total: Number(totalRows[0]?.value ?? 0),
			items: items.map(r => {
				const opts = (r.options as ProductCostOption[]) ?? []
				const currencies = Array.from(new Set(opts.map(o => o.currency))) as CurrencyCode[]
				return {
					productCostId: r.id,
					storeIntegrationId: r.storeIntegrationId,
					productId: r.productId,
					costType: r.costType as ProductCostType,
					displayName: r.displayName,
					summary: { currencies, optionsCount: opts.length },
				}
			}),
		}
	}
}

