import { faker, mockId, mockMetric, mockSeries } from '@shared/testing/mock'

const AdAccountSchema = z.object({
	id: z.string(),
	name: z.string(),
	spend: MetricSchema,
	active: z.boolean(),
})

const MarketingProfileStatus = z.enum(['active', 'expired'])

const MarketingProfileSchema = z.object({
	id: z.string(),
	name: z.string(),
	avatarUrl: z.string().url().nullable(),
	status: MarketingProfileStatus,
	accountsCount: z.number(),
	activeAccountsCount: z.number(),
	spend: MetricSchema,
	adAccounts: z.array(AdAccountSchema),
})

export const ListMarketingProfilesInputSchema = z.object({
	platform: z.enum(MarketingPlatform).optional(),
	search: z.string().optional(),
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(100).default(20),
})

export const ListMarketingProfilesOutputSchema = z.paginatedResponse({
	id: z.string(),
	name: z.string(),
	avatarUrl: z.string().url().nullable(),
	status: MarketingProfileStatus,
	accountsCount: z.number(),
	activeAccountsCount: z.number(),
	spend: MetricSchema,
	adAccounts: z.array(AdAccountSchema),
})

/** MOCK. Paginated marketing profiles with ad accounts for a given platform. Faker fixtures. */
@injectable()
export class ListMarketingProfiles extends Handler<typeof ListMarketingProfilesInputSchema, typeof ListMarketingProfilesOutputSchema> {
	readonly name = 'list_marketing_profiles' as const
	readonly inputSchema = ListMarketingProfilesInputSchema
	readonly outputSchema = ListMarketingProfilesOutputSchema

	protected async handle(): Promise<this['output']> {
		const items = mockSeries(5, () => {
			const accountsCount = faker.number.int({ min: 1, max: 30 })
			const activeAccountsCount = faker.number.int({ min: 0, max: accountsCount })
			return {
				id: mockId(),
				name: faker.person.fullName(),
				avatarUrl: faker.datatype.boolean() ? faker.image.url() : null,
				status: faker.helpers.arrayElement(['active', 'expired'] as const),
				accountsCount,
				activeAccountsCount,
				spend: mockMetric(),
				adAccounts: mockSeries(faker.number.int({ min: 1, max: 5 }), () => ({
					id: mockId(),
					name: faker.company.name(),
					spend: mockMetric(),
					active: faker.datatype.boolean(),
				})),
			}
		})

		return {
			items,
			total: 23,
			totalPages: 5,
		}
	}
}

