import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'
import { CurrencyCode, AdSpendGroupBy } from '@bk-dash/contracts-typescript/wire/enums'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import type { AdSpendManual } from '../entities/AdSpendManual'

const toDateOnly = (date: Date): string => date.toISOString().slice(0, 10)

export const GetAdSpendBreakdownInputSchema = z.object({
	storeId: z.uuid(),
	storeIntegrationIds: z.array(z.uuid()).optional(),
	from: z.date(),
	to: z.date(),
	groupBy: z.enum(AdSpendGroupBy),
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(500).default(100),
})

export const GetAdSpendBreakdownOutputSchema = z.object({
	total: z.number().int().min(0),
	items: z.array(
		z.object({
			bucketDate: z.iso.date(),
			amountCents: z.number().int(),
			currency: z.enum(CurrencyCode),
			impressions: z.number().int(),
			clicks: z.number().int(),
			conversions: z.number().int(),
			roas: z.number(),
		}),
	),
})

/**
 * T21 AdSpendBreakdown. Maps repository AdSpendManual rows to the dashboard
 * breakdown shape: each entity's `startDate` becomes the `bucketDate`;
 * impressions/clicks/conversions fall back to 0 when the row didn't
 * carry them; `roas` defaults to 0 (downstream ROAS recompute requires
 * joining revenue, which lands with the Analytics dashboard impl).
 *
 * MANUAL-only rows — AUTOMATIC rows are Go-owned reads served directly
 * from the Go worker's own query surface.
 */
@injectable()
export class GetAdSpendBreakdown extends Handler<typeof GetAdSpendBreakdownInputSchema, typeof GetAdSpendBreakdownOutputSchema> {
	readonly name = 'get_ad_spend_breakdown' as const
	readonly inputSchema = GetAdSpendBreakdownInputSchema
	readonly outputSchema = GetAdSpendBreakdownOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const result = await this.adSpends.breakdown(
			{
				storeId: input.storeId,
				storeIntegrationIds: input.storeIntegrationIds,
				from: input.from,
				to: input.to,
				groupBy: input.groupBy,
				page: input.page,
				limit: input.limit,
			},
			tx,
		)
		return {
			total: result.total,
			items: result.items.map((s: AdSpendManual) => ({
				// startDate is a full ISO datetime; bucketDate is the date portion only.
				bucketDate: toDateOnly(s.startDate),
				amountCents: s.spend.amountCents,
				currency: s.spend.currency,
				impressions: s.impressions ?? 0,
				clicks: s.clicks ?? 0,
				conversions: s.conversions ?? 0,
				roas: 0,
			})),
		}
	}
}

