import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'
import { and, desc, eq, ilike, sql } from 'drizzle-orm'
import { products } from '@bk-dash/contracts/db'
import { ProductStatus } from '@bk-dash/contracts-typescript/wire/enums'

export const GetProductsListInputSchema = z.object({
	storeId: z.uuid(),
	search: z.string().optional(),
	status: z.enum(ProductStatus).optional(),
	page: z.number().int().positive().default(1),
	limit: z.number().int().positive().max(100).default(20),
})

export const GetProductsListOutputSchema = z.object({
	total: z.number().int().nonnegative(),
	items: z.array(
		z.object({
			productId: z.uuid(),
			title: z.string(),
			handle: z.string().nullable(),
			vendor: z.string().nullable(),
			productType: z.string().nullable(),
			imageUrl: z.string().nullable(),
			status: z.enum(ProductStatus),
			tags: z.array(z.string()),
			minPriceCents: z.number().int().nullable(),
			maxPriceCents: z.number().int().nullable(),
			currency: z.string().nullable(),
		}),
	),
})

/**
 * T16 ProductsList. BFF query — paginated list of canonical products
 * for a store, optionally filtered by status + title search. Direct
 * Drizzle read against catalog.products (Go-owned); no entity
 * rehydration since this is read-only and the projection IS the row.
 */
@injectable()
export class GetProductsList extends Handler<typeof GetProductsListInputSchema, typeof GetProductsListOutputSchema> {
	readonly name = 'get_products_list' as const
	readonly inputSchema = GetProductsListInputSchema
	readonly outputSchema = GetProductsListOutputSchema

	constructor(private readonly db: DrizzleClient) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const dbc = tx ?? this.db

		const where = and(
			eq(products.storeId, input.storeId),
			input.status ? eq(products.status, input.status) : undefined,
			input.search ? ilike(products.title, `%${input.search}%`) : undefined,
		)

		const offset = (input.page - 1) * input.limit

		const [countRow] = await dbc.select({ count: sql<number>`count(*)::int` }).from(products).where(where)

		const rows = await dbc.select().from(products).where(where).orderBy(desc(products.externalCreatedAt)).limit(input.limit).offset(offset)

		return {
			total: Number(countRow?.count ?? 0),
			items: rows.map((r: any) => ({
				productId: r.id,
				title: r.title,
				handle: r.handle ?? null,
				vendor: r.vendor ?? null,
				productType: r.productType ?? null,
				imageUrl: r.imageUrl ?? null,
				status: r.status,
				tags: Array.isArray(r.tags) ? r.tags : [],
				minPriceCents: r.minPriceCents != null ? Number(r.minPriceCents) : null,
				maxPriceCents: r.maxPriceCents != null ? Number(r.maxPriceCents) : null,
				currency: r.currency ?? null,
			})),
		}
	}
}

