	readonly inputSchema = GetActiveWarrantyInputSchema
	readonly outputSchema = GetActiveWarrantyOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		if (faker.datatype.boolean()) {
			return null
		}
		return {
			percentage: faker.number.float({ min: 0, max: 1, fractionDigits: 2 }),
			startDate: mockIsoDate(),
			period: pick(Object.values(WarrantyPeriod)),
		}
	}
}

