// Simplified: video-streaming has a flat actor model (user = actor, no clinic-switching).
import { singleton } from 'tsyringe-neo'
import { BaseError } from '@bk-dash/core-typescript'
import type { HttpControllerRequest, HttpMiddlewareResponse } from '@bk-dash/core-typescript'
import type { Middleware } from '@bk-dash/core-typescript'
import type { BaseInterfaceErrors } from '@bk-dash/core-typescript'
import { SessionSchema } from '@auth/schemas'
import { BetterAuth } from '../services/Authentication/BetterAuth'

/**
 * Validates the better-auth session and attaches the canonical
 * SessionSchema shape to request.ctx:
 *   ctx.user    — { id, email, name, emailVerified }
 *   ctx.session — { id, userId, expiresAt }
 *
 * Downstream consumers read `ctx.user.id` (not `ctx.session.userId`).
 * See SPEC-05.
 */
@singleton()
export class AuthAccountMiddleware implements Middleware {
	constructor(private betterAuth: BetterAuth) {}

	async execute(request: HttpControllerRequest<unknown>): Promise<HttpMiddlewareResponse<void>> {
		const response = await this.betterAuth.auth.api.getSession({
			headers: request.raw.headers as Headers,
			asResponse: true,
		})

		if (!response.ok) {
			throw new BaseError<BaseInterfaceErrors>('UNAUTHORIZED')
		}

		const rawSession = await response.json()

		// Parse the better-auth response with an extended schema that captures
		// the additionalFields value (activeStoreId) before mapping to SessionSchema.
		const BetterAuthSessionSchema = SessionSchema.extend({
			session: SessionSchema.shape.session.extend({
				activeStoreId: SessionSchema.shape.session.shape.storeId.optional(),
			}),
		})

		const validated = BetterAuthSessionSchema.safeParse(rawSession)

		if (!validated.success) {
			throw new BaseError<BaseInterfaceErrors>('UNAUTHORIZED', 'Invalid session structure')
		}

		request.ctx = {
			...request.ctx,
			user: validated.data.user,
			session: {
				id: validated.data.session.id,
				userId: validated.data.session.userId,
				expiresAt: validated.data.session.expiresAt,
				storeId: validated.data.session.activeStoreId ?? null,
			},
		}

		return {}
	}
}

import { z, type ZodObject, type ZodRawShape, type ZodTypeAny, type ZodLiteral } from 'zod'
import { stringToInteger } from './Transforms'
import { BaseEventSchema } from '../../types/BaseEvent'
import { BaseDomainEventSchema } from '../../types/BaseDomainEvent'
import { BaseIntegrationEventSchema } from '../../types/BaseIntegrationEvent'

// Meta options with examples
interface SchemaOptions {
	examples?: unknown[]
}

type IntegrationEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: ZodObject<T> }
>

type IntegrationEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: T }
>

type DomainEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

type DomainEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: T }
>

type BaseEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

// Helper to get examples from schema meta
const getExamples = (schema: ZodTypeAny): unknown[] => {
	// Access meta from the schema definition - Zod v4 uses 'def' property
	const def = (schema as unknown as { def?: { meta?: SchemaOptions } }).def
	return def?.meta?.examples ?? []
}

// Helper function to merge examples from two schemas
const mergeExamples = (baseExamples: unknown[] = [], additionalExamples: unknown[] = []) => {
	if (baseExamples.length === 0) return additionalExamples
	if (additionalExamples.length === 0) return baseExamples

	const merged: unknown[] = []

	// Create all possible combinations
	for (const baseExample of baseExamples) {
		for (const additionalExample of additionalExamples) {
			merged.push({
				...(baseExample as object),
				...(additionalExample as object),
			})
		}
	}

	return merged
}

// PaginatedQuery schema
export const PaginatedQuery = z
	.object({
		page: stringToInteger({ minimum: 1 }).default(1),
		limit: stringToInteger({ minimum: 1, maximum: 100 }).default(10),
		search: z.string().optional(),
	})
	.meta({
		examples: [
			{
				limit: 10,
				page: 1,
				search: 'Kitten drinking coffee.',
			},
		],
	})

