import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'

import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { GetOrdersList, GetOrdersListOutputSchema } from '../usecases/GetOrdersList'
import { PaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'

export const GetOrdersListControllerInputSchema = z.object({
	ctx: z.object({
		user: z.object({ id: z.string() }),
		membership: z.object({ storeId: z.uuid() }),
	}),
	query: z.paginatedQuery({
		storeIntegrationIds: z.stringToArray(z.uuid()).optional(),
		paymentStatus: z.stringToArray(z.enum(PaymentStatus)).optional(),
		from: z.stringToDate().optional(),
		to: z.stringToDate().optional(),
	}),
})

export const GetOrdersListControllerOutputSchema = GetOrdersListOutputSchema

@injectable()
export class GetOrdersListController extends Controller<
	typeof GetOrdersListControllerInputSchema,
	typeof GetOrdersListControllerOutputSchema
> {
	readonly path = '/orders'
	readonly method = 'get' as const
	readonly description = 'Paginated orders list with filters (T13)'
	readonly inputSchema = GetOrdersListControllerInputSchema
	readonly outputSchema = GetOrdersListControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private query: GetOrdersList) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.query.execute({
			storeId: request.ctx.membership.storeId,
			storeIntegrationIds: request.query.storeIntegrationIds,
			paymentStatus: request.query.paymentStatus,
			from: request.query.from,
			to: request.query.to,
			search: request.query.search,
			page: request.query.page,
			limit: request.query.limit,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

