import { faker, mockId, mockIsoDate, pick } from '@shared/testing/mock'

export const GetMyAccountInputSchema = z.object({
	storeId: z.uuid(),
	userId: z.string(),
})

export const GetMyAccountOutputSchema = z.object({
	profile: z.object({
		userId: z.string(),
		name: z.string(),
		email: z.string().email(),
		phone: z.string().nullable(),
		company: z.string().nullable(),
		pictureUrl: z.string().url().nullable(),
	}),
	preferences: z.object({
		language: z.enum(Language),
		currency: z.enum(CurrencyCode),
		timezone: z.enum(Timezone),
		emailNotifications: z.boolean(),
	}),
	security: z.object({
		hasPassword: z.boolean(),
		lastPasswordChangeAt: z.string().datetime({ offset: true }).nullable(),
		twoFactorEnabled: z.boolean(),
