import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { PatchAdAccounts, PatchAdAccountsOutputSchema } from '../usecases/PatchAdAccounts'

export const PatchAdAccountsControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), membership: z.object({ storeId: z.uuid() }) }),
	body: z.object({
		adAccountIds: z.array(z.uuid()).min(1),
		active: z.boolean(),
	}),
})

export const PatchAdAccountsControllerOutputSchema = PatchAdAccountsOutputSchema

@injectable()
export class PatchAdAccountsController extends Controller<
	typeof PatchAdAccountsControllerInputSchema,
	typeof PatchAdAccountsControllerOutputSchema
> {
	readonly path = '/marketing/ad-accounts'
	readonly method = 'patch' as const
	readonly description = 'MOCK. Batch-toggle active status on one or more ad accounts'
	readonly inputSchema = PatchAdAccountsControllerInputSchema
	readonly outputSchema = PatchAdAccountsControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private command: PatchAdAccounts) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		return {
			status: HttpStatusCode.OK,
			data: await this.command.execute({
				storeId: request.ctx.membership.storeId,
				adAccountIds: request.body.adAccountIds,
				active: request.body.active,
			}),
		}
	}
}

