import { Handler, z } from '@bk-dash/core-typescript'
import { NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { faker, mockId, mockIsoDate, mockSeries, pick } from '@shared/testing/mock'

export const ListNotificationsInputSchema = z.object({
	userId: z.string(),
})

export const ListNotificationsOutputSchema = z.object({
	items: z.array(
		z.object({
			id: z.string(),
			type: z.enum(NotificationCategory),
			message: z.string(),
			unread: z.boolean(),
			createdAt: z.iso.datetime({ offset: true }),
		}),
	),
	total: z.number().int().min(0),
})

/** MOCK. Header notification feed consumed by nearly every screen. */
@injectable()
export class ListNotifications extends Handler<typeof ListNotificationsInputSchema, typeof ListNotificationsOutputSchema> {
	readonly name = 'list_notifications' as const
	readonly inputSchema = ListNotificationsInputSchema
	readonly outputSchema = ListNotificationsOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		const items = mockSeries(8, () => ({
			id: mockId(),
			type: pick([
				NotificationCategory.ORDER_RECEIVED,
				NotificationCategory.PAYMENT_PROCESSED,
				NotificationCategory.SYNC_ERROR,
				NotificationCategory.INTEGRATION_DISCONNECTED,
			]),
			message: faker.lorem.sentence(),
			unread: faker.datatype.boolean(),
			createdAt: mockIsoDate(),
		}))
		return { items, total: items.length }
	}
}

