import { faker, mockId } from '@shared/testing/mock'

const TreeNodeSchema = z.object({
	id: z.string().nullable(),
	name: z.string().nullable(),
	isActive: z.boolean().nullable(),
})

const CampaignNodeSchema = TreeNodeSchema

const AdAccountNodeSchema = TreeNodeSchema.extend({
	campaigns: z.record(z.string(), CampaignNodeSchema),
})

const BusinessAccountNodeSchema = TreeNodeSchema.extend({
	adAccounts: z.record(z.string(), AdAccountNodeSchema),
})

const AccountInfoNodeSchema = TreeNodeSchema.extend({
	businessAccounts: z.record(z.string(), BusinessAccountNodeSchema),
})

const PlatformNodeSchema = z.object({
	id: z.string().nullable(),
	name: z.enum(MarketingPlatform),
	isActive: z.boolean().nullable(),
	accountInfos: z.record(z.string(), AccountInfoNodeSchema),
})

export const GetCampaignsTreeInputSchema = z.object({
	storeId: z.uuid(),
	search: z.string().optional(),
	treeLevel: z.enum(AdTreeLevel).optional(),
})

export const GetCampaignsTreeOutputSchema = z.object({
	campaignsTree: z.record(z.string(), PlatformNodeSchema),
})

type CampaignNode = z.infer<typeof CampaignNodeSchema>
type AdAccountNode = z.infer<typeof AdAccountNodeSchema>
type BusinessAccountNode = z.infer<typeof BusinessAccountNodeSchema>
type AccountInfoNode = z.infer<typeof AccountInfoNodeSchema>
type PlatformNode = z.infer<typeof PlatformNodeSchema>

const mockCampaign = (): CampaignNode => ({
	id: mockId(),
	name: faker.commerce.productName(),
	isActive: faker.datatype.boolean(),
})

const mockAdAccount = (): AdAccountNode => {
	const c1 = mockId()
	const c2 = mockId()
	return {
		id: mockId(),
		name: faker.company.name(),
		isActive: faker.datatype.boolean(),
		campaigns: {
			[c1]: mockCampaign(),
			[c2]: mockCampaign(),
		},
	}
}

const mockBusinessAccount = (): BusinessAccountNode => {
	const a1 = mockId()
	const a2 = mockId()
	return {
		id: mockId(),
		name: faker.company.name(),
		isActive: faker.datatype.boolean(),
		adAccounts: {
			[a1]: mockAdAccount(),
			[a2]: mockAdAccount(),
		},
	}
}

const mockAccountInfo = (): AccountInfoNode => {
	const b1 = mockId()
	return {
		id: mockId(),
		name: faker.person.fullName(),
		isActive: true,
		businessAccounts: {
			[b1]: mockBusinessAccount(),
		},
	}
}

const mockPlatformNode = (platform: MarketingPlatform): PlatformNode => {
	const acc1 = mockId()
	const acc2 = mockId()
	return {
		id: mockId(),
		name: platform,
		isActive: true,
		accountInfos: {
			[acc1]: mockAccountInfo(),
			[acc2]: mockAccountInfo(),
		},
	}
}

/** MOCK. 5-level campaigns tree: Platform → AccountInfo → BusinessAccount → AdAccount → Campaign. Faker fixtures. */
@injectable()
export class GetCampaignsTree extends Handler<typeof GetCampaignsTreeInputSchema, typeof GetCampaignsTreeOutputSchema> {
	readonly name = 'get_campaigns_tree' as const
	readonly inputSchema = GetCampaignsTreeInputSchema
	readonly outputSchema = GetCampaignsTreeOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		const meta = mockId()
		const google = mockId()
		return {
			campaignsTree: {
				[meta]: mockPlatformNode(MarketingPlatform.META),
				[google]: mockPlatformNode(MarketingPlatform.GOOGLE_ADS),
			},
		}
	}
}

