		if (input.storeIntegrationIds !== undefined && input.storeIntegrationIds.length > 0) {
			filters.push(inArray(productCosts.storeIntegrationId, input.storeIntegrationIds) as any)
		}
		const where = and(...filters)

		const offset = Math.max(0, (input.page - 1) * input.limit)

		const [items, totalRows] = await Promise.all([
			dbc
				.select({
					id: productCosts.id,
					storeIntegrationId: productCosts.storeIntegrationId,
					productId: productCosts.productId,
					costType: productCosts.costType,
					displayName: productCosts.displayName,
					options: productCosts.options,
				})
				.from(productCosts)
				.where(where ?? sql`true`)
				.orderBy(desc(productCosts.createdAt))
				.limit(input.limit)
				.offset(offset),
			dbc
				.select({ value: count() })
				.from(productCosts)
				.where(where ?? sql`true`),
		])

		return {
			total: Number(totalRows[0]?.value ?? 0),
			items: items.map(r => {
				const opts = (r.options as ProductCostOption[]) ?? []
				const currencies = Array.from(new Set(opts.map(o => o.currency))) as CurrencyCode[]
				return {
					productCostId: r.id,
					storeIntegrationId: r.storeIntegrationId,
					productId: r.productId,
					costType: r.costType as ProductCostType,
					displayName: r.displayName,
					summary: { currencies, optionsCount: opts.length },
				}
			}),
		}
	}
}

