```ts
// AuthAccountMiddleware (unchanged): ctx.user = {id,email,name,emailVerified}
//                                    ctx.session = {id, userId, expiresAt, storeId}  ← active store
// RequireStoreMember (MOVED to src/tenancy/middlewares/): reshaped ctx.membership:
ctx.membership = {
  id: string,            // the ACTIVE store's membership id (session.storeId)
  userId: string,
  role: Role,            // role in the active store
