import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DrizzleClient } from '@bk-dash/core-typescript'
import { adSpends, orders, products } from '@bk-dash/contracts/db'
import { CurrencyCode, PaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { AnalyticsFrequency } from '@analytics/enums'
import { GetProductPerformanceReport } from './GetProductPerformanceReport'
import { GetProfitMarginReport } from './GetProfitMarginReport'

const STORE = testId('store', '1')
const INTEGRATION_ID = testId('integration', '1')

describe('Analytics reports (T32 + T33)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let perf: GetProductPerformanceReport
	let margin: GetProfitMarginReport
	let db: any

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		perf = testBed.resolve(GetProductPerformanceReport)
		margin = testBed.resolve(GetProfitMarginReport)
		db = testBed.resolve(DrizzleClient) as any
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedProduct(id: string, title: string) {
		await db.insert(products).values({
			id,
			storeId: STORE,
			storeIntegrationId: INTEGRATION_ID,
			storeIntegrationExternalId: 'shop.myshopify.com',
			platform: 'SHOPIFY',
			externalId: `ext-${id}`,
			title,
			handle: title.toLowerCase(),
			status: 'ACTIVE',
			tags: [],
			externalCreatedAt: new Date('2026-05-01T10:00:00Z'),
		})
	}

	async function seedOrder(id: string, createdAt: Date, totalCents: number) {
		await db.insert(orders).values({
			id,
			storeId: STORE,
			storeIntegrationId: INTEGRATION_ID,
			storeIntegrationExternalId: 'shop.myshopify.com',
			platform: 'SHOPIFY',
			externalId: `ord-${id}`,
			externalCreatedAt: createdAt,
			customerEmail: 'b@x.com',
			customerName: 'Buyer',
			subtotalCents: BigInt(totalCents),
			discountTotalCents: 0n,
			shippingTotalCents: 0n,
			taxTotalCents: 0n,
			totalCents: BigInt(totalCents),
			totalCurrency: CurrencyCode.USD,
			paymentStatus: PaymentStatus.PAID,
			paymentMethod: 'CREDIT_CARD',
			paymentGateway: 'STRIPE',
			lines: [],
			transactions: [],
			isManual: false,
			isDraft: false,
		})
	}

	async function seedAdSpend(id: string, bucketStart: Date, amountCents: number) {
		const isoDate = bucketStart.toISOString().slice(0, 10)
		await db.insert(adSpends).values({
			id,
			storeId: STORE,
			storeIntegrationId: INTEGRATION_ID,
			storeIntegrationExternalId: 'shop.myshopify.com',
			platform: 'META',
			groupBy: 'DAILY',
			bucketStart,
			startDate: isoDate,
			endDate: isoDate,
			amountCents: BigInt(amountCents),
			currency: CurrencyCode.USD,
		})
	}

	describe('GetProductPerformanceReport (T32)', () => {
		it('returns total=0 + empty items when no products exist', async () => {
			const r = await perf.execute({
				storeIds: [STORE],
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				page: 1,
				limit: 50,
			})
			expect(r.total).toBe(0)
			expect(r.items).toEqual([])
			expect(r.reportingCurrency).toBe(CurrencyCode.USD)
		})

		it('lists store products with placeholder zero metrics', async () => {
			await seedProduct(testId('product', '1'), 'Product A')
			await seedProduct(testId('product', '2'), 'Product B')

			const r = await perf.execute({
				storeIds: [STORE],
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				page: 1,
				limit: 50,
			})
			expect(r.total).toBe(2)
			expect(r.items).toHaveLength(2)
			expect(r.items[0]!.unitsSold).toBe(0)
			expect(r.items[0]!.profitAmountCents).toBe(0)
		})

		it('paginates: total = unpaged count, items = page slice', async () => {
			for (let i = 1; i <= 4; i++) await seedProduct(testId('product', `page${i}`), `P${i}`)
			const page1 = await perf.execute({
				storeIds: [STORE],
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				page: 1,
				limit: 2,
			})
			const page2 = await perf.execute({
				storeIds: [STORE],
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				page: 2,
				limit: 2,
			})
			expect(page1.total).toBe(4)
			expect(page1.items).toHaveLength(2)
			expect(page2.items).toHaveLength(2)
		})
	})

	describe('GetProfitMarginReport (T33)', () => {
		it('returns empty periods when no orders + no ad-spend exist', async () => {
			const r = await margin.execute({
				storeIds: [STORE],
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				frequency: AnalyticsFrequency.MONTHLY,
			})
			expect(r.periods).toEqual([])
		})

		it('aggregates revenue + marketingSpend per period; computes profit + margin', async () => {
			await seedOrder(testId('order', '1'), new Date('2026-05-10T09:00:00Z'), 10_000)
			await seedOrder(testId('order', '2'), new Date('2026-05-20T09:00:00Z'), 5_000)
			await seedAdSpend(testId('adspend', '1'), new Date('2026-05-12T00:00:00Z'), 3_000)

			const r = await margin.execute({
				storeIds: [STORE],
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				frequency: AnalyticsFrequency.MONTHLY,
			})
			expect(r.periods).toHaveLength(1)
			const p = r.periods[0]!
			expect(p.revenueAmountCents).toBe(15_000)
			expect(p.marketingAmountCents).toBe(3_000)
			// profit = revenue - (cost + tax + fees + marketing + operational + warranty)
			//        = 15_000 - 3_000 = 12_000
			expect(p.profitAmountCents).toBe(12_000)
			// margin = profit / revenue * 100 = 80%
			expect(p.marginPercent).toBeCloseTo(80)
		})

		it('splits periods by frequency bucket', async () => {
			await seedOrder(testId('order', 'may'), new Date('2026-05-10T09:00:00Z'), 10_000)
			await seedOrder(testId('order', 'jun'), new Date('2026-06-10T09:00:00Z'), 5_000)

			const r = await margin.execute({
				storeIds: [STORE],
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-06-30T23:59:59.999Z'),
				frequency: AnalyticsFrequency.MONTHLY,
			})
			expect(r.periods).toHaveLength(2)
		})
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, GoalType } from '@bk-dash/contracts-typescript/wire/enums'
import { CreateGoal } from './CreateGoal'
import { UpdateGoal } from './UpdateGoal'
import { DeleteGoal } from './DeleteGoal'
import { GetGoals } from './GetGoals'
import { DuplicateLastGoal } from './DuplicateLastGoal'
import { GoalRepository } from '../repositories/GoalRepository'
import { GoalCreatedEvent, GoalDeletedEvent, GoalUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('Goal (C50/C51/C52 + T32 + DuplicateLast)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let create: CreateGoal
	let update: UpdateGoal
	let del: DeleteGoal
	let getGoals: GetGoals
	let duplicate: DuplicateLastGoal
	let repo: GoalRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		create = testBed.resolve(CreateGoal)
		update = testBed.resolve(UpdateGoal)
		del = testBed.resolve(DeleteGoal)
		getGoals = testBed.resolve(GetGoals)
		duplicate = testBed.resolve(DuplicateLastGoal)
		repo = testBed.resolve(GoalRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readCreatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(GoalCreatedEvent)
	}
	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(GoalUpdatedEvent)
	}
	async function readDeletedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(GoalDeletedEvent)
	}

	async function seed(over: { from?: Date; to?: Date; amount?: number } = {}): Promise<string> {
		const r = await create.execute({
			storeId: STORE,
			type: GoalType.REVENUE,
			targetAmount: { amountCents: over.amount ?? 100_000, currency: CurrencyCode.USD },
			from: over.from ?? new Date('2026-06-01T00:00:00.000Z'),
			to: over.to ?? new Date('2026-06-30T00:00:00.000Z'),
		})
		return r.goalId
	}

	it('Create persists + emits GoalCreatedEvent', async () => {
		const id = await seed()
		const saved = await repo.findById(id)
		expect(saved?.targetAmount.amountCents).toBe(100_000)
		const emitted = await readCreatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.goal).toBeDefined()
		expect(emitted[0]!.payload.goal.storeId).toBe(STORE)
	})

	it('Create propagates INVALID_DATE_RANGE when from > to', async () => {
		await expect(seed({ from: new Date('2026-07-01T00:00:00.000Z'), to: new Date('2026-06-01T00:00:00.000Z') })).rejects.toMatchObject({
			name: 'INVALID_DATE_RANGE',
		})
	})

	it('Update emits GoalUpdatedEvent (idempotent re-publish on same value)', async () => {
		const id = await seed()
		await update.execute({ userId: USER, goalId: id, targetAmount: { amountCents: 200_000, currency: CurrencyCode.USD } })
		expect((await repo.findById(id))?.targetAmount.amountCents).toBe(200_000)

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.goal).toBeDefined()
		expect(emitted[0]!.payload.goal.storeId).toBe(STORE)

		await update.execute({ userId: USER, goalId: id, targetAmount: { amountCents: 200_000, currency: CurrencyCode.USD } })
		expect(await readUpdatedEvents()).toHaveLength(2) // idempotent re-publish
	})

	it('Update throws GOAL_NOT_FOUND on missing id', async () => {
		await expect(
			update.execute({
				userId: USER,
				goalId: testId(),
				targetAmount: { amountCents: 1, currency: CurrencyCode.USD },
			}),
		).rejects.toMatchObject({ name: 'GOAL_NOT_FOUND' })
	})

	it('Delete removes + emits + second delete throws NOT_FOUND', async () => {
		const id = await seed()
		await del.execute({ goalId: id })
		expect(await repo.findById(id)).toBeUndefined()
		expect(await readDeletedEvents()).toHaveLength(1)

		await expect(del.execute({ goalId: id })).rejects.toMatchObject({ name: 'GOAL_NOT_FOUND' })
	})

	it('GetGoals lists store Goals newest-first by `to`', async () => {
		await seed({ from: new Date('2026-04-01T00:00:00.000Z'), to: new Date('2026-04-30T00:00:00.000Z') })
		await seed({ from: new Date('2026-06-01T00:00:00.000Z'), to: new Date('2026-06-30T00:00:00.000Z') })
		const r = await getGoals.execute({ storeId: STORE })
		expect(r.items.map(i => i.to.toISOString().slice(0, 10))).toEqual(['2026-06-30', '2026-04-30'])
	})

	it('DuplicateLastGoal shifts the window forward by same length + emits GoalCreatedEvent', async () => {
		await seed({ from: new Date('2026-06-01T00:00:00.000Z'), to: new Date('2026-06-30T00:00:00.000Z') }) // window length = 29-day delta

		const r = await duplicate.execute({ storeId: STORE })
		const fresh = await repo.findById(r.goalId)
		expect(fresh?.from.toISOString().slice(0, 10)).toBe('2026-07-01') // day after previous `to`
		expect(fresh?.to.toISOString().slice(0, 10)).toBe('2026-07-30') // new from + 29-day window delta

		const emitted = await readCreatedEvents()
		expect(emitted).toHaveLength(2)
	})

	it('DuplicateLastGoal throws NO_PREVIOUS_GOAL when (user, store) has none', async () => {
		await expect(duplicate.execute({ storeId: STORE })).rejects.toMatchObject({ name: 'NO_PREVIOUS_GOAL' })
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
