describe('ProductTags (C31 AddProductTag + C32 RemoveProductTag) — SPEC-10 ProductOverride overlay', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let addUseCase: AddProductTag
	let removeUseCase: RemoveProductTag
	let overrides: ProductOverrideRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		addUseCase = testBed.resolve(AddProductTag)
		removeUseCase = testBed.resolve(RemoveProductTag)
		overrides = testBed.resolve(ProductOverrideRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents<E extends BaseDomainEvent>(eventClass: DomainEventConstructor<E>) {
		return testBed.resolve(DomainEventRepository).findByType(eventClass)
	}

	describe('AddProductTag (C31)', () => {
		it('appends a new tag + emits ProductTagAddedEvent', async () => {
			await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'bestseller' })

			const override = await overrides.findByProductAndStore(PRODUCT, STORE)
			expect(override?.tags).toEqual(['bestseller'])

			const emitted = await readEvents(ProductTagAddedEvent)
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload).toEqual({ productId: PRODUCT, storeId: STORE, tag: 'bestseller' })
		})

		it('is idempotent — re-adding an existing tag emits no event', async () => {
			await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'bestseller' })
			await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'bestseller' })

			const override = await overrides.findByProductAndStore(PRODUCT, STORE)
			expect(override?.tags).toEqual(['bestseller'])
			const emitted = await readEvents(ProductTagAddedEvent)
			expect(emitted).toHaveLength(1)
		})
	})

	describe('RemoveProductTag (C32)', () => {
		it('removes an existing tag + emits ProductTagRemovedEvent', async () => {
			await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'bestseller' })
			await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'limited' })

			await removeUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'limited' })

			const override = await overrides.findByProductAndStore(PRODUCT, STORE)
			expect(override?.tags).toEqual(['bestseller'])

			const emitted = await readEvents(ProductTagRemovedEvent)
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload).toEqual({ productId: PRODUCT, storeId: STORE, tag: 'limited' })
		})

		it('is idempotent — removing a missing tag emits no event', async () => {
			await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'bestseller' })

			await removeUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'ghost' })

			const override = await overrides.findByProductAndStore(PRODUCT, STORE)
			expect(override?.tags).toEqual(['bestseller'])
			const emitted = await readEvents(ProductTagRemovedEvent)
			expect(emitted).toHaveLength(0)
		})

		it('is idempotent — removing from a non-existent override emits no event', async () => {
			await removeUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'whatever' })
			const emitted = await readEvents(ProductTagRemovedEvent)
			expect(emitted).toHaveLength(0)
		})
	})

	it('add → remove → add cycle emits add, remove, add (3 events)', async () => {
		await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'seasonal' })
		await removeUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'seasonal' })
		await addUseCase.execute({ userId: USER, productId: PRODUCT, storeId: STORE, tag: 'seasonal' })

		const added = await readEvents(ProductTagAddedEvent)
		const removed = await readEvents(ProductTagRemovedEvent)
		expect(added).toHaveLength(2)
		expect(removed).toHaveLength(1)

		const override = await overrides.findByProductAndStore(PRODUCT, STORE)
		expect(override?.tags).toEqual(['seasonal'])
	})
})

