import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, GoalType } from '@bk-dash/contracts-typescript/wire/enums'
import { CreateGoal } from './CreateGoal'
import { UpdateGoal } from './UpdateGoal'
import { DeleteGoal } from './DeleteGoal'
import { GetGoals } from './GetGoals'
import { DuplicateLastGoal } from './DuplicateLastGoal'
import { GoalRepository } from '../repositories/GoalRepository'
import { GoalCreatedEvent, GoalDeletedEvent, GoalUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('Goal (C50/C51/C52 + T32 + DuplicateLast)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let create: CreateGoal
	let update: UpdateGoal
	let del: DeleteGoal
	let getGoals: GetGoals
	let duplicate: DuplicateLastGoal
	let repo: GoalRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		create = testBed.resolve(CreateGoal)
		update = testBed.resolve(UpdateGoal)
		del = testBed.resolve(DeleteGoal)
		getGoals = testBed.resolve(GetGoals)
		duplicate = testBed.resolve(DuplicateLastGoal)
		repo = testBed.resolve(GoalRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readCreatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(GoalCreatedEvent)
	}
	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(GoalUpdatedEvent)
	}
	async function readDeletedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(GoalDeletedEvent)
	}

	async function seed(over: { from?: Date; to?: Date; amount?: number } = {}): Promise<string> {
		const r = await create.execute({
			storeId: STORE,
			type: GoalType.REVENUE,
			targetAmount: { amountCents: over.amount ?? 100_000, currency: CurrencyCode.USD },
			from: over.from ?? new Date('2026-06-01T00:00:00.000Z'),
			to: over.to ?? new Date('2026-06-30T00:00:00.000Z'),
		})
		return r.goalId
	}

	it('Create persists + emits GoalCreatedEvent', async () => {
		const id = await seed()
		const saved = await repo.findById(id)
		expect(saved?.targetAmount.amountCents).toBe(100_000)
		const emitted = await readCreatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.goal).toBeDefined()
		expect(emitted[0]!.payload.goal.storeId).toBe(STORE)
	})

	it('Create propagates INVALID_DATE_RANGE when from > to', async () => {
		await expect(seed({ from: new Date('2026-07-01T00:00:00.000Z'), to: new Date('2026-06-01T00:00:00.000Z') })).rejects.toMatchObject({
			name: 'INVALID_DATE_RANGE',
		})
	})

	it('Update emits GoalUpdatedEvent (idempotent re-publish on same value)', async () => {
		const id = await seed()
		await update.execute({ userId: USER, goalId: id, targetAmount: { amountCents: 200_000, currency: CurrencyCode.USD } })
		expect((await repo.findById(id))?.targetAmount.amountCents).toBe(200_000)

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.goal).toBeDefined()
		expect(emitted[0]!.payload.goal.storeId).toBe(STORE)

		await update.execute({ userId: USER, goalId: id, targetAmount: { amountCents: 200_000, currency: CurrencyCode.USD } })
		expect(await readUpdatedEvents()).toHaveLength(2) // idempotent re-publish
	})

	it('Update throws GOAL_NOT_FOUND on missing id', async () => {
		await expect(
			update.execute({
				userId: USER,
				goalId: testId(),
				targetAmount: { amountCents: 1, currency: CurrencyCode.USD },
			}),
		).rejects.toMatchObject({ name: 'GOAL_NOT_FOUND' })
	})

	it('Delete removes + emits + second delete throws NOT_FOUND', async () => {
		const id = await seed()
		await del.execute({ goalId: id })
		expect(await repo.findById(id)).toBeUndefined()
		expect(await readDeletedEvents()).toHaveLength(1)

		await expect(del.execute({ goalId: id })).rejects.toMatchObject({ name: 'GOAL_NOT_FOUND' })
	})

	it('GetGoals lists store Goals newest-first by `to`', async () => {
		await seed({ from: new Date('2026-04-01T00:00:00.000Z'), to: new Date('2026-04-30T00:00:00.000Z') })
		await seed({ from: new Date('2026-06-01T00:00:00.000Z'), to: new Date('2026-06-30T00:00:00.000Z') })
		const r = await getGoals.execute({ storeId: STORE })
		expect(r.items.map(i => i.to.toISOString().slice(0, 10))).toEqual(['2026-06-30', '2026-04-30'])
	})

	it('DuplicateLastGoal shifts the window forward by same length + emits GoalCreatedEvent', async () => {
		await seed({ from: new Date('2026-06-01T00:00:00.000Z'), to: new Date('2026-06-30T00:00:00.000Z') }) // window length = 29-day delta

		const r = await duplicate.execute({ storeId: STORE })
		const fresh = await repo.findById(r.goalId)
		expect(fresh?.from.toISOString().slice(0, 10)).toBe('2026-07-01') // day after previous `to`
		expect(fresh?.to.toISOString().slice(0, 10)).toBe('2026-07-30') // new from + 29-day window delta

		const emitted = await readCreatedEvents()
		expect(emitted).toHaveLength(2)
	})

	it('DuplicateLastGoal throws NO_PREVIOUS_GOAL when (user, store) has none', async () => {
		await expect(duplicate.execute({ storeId: STORE })).rejects.toMatchObject({ name: 'NO_PREVIOUS_GOAL' })
	})
})

