import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { SalesPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'
import { GetIntegrationDetail } from './GetIntegrationDetail'
import { StoreIntegration } from '../entities/StoreIntegration'
import { IntegrationCredentialSecret } from '../entities/IntegrationCredentialSecret'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../repositories/IntegrationCredentialSecretRepository'

const STORE = testId('store', '1')
const OWNER = 'user-owner-1'

describe('GetIntegrationDetail use case (T12)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: GetIntegrationDetail
	let storeIntegrationRepo: StoreIntegrationRepository
	let credentialSecretRepo: IntegrationCredentialSecretRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(GetIntegrationDetail)
		storeIntegrationRepo = testBed.resolve(StoreIntegrationRepository)
		credentialSecretRepo = testBed.resolve(IntegrationCredentialSecretRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('throws STORE_INTEGRATION_NOT_FOUND for unknown id', async () => {
		await expect(useCase.execute({ storeIntegrationId: crypto.randomUUID() })).rejects.toMatchObject({
			name: 'STORE_INTEGRATION_NOT_FOUND',
		})
	})

	it('returns lifecycle + credentials.hasSecret=false when no secret persisted', async () => {
		const i = StoreIntegration.create({
			storeId: STORE,
			platform: { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY },
			externalId: 'foo.myshopify.com',
			displayName: 'Foo',
			ownerId: OWNER,
		})
		await storeIntegrationRepo.save(i)

		const result = await useCase.execute({ storeIntegrationId: i.id.value })
		expect(result.storeIntegrationId).toBe(i.id.value)
		expect(result.credentials.hasSecret).toBe(false)
		expect(result.credentials.rotatedAt).toBeNull()
	})

	it('returns credentials.hasSecret=true when a secret is persisted', async () => {
		const i = StoreIntegration.create({
			storeId: STORE,
			platform: { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY },
			externalId: 'foo.myshopify.com',
			displayName: 'Foo',
			ownerId: OWNER,
		})
		await storeIntegrationRepo.save(i)
		await credentialSecretRepo.save(
			IntegrationCredentialSecret.create({
				storeIntegrationId: i.id.value,
				sealed: {
					encryptionAlgorithm: 'aes-256-gcm-v1',
					encryptedPayload: { iv: 'aa', ct: 'bb', tag: 'cc' },
				},
			}),
		)

		const result = await useCase.execute({ storeIntegrationId: i.id.value })
		expect(result.credentials.hasSecret).toBe(true)
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId, givenStoreIntegration } from '@test/support'
import { GetIntegrationsList } from './GetIntegrationsList'

const STORE = testId('store', 'a')
const OTHER_STORE = testId('store', 'b')
const OWNER = 'user-owner-1'

describe('GetIntegrationsList use case (T11)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: GetIntegrationsList

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(GetIntegrationsList)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('returns empty list when store has no integrations', async () => {
		const result = await useCase.execute({ storeId: STORE })
		expect(result.items).toEqual([])
	})

	it('returns only integrations for the requested store (filters by storeId)', async () => {
		const a = await givenStoreIntegration(testBed, {
			storeId: STORE,
			externalId: 'a.myshopify.com',
			displayName: 'Acme',
			ownerId: OWNER,
		})
		await givenStoreIntegration(testBed, {
			storeId: OTHER_STORE,
			externalId: 'b.myshopify.com',
			displayName: 'Other',
			ownerId: OWNER,
		})

		const result = await useCase.execute({ storeId: STORE })
		expect(result.items).toHaveLength(1)
		expect(result.items[0]!.storeIntegrationId).toBe(a.id.value)
	})

	it('projects active + lifecycle fields without secrets', async () => {
		await givenStoreIntegration(testBed, {
			storeId: STORE,
			externalId: 'foo.myshopify.com',
			displayName: 'Foo',
			ownerId: OWNER,
		})

		const result = await useCase.execute({ storeId: STORE })
		const item = result.items[0]!
		expect(item.active).toBe(true)
		expect(item.disconnectedAt).toBeNull()
		// Secrets must NOT be exposed in the list projection per spec.
		expect(item).not.toHaveProperty('credentials')
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import type Z from 'zod'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { Config, DomainEventRepository, HttpStatusCode, type HttpControllerRequest } from '@bk-dash/core-typescript'
import { MarketingPlatform, SalesPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'
import { IntegrationOAuthCallbackController, IntegrationOAuthCallbackInputSchema } from './IntegrationOAuthCallbackController'
import { OAuthStateTokenService } from '../services/OAuthStateTokenService'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationActivatedEvent, IntegrationConnectionInitiatedEvent, IntegrationHandshakeSucceededEvent } from '../events'

const STORE_ID = testId('store', '1')
const USER_ID = testId('user', '1')

type CallbackInput = HttpControllerRequest<Z.output<typeof IntegrationOAuthCallbackInputSchema>>

describe('IntegrationOAuthCallbackController', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let controller: IntegrationOAuthCallbackController
	let stateService: OAuthStateTokenService
	let storeIntegrationRepo: StoreIntegrationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		controller = testBed.resolve(IntegrationOAuthCallbackController)
		stateService = testBed.resolve(OAuthStateTokenService)
		storeIntegrationRepo = testBed.resolve(StoreIntegrationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function mintShopifyState(identifier = 'acme.myshopify.com'): string {
		return stateService.generate({
			userId: USER_ID,
			storeId: STORE_ID,
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
			identifier,
			ttlSec: 300,
		})
	}

	function callbackRequest(fields: Z.output<typeof IntegrationOAuthCallbackInputSchema>): CallbackInput {
		return {
			...fields,
			url: 'http://localhost/integrations/oauth/callback/stub',
			ctx: {},
			raw: new Request('http://localhost/integrations/oauth/callback/stub'),
		}
	}

	it('happy path Shopify: invokes ConnectIntegration and 302s to APP_URL with status=ok', async () => {
		const state = mintShopifyState('acme.myshopify.com')
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'shopify' },
				query: { code: 'auth_code_abc', state },
			}),
		)

		expect(response.status).toBe(HttpStatusCode.MOVED_TEMPORARILY)
		expect(response.data).toBeUndefined()
		const loc = new URL(response.headers!.Location!)
		expect(loc.origin + loc.pathname).toBe(`${Config.env.APP_URL}/app/integrations`)
		expect(loc.searchParams.get('status')).toBe('ok')
		expect(loc.searchParams.get('platform')).toBe(SalesPlatform.SHOPIFY)
		expect(loc.searchParams.get('storeIntegrationId')).toMatch(/^[0-9a-f-]{36}$/)

		// row exists, events emitted
		const persisted = await storeIntegrationRepo.findByStoreIdAndPlatform(STORE_ID, {
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
		})
		expect(persisted).toBeDefined()
		expect(persisted!.active).toBe(true)

		const eventRepo = testBed.resolve(DomainEventRepository)
		expect(await eventRepo.findByType(IntegrationConnectionInitiatedEvent)).toHaveLength(1)
		expect(await eventRepo.findByType(IntegrationHandshakeSucceededEvent)).toHaveLength(1)
		expect(await eventRepo.findByType(IntegrationActivatedEvent)).toHaveLength(1)
	})

	it('happy path Google Ads (no identifier in state): passes empty credentials to ConnectIntegration', async () => {
		const state = stateService.generate({
			userId: USER_ID,
			storeId: STORE_ID,
			type: StoreIntegrationType.MARKETING_PLATFORM,
			platform: MarketingPlatform.GOOGLE_ADS,
			ttlSec: 300,
		})
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'google_ads' },
				query: { code: 'g_auth_code', state },
			}),
		)

		expect(response.status).toBe(HttpStatusCode.MOVED_TEMPORARILY)
		const loc = new URL(response.headers!.Location!)
		expect(loc.searchParams.get('status')).toBe('ok')
		expect(loc.searchParams.get('platform')).toBe(MarketingPlatform.GOOGLE_ADS)
	})

	it('user denied: ?error=access_denied without code → 302 with code=OAUTH_USER_DENIED, no row created', async () => {
		const state = mintShopifyState()
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'shopify' },
				query: { error: 'access_denied', state },
			}),
		)

		expect(response.status).toBe(HttpStatusCode.MOVED_TEMPORARILY)
		const loc = new URL(response.headers!.Location!)
		expect(loc.searchParams.get('status')).toBe('error')
		expect(loc.searchParams.get('code')).toBe('OAUTH_USER_DENIED')
		expect(loc.searchParams.get('platform')).toBe(SalesPlatform.SHOPIFY)
		expect(
			await storeIntegrationRepo.findByStoreIdAndPlatform(STORE_ID, {
				type: StoreIntegrationType.SALES_CHANNEL,
				platform: SalesPlatform.SHOPIFY,
			}),
		).toBeUndefined()
	})

	it('tampered state → 302 with code=OAUTH_STATE_INVALID', async () => {
		const state = mintShopifyState()
		const [b64, sig] = state.split('.') as [string, string]
		const tampered = `${b64}.${sig.slice(0, -1)}${sig.slice(-1) === 'a' ? 'b' : 'a'}`
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'shopify' },
				query: { code: 'whatever', state: tampered },
			}),
		)
		const loc = new URL(response.headers!.Location!)
		expect(loc.searchParams.get('code')).toBe('OAUTH_STATE_INVALID')
	})

	it('expired state → 302 with code=OAUTH_STATE_EXPIRED', async () => {
		const expired = stateService.generate({
			userId: USER_ID,
			storeId: STORE_ID,
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
			identifier: 'acme.myshopify.com',
			ttlSec: -1,
		})
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'shopify' },
				query: { code: 'whatever', state: expired },
			}),
		)
		const loc = new URL(response.headers!.Location!)
		expect(loc.searchParams.get('code')).toBe('OAUTH_STATE_EXPIRED')
	})

	it('platform mismatch: Shopify state at meta callback → 302 with code=OAUTH_STATE_PLATFORM_MISMATCH', async () => {
		const state = mintShopifyState()
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'meta' },
				query: { code: 'whatever', state },
			}),
		)
		const loc = new URL(response.headers!.Location!)
		expect(loc.searchParams.get('code')).toBe('OAUTH_STATE_PLATFORM_MISMATCH')
	})

	it('missing code and no error: → 302 with code=OAUTH_CODE_INVALID', async () => {
		const state = mintShopifyState()
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'shopify' },
				query: { state },
			}),
		)
		const loc = new URL(response.headers!.Location!)
		expect(loc.searchParams.get('code')).toBe('OAUTH_CODE_INVALID')
	})

	it('unknown platform segment → 302 with code=PLATFORM_NOT_SUPPORTED (never JSON 4xx)', async () => {
		const response = await controller.handle(
			callbackRequest({
				params: { platform: 'not_a_platform' },
				query: { code: 'x', state: 'y.z' },
			}),
		)
		expect(response.status).toBe(HttpStatusCode.MOVED_TEMPORARILY)
		const loc = new URL(response.headers!.Location!)
		expect(loc.searchParams.get('status')).toBe('error')
		expect(loc.searchParams.get('code')).toBe('PLATFORM_NOT_SUPPORTED')
		expect(loc.searchParams.get('platform')).toBe('not_a_platform')
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { BindCampaignToProduct } from './BindCampaignToProduct'
import { UnbindCampaignFromProduct } from './UnbindCampaignFromProduct'
import { GetCampaignProductBindings } from './GetCampaignProductBindings'
import { CampaignProductBindingRepository } from '../repositories/CampaignProductBindingRepository'
import { CampaignProductBindingCreatedEvent, CampaignProductBindingRemovedEvent } from '../events'

const STORE = testId('store', '1')
const STORE_OTHER = testId('store', '2')
const CAMPAIGN_A = testId('campaign', 'a')
const CAMPAIGN_B = testId('campaign', 'b')
const PRODUCT_1 = testId('product', '1')
const PRODUCT_2 = testId('product', '2')
const VARIANT_1 = testId('variant', '1')
const USER = testId('user', '1')

describe('CampaignProductBinding (C36 + C37 + T22)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let bind: BindCampaignToProduct
	let unbind: UnbindCampaignFromProduct
	let list: GetCampaignProductBindings
	let repo: CampaignProductBindingRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		bind = testBed.resolve(BindCampaignToProduct)
		unbind = testBed.resolve(UnbindCampaignFromProduct)
		list = testBed.resolve(GetCampaignProductBindings)
		repo = testBed.resolve(CampaignProductBindingRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readCreatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(CampaignProductBindingCreatedEvent)
	}
	async function readRemovedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(CampaignProductBindingRemovedEvent)
	}

	describe('BindCampaignToProduct (C36)', () => {
		it('inserts one row per (campaignId, productId|variantId) + emits one event', async () => {
			await bind.execute({
				userId: USER,
				storeId: STORE,
				campaignId: CAMPAIGN_A,
				productIds: [PRODUCT_1, PRODUCT_2],
				variantIds: [VARIANT_1],
			})

			const items = await repo.listByStore(STORE)
			expect(items).toHaveLength(1)
			expect(items[0]!.campaignId).toBe(CAMPAIGN_A)
			expect(items[0]!.productIds.sort()).toEqual([PRODUCT_1, PRODUCT_2].sort())
			expect(items[0]!.variantIds).toEqual([VARIANT_1])

			const emitted = await readCreatedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.campaignId).toBe(CAMPAIGN_A)
			expect((emitted[0]!.payload.productIds as string[]).sort()).toEqual([PRODUCT_1, PRODUCT_2].sort())
		})

		it('is idempotent at the row level — re-binding the same product is a no-op', async () => {
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })

			const items = await repo.listByStore(STORE)
			expect(items).toHaveLength(1)
			expect(items[0]!.productIds).toEqual([PRODUCT_1])

			const emitted = await readCreatedEvents()
			expect(emitted).toHaveLength(2) // event still fires (idempotency lives at the row level, not the command level)
		})

		it('throws VALIDATION_ERROR when both productIds + variantIds are empty', async () => {
			await expect(
				bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [], variantIds: [] }),
			).rejects.toMatchObject({ name: 'VALIDATION_ERROR' })

			const emitted = await readCreatedEvents()
			expect(emitted).toHaveLength(0)
		})
	})

	describe('UnbindCampaignFromProduct (C37)', () => {
		it('removes existing rows + emits ProductBindingRemovedEvent', async () => {
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1, PRODUCT_2], variantIds: [] })

			await unbind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })

			const items = await repo.listByStore(STORE)
			expect(items).toHaveLength(1)
			expect(items[0]!.productIds).toEqual([PRODUCT_2])

			const emitted = await readRemovedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.productIds as string[]).toEqual([PRODUCT_1])
		})

		it('is idempotent — removing a non-bound product is a no-op but still emits the event', async () => {
			await unbind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })

			const items = await repo.listByStore(STORE)
			expect(items).toEqual([])

			const emitted = await readRemovedEvents()
			expect(emitted).toHaveLength(1) // spec says always-emit for idempotency
		})

		it('returns early without emitting when both lists are empty', async () => {
			await unbind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [], variantIds: [] })
			const emitted = await readRemovedEvents()
			expect(emitted).toHaveLength(0)
		})
	})

	describe('GetCampaignProductBindings (T22)', () => {
		it('aggregates bindings per campaign within the store', async () => {
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [VARIANT_1] })
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_B, productIds: [PRODUCT_2], variantIds: [] })
			await bind.execute({ userId: USER, storeId: STORE_OTHER, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })

			const result = await list.execute({ storeId: STORE })

			expect(result.items).toHaveLength(2)
			const a = result.items.find(i => i.campaignId === CAMPAIGN_A)
			const b = result.items.find(i => i.campaignId === CAMPAIGN_B)
			expect(a?.productIds).toEqual([PRODUCT_1])
			expect(a?.variantIds).toEqual([VARIANT_1])
			expect(b?.productIds).toEqual([PRODUCT_2])
			expect(b?.variantIds).toEqual([])
		})

		it('returns empty list when no bindings exist for the store', async () => {
			const r = await list.execute({ storeId: STORE })
			expect(r.items).toEqual([])
		})
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { SendNotification } from './SendNotification'
import { MarkNotificationRead } from './MarkNotificationRead'
import { GetNotificationsInbox } from './GetNotificationsInbox'
import { TriggerDailyDigest } from './TriggerDailyDigest'
import { BkdashNotificationRepository } from '../repositories/BkdashNotificationRepository'
import { BkdashNotificationDeliveryRepository } from '../repositories/BkdashNotificationDeliveryRepository'
import { DailyDigestTriggeredEvent, NotificationDeliveryReadEvent, NotificationSentEvent } from '../events'

const STORE = testId('store', '1')
const USER_SENDER = testId('user', 'sender')
const USER_A = testId('user', 'a')
const USER_B = testId('user', 'b')

describe('Notifications (C53/C54/C55 + T37)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let send: SendNotification
	let markRead: MarkNotificationRead
	let inbox: GetNotificationsInbox
	let trigger: TriggerDailyDigest
	let notifRepo: BkdashNotificationRepository
	let deliveryRepo: BkdashNotificationDeliveryRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		send = testBed.resolve(SendNotification)
		markRead = testBed.resolve(MarkNotificationRead)
		inbox = testBed.resolve(GetNotificationsInbox)
		trigger = testBed.resolve(TriggerDailyDigest)
		notifRepo = testBed.resolve(BkdashNotificationRepository)
		deliveryRepo = testBed.resolve(BkdashNotificationDeliveryRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readSentEvents() {
		return testBed.resolve(DomainEventRepository).findByType(NotificationSentEvent)
	}
	async function readReadEvents() {
		return testBed.resolve(DomainEventRepository).findByType(NotificationDeliveryReadEvent)
	}
	async function readDigestEvents() {
		return testBed.resolve(DomainEventRepository).findByType(DailyDigestTriggeredEvent)
	}

	describe('SendNotification (C53)', () => {
		it('creates one notification + one delivery per (target × enabled channel) + emits Sent', async () => {
			const r = await send.execute({
				userId: USER_SENDER,
				storeId: STORE,
				targetUserIds: [USER_A, USER_B],
				title: 'Hello',
				content: 'World',
				category: NotificationCategory.OTHER,
				important: false,
				pushEnabled: true,
				emailEnabled: true,
				contentType: 'text/plain',
			})
			// 2 targets × 2 channels = 4 deliveries
			expect(r.deliveriesCreated).toBe(4)

			const emitted = await readSentEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.recipientCount).toBe(2)
			expect(emitted[0]!.payload.deliveriesCreated).toBe(4)
		})

		it('throws EMPTY_RECIPIENTS when targetUserIds is empty', async () => {
			await expect(
				send.execute({
					userId: USER_SENDER,
					storeId: STORE,
					targetUserIds: [],
					title: 'x',
					content: 'y',
					category: NotificationCategory.OTHER,
					important: false,
					pushEnabled: true,
					emailEnabled: false,
					contentType: 'text/plain',
				}),
			).rejects.toMatchObject({ name: 'EMPTY_RECIPIENTS' })
		})

		it('throws NO_CHANNEL_ENABLED when both pushEnabled and emailEnabled are false', async () => {
			await expect(
				send.execute({
					userId: USER_SENDER,
					storeId: STORE,
					targetUserIds: [USER_A],
					title: 'x',
					content: 'y',
					category: NotificationCategory.OTHER,
					important: false,
					pushEnabled: false,
					emailEnabled: false,
					contentType: 'text/plain',
				}),
			).rejects.toMatchObject({ name: 'NO_CHANNEL_ENABLED' })
		})
	})

	describe('GetNotificationsInbox (T37)', () => {
		it('returns empty inbox when no deliveries exist for the user', async () => {
			const r = await inbox.execute({ userId: USER_A, unreadOnly: false, page: 1, limit: 20 })
			expect(r.total).toBe(0)
			expect(r.unreadCount).toBe(0)
		})

		it('returns scoped deliveries with notification metadata joined', async () => {
			await send.execute({
				userId: USER_SENDER,
				storeId: STORE,
				targetUserIds: [USER_A],
				title: 'Hello A',
				content: 'For you',
				category: NotificationCategory.SYNC_ERROR,
				important: true,
				pushEnabled: true,
				emailEnabled: false,
				contentType: 'text/plain',
			})
			await send.execute({
				userId: USER_SENDER,
				storeId: STORE,
				targetUserIds: [USER_B],
				title: 'Hello B',
				content: 'For B',
				category: NotificationCategory.OTHER,
				important: false,
				pushEnabled: true,
				emailEnabled: false,
				contentType: 'text/plain',
			})

			const r = await inbox.execute({ userId: USER_A, unreadOnly: false, page: 1, limit: 20 })
			expect(r.total).toBe(1)
			expect(r.items[0]!.title).toBe('Hello A')
			expect(r.items[0]!.important).toBe(true)
		})

		it('filters by unreadOnly + categories', async () => {
			await send.execute({
				userId: USER_SENDER,
				storeId: STORE,
				targetUserIds: [USER_A],
				title: 'System note',
				content: '...',
				category: NotificationCategory.OTHER,
				important: false,
				pushEnabled: true,
				emailEnabled: false,
				contentType: 'text/plain',
			})
			await send.execute({
				userId: USER_SENDER,
				storeId: STORE,
				targetUserIds: [USER_A],
				title: 'Alert note',
				content: '...',
				category: NotificationCategory.SYNC_ERROR,
				important: false,
				pushEnabled: true,
				emailEnabled: false,
				contentType: 'text/plain',
			})

			const alertOnly = await inbox.execute({
				userId: USER_A,
				unreadOnly: false,
				categories: [NotificationCategory.SYNC_ERROR],
				page: 1,
				limit: 20,
			})
			expect(alertOnly.total).toBe(1)
			expect(alertOnly.items[0]!.category).toBe(NotificationCategory.SYNC_ERROR)
		})
	})

	describe('MarkNotificationRead (C55)', () => {
		it('marks a delivery read + emits + is idempotent on second call', async () => {
			await send.execute({
				userId: USER_SENDER,
				storeId: STORE,
				targetUserIds: [USER_A],
				title: 't',
				content: 'c',
				category: NotificationCategory.OTHER,
				important: false,
				pushEnabled: true,
				emailEnabled: false,
				contentType: 'text/plain',
			})
			const r = await inbox.execute({ userId: USER_A, unreadOnly: false, page: 1, limit: 20 })
			const deliveryId = r.items[0]!.notificationDeliveryId

			await markRead.execute({ userId: USER_A, notificationDeliveryId: deliveryId })

			const after = await inbox.execute({ userId: USER_A, unreadOnly: true, page: 1, limit: 20 })
			expect(after.total).toBe(0) // no longer unread
			expect(await readReadEvents()).toHaveLength(1)

			// idempotent: second call does nothing + emits no new event
			await markRead.execute({ userId: USER_A, notificationDeliveryId: deliveryId })
			expect(await readReadEvents()).toHaveLength(1)
		})

		it('throws DELIVERY_NOT_OWNED_BY_USER when the calling user is not the recipient', async () => {
			await send.execute({
				userId: USER_SENDER,
