				important: false,
				pushEnabled: true,
				emailEnabled: false,
				contentType: 'text/plain',
			})
			const r = await inbox.execute({ userId: USER_A, unreadOnly: false, page: 1, limit: 20 })

			await expect(markRead.execute({ userId: USER_B, notificationDeliveryId: r.items[0]!.notificationDeliveryId })).rejects.toMatchObject({
				name: 'DELIVERY_NOT_OWNED_BY_USER',
			})
		})

		it('throws NOTIFICATION_DELIVERY_NOT_FOUND on missing id', async () => {
			await expect(markRead.execute({ userId: USER_A, notificationDeliveryId: testId() })).rejects.toMatchObject({
