import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { BindCampaignToProduct } from './BindCampaignToProduct'
import { UnbindCampaignFromProduct } from './UnbindCampaignFromProduct'
import { GetCampaignProductBindings } from './GetCampaignProductBindings'
import { CampaignProductBindingRepository } from '../repositories/CampaignProductBindingRepository'
import { CampaignProductBindingCreatedEvent, CampaignProductBindingRemovedEvent } from '../events'

const STORE = testId('store', '1')
const STORE_OTHER = testId('store', '2')
const CAMPAIGN_A = testId('campaign', 'a')
const CAMPAIGN_B = testId('campaign', 'b')
const PRODUCT_1 = testId('product', '1')
const PRODUCT_2 = testId('product', '2')
const VARIANT_1 = testId('variant', '1')
const USER = testId('user', '1')

describe('CampaignProductBinding (C36 + C37 + T22)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let bind: BindCampaignToProduct
	let unbind: UnbindCampaignFromProduct
	let list: GetCampaignProductBindings
	let repo: CampaignProductBindingRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		bind = testBed.resolve(BindCampaignToProduct)
		unbind = testBed.resolve(UnbindCampaignFromProduct)
		list = testBed.resolve(GetCampaignProductBindings)
		repo = testBed.resolve(CampaignProductBindingRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readCreatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(CampaignProductBindingCreatedEvent)
	}
	async function readRemovedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(CampaignProductBindingRemovedEvent)
	}

	describe('BindCampaignToProduct (C36)', () => {
		it('inserts one row per (campaignId, productId|variantId) + emits one event', async () => {
			await bind.execute({
				userId: USER,
				storeId: STORE,
				campaignId: CAMPAIGN_A,
				productIds: [PRODUCT_1, PRODUCT_2],
				variantIds: [VARIANT_1],
			})

			const items = await repo.listByStore(STORE)
			expect(items).toHaveLength(1)
			expect(items[0]!.campaignId).toBe(CAMPAIGN_A)
			expect(items[0]!.productIds.sort()).toEqual([PRODUCT_1, PRODUCT_2].sort())
			expect(items[0]!.variantIds).toEqual([VARIANT_1])

			const emitted = await readCreatedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.campaignId).toBe(CAMPAIGN_A)
			expect((emitted[0]!.payload.productIds as string[]).sort()).toEqual([PRODUCT_1, PRODUCT_2].sort())
		})

		it('is idempotent at the row level — re-binding the same product is a no-op', async () => {
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })

			const items = await repo.listByStore(STORE)
			expect(items).toHaveLength(1)
			expect(items[0]!.productIds).toEqual([PRODUCT_1])

			const emitted = await readCreatedEvents()
			expect(emitted).toHaveLength(2) // event still fires (idempotency lives at the row level, not the command level)
		})

		it('throws VALIDATION_ERROR when both productIds + variantIds are empty', async () => {
			await expect(
				bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [], variantIds: [] }),
			).rejects.toMatchObject({ name: 'VALIDATION_ERROR' })

			const emitted = await readCreatedEvents()
			expect(emitted).toHaveLength(0)
		})
	})

	describe('UnbindCampaignFromProduct (C37)', () => {
		it('removes existing rows + emits ProductBindingRemovedEvent', async () => {
			await bind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1, PRODUCT_2], variantIds: [] })

			await unbind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })

			const items = await repo.listByStore(STORE)
			expect(items).toHaveLength(1)
			expect(items[0]!.productIds).toEqual([PRODUCT_2])

			const emitted = await readRemovedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.productIds as string[]).toEqual([PRODUCT_1])
		})

		it('is idempotent — removing a non-bound product is a no-op but still emits the event', async () => {
			await unbind.execute({ userId: USER, storeId: STORE, campaignId: CAMPAIGN_A, productIds: [PRODUCT_1], variantIds: [] })

			const items = await repo.listByStore(STORE)
