import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CreateWarrantyReserve } from './CreateWarrantyReserve'
import { UpdateWarrantyReserve } from './UpdateWarrantyReserve'
import { DeleteWarrantyReserve } from './DeleteWarrantyReserve'
import { WarrantyReserveRepository } from '../repositories/WarrantyReserveRepository'
import { WarrantyReserveCreatedEvent, WarrantyReserveDeletedEvent, WarrantyReserveUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('WarrantyReserve (C45/C46/C47)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let create: CreateWarrantyReserve
	let update: UpdateWarrantyReserve
	let del: DeleteWarrantyReserve
	let repo: WarrantyReserveRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		create = testBed.resolve(CreateWarrantyReserve)
		update = testBed.resolve(UpdateWarrantyReserve)
		del = testBed.resolve(DeleteWarrantyReserve)
		repo = testBed.resolve(WarrantyReserveRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function eventRepo() {
		return testBed.resolve(DomainEventRepository)
	}

	it('Create opens a fresh row + emits event with previousWarrantyReserveId=null', async () => {
		const { warrantyReserveId } = await create.execute({
			userId: USER,
			storeId: STORE,
			rate: 5,
			effectiveFrom: new Date('2026-05-01T00:00:00.000Z'),
		})
		const saved = await repo.findById(warrantyReserveId)
		expect(saved?.rate).toBeCloseTo(0.05) // 5% → 0.05
		expect(saved?.isActive).toBe(true)

		const emitted = await eventRepo().findByType(WarrantyReserveCreatedEvent)
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.previousWarrantyReserveId).toBeNull()
	})

	it('Second Create supersedes the previous active row + chains previousWarrantyReserveId', async () => {
		const first = await create.execute({
			userId: USER,
			storeId: STORE,
			rate: 5,
			effectiveFrom: new Date('2026-05-01T00:00:00.000Z'),
		})
		const second = await create.execute({
			userId: USER,
			storeId: STORE,
			rate: 7,
			effectiveFrom: new Date('2026-06-01T00:00:00.000Z'),
		})

		const oldRow = await repo.findById(first.warrantyReserveId)
		expect(oldRow?.effectiveTo).toEqual(new Date('2026-06-01T00:00:00.000Z'))
		const newRow = await repo.findById(second.warrantyReserveId)
		expect(newRow?.isActive).toBe(true)

		const emitted = await eventRepo().findByType(WarrantyReserveCreatedEvent)
		expect(emitted[1]!.payload.previousWarrantyReserveId).toBe(first.warrantyReserveId)
	})

	it('Update mutates rate + emits Updated; idempotent re-publish on same value', async () => {
		const { warrantyReserveId } = await create.execute({
			userId: USER,
			storeId: STORE,
			rate: 5,
			effectiveFrom: new Date('2026-05-01T00:00:00.000Z'),
		})

		await update.execute({ userId: USER, warrantyReserveId, rate: 9 })
		const saved = await repo.findById(warrantyReserveId)
		expect(saved?.rate).toBeCloseTo(0.09)

		const emitted = await eventRepo().findByType(WarrantyReserveUpdatedEvent)
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.warrantyReserve).toBeDefined()
		expect(emitted[0]!.payload.warrantyReserve.storeId).toBe(STORE)

		await update.execute({ userId: USER, warrantyReserveId, rate: 9 }) // same — idempotent re-publish
		const after = await eventRepo().findByType(WarrantyReserveUpdatedEvent)
		expect(after).toHaveLength(2)
	})

	it('Update throws WARRANTY_RESERVE_NOT_FOUND on missing id', async () => {
		await expect(update.execute({ userId: USER, warrantyReserveId: testId('warranty-reserve', 'missing'), rate: 1 })).rejects.toMatchObject(
			{ name: 'WARRANTY_RESERVE_NOT_FOUND' },
		)
	})

	it('Delete soft-deletes + emits + second delete throws NOT_FOUND', async () => {
		const { warrantyReserveId } = await create.execute({
			userId: USER,
			storeId: STORE,
			rate: 5,
			effectiveFrom: new Date('2026-05-01T00:00:00.000Z'),
		})

		await del.execute({ userId: USER, warrantyReserveId })
		const saved = await repo.findById(warrantyReserveId)
		expect(saved?.isDeleted).toBe(true)

		const emitted = await eventRepo().findByType(WarrantyReserveDeletedEvent)
		expect(emitted).toHaveLength(1)

		await expect(del.execute({ userId: USER, warrantyReserveId })).rejects.toMatchObject({ name: 'WARRANTY_RESERVE_NOT_FOUND' })
	})

	it('List returns history (newest first), rates in 0..100 %', async () => {
		await create.execute({ userId: USER, storeId: STORE, rate: 5, effectiveFrom: new Date('2026-05-01T00:00:00.000Z') })
		await create.execute({ userId: USER, storeId: STORE, rate: 7, effectiveFrom: new Date('2026-06-01T00:00:00.000Z') })

		const r = await list.execute({ storeId: STORE })
		expect(r.items).toHaveLength(2)
		expect(r.items[0]!.rate).toBeCloseTo(7)
		expect(r.items[1]!.rate).toBeCloseTo(5)
		expect(r.items[0]!.effectiveTo).toBeNull() // current
		expect(r.items[1]!.effectiveTo).toEqual(new Date('2026-06-01T00:00:00.000Z'))
	})

	it('List excludes deleted rows', async () => {
		const { warrantyReserveId } = await create.execute({
			userId: USER,
			storeId: STORE,
			rate: 5,
			effectiveFrom: new Date('2026-05-01T00:00:00.000Z'),
		})
		await del.execute({ userId: USER, warrantyReserveId })

		const r = await list.execute({ storeId: STORE })
		expect(r.items).toEqual([])
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import {
	CurrencyCode,
	OperationalCostCategory,
	OperationalCostFlow,
	OperationalCostPaymentStatus,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import { CreateOperationalCost } from './CreateOperationalCost'
import { UpdateOperationalCost } from './UpdateOperationalCost'
import { DeleteOperationalCost } from './DeleteOperationalCost'
import { SetOperationalCostStatusOverride } from './SetOperationalCostStatusOverride'
import { GetOperationalCostsList } from './GetOperationalCostsList'
import { GetOperationalCostOccurrences } from './GetOperationalCostOccurrences'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import {
	OperationalCostCreatedEvent,
	OperationalCostDeletedEvent,
	OperationalCostStatusOverriddenEvent,
	OperationalCostUpdatedEvent,
} from '../events'

const STORE = testId('store', '1')
const STORE_OTHER = testId('store', '2')
const USER = testId('user', '1')

describe('OperationalCost (C41/C42/C43/C44 + T27)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let create: CreateOperationalCost
	let update: UpdateOperationalCost
	let del: DeleteOperationalCost
	let setOverride: SetOperationalCostStatusOverride
	let list: GetOperationalCostsList
	let occurrences: GetOperationalCostOccurrences
	let repo: OperationalCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		create = testBed.resolve(CreateOperationalCost)
		update = testBed.resolve(UpdateOperationalCost)
		del = testBed.resolve(DeleteOperationalCost)
		setOverride = testBed.resolve(SetOperationalCostStatusOverride)
		list = testBed.resolve(GetOperationalCostsList)
		occurrences = testBed.resolve(GetOperationalCostOccurrences)
		repo = testBed.resolve(OperationalCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function eventRepo() {
		return testBed.resolve(DomainEventRepository)
	}

	async function seed(): Promise<string> {
		const { operationalCostId } = await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.RENT,
			description: 'Office rent',
			amount: { amountCents: 100_000, currency: CurrencyCode.BRL },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01'),
		})
		return operationalCostId
	}

	it('Create persists + emits OperationalCostCreatedEvent', async () => {
		const id = await seed()

		const saved = await repo.findById(id)
		expect(saved?.category).toBe(OperationalCostCategory.RENT)
		expect(saved?.amount.amountCents).toBe(100_000)
		expect(saved?.flow).toBe(OperationalCostFlow.DEBIT) // defaults to DEBIT when omitted

		const emitted = await eventRepo().findByType(OperationalCostCreatedEvent)
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.operationalCost).toBeDefined()
		expect(emitted[0]!.payload.operationalCost.storeId).toBe(STORE)
	})

	it('Create honors an explicit CREDIT flow', async () => {
		const { operationalCostId } = await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.TAKE_PROFIT,
			flow: OperationalCostFlow.CREDIT,
			description: 'Partner deposit',
			amount: { amountCents: 50_000, currency: CurrencyCode.BRL },
			recurrency: OperationalCostRecurrency.ONCE,
			startDate: new Date('2026-06-01'),
		})
		const saved = await repo.findById(operationalCostId)
		expect(saved?.flow).toBe(OperationalCostFlow.CREDIT)
	})

	it('Create propagates INVALID_DATE_RANGE on startDate > endDate', async () => {
		await expect(
			create.execute({
				userId: USER,
				storeId: STORE,
				category: OperationalCostCategory.RENT,
				description: 'x',
				amount: { amountCents: 100, currency: CurrencyCode.USD },
				recurrency: OperationalCostRecurrency.ONCE,
				startDate: new Date('2026-12-01'),
				endDate: new Date('2026-11-01'),
			}),
		).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
	})

	it('Update emits OperationalCostUpdatedEvent (idempotent re-publish on same value)', async () => {
		const id = await seed()
		await update.execute({
			userId: USER,
			operationalCostId: id,
			amount: { amountCents: 200_000, currency: CurrencyCode.BRL },
			description: 'New rent',
		})

		const saved = await repo.findById(id)
		expect(saved?.amount.amountCents).toBe(200_000)
		expect(saved?.description).toBe('New rent')
		const emitted = await eventRepo().findByType(OperationalCostUpdatedEvent)
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.operationalCost).toBeDefined()
		expect(emitted[0]!.payload.operationalCost.storeId).toBe(STORE)

		// Idempotent re-publish — still emits a second event
		await update.execute({ userId: USER, operationalCostId: id, amount: { amountCents: 200_000, currency: CurrencyCode.BRL } })
		const after = await eventRepo().findByType(OperationalCostUpdatedEvent)
		expect(after).toHaveLength(2) // second idempotent event
	})

	it('Update throws OPERATIONAL_COST_NOT_FOUND on missing id', async () => {
		await expect(
			update.execute({
				userId: USER,
				operationalCostId: testId('operational-cost', 'missing'),
				amount: { amountCents: 100, currency: CurrencyCode.USD },
			}),
		).rejects.toMatchObject({ name: 'OPERATIONAL_COST_NOT_FOUND' })
	})

	it('Delete soft-deletes + emits + second delete throws NOT_FOUND', async () => {
		const id = await seed()
		await del.execute({ userId: USER, operationalCostId: id })

		const saved = await repo.findById(id)
		expect(saved?.isDeleted).toBe(true)
		const emitted = await eventRepo().findByType(OperationalCostDeletedEvent)
		expect(emitted).toHaveLength(1)

		await expect(del.execute({ userId: USER, operationalCostId: id })).rejects.toMatchObject({ name: 'OPERATIONAL_COST_NOT_FOUND' })
	})

	it('Override records a non-default deviation, prunes back to default, + emits each time', async () => {
		const id = await seed()
		const occurrenceDate = new Date('2026-06-01T00:00:00.000Z')

		// Default is PAID — flip this occurrence to UNPAID (a real deviation).
		await setOverride.execute({ userId: USER, operationalCostId: id, occurrenceDate, status: OperationalCostPaymentStatus.UNPAID })

		let saved = await repo.findById(id)
		expect(saved?.statusOverrides).toHaveLength(1)
		expect(saved?.statusOverrides[0]).toEqual({ occurrenceDate, status: OperationalCostPaymentStatus.UNPAID })

		// Set back to the default (PAID) → override is pruned (exclusion stays minimal).
		await setOverride.execute({ userId: USER, operationalCostId: id, occurrenceDate, status: OperationalCostPaymentStatus.PAID })

		saved = await repo.findById(id)
		expect(saved?.statusOverrides).toHaveLength(0)

		const emitted = await eventRepo().findByType(OperationalCostStatusOverriddenEvent)
		expect(emitted).toHaveLength(2)
	})

	it('Occurrences are derived at runtime, windowed, and resolved by exclusion', async () => {
		// MONTHLY cost starting 2026-06-01, capped by endDate 2026-12-01 → 7 occurrences (Jun..Dec).
		const { operationalCostId: id } = await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.RENT,
			description: 'Capped rent',
			amount: { amountCents: 100_000, currency: CurrencyCode.BRL },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01T00:00:00.000Z'),
			endDate: new Date('2026-12-01T00:00:00.000Z'),
		})

		// Override August to CANCELLED — a deviation from the PAID default.
		await setOverride.execute({
			userId: USER,
			operationalCostId: id,
			occurrenceDate: new Date('2026-08-01T00:00:00.000Z'),
			status: OperationalCostPaymentStatus.CANCELLED,
		})

		const window = { from: new Date('2026-01-01T00:00:00.000Z'), to: new Date('2027-01-01T00:00:00.000Z') }

		const page1 = await occurrences.execute({ operationalCostId: id, ...window, page: 1, limit: 3 })
		expect(page1.total).toBe(7) // total reflects the full series, not the page
		expect(page1.occurrences).toHaveLength(3) // only the requested slice is materialized
		expect(page1.occurrences[0]).toEqual({
			occurrenceDate: new Date('2026-06-01T00:00:00.000Z'),
			status: OperationalCostPaymentStatus.PAID,
		})

		const all = await occurrences.execute({ operationalCostId: id, ...window, page: 1, limit: 50 })
		const august = all.occurrences.find(o => o.occurrenceDate.getTime() === new Date('2026-08-01T00:00:00.000Z').getTime())
		expect(august?.status).toBe(OperationalCostPaymentStatus.CANCELLED) // override wins
		const july = all.occurrences.find(o => o.occurrenceDate.getTime() === new Date('2026-07-01T00:00:00.000Z').getTime())
		expect(july?.status).toBe(OperationalCostPaymentStatus.PAID) // default by exclusion
	})

	it('List returns scoped non-deleted rows', async () => {
		const a = await seed()
		await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.APP,
			description: 'SaaS',
			amount: { amountCents: 30_000, currency: CurrencyCode.USD },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01'),
		})
		// Different store
		await create.execute({
			userId: USER,
			storeId: STORE_OTHER,
			category: OperationalCostCategory.RENT,
			description: 'Other',
			amount: { amountCents: 1000, currency: CurrencyCode.USD },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01'),
		})

		await del.execute({ userId: USER, operationalCostId: a })

		const r = await list.execute({ storeId: STORE, page: 1, limit: 10 })
		expect(r.total).toBe(1)
		expect(r.items[0]!.description).toBe('SaaS')
		expect(r.items[0]!.flow).toBe(OperationalCostFlow.DEBIT)
	})
})

