  @doc("Conversion rate as a stringified decimal to preserve precision across the wire (clients re-parse to their preferred numeric).")
  rate: string;

  @doc("Provider that supplied the rate (used for audit + multi-source fallback at resolve time).")
  source: FxRateSource;

  @doc("RFC3339 instant this rate becomes effective. Combined with (fromCurrency, toCurrency, source) for the no-overwrite uniqueness key.")
  @encode("rfc3339", string)
  startDate: utcDateTime;
}

