import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { FxRate } from '../entities/FxRate'
import { FxRateRepository } from '../repositories/FxRateRepository'
import { FxRateCapturedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'
import { CurrencyCode, FxRateSource } from '@bk-dash/contracts-typescript/wire/enums'

export const CaptureFxRatesInputSchema = z.object({
	source: z.enum(FxRateSource),
	startDate: z.date(),
	rates: z
		.array(
			z.object({
				fromCurrency: z.enum(CurrencyCode),
				toCurrency: z.enum(CurrencyCode),
				rate: z.string(),
			}),
		)
		.min(1),
})

export const CaptureFxRatesOutputSchema = z.object({
	captured: z.number().int().nonnegative(),
})

/**
 * C48 CaptureFxRates. Per spec § 1.2 FX Management + § Scheduled Flows:
 * "Hourly: CaptureFxRates (TS) → FxRateCaptured." Persists a batch of
 * captured rates as new FxRate aggregates; each emits a
 * FxRateCapturedEvent so Analytics can invalidate profit-margin caches
 * that fold in the rate. Identity rates (from == to) are filtered out —
 * those are always "1.0" by the resolver short-circuit.
 *
 * Input is the rate payload coming from the scheduled fetcher (provider
 * stubbed for offline use). Use case is the seam: the fetcher reads the
 * provider, batches the per-pair list, and calls execute() once per
 * tick.
 */
@injectable()
export class CaptureFxRates extends Handler<typeof CaptureFxRatesInputSchema, typeof CaptureFxRatesOutputSchema> {
	readonly name = 'capture_fx_rates' as const
	readonly inputSchema = CaptureFxRatesInputSchema
	readonly outputSchema = CaptureFxRatesOutputSchema

	constructor(private readonly fxRates: FxRateRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const nonIdentity = input.rates.filter(r => r.fromCurrency !== r.toCurrency)
		if (nonIdentity.length === 0) {
			throw new BaseError<FinanceApplicationErrors>('FX_RATE_CAPTURE_EMPTY')
		}

		return this.withTransaction(tx, async tx => {
			let captured = 0
			for (const r of nonIdentity) {
				const entity = FxRate.create({
					fromCurrency: r.fromCurrency,
					toCurrency: r.toCurrency,
					rate: r.rate,
					source: input.source,
					startDate: input.startDate,
				})
				await this.fxRates.save(entity, tx)
				await this.domainEventRepository.save(
					new FxRateCapturedEvent({
						entityId: entity.id.value,
						payload: {
							fxRateId: entity.id.value,
							fromCurrency: r.fromCurrency,
							toCurrency: r.toCurrency,
							rate: r.rate,
							source: input.source,
							startDate: input.startDate,
						},
					}),
					tx,
				)
				captured++
			}
			return { captured }
		})
	}
}
