	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(FxRateRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: { from?: CurrencyCode; to?: CurrencyCode; rate?: string; startDate?: string; source?: FxRateSource }): FxRate {
		return FxRate.create({
			fromCurrency: opts.from ?? CurrencyCode.USD,
			toCurrency: opts.to ?? CurrencyCode.BRL,
			rate: opts.rate ?? '5.10',
			source: opts.source ?? FxRateSource.MANUAL,
			startDate: new Date(opts.startDate ?? '2026-05-01T00:00:00.000Z'),
		})
	}

	describe('save + findById', () => {
		it('round-trips an FxRate verbatim (rate string precision preserved)', async () => {
			const entity = build({ rate: '5.250000', startDate: '2026-06-15T12:00:00.000Z' })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.fromCurrency).toBe(CurrencyCode.USD)
			expect(fetched?.toCurrency).toBe(CurrencyCode.BRL)
			// Trailing zeros preserved (iter 303 fix: column is text, not double).
			expect(fetched?.rate).toBe('5.250000')
			expect(fetched?.source).toBe(FxRateSource.MANUAL)
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId())
			expect(r).toBeUndefined()
		})
	})

	describe('findEffective', () => {
		it('returns undefined when no rate exists for the pair', async () => {
			const r = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(r).toBeUndefined()
		})

		it('returns the latest rate with startDate <= asOf', async () => {
			await repo.save(build({ rate: '5.10', startDate: '2026-05-01T00:00:00.000Z' }))
			await repo.save(build({ rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' }))
			await repo.save(build({ rate: '5.30', startDate: '2026-07-01T00:00:00.000Z' }))

			const r = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(r?.rate).toBe('5.25')
		})

		it('filters by (fromCurrency, toCurrency) pair', async () => {
			await repo.save(build({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25' }))
			await repo.save(build({ from: CurrencyCode.EUR, to: CurrencyCode.BRL, rate: '5.60' }))

			const usd = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			const eur = await repo.findEffective(CurrencyCode.EUR, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(usd?.rate).toBe('5.25')
			expect(eur?.rate).toBe('5.60')
		})

		it('returns undefined when no rate is on or before asOf', async () => {
			await repo.save(build({ rate: '5.25', startDate: '2026-12-01T00:00:00.000Z' }))

			const r = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(r).toBeUndefined()
		})
	})

	describe('list', () => {
		it('paginates newest-first by startDate', async () => {
			await repo.save(build({ rate: '5.10', startDate: '2026-05-01T00:00:00.000Z' }))
			await repo.save(build({ rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' }))

			const r = await repo.list({ page: 1, limit: 10 })
			expect(r.total).toBe(2)
			expect(r.items.map(i => i.rate)).toEqual(['5.25', '5.10'])
		})

		it('filters by fromCurrency', async () => {
			await repo.save(build({ from: CurrencyCode.USD, rate: '5.25' }))
			await repo.save(build({ from: CurrencyCode.EUR, rate: '5.60' }))

			const r = await repo.list({ fromCurrency: CurrencyCode.EUR, page: 1, limit: 10 })
			expect(r.total).toBe(1)
			expect(r.items[0]?.fromCurrency).toBe(CurrencyCode.EUR)
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
			const entity = build({ rate: '5.10' })
			await repo.save(entity)
			await repo.delete(entity.id.value)
			expect(await repo.findById(entity.id.value)).toBeUndefined()
		})
	})
})
