		return this.rows.get(id)
	}

	async findEffective(fromCurrency: CurrencyCode, toCurrency: CurrencyCode, asOf: Date, _tx?: Transaction): Promise<FxRate | undefined> {
		const candidates = [...this.rows.values()]
			.filter(r => r.fromCurrency === fromCurrency && r.toCurrency === toCurrency && r.startDate <= asOf)
			.sort((a, b) => (a.startDate < b.startDate ? 1 : -1))
		return candidates[0]
	}

	async list(query: FxRateListQuery, _tx?: Transaction): Promise<FxRateListResult> {
		const matched = [...this.rows.values()].filter(r => {
			if (query.fromCurrency !== undefined && r.fromCurrency !== query.fromCurrency) return false
			if (query.toCurrency !== undefined && r.toCurrency !== query.toCurrency) return false
			if (query.from !== undefined && r.startDate < query.from) return false
			if (query.to !== undefined && r.startDate > query.to) return false
			return true
		})
		matched.sort((a, b) => (a.startDate < b.startDate ? 1 : -1))
		const start = (query.page - 1) * query.limit
		return { total: matched.length, items: matched.slice(start, start + query.limit) }
	}

	async save(entity: FxRate, _tx?: Transaction): Promise<FxRate> {
		entity.incrementVersion()
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(entity: FxRate): void {
		this.rows.set(entity.id.value, entity)
	}

	clear(): void {
		this.rows.clear()
	}
}
