import type { Transaction } from '@bk-dash/core-typescript'
import type { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { FxRate } from '../../entities/FxRate'

export interface FxRateListQuery {
	fromCurrency?: CurrencyCode
	toCurrency?: CurrencyCode
	from?: Date
	to?: Date
	page: number
	limit: number
}

export interface FxRateListResult {
	total: number
	items: FxRate[]
}

export abstract class FxRateRepository extends Repository<FxRate> {
	abstract findById(id: string, tx?: Transaction): Promise<FxRate | undefined>
	/** Returns the latest captured rate with startDate <= asOf for (from, to), or undefined when no series exists. */
	abstract findEffective(fromCurrency: CurrencyCode, toCurrency: CurrencyCode, asOf: Date, tx?: Transaction): Promise<FxRate | undefined>
	abstract list(query: FxRateListQuery, tx?: Transaction): Promise<FxRateListResult>
}

