import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'

import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { CaptureFxRates, CaptureFxRatesOutputSchema } from '../usecases/CaptureFxRates'
import { CurrencyCode, FxRateSource } from '@bk-dash/contracts-typescript/wire/enums'

export const CaptureFxRatesControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }) }),
	body: z.object({
		source: z.enum(FxRateSource),
		startDate: z.stringToDate(),
		rates: z
			.array(
				z.object({
					fromCurrency: z.enum(CurrencyCode),
					toCurrency: z.enum(CurrencyCode),
					rate: z.string(),
				}),
			)
			.min(1),
	}),
})

export const CaptureFxRatesControllerOutputSchema = CaptureFxRatesOutputSchema

@injectable()
export class CaptureFxRatesController extends Controller<
	typeof CaptureFxRatesControllerInputSchema,
	typeof CaptureFxRatesControllerOutputSchema
> {
	readonly path = '/fx-rates/capture'
	readonly method = 'post' as const
	readonly description = 'Capture a batch of FX rates from the scheduled fetcher (C48)'
	readonly inputSchema = CaptureFxRatesControllerInputSchema
	readonly outputSchema = CaptureFxRatesControllerOutputSchema

	override middlewares = [AuthAccountMiddleware]

	constructor(private cmd: CaptureFxRates) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			source: request.body.source,
			startDate: request.body.startDate,
			rates: request.body.rates,
		})
		return { status: HttpStatusCode.OK, data }
	}
}
