		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<FxRate | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(fxRates).where(eq(fxRates.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findEffective(fromCurrency: CurrencyCode, toCurrency: CurrencyCode, asOf: Date, tx?: DrizzleClient): Promise<FxRate | undefined> {
		const dbc = tx ?? this.db
