			const rows = await dbc
				.select()
				.from(fxRates)
				.where(and(eq(fxRates.fromCurrency, fromCurrency), eq(fxRates.toCurrency, toCurrency), lte(fxRates.startDate, asOf)))
				.orderBy(desc(fxRates.startDate))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

