		const whereClause = filters.length > 0 ? and(...filters) : sql`true`
		const result = await tryCatchAsync(async () => {
			const offset = Math.max(0, (query.page - 1) * query.limit)
			const [items, totalRows] = await Promise.all([
				dbc.select().from(fxRates).where(whereClause).orderBy(desc(fxRates.startDate)).limit(query.limit).offset(offset),
				dbc.select({ value: count() }).from(fxRates).where(whereClause),
			])
			return { items, total: Number(totalRows[0]?.value ?? 0) }
		})
		if (!result.success) throw result.error
		return {
			total: result.data.total,
			items: result.data.items.map(r => this.toDomain(r)),
		}
	}

	async save(entity: FxRate, tx?: DrizzleClient): Promise<FxRate> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(fxRates)
				.values(data)
				.onConflictDoUpdate({
					target: fxRates.id,
					set: {
						fromCurrency: data.fromCurrency,
						toCurrency: data.toCurrency,
						rate: data.rate,
						startDate: data.startDate,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(fxRates).where(eq(fxRates.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof fxRates.$inferSelect): FxRate {
		const parsed = FxRateSchema.parse({
			fromCurrency: row.fromCurrency,
			toCurrency: row.toCurrency,
			rate: row.rate,
			startDate: row.startDate,
		})
		return new FxRate({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
		})
	}

	private toPersistence(entity: FxRate): typeof fxRates.$inferInsert {
		return {
			id: entity.id.value,
			fromCurrency: entity.fromCurrency,
			toCurrency: entity.toCurrency,
			rate: entity.rate,
			source: entity.source,
			startDate: entity.startDate,
		}
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, FxRateSource } from '@bk-dash/contracts-typescript/wire/enums'
import { ResolveFxRate } from './ResolveFxRate'
import { GetFxRates } from './GetFxRates'
import { CaptureFxRates } from './CaptureFxRates'
import { FxRateRepository } from '../repositories/FxRateRepository'
import { FxRate } from '../entities/FxRate'
import { FxRateCapturedEvent } from '../events'

describe('FxRate (C48 CaptureFxRates + C49 ResolveFxRate + T28 GetFxRates)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let resolve: ResolveFxRate
	let list: GetFxRates
	let capture: CaptureFxRates
	let repo: FxRateRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		resolve = testBed.resolve(ResolveFxRate)
		list = testBed.resolve(GetFxRates)
		capture = testBed.resolve(CaptureFxRates)
		repo = testBed.resolve(FxRateRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seed(rate: {
		from: CurrencyCode
		to: CurrencyCode
		rate: string
		startDate: string
		source?: FxRateSource
	}): Promise<FxRate> {
		const entity = FxRate.create({
			fromCurrency: rate.from,
			toCurrency: rate.to,
			rate: rate.rate,
			source: rate.source ?? FxRateSource.MANUAL,
			startDate: new Date(rate.startDate),
		})
		await repo.save(entity)
		return entity
	}

	describe('ResolveFxRate (C49)', () => {
		it('short-circuits identity pairs to "1.0" without touching the repo', async () => {
			const r = await resolve.execute({ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.USD, date: new Date('2026-06-15') })
			expect(r.rate).toBe('1.0')
		})

		it('returns the latest captured rate with startDate <= date', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.10', startDate: '2026-05-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.30', startDate: '2026-07-01T00:00:00.000Z' })

			const r = await resolve.execute({ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.BRL, date: new Date('2026-06-15') })
			expect(r.rate).toBe('5.25') // the June row, not July
		})

		it('throws FX_RATE_NOT_FOUND when no captured rate exists for the pair', async () => {
			await expect(
				resolve.execute({ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.BRL, date: new Date('2026-06-15') }),
			).rejects.toMatchObject({ name: 'FX_RATE_NOT_FOUND' })
		})

		it('throws FX_RATE_NOT_FOUND when no rate is captured on or before the requested date', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-12-01T00:00:00.000Z' })

			await expect(
				resolve.execute({ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.BRL, date: new Date('2026-06-15') }),
			).rejects.toMatchObject({ name: 'FX_RATE_NOT_FOUND' })
		})
	})

	describe('GetFxRates (T28)', () => {
		it('returns total=0 + empty items when no captured rates exist', async () => {
			const r = await list.execute({ page: 1, limit: 10 })
			expect(r.total).toBe(0)
			expect(r.items).toEqual([])
		})

		it('lists captured rates newest-first', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.10', startDate: '2026-05-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })

			const r = await list.execute({ page: 1, limit: 10 })
			expect(r.items.map(i => i.rate)).toEqual(['5.25', '5.10'])
		})

		it('filters by currency pair', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.EUR, to: CurrencyCode.BRL, rate: '5.60', startDate: '2026-06-01T00:00:00.000Z' })

			const r = await list.execute({ fromCurrency: CurrencyCode.EUR, page: 1, limit: 10 })
			expect(r.total).toBe(1)
			expect(r.items[0]!.fromCurrency).toBe(CurrencyCode.EUR)
		})

		it('filters by date range', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.10', startDate: '2026-04-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })

			const r = await list.execute({ from: new Date('2026-05-01'), to: new Date('2026-12-31'), page: 1, limit: 10 })
			expect(r.total).toBe(1)
			expect(r.items[0]!.rate).toBe('5.25')
		})
	})

	describe('CaptureFxRates (C48)', () => {
		async function readCapturedEvents() {
			return testBed.resolve(DomainEventRepository).findByType(FxRateCapturedEvent)
		}

		it('persists each non-identity rate + emits one FxRateCapturedEvent per row', async () => {
			const startDate = new Date('2026-06-15T00:00:00.000Z')
			const out = await capture.execute({
				source: FxRateSource.MANUAL,
				startDate,
				rates: [
					{ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.BRL, rate: '5.25' },
					{ fromCurrency: CurrencyCode.EUR, toCurrency: CurrencyCode.BRL, rate: '5.60' },
					{ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.USD, rate: '1.0' }, // identity — filtered out
				],
			})
			expect(out.captured).toBe(2)

			const emitted = await readCapturedEvents()
			expect(emitted).toHaveLength(2)
			expect(emitted.map(e => e.payload.rate).sort()).toEqual(['5.25', '5.60'])

			// Captured rate is now resolvable
			const r = await resolve.execute({ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.BRL, date: new Date('2026-06-20') })
			expect(r.rate).toBe('5.25')
		})

		it('throws FX_RATE_CAPTURE_EMPTY when all supplied pairs are identity', async () => {
			await expect(
				capture.execute({
					source: FxRateSource.MANUAL,
					startDate: new Date('2026-06-15T00:00:00.000Z'),
					rates: [
						{ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.USD, rate: '1.0' },
						{ fromCurrency: CurrencyCode.BRL, toCurrency: CurrencyCode.BRL, rate: '1.0' },
					],
				}),
			).rejects.toMatchObject({ name: 'FX_RATE_CAPTURE_EMPTY' })
		})
	})
})

