		it('round-trips an FxRate verbatim (rate string precision preserved)', async () => {
			const entity = build({ rate: '5.250000', startDate: '2026-06-15T12:00:00.000Z' })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.fromCurrency).toBe(CurrencyCode.USD)
			expect(fetched?.toCurrency).toBe(CurrencyCode.BRL)
			// Trailing zeros preserved (iter 303 fix: column is text, not double).
			expect(fetched?.rate).toBe('5.250000')
			expect(fetched?.source).toBe(FxRateSource.MANUAL)
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId())
			expect(r).toBeUndefined()
		})
	})

	describe('findEffective', () => {
		it('returns undefined when no rate exists for the pair', async () => {
