import type { ProductCostSolverConstructorDTO, SolvedProductCost } from './types'
import { expandOptions } from './optionExpansion'
import { search } from './search'
import { selectBest } from './scoring'

/**
 * Ported faithfully from bk-dash `ProductCostSolver` (backtracking solver that
 * picks the optimal combination of overlapping cost rules for an order's
 * product/variant mix). The algorithm is unchanged; the class is now a thin
 * composer over three pure functions: expandOptions → search → selectBest.
 */
export class ProductCostSolver {
	private readonly costs: ProductCostSolverConstructorDTO['costs']
	private readonly orderVariants: Map<string, number>
	private readonly variantProducts: Map<string, string>
	private readonly orderProducts: Record<string, number>

	constructor({ costs, variantProducts, variants }: ProductCostSolverConstructorDTO) {
		this.costs = costs
		this.orderVariants = variants
		this.variantProducts = variantProducts
		this.orderProducts = Array.from(variants.entries()).reduce(
			(obj, [variant, quantity]) => {
				const product = variantProducts.get(variant)!
				obj[product] = (obj[product] ?? 0) + quantity
				return obj
			},
			{} as Record<string, number>,
		)
	}

	public solve(): SolvedProductCost[] {
		const options = expandOptions({
			costs: this.costs,
			orderProducts: this.orderProducts,
			orderVariants: this.orderVariants,
			variantProducts: this.variantProducts,
		})
		const results = search({ options, orderProducts: this.orderProducts, variantProducts: this.variantProducts })
		return selectBest(results)
	}
}

import { ProductCostType, type CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import type { ApplicableProductCost, ApplicableProductCostItem } from '@catalog/services/ProductCostQueryService'

export type ProductCostToExpand = Omit<ApplicableProductCost, 'data'>

export interface ProductCostSolverConstructorDTO {
	costs: ApplicableProductCost[]
	debug?: boolean
	variantProducts: Map<string, string>
	variants: Map<string, number>
}

export interface ProductCostSolverOption extends ApplicableProductCostItem {
	costId: string
	costOptionId: string
	requirements?: Array<{
		productId: string
		quantity: number
		variants: string[]
	}>
	type: ProductCostType
}

export type ProductCostSolverResult = Array<{
	content: ProductCostSolverOption
	products: Record<string, number>
	times: number
}>

export interface ProductCostBacktrackDTO {
	combo?: ProductCostSolverResult
	index: number
	products: Record<string, number>
}

/** A single resolved cost entry — the solver's per-combo output. */
export interface SolvedProductCost {
	costId: string
	costOptionId: string
	costOptionItemId: string | null
	cost: { amountCents: number; currency: CurrencyCode }
	shipping: { amountCents: number; currency: CurrencyCode }
	products: string[]
	productQuantity: Record<string, number>
}

import { ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import type { ApplicableProductCost, ApplicableProductCostItem } from '@catalog/services/ProductCostQueryService'
import type { ProductCostSolverOption, ProductCostToExpand } from './types'
import { pick } from './util'

interface ExpandInput {
	costs: ApplicableProductCost[]
	orderProducts: Record<string, number>
	orderVariants: Map<string, number>
	variantProducts: Map<string, string>
}

/** Pure: flatten cost rules into discrete solver options (one per qty tier). */
export function expandOptions({ costs, orderProducts, orderVariants, variantProducts }: ExpandInput): ProductCostSolverOption[] {
	const options: ProductCostSolverOption[] = []

	const maxRequired: Record<string, number> = {}
	const productVariantsMap = new Map<string, string[]>(Object.keys(orderProducts).map(productId => [productId, []]))

	for (const [variantId, quantity] of orderVariants.entries()) {
		const productId = variantProducts.get(variantId)!

		maxRequired[productId] = Math.max(maxRequired[productId] ?? 0, quantity)

		productVariantsMap.get(productId)?.push(variantId)
	}

	// Step 1: identify which variants have variant-specific costs.
	const variantsWithSpecificCosts = new Set<string>()
	for (const { data, type } of costs) {
		if (type === ProductCostType.SINGLE) {
			data.forEach(item => {
				item.variants?.forEach(v => {
					variantsWithSpecificCosts.add(v)
				})
			})
		}
	}

	const costFields: Array<keyof ProductCostToExpand> = ['costId', 'costOptionId', 'type']
	const itemFields: Array<keyof ApplicableProductCostItem> = [
		'cost',
		'costOptionItemId',
		'currency',
		'productId',
		'quantity',
		'quantityModifier',
		'shipping',
		'variants',
	]

	for (const { data, ...cost } of costs) {
		// MULTIPLE: one option requiring ALL items in `data` (a kit).
		if (cost.type === ProductCostType.MULTIPLE) {
			options.push({
				...pick(cost, [...costFields, 'cost', 'shipping']),
				costOptionItemId: null,
				currency: data[0]!.currency,
				quantity: 1,
				quantityModifier: QuantityModifier.EQ,
				requirements: data.map(item => ({
					productId: item.productId!,
					quantity: item.quantity,
					variants: item.variants!,
				})),
			})
		} else {
			// SINGLE
			for (const item of data) {
				const productId = item.productId!
				let targetVariants = item.variants

				const isGenericCost = !item.variants?.length
				if (isGenericCost) {
					// Generic: all order variants of this product MINUS the ones
					// that already have a variant-specific cost elsewhere.
					targetVariants = productVariantsMap.get(productId)?.filter(v => !variantsWithSpecificCosts.has(v))

					if (!targetVariants?.length) {
						continue
					}
				}

				expandItem(
					options,
					{
						...pick(cost, costFields),
						...pick(item, itemFields),
						variants: targetVariants,
					},
					maxRequired[productId]!,
				)
			}
		}
	}

	return options
}

function expandItem(options: ProductCostSolverOption[], option: ProductCostSolverOption, max: number) {
	const { quantity, quantityModifier } = option
	let start: number
	let effectiveMax = max

	switch (quantityModifier) {
		case QuantityModifier.EQ:
			start = quantity
			effectiveMax = quantity
			break
		case QuantityModifier.GT:
			start = quantity + 1
			break
		case QuantityModifier.GTE:
			start = quantity
			break
		case QuantityModifier.LT:
			start = 1
			effectiveMax = quantity - 1
			break
		case QuantityModifier.LTE:
			start = 1
			effectiveMax = quantity
			break
	}

	// Bail out on impossible ranges.
	if (start! > effectiveMax) return

	for (let i = start!; i <= effectiveMax; i++) {
		options.push({ ...option, quantity: i })
	}
}

import { ProductCostType, type CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import type { ProductCostSolverResult, SolvedProductCost } from './types'
import { pick, sum } from './util'

/** Pure: score combos (most-covered ↓, then cheapest ↑) and shape the winner. */
export function selectBest(results: ProductCostSolverResult[]): SolvedProductCost[] {
	if (results.length === 0) return []

	const [best] = results
		.map(combo => {
			let covered = 0
			let total = 0

			const processedCombo = combo.map(({ content: { currency, type, ...content }, products, times }) => {
				const coveredCount = sum(Object.values(products))
				covered += coveredCount

				const costQuantityMultiplier = type === ProductCostType.SINGLE ? coveredCount : times
				const cost = content.cost! * costQuantityMultiplier
				const shipping = (content.shipping ?? 0) * times
				total += cost + shipping

				return {
					content: {
						...pick(content, ['costId', 'costOptionId', 'costOptionItemId']),
						cost: { amountCents: cost, currency: currency as CurrencyCode },
						productQuantity: products,
						products: Object.keys(products),
						shipping: { amountCents: shipping, currency: currency as CurrencyCode },
					},
				}
			})

			return { combo: processedCombo, covered, total }
		})
		.sort((a, b) => {
			// Priority 1: most units covered (descending).
			if (a.covered !== b.covered) return b.covered - a.covered
			// Priority 2: lowest total cost (ascending).
			return a.total - b.total
		})

	return best?.combo.map(each => each.content as SolvedProductCost) ?? []
}

import { injectable } from 'tsyringe-neo'
import { EventHandler, Id, type Transaction } from '@bk-dash/core-typescript'
import { OrderUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import { ProductCostSolver } from '../../services/ProductCostSolver'
import { ProductCostLineAllocator } from '../../services/ProductCostLineAllocator'
import { ProductCostQueryService } from '../../../catalog/services/ProductCostQueryService'
import { OrderOverride } from '../../entities/OrderOverride'
import { OrderOverrideRepository } from '../../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderQueryService, type OrderLineDTO } from '../../services/OrderQueryService'

type OrderQueryResult = Awaited<ReturnType<OrderQueryService['findById']>>

@injectable()
export class ProductCostApplicationHandler extends EventHandler<typeof OrderUpdatedEvent> {
	readonly event = OrderUpdatedEvent
	private readonly allocator = new ProductCostLineAllocator()

	constructor(
		private readonly orderQuery: OrderQueryService,
		private readonly costQuery: ProductCostQueryService,
		private readonly overrideRepo: OrderOverrideRepository,
	) {
		super()
	}

	async handle(event: this['input'], tx?: Transaction): Promise<void> {
		const { platform, externalId } = event.payload
		const orderId = Id.fromSeed('order', platform, externalId).value
		const order = await this.orderQuery.findById(orderId)
		if (!order) return
		await this.applyForOrder(order, tx)
	}

	private async applyForOrder(order: NonNullable<OrderQueryResult>, tx?: Transaction): Promise<void> {
		const lines: OrderLineDTO[] = order.lines
		if (lines.length === 0) return

		const variantProducts = new Map<string, string>()
		const variantQuantities = new Map<string, number>()
		const guardedLines: Array<{ id: string; productId: string; variantId: string; quantity: number }> = []
		for (const line of lines) {
			if (!line.variantId || !line.productId) continue
			variantProducts.set(line.variantId, line.productId)
			variantQuantities.set(line.variantId, (variantQuantities.get(line.variantId) ?? 0) + line.quantity)
			guardedLines.push({ id: line.id, productId: line.productId, variantId: line.variantId, quantity: line.quantity })
		}
		if (variantQuantities.size === 0) return

		const productIds = Array.from(new Set(variantProducts.values()))
		const costs = await this.costQuery.findApplicable({ storeId: order.storeId, productIds, at: order.externalCreatedAt })

		const solved = new ProductCostSolver({ costs, variantProducts, variants: variantQuantities }).solve()
		const productCostByLine = this.allocator.allocate(
			solved,
			guardedLines.map(l => ({ id: l.id, productId: l.productId, quantity: l.quantity })),
		)

		let override = await this.overrideRepo.findByPin(order.id, order.storeIntegrationExternalId, tx)
		if (!override) {
			override = OrderOverride.create({
				storeId: order.storeId,
				orderId: order.id,
				storeIntegrationExternalId: order.storeIntegrationExternalId,
				fields: {},
			})
		}
		override.setProductCostByLine(productCostByLine)
		await this.overrideRepo.save(override, tx)
	}
}

import type { ApplicableProductCost } from './ApplicableProductCost'

export interface FindApplicableProductCostsInput {
	storeId: string
	/** Canonical product UUIDs present on the order. When omitted, all store costs are returned. */
	productIds?: string[]
	/** Order date used to filter costs by their effective interval. */
	at?: Date
}

/**
 * Cross-BC read port: surfaces catalog cost rules in the solver's
 * `ApplicableProductCost` shape so the sales-side ProductCostApplicationHandler
 * can resolve per-line costs without depending on catalog internals.
 * (Naming + Zod-return convention per feedback_query_service_naming_and_zod.)
 */
export abstract class ProductCostQueryService {
	abstract findApplicable(input: FindApplicableProductCostsInput): Promise<ApplicableProductCost[]>
}

import { injectable } from 'tsyringe-neo'
import { and, eq, inArray, isNull } from 'drizzle-orm'
import { DrizzleClient } from '@bk-dash/core-typescript'
import { productCosts } from '@bk-dash/contracts/db'
import type { QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { ApplicableProductCostSchema, ApplicableProductCostItemSchema } from './ApplicableProductCost'
import type { ApplicableProductCost } from './ApplicableProductCost'
import { ProductCostQueryService, type FindApplicableProductCostsInput } from './ProductCostQueryService'

/** Serialized shape of a MonetaryAmount after JSONB round-trip. */
interface StoredMonetaryAmount {
	amountCents: number
	currency: string
}

/** Serialized shape of a ProductCostOptionItem after JSONB round-trip.
 *  Id.toJSON() → raw UUID string; MonetaryAmount.toJSON() → {amountCents, currency}. */
interface StoredProductCostOptionItem {
	id: string
	variantIds: string[]
	quantity: number
	quantityModifier: QuantityModifier
	unitCost: StoredMonetaryAmount
	shipping: StoredMonetaryAmount
	variantsHash: string
}

/** Serialized shape of a ProductCostOption after JSONB round-trip. */
interface StoredProductCostOption {
	id: string
	currency: string
	country?: string
	startDate: string
	endDate?: string | null
	shipping: StoredMonetaryAmount
	items: StoredProductCostOptionItem[]
}

@injectable()
export class DrizzleProductCostQueryService extends ProductCostQueryService {
	constructor(private readonly db: DrizzleClient) {
		super()
	}

	async findApplicable(input: FindApplicableProductCostsInput): Promise<ApplicableProductCost[]> {
		const filters = [eq(productCosts.storeId, input.storeId), isNull(productCosts.deletedAt)]
		if (input.productIds && input.productIds.length > 0) {
			filters.push(inArray(productCosts.productId, input.productIds))
		}
		const rows = await this.db
			.select()
			.from(productCosts)
			.where(and(...filters))

		const out: ApplicableProductCost[] = []
		for (const row of rows) {
			const options = (row.options as StoredProductCostOption[]) ?? []
			for (const option of options) {
				const startDate = new Date(option.startDate)
				const endDate = option.endDate ? new Date(option.endDate) : null
				if (input.at) {
					if (input.at < startDate) continue
					if (endDate && input.at > endDate) continue
				}
				const data = option.items.map(item =>
					ApplicableProductCostItemSchema.parse({
						cost: item.unitCost.amountCents,
						costOptionItemId: item.id,
						currency: item.unitCost.currency,
						productId: row.productId ?? undefined,
						quantity: item.quantity,
						quantityModifier: item.quantityModifier,
						shipping: item.shipping.amountCents,
						variants: item.variantIds,
					}),
				)
				out.push(
					ApplicableProductCostSchema.parse({
						costId: row.id,
						costOptionId: option.id,
						type: row.costType,
						country: option.country,
						startDate,
						endDate,
						data,
						productId: row.productId ?? undefined,
						shipping: option.shipping.amountCents,
						variants: data.flatMap(d => d.variants ?? []),
					}),
				)
			}
		}
		return out
	}
}

