import { ProductCostUpdatedEvent } from '../events'
import type { CatalogApplicationErrors } from '../errors'

export const UpdateProductCostInputSchema = z.object({
	userId: z.uuid(),
	productCostId: z.uuid(),
	options: z.array(ProductCostOptionInputSchema).optional(),
	displayName: z.string().max(120).optional(),
})

export const UpdateProductCostOutputSchema = z.void()

/**
 * C28 UpdateProductCost. Loads the existing aggregate, applies the
 * (displayName / options) patch via `entity.update()` — which re-validates
 * the date-range invariant on the new options — then persists + emits
 * ProductCostUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateProductCost extends Handler<typeof UpdateProductCostInputSchema, typeof UpdateProductCostOutputSchema> {
	readonly name = 'update_product_cost' as const
	readonly inputSchema = UpdateProductCostInputSchema
	readonly outputSchema = UpdateProductCostOutputSchema

	constructor(private readonly productCosts: ProductCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const productCost = await this.productCosts.findById(input.productCostId, tx)
		if (!productCost || productCost.isDeleted) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			productCost.update({ displayName: input.displayName, options: input.options })
			await this.productCosts.save(productCost, tx)

			await this.domainEventRepository.save(
				new ProductCostUpdatedEvent({
					entityId: productCost.id.value,
					ownerId: productCost.storeId.value,
					payload: { productCost: productCost.toJSON() },
				}),
				tx,
			)
		})

		return
	}
}

import { injectable } from 'tsyringe-neo'
import { and, eq, inArray, isNull, or, sql } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { productCosts } from '@bk-dash/contracts/db'
import { ProductCost, ProductCostSchema } from '../../entities/ProductCost'
import { ProductCostRepository } from './ProductCostRepository'

/**
 * Drizzle-backed ProductCostRepository (iter 320 — paired with the
 * 0028 schema migration that adds storeIntegrationId / costType /
 * displayName / options(jsonb) / deletedAt columns to product_costs
 * and drops the product_cost_options child table).
 *
 * Options are stored inline as a jsonb column (replacing the
 * child-table normalization). The aggregate is always read as a
 * complete document so the child-table shape was pure complexity tax
 * with no actual normalization benefit.
 */
@injectable()
export class DrizzleProductCostRepository extends ProductCostRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<ProductCost | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(productCosts).where(eq(productCosts.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreAndProduct(storeId: string, productId: string | null, tx?: DrizzleClient): Promise<ProductCost | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const productClause = productId === null ? isNull(productCosts.productId) : eq(productCosts.productId, productId)
			const rows = await dbc
				.select()
				.from(productCosts)
				.where(and(eq(productCosts.storeId, storeId), productClause, isNull(productCosts.deletedAt)))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreAndProducts(storeId: string, productIds: (string | null)[], tx?: DrizzleClient): Promise<ProductCost[]> {
		if (productIds.length === 0) return []
		const dbc = tx ?? this.db
		const nonNullIds = productIds.filter((id): id is string => id !== null)
		const hasNull = productIds.includes(null)
		const productClause = or(
			nonNullIds.length > 0 ? inArray(productCosts.productId, nonNullIds) : undefined,
			hasNull ? isNull(productCosts.productId) : undefined,
		)
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(productCosts)
				.where(and(eq(productCosts.storeId, storeId), productClause, isNull(productCosts.deletedAt)))
			return rows
		})
		if (!result.success) throw result.error
		return result.data.map(row => this.toDomain(row))
	}

	async save(entity: ProductCost, tx?: DrizzleClient): Promise<ProductCost> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(productCosts)
				.values(data)
				.onConflictDoUpdate({
					target: productCosts.id,
					set: {
						storeId: data.storeId,
						storeIntegrationId: data.storeIntegrationId,
						productId: data.productId,
						costType: data.costType,
						displayName: data.displayName,
						options: data.options,
						deletedAt: data.deletedAt,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async saveMany(entities: ProductCost[], tx?: DrizzleClient): Promise<ProductCost[]> {
		if (entities.length === 0) return []
		for (const entity of entities) entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = entities.map(e => this.toPersistence(e))
			await dbc
				.insert(productCosts)
				.values(data)
				.onConflictDoUpdate({
					target: productCosts.id,
					// Multi-row upsert: the SET clause must reference the incoming
					// row (`excluded.*`), not a single captured `data` object.
					set: {
						storeId: sql`excluded.store_id`,
						storeIntegrationId: sql`excluded.store_integration_id`,
						productId: sql`excluded.product_id`,
						costType: sql`excluded.cost_type`,
						displayName: sql`excluded.display_name`,
						options: sql`excluded.options`,
						deletedAt: sql`excluded.deleted_at`,
						updatedAt: new Date(),
						version: sql`excluded.version`,
					},
				})
			return entities
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(productCosts).where(eq(productCosts.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof productCosts.$inferSelect): ProductCost {
		// `options` jsonb persists Date values as ISO strings on write. On read,
		// `z.coerce.date()` (via z.historical inside ProductCostOptionSchema)
		// rehydrates those ISO strings back to Date instances — no manual parsing needed.
		const parsed = ProductCostSchema.parse({
			storeId: row.storeId,
			storeIntegrationId: row.storeIntegrationId,
			productId: row.productId,
			costType: row.costType,
			displayName: row.displayName ?? undefined,
			options: row.options ?? [],
			deletedAt: row.deletedAt ?? null,
		})
		return new ProductCost({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: ProductCost): typeof productCosts.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			storeIntegrationId: entity.storeIntegrationId.value,
			productId: entity.productId?.value ?? null,
			costType: entity.costType,
			displayName: entity.displayName ?? null,
			options: entity.options,
			deletedAt: entity.deletedAt ?? null,
			version: entity.version,
		}
	}
}

 * variant-level granularity is encoded in `product_cost_options.items`.
 */
export const productCosts = catalogSchema.table(
	'product_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),
		// Scopes the cost row to the StoreIntegration that owns the
		// underlying product/variant ids. Required because the same
		// product can appear under multiple integrations (multi-channel
		// merchant) and merchant cost rules are typically per-channel.
		storeIntegrationId: uuid('store_integration_id').notNull(),
		// References catalog.products.id but no FK — products can be
		// re-synced (re-UPSERTed) without breaking the merchant's cost
		// data; we want costs to survive provider id changes. Nullable
		// for kit-scoped costs (multi-variant bundle priced together).
		productId: uuid('product_id'),

		// Discriminator from spec ProductCostType (SINGLE / MULTIPLE).
		// SINGLE = one cost across all variants; MULTIPLE = per-variant.
		costType: text('cost_type').notNull(),

		// Optional merchant-facing label (used by the BFF list shape).
		displayName: text('display_name'),

		// Time-effective option array, stored inline as jsonb. Each
		// option carries: { id, currency, country?, startDate, endDate?,
		// shipping: {amountCents, currency}, items: [{id, variantIds,
		// quantity, quantityModifier, unitCost, shipping, variantsHash}] }.
		// Inlined (vs the original product_cost_options child table)
		// because reads always pull the full document; the child-table
		// shape required cascade writes + N+1 reads for no actual
		// normalization benefit.
		options: jsonb('options').notNull().default([]),

		// Soft-delete timestamp. List queries filter by `deleted_at IS NULL`.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Partial unique — only enforce on live rows so a re-created cost
		// for the same (storeId, productId) after soft-delete doesn't
		// collide with the historical row.
		storeProductUnq: uniqueIndex('product_costs_store_product_unq').on(t.storeId, t.productId).where(sql`${t.deletedAt} IS NULL`),
		storeIdx: index('product_costs_store_id_idx').on(t.storeId),
		storeIntegrationIdx: index('product_costs_store_integration_id_idx').on(t.storeIntegrationId),
	}),
)

