 * 0028 schema migration that adds storeIntegrationId / costType /
 * displayName / options(jsonb) / deletedAt columns to product_costs
 * and drops the product_cost_options child table).
 *
 * Options are stored inline as a jsonb column (replacing the
 * child-table normalization). The aggregate is always read as a
 * complete document so the child-table shape was pure complexity tax
 * with no actual normalization benefit.
 */
@injectable()
export class DrizzleProductCostRepository extends ProductCostRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<ProductCost | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(productCosts).where(eq(productCosts.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreAndProduct(storeId: string, productId: string | null, tx?: DrizzleClient): Promise<ProductCost | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const productClause = productId === null ? isNull(productCosts.productId) : eq(productCosts.productId, productId)
			const rows = await dbc
				.select()
				.from(productCosts)
				.where(and(eq(productCosts.storeId, storeId), productClause, isNull(productCosts.deletedAt)))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreAndProducts(storeId: string, productIds: (string | null)[], tx?: DrizzleClient): Promise<ProductCost[]> {
		if (productIds.length === 0) return []
		const dbc = tx ?? this.db
		const nonNullIds = productIds.filter((id): id is string => id !== null)
		const hasNull = productIds.includes(null)
		const productClause = or(
			nonNullIds.length > 0 ? inArray(productCosts.productId, nonNullIds) : undefined,
			hasNull ? isNull(productCosts.productId) : undefined,
		)
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(productCosts)
				.where(and(eq(productCosts.storeId, storeId), productClause, isNull(productCosts.deletedAt)))
			return rows
		})
		if (!result.success) throw result.error
		return result.data.map(row => this.toDomain(row))
	}

	async save(entity: ProductCost, tx?: DrizzleClient): Promise<ProductCost> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(productCosts)
				.values(data)
				.onConflictDoUpdate({
					target: productCosts.id,
					set: {
						storeId: data.storeId,
						storeIntegrationId: data.storeIntegrationId,
						productId: data.productId,
						costType: data.costType,
						displayName: data.displayName,
						options: data.options,
						deletedAt: data.deletedAt,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async saveMany(entities: ProductCost[], tx?: DrizzleClient): Promise<ProductCost[]> {
		if (entities.length === 0) return []
		for (const entity of entities) entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = entities.map(e => this.toPersistence(e))
			await dbc
				.insert(productCosts)
				.values(data)
				.onConflictDoUpdate({
					target: productCosts.id,
					// Multi-row upsert: the SET clause must reference the incoming
					// row (`excluded.*`), not a single captured `data` object.
					set: {
						storeId: sql`excluded.store_id`,
						storeIntegrationId: sql`excluded.store_integration_id`,
						productId: sql`excluded.product_id`,
						costType: sql`excluded.cost_type`,
						displayName: sql`excluded.display_name`,
						options: sql`excluded.options`,
						deletedAt: sql`excluded.deleted_at`,
						updatedAt: new Date(),
						version: sql`excluded.version`,
					},
				})
			return entities
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(productCosts).where(eq(productCosts.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof productCosts.$inferSelect): ProductCost {
		// `options` jsonb persists Date values as ISO strings on write. On read,
		// `z.coerce.date()` (via z.historical inside ProductCostOptionSchema)
		// rehydrates those ISO strings back to Date instances — no manual parsing needed.
		const parsed = ProductCostSchema.parse({
			storeId: row.storeId,
			storeIntegrationId: row.storeIntegrationId,
			productId: row.productId,
			costType: row.costType,
			displayName: row.displayName ?? undefined,
			options: row.options ?? [],
			deletedAt: row.deletedAt ?? null,
		})
		return new ProductCost({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: ProductCost): typeof productCosts.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			storeIntegrationId: entity.storeIntegrationId.value,
			productId: entity.productId?.value ?? null,
			costType: entity.costType,
			displayName: entity.displayName ?? null,
			options: entity.options,
			deletedAt: entity.deletedAt ?? null,
			version: entity.version,
		}
	}
}

