import { ProductCostType, type CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import type { ProductCostSolverResult, SolvedProductCost } from './types'
import { pick, sum } from './util'

/** Pure: score combos (most-covered ↓, then cheapest ↑) and shape the winner. */
export function selectBest(results: ProductCostSolverResult[]): SolvedProductCost[] {
	if (results.length === 0) return []

	const [best] = results
		.map(combo => {
			let covered = 0
			let total = 0

			const processedCombo = combo.map(({ content: { currency, type, ...content }, products, times }) => {
				const coveredCount = sum(Object.values(products))
				covered += coveredCount

				const costQuantityMultiplier = type === ProductCostType.SINGLE ? coveredCount : times
				const cost = content.cost! * costQuantityMultiplier
				const shipping = (content.shipping ?? 0) * times
				total += cost + shipping

				return {
					content: {
						...pick(content, ['costId', 'costOptionId', 'costOptionItemId']),
						cost: { amountCents: cost, currency: currency as CurrencyCode },
						productQuantity: products,
						products: Object.keys(products),
						shipping: { amountCents: shipping, currency: currency as CurrencyCode },
					},
				}
			})

			return { combo: processedCombo, covered, total }
		})
		.sort((a, b) => {
			// Priority 1: most units covered (descending).
			if (a.covered !== b.covered) return b.covered - a.covered
			// Priority 2: lowest total cost (ascending).
			return a.total - b.total
		})

	return best?.combo.map(each => each.content as SolvedProductCost) ?? []
}

