import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { CreateProductCost } from './CreateProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostCreatedEvent } from '../events'
import type { ProductCostOptionInput } from '../entities/ProductCost'

const STORE = testId('store', '1')
const STORE_INTEGRATION = testId('store-integration', '1')
const PRODUCT_A = testId('product', 'a')
const PRODUCT_B = testId('product', 'b')
const VARIANT_1 = testId('variant', '1')
const USER = testId('user', '1')

function singleOption(overrides: Partial<ProductCostOptionInput> = {}): ProductCostOptionInput {
	return {
		currency: CurrencyCode.USD,
		startDate: '2026-05-01',
		shipping: { amountCents: 0, currency: CurrencyCode.USD },
		items: [
			{
				variantIds: [VARIANT_1],
				quantity: 1,
				quantityModifier: QuantityModifier.EQ,
				unitCost: { amountCents: 500, currency: CurrencyCode.USD },
				shipping: { amountCents: 0, currency: CurrencyCode.USD },
			},
		],
		...overrides,
	}
}

describe('CreateProductCost (C27)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: CreateProductCost
	let repo: ProductCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(CreateProductCost)
		repo = testBed.resolve(ProductCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
		// Mock repos hold state in-process; testBed.reset() only truncates
		// PGlite tables (events outbox, etc), so clear the Mock explicitly.
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readCreatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ProductCostCreatedEvent)
	}

	it('persists a new ProductCost + emits ProductCostCreatedEvent', async () => {
		const out = await useCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			displayName: 'USD cost for product A',
			options: [singleOption()],
		})

		expect(out.productCostId).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findById(out.productCostId)
		expect(saved?.storeId.value).toBe(STORE)
		expect(saved?.productId?.value).toBe(PRODUCT_A)
		expect(saved?.costType).toBe(ProductCostType.SINGLE)
		expect(saved?.displayName).toBe('USD cost for product A')
		expect(saved?.options).toHaveLength(1)
		// Entity stamps an id + variantsHash on each option's items
		const firstItem = saved?.options.at(0)?.items.at(0)
		expect(firstItem?.id.value).toMatch(/^[0-9a-f-]{36}$/)
		expect(firstItem?.variantsHash).toBe(VARIANT_1)

		const emitted = await readCreatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
		expect(emitted[0]!.payload.productCost.productId).toBe(PRODUCT_A)
		expect(emitted[0]!.payload.productCost.costType).toBe(ProductCostType.SINGLE)
	})

	it('throws PRODUCT_COST_ALREADY_EXISTS when a rule already exists for the same (storeId, productId)', async () => {
		await useCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		await expect(
			useCase.execute({
				userId: USER,
				storeId: STORE,
				storeIntegrationId: STORE_INTEGRATION,
				productId: PRODUCT_A,
				costType: ProductCostType.SINGLE,
				options: [singleOption()],
			}),
		).rejects.toMatchObject({ name: 'PRODUCT_COST_ALREADY_EXISTS' })
	})

	it('allows a second rule for a different product on the same store', async () => {
		await useCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		const out = await useCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_B,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		expect(out.productCostId).toMatch(/^[0-9a-f-]{36}$/)
		const both = await readCreatedEvents()
		expect(both).toHaveLength(2)
	})

	it('allows kit-scoped rules (productId=null) alongside product-scoped rules', async () => {
		await useCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		// Kit-scoped (productId=null) is a distinct uniqueness slot per storeId.
		const out = await useCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: null,
			costType: ProductCostType.MULTIPLE,
			options: [singleOption()],
		})

		expect(out.productCostId).toMatch(/^[0-9a-f-]{36}$/)
		const saved = await repo.findById(out.productCostId)
		expect(saved?.productId).toBeNull()
		expect(saved?.costType).toBe(ProductCostType.MULTIPLE)
	})

	it('propagates INVALID_DATE_RANGE from the entity when startDate > endDate', async () => {
		await expect(
			useCase.execute({
				userId: USER,
				storeId: STORE,
				storeIntegrationId: STORE_INTEGRATION,
				productId: PRODUCT_A,
				costType: ProductCostType.SINGLE,
				options: [singleOption({ startDate: '2026-12-01', endDate: '2026-11-01' })],
			}),
		).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })

		// Confirm nothing persisted.
		const found = await repo.findByStoreAndProduct(STORE, PRODUCT_A)
		expect(found).toBeUndefined()
	})
})

