import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { DeleteProductCost } from './DeleteProductCost'
import { CreateProductCost } from './CreateProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostDeletedEvent } from '../events'
import type { ProductCostOptionInput } from '../entities/ProductCost'

const STORE = testId('store', '1')
const STORE_INTEGRATION = testId('store-integration', '1')
const PRODUCT_A = testId('product', 'a')
const VARIANT_1 = testId('variant', '1')
const USER = testId('user', '1')

function singleOption(): ProductCostOptionInput {
	return {
		currency: CurrencyCode.USD,
		startDate: '2026-05-01',
		shipping: { amountCents: 0, currency: CurrencyCode.USD },
		items: [
			{
				variantIds: [VARIANT_1],
				quantity: 1,
				quantityModifier: QuantityModifier.EQ,
				unitCost: { amountCents: 500, currency: CurrencyCode.USD },
				shipping: { amountCents: 0, currency: CurrencyCode.USD },
			},
		],
	}
}

describe('DeleteProductCost (C29)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: DeleteProductCost
	let createUseCase: CreateProductCost
	let repo: ProductCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(DeleteProductCost)
		createUseCase = testBed.resolve(CreateProductCost)
		repo = testBed.resolve(ProductCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedProductCost(): Promise<string> {
		const { productCostId } = await createUseCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})
		return productCostId
	}

	async function readDeletedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ProductCostDeletedEvent)
	}

	it('soft-deletes the row + emits ProductCostDeletedEvent + frees the (storeId, productId) slot', async () => {
		const productCostId = await seedProductCost()

		await useCase.execute({ userId: USER, productCostId })

		// Row is preserved but isDeleted = true
		const after = await repo.findById(productCostId)
		expect(after?.isDeleted).toBe(true)
		expect(after?.deletedAt).not.toBeNull()

		const emitted = await readDeletedEvents()
		expect(emitted).toHaveLength(1)
		// The deleted cost's id lives on the canonical event.entityId; the payload
		// carries the entity snapshot (Id VOs serialized to their string .value).
		expect(emitted[0]!.entityId).toBe(productCostId)
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
		expect(emitted[0]!.payload.productCost.productId).toBe(PRODUCT_A)

		// (storeId, productId) slot is free — Create succeeds again afterwards.
		const reopen = await createUseCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})
		expect(reopen.productCostId).toMatch(/^[0-9a-f-]{36}$/)
		expect(reopen.productCostId).not.toBe(productCostId)
	})

	it('throws PRODUCT_COST_NOT_FOUND when the row is missing', async () => {
		await expect(
			useCase.execute({
				userId: USER,
				productCostId: testId(),
			}),
		).rejects.toMatchObject({ name: 'PRODUCT_COST_NOT_FOUND' })

		const emitted = await readDeletedEvents()
		expect(emitted).toHaveLength(0)
	})

	it('throws PRODUCT_COST_NOT_FOUND on a second delete (idempotency boundary)', async () => {
		const productCostId = await seedProductCost()
		await useCase.execute({ userId: USER, productCostId })

		await expect(useCase.execute({ userId: USER, productCostId })).rejects.toMatchObject({ name: 'PRODUCT_COST_NOT_FOUND' })

		// Only one event emitted across both calls.
		const emitted = await readDeletedEvents()
		expect(emitted).toHaveLength(1)
	})
})

