function build(opts: {
	storeId?: string
	storeIntegrationId?: string
	productId?: string | null
	displayName?: string
	startDate?: string
	currency?: CurrencyCode
}): ProductCost {
	return ProductCost.create({
		storeId: opts.storeId ?? STORE_A,
		storeIntegrationId: opts.storeIntegrationId ?? STORE_INTEGRATION_A,
		// Distinguish "not supplied" from "explicit null" — `??` would
		// fall back on both; the spec's kit-scoped path needs null
		// to survive the default.
		productId: 'productId' in opts ? (opts.productId ?? null) : PRODUCT_A,
		costType: ProductCostType.SINGLE,
		displayName: opts.displayName,
		options: [
			{
				currency: opts.currency ?? CurrencyCode.USD,
				startDate: opts.startDate ?? '2026-05-01',
				shipping: { amountCents: 1000, currency: opts.currency ?? CurrencyCode.USD },
				items: [
					{
						variantIds: [VARIANT_1],
						quantity: 1,
						quantityModifier: QuantityModifier.EQ,
						unitCost: { amountCents: 500, currency: opts.currency ?? CurrencyCode.USD },
						shipping: { amountCents: 100, currency: opts.currency ?? CurrencyCode.USD },
					},
				],
			},
		],
	})
}

describe('save + findById', () => {
	it('round-trips through Drizzle with options jsonb inline', async () => {
		const entity = build({ displayName: 'May cost' })
		await repo.save(entity)

		const fetched = await repo.findById(entity.id.value)
		expect(fetched?.storeId.value).toBe(STORE_A)
		expect(fetched?.storeIntegrationId.value).toBe(STORE_INTEGRATION_A)
		expect(fetched?.productId?.value).toBe(PRODUCT_A)
		expect(fetched?.costType).toBe(ProductCostType.SINGLE)
		expect(fetched?.displayName).toBe('May cost')
		expect(fetched?.options).toHaveLength(1)
		expect(fetched?.options[0]?.currency).toBe(CurrencyCode.USD)
		expect(fetched?.options[0]?.items).toHaveLength(1)
		expect(fetched?.options[0]?.items[0]?.unitCost.amountCents).toBe(500)
		expect(fetched?.deletedAt).toBeNull()
	})

	it('returns undefined when no row matches', async () => {
		const r = await repo.findById('ffffffff-0001-4000-8000-000000000000')
		expect(r).toBeUndefined()
	})

	it('UPSERT persists options replacement', async () => {
		const entity = build({ displayName: 'original' })
		await repo.save(entity)

		entity.update({
			displayName: 'updated',
			options: [
				{
					currency: CurrencyCode.USD,
					startDate: '2026-06-01',
					shipping: { amountCents: 2000, currency: CurrencyCode.USD },
					items: [
						{
							variantIds: [VARIANT_1],
							quantity: 2,
							quantityModifier: QuantityModifier.EQ,
							unitCost: { amountCents: 800, currency: CurrencyCode.USD },
							shipping: { amountCents: 200, currency: CurrencyCode.USD },
						},
					],
				},
			],
		})
		await repo.save(entity)

		const fetched = await repo.findById(entity.id.value)
		expect(fetched?.displayName).toBe('updated')
		// startDate is now a coerced Date (z.coerce.date() via z.historical)
		expect(fetched?.options[0]?.startDate).toBeInstanceOf(Date)
		expect((fetched?.options[0]?.startDate as Date).toISOString().startsWith('2026-06-01')).toBe(true)
		expect(fetched?.options[0]?.items[0]?.unitCost.amountCents).toBe(800)
		expect(fetched?.version).toBeGreaterThan(1)
	})

	it('round-trips kit-scoped cost (productId null)', async () => {
		const entity = build({ productId: null })
		await repo.save(entity)

		const fetched = await repo.findById(entity.id.value)
		expect(fetched?.productId).toBeNull()
	})
})

describe('findByStoreAndProduct', () => {
	it('returns undefined when no row matches', async () => {
		const r = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
		expect(r).toBeUndefined()
	})

	it('returns the matching row', async () => {
		const entity = build({})
		await repo.save(entity)

		const r = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
		expect(r?.id.value).toBe(entity.id.value)
	})

