import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductCost } from '../../entities/ProductCost'
import { ProductCostRepository } from './ProductCostRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')
const STORE_INTEGRATION_A = testId('store-integration', 'a')
const PRODUCT_A = testId('product', 'a')
const PRODUCT_B = testId('product', 'b')
const VARIANT_1 = testId('variant', '1')

describe('DrizzleProductCostRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: ProductCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(ProductCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: {
		storeId?: string
		storeIntegrationId?: string
		productId?: string | null
		displayName?: string
		startDate?: string
		currency?: CurrencyCode
	}): ProductCost {
		return ProductCost.create({
			storeId: opts.storeId ?? STORE_A,
			storeIntegrationId: opts.storeIntegrationId ?? STORE_INTEGRATION_A,
			// Distinguish "not supplied" from "explicit null" — `??` would
			// fall back on both; the spec's kit-scoped path needs null
			// to survive the default.
			productId: 'productId' in opts ? (opts.productId ?? null) : PRODUCT_A,
			costType: ProductCostType.SINGLE,
			displayName: opts.displayName,
			options: [
				{
					currency: opts.currency ?? CurrencyCode.USD,
					startDate: opts.startDate ?? '2026-05-01',
					shipping: { amountCents: 1000, currency: opts.currency ?? CurrencyCode.USD },
					items: [
						{
							variantIds: [VARIANT_1],
							quantity: 1,
							quantityModifier: QuantityModifier.EQ,
							unitCost: { amountCents: 500, currency: opts.currency ?? CurrencyCode.USD },
							shipping: { amountCents: 100, currency: opts.currency ?? CurrencyCode.USD },
						},
					],
				},
			],
		})
	}

	describe('save + findById', () => {
		it('round-trips through Drizzle with options jsonb inline', async () => {
			const entity = build({ displayName: 'May cost' })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.storeId.value).toBe(STORE_A)
			expect(fetched?.storeIntegrationId.value).toBe(STORE_INTEGRATION_A)
			expect(fetched?.productId?.value).toBe(PRODUCT_A)
			expect(fetched?.costType).toBe(ProductCostType.SINGLE)
			expect(fetched?.displayName).toBe('May cost')
			expect(fetched?.options).toHaveLength(1)
			expect(fetched?.options[0]?.currency).toBe(CurrencyCode.USD)
			expect(fetched?.options[0]?.items).toHaveLength(1)
			expect(fetched?.options[0]?.items[0]?.unitCost.amountCents).toBe(500)
			expect(fetched?.deletedAt).toBeNull()
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById('ffffffff-0001-4000-8000-000000000000')
			expect(r).toBeUndefined()
		})

		it('UPSERT persists options replacement', async () => {
			const entity = build({ displayName: 'original' })
			await repo.save(entity)

			entity.update({
				displayName: 'updated',
				options: [
					{
						currency: CurrencyCode.USD,
						startDate: '2026-06-01',
						shipping: { amountCents: 2000, currency: CurrencyCode.USD },
						items: [
							{
								variantIds: [VARIANT_1],
								quantity: 2,
								quantityModifier: QuantityModifier.EQ,
								unitCost: { amountCents: 800, currency: CurrencyCode.USD },
								shipping: { amountCents: 200, currency: CurrencyCode.USD },
							},
						],
					},
				],
			})
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.displayName).toBe('updated')
			// startDate is now a coerced Date (z.coerce.date() via z.historical)
			expect(fetched?.options[0]?.startDate).toBeInstanceOf(Date)
			expect((fetched?.options[0]?.startDate as Date).toISOString().startsWith('2026-06-01')).toBe(true)
			expect(fetched?.options[0]?.items[0]?.unitCost.amountCents).toBe(800)
			expect(fetched?.version).toBeGreaterThan(1)
		})

		it('round-trips kit-scoped cost (productId null)', async () => {
			const entity = build({ productId: null })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.productId).toBeNull()
		})
	})

	describe('findByStoreAndProduct', () => {
		it('returns undefined when no row matches', async () => {
			const r = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
			expect(r).toBeUndefined()
		})

		it('returns the matching row', async () => {
			const entity = build({})
			await repo.save(entity)

			const r = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
			expect(r?.id.value).toBe(entity.id.value)
		})

		it('filters by storeId (cross-store leak protection)', async () => {
			await repo.save(build({ storeId: STORE_A, productId: PRODUCT_A }))
			await repo.save(build({ storeId: STORE_B, productId: PRODUCT_A }))

			const a = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
			const b = await repo.findByStoreAndProduct(STORE_B, PRODUCT_A)
			expect(a?.storeId.value).toBe(STORE_A)
			expect(b?.storeId.value).toBe(STORE_B)
		})

		it('handles kit-scoped productId=null lookup separately', async () => {
			await repo.save(build({ productId: null }))
			await repo.save(build({ productId: PRODUCT_B }))

			const kit = await repo.findByStoreAndProduct(STORE_A, null)
			const direct = await repo.findByStoreAndProduct(STORE_A, PRODUCT_B)
			expect(kit?.productId).toBeNull()
			expect(direct?.productId?.value).toBe(PRODUCT_B)
		})

		it('excludes soft-deleted rows', async () => {
			const entity = build({})
			entity.delete()
			await repo.save(entity)

			const r = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
			expect(r).toBeUndefined()
		})
	})

	describe('findByStoreAndProducts', () => {
		it('returns the matching aggregates for multiple productIds in one call', async () => {
			const a = build({ productId: PRODUCT_A })
			const b = build({ productId: PRODUCT_B })
			await repo.save(a)
			await repo.save(b)

			const results = await repo.findByStoreAndProducts(STORE_A, [PRODUCT_A, PRODUCT_B])
			const ids = results.map(r => r.id.value).sort()
			expect(ids).toEqual([a.id.value, b.id.value].sort())
		})

		it('includes the kit-scoped (null productId) row when null is in the list', async () => {
			const kit = build({ productId: null })
			const direct = build({ productId: PRODUCT_A })
			await repo.save(kit)
			await repo.save(direct)

			const results = await repo.findByStoreAndProducts(STORE_A, [null, PRODUCT_A])
			expect(results).toHaveLength(2)
			const hasKit = results.some(r => r.productId === null)
			const hasDirect = results.some(r => r.productId?.value === PRODUCT_A)
			expect(hasKit).toBe(true)
			expect(hasDirect).toBe(true)
		})

		it('excludes soft-deleted and other-store rows', async () => {
			const live = build({ storeId: STORE_A, productId: PRODUCT_A })
			await repo.save(live)

