			const direct = await repo.findByStoreAndProduct(STORE_A, PRODUCT_B)
			expect(kit?.productId).toBeNull()
			expect(direct?.productId?.value).toBe(PRODUCT_B)
		})

		it('excludes soft-deleted rows', async () => {
			const entity = build({})
			entity.delete()
			await repo.save(entity)

			const r = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
			expect(r).toBeUndefined()
		})
	})

	describe('findByStoreAndProducts', () => {
		it('returns the matching aggregates for multiple productIds in one call', async () => {
			const a = build({ productId: PRODUCT_A })
			const b = build({ productId: PRODUCT_B })
			await repo.save(a)
			await repo.save(b)

			const results = await repo.findByStoreAndProducts(STORE_A, [PRODUCT_A, PRODUCT_B])
			const ids = results.map(r => r.id.value).sort()
			expect(ids).toEqual([a.id.value, b.id.value].sort())
		})

		it('includes the kit-scoped (null productId) row when null is in the list', async () => {
			const kit = build({ productId: null })
			const direct = build({ productId: PRODUCT_A })
			await repo.save(kit)
			await repo.save(direct)

			const results = await repo.findByStoreAndProducts(STORE_A, [null, PRODUCT_A])
			expect(results).toHaveLength(2)
			const hasKit = results.some(r => r.productId === null)
			const hasDirect = results.some(r => r.productId?.value === PRODUCT_A)
			expect(hasKit).toBe(true)
			expect(hasDirect).toBe(true)
		})

		it('excludes soft-deleted and other-store rows', async () => {
			const live = build({ storeId: STORE_A, productId: PRODUCT_A })
			await repo.save(live)

			const deleted = build({ storeId: STORE_A, productId: PRODUCT_B })
			deleted.delete()
			await repo.save(deleted)

			const otherStore = build({ storeId: STORE_B, productId: PRODUCT_A })
			await repo.save(otherStore)

			const results = await repo.findByStoreAndProducts(STORE_A, [PRODUCT_A, PRODUCT_B])
			expect(results).toHaveLength(1)
			expect(results[0]?.id.value).toBe(live.id.value)
		})

		it('returns an empty array when productIds is empty', async () => {
			await repo.save(build({ productId: PRODUCT_A }))

			const results = await repo.findByStoreAndProducts(STORE_A, [])
			expect(results).toEqual([])
		})
	})

	describe('partial unique index on (storeId, productId) WHERE deletedAt IS NULL', () => {
		it('soft-delete frees the slot — re-create for the same (storeId, productId) succeeds', async () => {
			const original = build({})
			await repo.save(original)

			original.delete()
			await repo.save(original)

			// Re-create for the same (storeId, productId) — partial unique
			// allows it because the original is now soft-deleted.
			const reopen = build({})
			await repo.save(reopen)

			// Both rows coexist (one deleted, one live).
			const live = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
			expect(live?.id.value).toBe(reopen.id.value)
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
			const entity = build({})
			await repo.save(entity)
			await repo.delete(entity.id.value)
			expect(await repo.findById(entity.id.value)).toBeUndefined()
		})
	})

	describe('saveMany', () => {
		it('saveMany inserts new rows and upserts existing ones in one batch', async () => {
			// Seed one existing aggregate.
			const existing = build({ productId: PRODUCT_A, displayName: 'before' })
			await repo.save(existing)
			const versionBefore = existing.version

			// Mutate the existing one + create a brand-new one.
			existing.update({ displayName: 'after' })
			const fresh = build({ productId: PRODUCT_B })

			const saved = await repo.saveMany([existing, fresh])
			expect(saved).toHaveLength(2)

			const a = await repo.findByStoreAndProduct(STORE_A, PRODUCT_A)
			const b = await repo.findByStoreAndProduct(STORE_A, PRODUCT_B)
			expect(a?.displayName).toBe('after')
			expect(a?.version).toBe(versionBefore + 1) // incremented by saveMany
			expect(b).not.toBeUndefined()
			expect(b?.productId?.value).toBe(PRODUCT_B)
		})

		it('saveMany with an empty array is a no-op', async () => {
			const saved = await repo.saveMany([])
			expect(saved).toEqual([])
		})
	})
})

