import { describe, expect, it } from 'bun:test'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductCostSolver } from './ProductCostSolver'
import type { ApplicableProductCost } from '@catalog/services/ProductCostQueryService'

const PRODUCT_A = 'prod-a'
const VARIANT_A1 = 'var-a1'
const VARIANT_A2 = 'var-a2'
const PRODUCT_B = 'prod-b'
const VARIANT_B1 = 'var-b1'

function singleCost(opts: {
	costId: string
	costOptionId: string
	productId: string
	cost: number
	currency?: CurrencyCode
	quantity?: number
	quantityModifier?: QuantityModifier
	variants?: string[]
	shipping?: number
}): ApplicableProductCost {
	return {
		costId: opts.costId,
		costOptionId: opts.costOptionId,
		type: ProductCostType.SINGLE,
		startDate: new Date('2026-01-01'),
		endDate: null,
		data: [
			{
				cost: opts.cost,
				costOptionItemId: `${opts.costOptionId}-item`,
				currency: opts.currency ?? CurrencyCode.USD,
				productId: opts.productId,
				quantity: opts.quantity ?? 1,
				quantityModifier: opts.quantityModifier ?? QuantityModifier.GTE,
				shipping: opts.shipping ?? 0,
				variants: opts.variants,
			},
		],
	}
}

// ── Kit helper ────────────────────────────────────────────────────────────────
function kit(cost: number, members: Array<{ product: string; variant: string; quantity: number }>): ApplicableProductCost {
	return {
		costId: 'kit',
		costOptionId: 'kit-o',
		type: ProductCostType.MULTIPLE,
		startDate: new Date('2026-01-01'),
		endDate: null,
		cost,
		shipping: 0,
		data: members.map((m, i) => ({
			cost: i === 0 ? cost : 0,
			costOptionItemId: `ki-${i}`,
			currency: CurrencyCode.USD,
			productId: m.product,
			quantity: m.quantity,
			quantityModifier: QuantityModifier.EQ,
			variants: [m.variant],
		})),
	}
}

describe('ProductCostSolver (ported from bk-dash)', () => {
	it('single generic cost matches every unit of the product', () => {
		const solver = new ProductCostSolver({
			costs: [singleCost({ costId: 'c1', costOptionId: 'o1', productId: PRODUCT_A, cost: 500 })],
			variantProducts: new Map([[VARIANT_A1, PRODUCT_A]]),
			variants: new Map([[VARIANT_A1, 3]]),
		})
		const result = solver.solve()
		expect(result).toHaveLength(1)
		expect(result[0]!.costId).toBe('c1')
		// GTE 1 with 3 units → applied 3 times at 500 each.
		expect(result[0]!.cost.amountCents).toBe(1500)
		expect(result[0]!.cost.currency).toBe('USD')
		expect(result[0]!.products).toContain(PRODUCT_A)
	})

	it('returns empty when no cost applies to the order products', () => {
		const solver = new ProductCostSolver({
			costs: [singleCost({ costId: 'c1', costOptionId: 'o1', productId: PRODUCT_B, cost: 500 })],
			variantProducts: new Map([[VARIANT_A1, PRODUCT_A]]),
			variants: new Map([[VARIANT_A1, 2]]),
		})
		expect(solver.solve()).toHaveLength(0)
	})

	it('variant-specific cost preferred over generic for the same product', () => {
		const generic = singleCost({ costId: 'c-gen', costOptionId: 'o-gen', productId: PRODUCT_A, cost: 900 })
		const specific = singleCost({
			costId: 'c-spec',
			costOptionId: 'o-spec',
			productId: PRODUCT_A,
			cost: 100,
			variants: [VARIANT_A1],
		})
		const solver = new ProductCostSolver({
			costs: [generic, specific],
			variantProducts: new Map([
				[VARIANT_A1, PRODUCT_A],
				[VARIANT_A2, PRODUCT_A],
			]),
			variants: new Map([
				[VARIANT_A1, 1],
				[VARIANT_A2, 1],
			]),
		})
		const result = solver.solve()
		// The specific variant cost must appear in the chosen combo.
		const costIds = result.map(r => r.costId)
		expect(costIds).toContain('c-spec')
	})

	it('MULTIPLE (kit) cost requires all member products present', () => {
		const kit: ApplicableProductCost = {
			costId: 'kit-1',
			costOptionId: 'kit-opt-1',
			type: ProductCostType.MULTIPLE,
			startDate: new Date('2026-01-01'),
			endDate: null,
			cost: 1200,
			shipping: 0,
			data: [
				{
					cost: 1200,
					costOptionItemId: 'kit-item',
					currency: CurrencyCode.USD,
					productId: PRODUCT_A,
					quantity: 1,
					quantityModifier: QuantityModifier.EQ,
					variants: [VARIANT_A1],
				},
				{
					cost: 0,
					costOptionItemId: 'kit-item-2',
					currency: CurrencyCode.USD,
					productId: PRODUCT_B,
					quantity: 1,
					quantityModifier: QuantityModifier.EQ,
					variants: [VARIANT_B1],
				},
			],
		}
		const solver = new ProductCostSolver({
			costs: [kit],
			variantProducts: new Map([
				[VARIANT_A1, PRODUCT_A],
				[VARIANT_B1, PRODUCT_B],
			]),
			variants: new Map([
				[VARIANT_A1, 1],
				[VARIANT_B1, 1],
			]),
		})
		const result = solver.solve()
		expect(result).toHaveLength(1)
		expect(result[0]!.costId).toBe('kit-1')
		expect(result[0]!.cost.amountCents).toBe(1200)
		expect(result[0]!.cost.currency).toBe('USD')
	})

	it('kit does NOT match when a required member product is absent', () => {
		const kit: ApplicableProductCost = {
			costId: 'kit-1',
			costOptionId: 'kit-opt-1',
			type: ProductCostType.MULTIPLE,
			startDate: new Date('2026-01-01'),
			endDate: null,
			cost: 1200,
			shipping: 0,
			data: [
				{
					cost: 1200,
					costOptionItemId: 'i1',
					currency: CurrencyCode.USD,
					productId: PRODUCT_A,
					quantity: 1,
					quantityModifier: QuantityModifier.EQ,
					variants: [VARIANT_A1],
				},
				{
					cost: 0,
					costOptionItemId: 'i2',
					currency: CurrencyCode.USD,
					productId: PRODUCT_B,
					quantity: 1,
					quantityModifier: QuantityModifier.EQ,
					variants: [VARIANT_B1],
				},
			],
		}
		const solver = new ProductCostSolver({
			costs: [kit],
			variantProducts: new Map([[VARIANT_A1, PRODUCT_A]]),
			variants: new Map([[VARIANT_A1, 1]]),
		})
		// PRODUCT_B missing → kit ineligible → no combo covers anything.
		expect(solver.solve()).toHaveLength(0)
	})

	// ── Quantity modifiers ──────────────────────────────────────────────
	it('EQ tier: under-tier → no cost, exact → 1×, multiple → N×', () => {
		const make = (qty: number) =>
			new ProductCostSolver({
				costs: [
					singleCost({
						costId: 'c',
						costOptionId: 'o',
						productId: PRODUCT_A,
						cost: 900,
						quantity: 3,
						quantityModifier: QuantityModifier.EQ,
					}),
				],
				variantProducts: new Map([[VARIANT_A1, PRODUCT_A]]),
				variants: new Map([[VARIANT_A1, qty]]),
			}).solve()

		// qty=2: expandItem bails (start=3 > max=2) → no option → empty
		expect(make(2)).toHaveLength(0)
		// qty=3: one EQ-3 application covering 3 units → cost = 900 × 3 (per-unit) = 2700
		expect(make(3)[0]!.cost.amountCents).toBe(2700)
		// qty=6: two EQ-3 applications covering 6 units → cost = 900 × 6 = 5400
		expect(make(6)[0]!.cost.amountCents).toBe(5400)
	})

	it('GT tier: equal does not apply, strictly greater applies', () => {
		const make = (qty: number) =>
			new ProductCostSolver({
				costs: [
					singleCost({
						costId: 'c',
						costOptionId: 'o',
						productId: PRODUCT_A,
						cost: 700,
						quantity: 2,
						quantityModifier: QuantityModifier.GT,
					}),
				],
				variantProducts: new Map([[VARIANT_A1, PRODUCT_A]]),
				variants: new Map([[VARIANT_A1, qty]]),
			}).solve()

		// qty=2: expandItem start=3 > max=2 → no option → empty
		expect(make(2)).toHaveLength(0)
		// qty=3: option at qty=3, available=3 → applies
		expect(make(3).some(r => r.costId === 'c')).toBe(true)
	})

	it('LT tier: qty strictly below threshold applies', () => {
		const lt = new ProductCostSolver({
			costs: [
				singleCost({
					costId: 'lt',
					costOptionId: 'o',
					productId: PRODUCT_A,
					cost: 400,
					quantity: 3,
					quantityModifier: QuantityModifier.LT,
				}),
			],
			variantProducts: new Map([[VARIANT_A1, PRODUCT_A]]),
			variants: new Map([[VARIANT_A1, 2]]),
		}).solve()

		// qty=2 < 3 → LT range [1, 2] expanded; option at qty=2 matches
		expect(lt.some(r => r.costId === 'lt')).toBe(true)
	})

	// ── Kits (MULTIPLE) ─────────────────────────────────────────────────
	it('kit limiting-ingredient: 2A+1B required, 10A+1B available → 1 kit', () => {
		const result = new ProductCostSolver({
			costs: [
				kit(1200, [
					{ product: PRODUCT_A, variant: VARIANT_A1, quantity: 2 },
					{ product: PRODUCT_B, variant: VARIANT_B1, quantity: 1 },
				]),
			],
			variantProducts: new Map([
				[VARIANT_A1, PRODUCT_A],
				[VARIANT_B1, PRODUCT_B],
			]),
			variants: new Map([
				[VARIANT_A1, 10],
				[VARIANT_B1, 1],
			]),
		}).solve()

		// limiting ingredient: floor(10/2)=5, floor(1/1)=1 → min=1 → cost × 1 = 1200
		expect(result[0]!.cost.amountCents).toBe(1200)
	})

	it('kit multi-application: 1A+1B required, 3A+3B available → 3 kits', () => {
		const result = new ProductCostSolver({
			costs: [
				kit(1000, [
					{ product: PRODUCT_A, variant: VARIANT_A1, quantity: 1 },
					{ product: PRODUCT_B, variant: VARIANT_B1, quantity: 1 },
				]),
			],
			variantProducts: new Map([
				[VARIANT_A1, PRODUCT_A],
				[VARIANT_B1, PRODUCT_B],
			]),
			variants: new Map([
				[VARIANT_A1, 3],
				[VARIANT_B1, 3],
			]),
		}).solve()

		// floor(3/1)=3 kits → cost multiplier = times = 3 → 1000 × 3 = 3000
		expect(result[0]!.cost.amountCents).toBe(3000)
	})

	// ── Precedence / non-interference ───────────────────────────────────
	it('variant-specific beats generic; generic only covers the remaining variant', () => {
		const result = new ProductCostSolver({
			costs: [
				singleCost({ costId: 'gen', costOptionId: 'og', productId: PRODUCT_A, cost: 900 }),
				singleCost({ costId: 'spec', costOptionId: 'os', productId: PRODUCT_A, cost: 100, variants: [VARIANT_A1] }),
			],
			variantProducts: new Map([
				[VARIANT_A1, PRODUCT_A],
				[VARIANT_A2, PRODUCT_A],
			]),
			variants: new Map([
				[VARIANT_A1, 1],
				[VARIANT_A2, 1],
			]),
		}).solve()

		const ids = result.map(r => r.costId)
		// The variant-specific cost must be chosen
		expect(ids).toContain('spec')
		// Total units covered across all combo entries = 2 (no double-counting)
		const totalUnits = result.reduce((n, r) => n + Object.values(r.productQuantity).reduce((a, b) => a + b, 0), 0)
		expect(totalUnits).toBe(2)
	})

	it('two independent products: each cost applies only to its own product', () => {
		const result = new ProductCostSolver({
			costs: [
				singleCost({ costId: 'ca', costOptionId: 'oa', productId: PRODUCT_A, cost: 300 }),
				singleCost({ costId: 'cb', costOptionId: 'ob', productId: PRODUCT_B, cost: 700 }),
			],
			variantProducts: new Map([
				[VARIANT_A1, PRODUCT_A],
				[VARIANT_B1, PRODUCT_B],
			]),
			variants: new Map([
				[VARIANT_A1, 1],
				[VARIANT_B1, 1],
			]),
		}).solve()

		const byProduct = new Map(result.map(r => [r.costId, r.products]))
		expect(byProduct.get('ca')).toEqual([PRODUCT_A])
		expect(byProduct.get('cb')).toEqual([PRODUCT_B])
	})

	// ── Partial coverage ────────────────────────────────────────────────
	it('partial coverage: when no combo fully covers, the best partial (≥1 unit) is returned', () => {
		const result = new ProductCostSolver({
			costs: [
				singleCost({
					costId: 'c',
					costOptionId: 'o',
					productId: PRODUCT_A,
					cost: 500,
					quantity: 5,
					quantityModifier: QuantityModifier.EQ,
				}),
			],
			variantProducts: new Map([
				[VARIANT_A1, PRODUCT_A],
				[VARIANT_B1, PRODUCT_B],
			]),
			variants: new Map([
				[VARIANT_A1, 5],
				[VARIANT_B1, 1],
			]),
		}).solve()

		// PRODUCT_A covered by EQ-5; PRODUCT_B has no cost → partial combo accepted
		expect(result.some(r => r.costId === 'c')).toBe(true)
	})
})

