// Shopify describe constants
const PRODUCT_SHIRT = 'cccccccc-0002-4000-8000-000000000001'
const VARIANT_BM = 'dddddddd-0002-4000-8000-000000000001'
const VARIANT_BL = 'dddddddd-0002-4000-8000-000000000002'

const HEADER = [
	'productId',
