import { AggregateRoot, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { Role as TenancyRole } from '@bk-dash/contracts-typescript/wire/enums'

const StoreMembershipSchema = z.object({
	storeId: z.instance(Id),
	userId: z.instance(Id),
	role: z.enum(TenancyRole),
	lastAccess: z.date().optional(),
})

export type StoreMembershipProps = Z.infer<typeof StoreMembershipSchema>

export class StoreMembership extends AggregateRoot<typeof StoreMembershipSchema> {
	static override schema = StoreMembershipSchema

	static forOwner(data: { storeId: string; userId: string }): StoreMembership {
		return new StoreMembership({
			storeId: data.storeId,
			userId: data.userId,
			role: TenancyRole.OWNER,
			lastAccess: new Date(),
		})
	}

	static forInvitee(data: { storeId: string; userId: string; role: TenancyRole }): StoreMembership {
		return new StoreMembership({
			storeId: data.storeId,
			userId: data.userId,
			role: data.role,
		})
	}

	// Pure setter — the CANNOT_DEMOTE_LAST_OWNER guard lives in the use case
	// where `countOwnersByStoreId` is available (entity has no global state).
	changeRole(newRole: TenancyRole): void {
		this.role = newRole
		this.validate()
	}

	touchAccess(at: Date = new Date()): void {
		this.lastAccess = at
		this.validate()
	}
}

