import { describe, it, expect, mock } from 'bun:test'
import { RequireStoreMember } from './RequireStoreMember'
import type { StoreMembershipRepository } from '@tenancy/repositories/StoreMembershipRepository'
import type { HttpControllerRequest } from '@bk-dash/core-typescript'
import { testId } from '@test/support'

/**
 * Minimal membership double. Returns plain objects shaped like the slice of
 * `StoreMembership` the middleware touches (`id`, `userId`, `role`, `storeId`).
 * `findByStoreAndUser` is the membership assertion; `findByUserId` feeds the
 * stamped `storeIds` list.
 */
function makeRepo(hit: boolean): StoreMembershipRepository {
	const active = { id: 'membership-1', storeId: 'store-1', userId: 'user-1', role: 'OWNER' as const }
	return {
		findByStoreAndUser: mock(async (_storeId: string, _userId: string) => (hit ? active : undefined)),
		findByUserId: mock(async (_userId: string) => (hit ? [active, { ...active, storeId: 'store-2' }] : [])),
	} as unknown as StoreMembershipRepository
}

const VALID_USER_ID = testId('user', '1')
const VALID_EXPIRES_AT = new Date('2099-01-01T00:00:00.000Z')

/** Full SessionSchema-compliant ctx with a specific storeId (or null). */
function makeCtx(storeId: string | null) {
	return {
		user: { id: 'user-1', email: 'a@b.com', name: 'Alice', emailVerified: true },
		session: { id: 's-1', userId: VALID_USER_ID, expiresAt: VALID_EXPIRES_AT, storeId },
	}
}

function makeRequest(ctx: unknown, params: unknown = {}, body: unknown = {}): HttpControllerRequest<unknown> {
	return { ctx, params, body, raw: {} } as unknown as HttpControllerRequest<unknown>
}

describe('RequireStoreMember', () => {
	it('throws STORE_MEMBERSHIP_NOT_FOUND when ctx has no user', async () => {
		const mw = new RequireStoreMember(makeRepo(true))
		const req = makeRequest(
			{
				/* no user */
			},
			{ storeId: 'store-1' },
		)
		await expect(mw.execute(req)).rejects.toMatchObject({ name: 'STORE_MEMBERSHIP_NOT_FOUND' })
	})

	it('throws STORE_MEMBERSHIP_NOT_FOUND when ctx.user.id is missing', async () => {
		const mw = new RequireStoreMember(makeRepo(true))
		const req = makeRequest(
			{
				user: {
					/* no id */
				},
			},
			{ storeId: 'store-1' },
		)
		await expect(mw.execute(req)).rejects.toMatchObject({ name: 'STORE_MEMBERSHIP_NOT_FOUND' })
	})

	it('throws STORE_MEMBERSHIP_NOT_FOUND when ctx.session.storeId is null', async () => {
		const mw = new RequireStoreMember(makeRepo(true))
		const req = makeRequest(makeCtx(null), {}, {})
		await expect(mw.execute(req)).rejects.toMatchObject({ name: 'STORE_MEMBERSHIP_NOT_FOUND' })
	})

	it('throws STORE_MEMBERSHIP_NOT_FOUND when membership not found', async () => {
		const mw = new RequireStoreMember(makeRepo(false))
		const req = makeRequest(makeCtx('store-1'), {})
		await expect(mw.execute(req)).rejects.toMatchObject({ name: 'STORE_MEMBERSHIP_NOT_FOUND' })
	})

	it('stamps membership { id, userId, role, storeIds } when storeId is a valid member', async () => {
		const mw = new RequireStoreMember(makeRepo(true))
		const req = makeRequest(makeCtx('store-1'), {})
		await mw.execute(req)
		const membership = (req.ctx as any).membership
		expect(membership).toMatchObject({ id: 'membership-1', userId: 'user-1', role: 'OWNER' })
		expect(membership.storeIds).toEqual(['store-1', 'store-2'])
		// No longer stamps a single storeId — controllers read ctx.session.storeId.
		expect(membership.storeId).toBeUndefined()
	})
})

