@injectable()
export class ChangeMemberRoleController extends Controller<
	typeof ChangeMemberRoleControllerInputSchema,
	typeof ChangeMemberRoleControllerOutputSchema
> {
	readonly path = '/stores/:storeId/memberships/:userId/role'
	readonly method = 'patch' as const
	readonly description = "Change a store member's role (C18 ChangeMemberRole; LAST_OWNER guarded)"
	readonly inputSchema = ChangeMemberRoleControllerInputSchema
	readonly outputSchema = ChangeMemberRoleControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER])]

	constructor(private changeMemberRole: ChangeMemberRole) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.changeMemberRole.execute({
			storeId: request.params.storeId,
			userId: request.params.userId,
			newRole: request.newRole,
		})
		// `changed=false` (same-role no-op) and `changed=true` both return the
		// data shape; HTTP status stays 200 — the use case returns the boolean
		// the SDK consumer can branch on. Leaving 204 for explicit no-data
		// endpoints (Disable/Enable/Update*) keeps the contract surface clean.
		return { status: HttpStatusCode.OK, data }
	}
}

