const MOCK_HANDSHAKE_META = new MockHandshakeService({ type: StoreIntegrationType.MARKETING_PLATFORM, platform: MarketingPlatform.META })
const MOCK_HANDSHAKE_GOOGLE = new MockHandshakeService({
	type: StoreIntegrationType.MARKETING_PLATFORM,
	platform: MarketingPlatform.GOOGLE_ADS,
})
const MOCK_HANDSHAKE_TIKTOK = new MockHandshakeService({
	type: StoreIntegrationType.MARKETING_PLATFORM,
	platform: MarketingPlatform.TIKTOK,
})
const MOCK_OAUTH_SHOPIFY = new MockOAuthCodeExchanger({ type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY })
const MOCK_OAUTH_NUVEMSHOP = new MockOAuthCodeExchanger({ type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.NUVEM_SHOP })
const MOCK_OAUTH_META = new MockOAuthCodeExchanger({ type: StoreIntegrationType.MARKETING_PLATFORM, platform: MarketingPlatform.META })
const MOCK_OAUTH_GOOGLE = new MockOAuthCodeExchanger({
	type: StoreIntegrationType.MARKETING_PLATFORM,
	platform: MarketingPlatform.GOOGLE_ADS,
})
const MOCK_OAUTH_TIKTOK = new MockOAuthCodeExchanger({ type: StoreIntegrationType.MARKETING_PLATFORM, platform: MarketingPlatform.TIKTOK })

// Connect-service bindings shared by mock + integration modes: the factories
// inject the concrete provider tokens, which resolve to mocks here. (No
// CredentialsExchanger concrete impls yet — all credential platforms are
// description-only, so CredentialsExchangerFactory resolves with no params.)
const MOCK_CONNECT_SERVICES: InstanceRegistry['mock'] = [
	{ token: ShopifyHandshaker, instance: MOCK_SHOPIFY_HANDSHAKE },
	{ token: NuvemShopHandshaker, instance: MOCK_HANDSHAKE_NUVEMSHOP },
	{ token: MetaHandshaker, instance: MOCK_HANDSHAKE_META },
	{ token: GoogleAdsHandshaker, instance: MOCK_HANDSHAKE_GOOGLE },
	{ token: TiktokHandshaker, instance: MOCK_HANDSHAKE_TIKTOK },
	{ token: ShopifyOAuthCodeExchanger, instance: MOCK_OAUTH_SHOPIFY },
	{ token: NuvemShopOAuthCodeExchanger, instance: MOCK_OAUTH_NUVEMSHOP },
	{ token: MetaOAuthCodeExchanger, instance: MOCK_OAUTH_META },
	{ token: GoogleAdsOAuthCodeExchanger, instance: MOCK_OAUTH_GOOGLE },
	{ token: TiktokOAuthCodeExchanger, instance: MOCK_OAUTH_TIKTOK },
	{ token: HandshakeServiceFactory, instance: HandshakeServiceFactory },
	{ token: OAuthCodeExchangerFactory, instance: OAuthCodeExchangerFactory },
	{ token: CredentialsExchangerFactory, instance: CredentialsExchangerFactory },
	{ token: ShopifyAuthorizeUrlBuilder, instance: MOCK_AUTHORIZE_SHOPIFY },
	{ token: NuvemShopAuthorizeUrlBuilder, instance: MOCK_AUTHORIZE_NUVEMSHOP },
	{ token: MetaAuthorizeUrlBuilder, instance: MOCK_AUTHORIZE_META },
	{ token: GoogleAdsAuthorizeUrlBuilder, instance: MOCK_AUTHORIZE_GOOGLE },
	{ token: TiktokAuthorizeUrlBuilder, instance: MOCK_AUTHORIZE_TIKTOK },
	{ token: AuthorizeUrlBuilderFactory, instance: AuthorizeUrlBuilderFactory },
	{ token: OAuthStateTokenService, instance: OAuthStateTokenService },
	{ token: ShopifyAdditionalPlatformHandler, instance: MOCK_ADDITIONAL_SHOPIFY },
	{ token: NuvemShopAdditionalPlatformHandler, instance: MOCK_ADDITIONAL_NUVEMSHOP },
	{ token: AdditionalPlatformHandlerFactory, instance: AdditionalPlatformHandlerFactory },
]

export const INSTANCE_REGISTRY: InstanceRegistry = {
	mock: [
		{ token: StoreIntegrationRepository, instance: MockStoreIntegrationRepository },
		{ token: IntegrationCredentialSecretRepository, instance: MockIntegrationCredentialSecretRepository },
		{ token: CredentialVault, instance: MockCredentialVault },
		{ token: CredentialHandleStore, instance: MockCredentialHandleStore },
		...MOCK_CONNECT_SERVICES,
	],
	integration: [
		// Mocks for the network-touching connect services keep tests hermetic;
		// production wiring (real fetch + app credentials) lives under `real`.
		{ token: StoreIntegrationRepository, instance: DrizzleStoreIntegrationRepository },
		{ token: IntegrationCredentialSecretRepository, instance: DrizzleIntegrationCredentialSecretRepository },
		{ token: CredentialVault, instance: MockCredentialVault },
		{ token: CredentialHandleStore, instance: MockCredentialHandleStore },
		...MOCK_CONNECT_SERVICES,
	],
	real: [
		{ token: StoreIntegrationRepository, instance: DrizzleStoreIntegrationRepository },
		{ token: IntegrationCredentialSecretRepository, instance: DrizzleIntegrationCredentialSecretRepository },
		{ token: CredentialVault, useFactory: () => realCredentialVaultFactory() },
		{ token: CredentialHandleStore, instance: RedisCredentialHandleStore },
		{ token: ShopifyHandshaker, useFactory: () => new ShopifyHandshaker() },
		{ token: ShopifyOAuthCodeExchanger, useFactory: realShopifyOAuth },
		{ token: NuvemShopOAuthCodeExchanger, useFactory: realNuvemShopOAuth },
		{ token: MetaOAuthCodeExchanger, useFactory: realMetaOAuth },
		{ token: GoogleAdsOAuthCodeExchanger, useFactory: realGoogleAdsOAuth },
		{ token: TiktokOAuthCodeExchanger, useFactory: realTiktokOAuth },
		{ token: HandshakeServiceFactory, instance: HandshakeServiceFactory },
		{ token: OAuthCodeExchangerFactory, instance: OAuthCodeExchangerFactory },
		{ token: CredentialsExchangerFactory, instance: CredentialsExchangerFactory },
		{ token: ShopifyAuthorizeUrlBuilder, useFactory: () => new ShopifyAuthorizeUrlBuilder() },
		{ token: MetaAuthorizeUrlBuilder, useFactory: () => new MetaAuthorizeUrlBuilder() },
		{ token: GoogleAdsAuthorizeUrlBuilder, useFactory: () => new GoogleAdsAuthorizeUrlBuilder() },
		{ token: NuvemShopAuthorizeUrlBuilder, useFactory: () => new NuvemShopAuthorizeUrlBuilder() },
		{ token: TiktokAuthorizeUrlBuilder, useFactory: () => new TiktokAuthorizeUrlBuilder() },
		{ token: AuthorizeUrlBuilderFactory, instance: AuthorizeUrlBuilderFactory },
		{ token: OAuthStateTokenService, instance: OAuthStateTokenService },
		{
			token: ShopifyAdditionalPlatformHandler,
			useFactory: c =>
				new ShopifyAdditionalPlatformHandler(new ShopifyWebhookRegister(), c.resolve(StoreRepository as any) as StoreRepository),
		},
		{ token: NuvemShopAdditionalPlatformHandler, useFactory: () => new NuvemShopAdditionalPlatformHandler() },
		{ token: AdditionalPlatformHandlerFactory, instance: AdditionalPlatformHandlerFactory },
	],
}

