import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { CurrencyCode, NotificationCurrencyMode } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { UpdateUserPreferences } from '../usecases/UpdateUserPreferences'

// Spec §7.1 C11 (line 2217-2237) uses `notificationCurrency`; the entity +
// internal use case use `customCurrency`. Translate at this SDK boundary.
export const UpdateUserPreferencesControllerInputSchema = z
	.object({
		ctx: z.object({
			user: z.object({ id: z.string() }),
		}),
		timezone: z.string().nullable().optional(),
		dailyNotificationsEnabled: z.boolean().optional(),
		notificationCurrency: z.enum(CurrencyCode).nullable().optional(),
		notificationCurrencyMode: z.enum(NotificationCurrencyMode).optional(),
	})
	.example([
		{
			ctx: { user: { id: 'user-123' } },
			timezone: 'America/Sao_Paulo',
			dailyNotificationsEnabled: true,
			notificationCurrency: CurrencyCode.BRL,
			notificationCurrencyMode: NotificationCurrencyMode.CUSTOM_CURRENCY,
		},
	])

export const UpdateUserPreferencesControllerOutputSchema = z.void()

@injectable()
export class UpdateUserPreferencesController extends Controller<
	typeof UpdateUserPreferencesControllerInputSchema,
	typeof UpdateUserPreferencesControllerOutputSchema
> {
	readonly path = '/me/preferences'
	readonly method = 'patch' as const
	readonly description = 'Update current user preferences (timezone, notification mode/currency, daily digest toggle)'
	readonly inputSchema = UpdateUserPreferencesControllerInputSchema
	readonly outputSchema = UpdateUserPreferencesControllerOutputSchema

	// AuthAccountMiddleware injects ctx.user.id
	override middlewares = [AuthAccountMiddleware]

	constructor(private updateUserPreferences: UpdateUserPreferences) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.updateUserPreferences.execute({
			userId: request.ctx.user.id,
			timezone: request.timezone,
			dailyNotificationsEnabled: request.dailyNotificationsEnabled,
			// Spec → entity field rename.
			customCurrency: request.notificationCurrency,
			notificationCurrencyMode: request.notificationCurrencyMode,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

