import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { Goal } from '../entities/Goal'
import { GoalRepository } from '../repositories/GoalRepository'
import { GoalCreatedEvent } from '../events'
import type { AnalyticsApplicationErrors } from '../errors'

export const DuplicateLastGoalInputSchema = z.object({
	storeId: z.uuid(),
})

export const DuplicateLastGoalOutputSchema = z.object({
	goalId: z.uuid(),
})

@injectable()
export class DuplicateLastGoal extends Handler<typeof DuplicateLastGoalInputSchema, typeof DuplicateLastGoalOutputSchema> {
	readonly name = 'duplicate_last_goal' as const
	readonly inputSchema = DuplicateLastGoalInputSchema
	readonly outputSchema = DuplicateLastGoalOutputSchema

	constructor(private readonly goals: GoalRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const previous = await this.goals.findLastByUserAndStore(input.storeId, tx)
		if (!previous) {
			throw new BaseError<AnalyticsApplicationErrors>('NO_PREVIOUS_GOAL')
		}

		const fromMs = previous.from.getTime()
		const toMs = previous.to.getTime()
		const windowMs = toMs - fromMs
		const dayMs = 86_400_000
		const newFromMs = toMs + dayMs
		const newToMs = newFromMs + windowMs

		return this.withTransaction(tx, async tx => {
			const fresh = Goal.create({
				storeId: input.storeId,
				type: previous.type,
				targetAmount: previous.targetAmount,
				from: new Date(newFromMs),
				to: new Date(newToMs),
			})
			await this.goals.save(fresh, tx)
			await this.domainEventRepository.save(
				new GoalCreatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: { goal: fresh.toJSON() },
				}),
				tx,
			)
			return { goalId: fresh.id.value }
		})
	}
}

