export const DeleteManualAdSpendInputSchema = z.object({
	userId: z.uuid(),
	adSpendId: z.uuid(),
})

export const DeleteManualAdSpendOutputSchema = z.void()

/**
 * C35 DeleteManualAdSpend. Hard delete (no historical attribution
 * requirement per spec, unlike ProductCost). Refuses AUTOMATIC rows via
 * the entity's guard. Emits ManualAdSpendDeletedEvent before the actual
 * delete so the row identity is still available for the event payload.
 */
@injectable()
export class DeleteManualAdSpend extends Handler<typeof DeleteManualAdSpendInputSchema, typeof DeleteManualAdSpendOutputSchema> {
	readonly name = 'delete_manual_ad_spend' as const
	readonly inputSchema = DeleteManualAdSpendInputSchema
	readonly outputSchema = DeleteManualAdSpendOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const entity = await this.adSpends.findById(input.adSpendId, tx)
		if (!entity) {
			throw new BaseError<MarketingApplicationErrors>('AD_SPEND_NOT_FOUND')
		}
		// All AdSpendManual rows are by definition MANUAL — guardManualOnly removed
		// in Spec β.2 D2 (AdSpend → AdSpendManual rename dropped the adSpendType discriminator).

		await this.withTransaction(tx, async tx => {
			await this.domainEventRepository.save(
				new ManualAdSpendDeletedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					payload: {
						adSpendId: entity.id.value,
						storeId: entity.storeId.value,
					},
				}),
				tx,
			)
			await this.adSpends.delete(entity.id.value, tx)
		})

		return
	}
}

