import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { CampaignProductBindingRepository } from '../repositories/CampaignProductBindingRepository'
import { CampaignProductBindingRemovedEvent } from '../events'

export const UnbindCampaignFromProductInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	campaignId: z.uuid(),
	productIds: z.array(z.uuid()).default([]),
	variantIds: z.array(z.uuid()).default([]),
})

export const UnbindCampaignFromProductOutputSchema = z.void()

/**
 * C37 UnbindCampaignFromProduct. Idempotent per spec — emits the
 * RemovedEvent even when no rows matched so downstream consumers can
 * no-op safely. Bulk delete by (campaignId, productIds[]) and
 * (campaignId, variantIds[]) in a single transaction.
 */
@injectable()
export class UnbindCampaignFromProduct extends Handler<
	typeof UnbindCampaignFromProductInputSchema,
	typeof UnbindCampaignFromProductOutputSchema
> {
	readonly name = 'unbind_campaign_from_product' as const
	readonly inputSchema = UnbindCampaignFromProductInputSchema
	readonly outputSchema = UnbindCampaignFromProductOutputSchema

	constructor(private readonly bindings: CampaignProductBindingRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		if (input.productIds.length === 0 && input.variantIds.length === 0) {
			return
		}

		await this.withTransaction(tx, async tx => {
			await this.bindings.unbindMany(input.campaignId, input.productIds, input.variantIds, tx)

			await this.domainEventRepository.save(
				new CampaignProductBindingRemovedEvent({
					entityId: input.campaignId,
					ownerId: input.storeId,
					payload: {
						storeId: input.storeId,
						campaignId: input.campaignId,
						productIds: input.productIds,
						variantIds: input.variantIds,
					},
				}),
				tx,
			)
		})

		return
	}
}

