import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'

import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { AdSpendManualSchema } from '../entities/AdSpendManual'
import { ManualAdSpendUpdatedEvent } from '../events'
import Z from 'zod'
import type { MarketingApplicationErrors } from '../errors'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateManualAdSpendInputSchema = z.object({
	userId: z.uuid(),
	adSpendId: z.uuid(),
	amountCents: z.number().int().positive().optional(),
	currency: z.enum(CurrencyCode).optional(),
	startDate: z.date().optional(),
	endDate: z.date().optional(),
	name: z.string().optional(),
	description: z.string().optional(),
})

export const UpdateManualAdSpendOutputSchema = z.void()

/**
 * C34 UpdateManualAdSpend. Loads the AdSpendManual, applies the patch,
 * persists, and emits ManualAdSpendUpdatedEvent.
 */
@injectable()
export class UpdateManualAdSpend extends Handler<typeof UpdateManualAdSpendInputSchema, typeof UpdateManualAdSpendOutputSchema> {
	readonly name = 'update_manual_ad_spend' as const
	readonly inputSchema = UpdateManualAdSpendInputSchema
	readonly outputSchema = UpdateManualAdSpendOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const entity = await this.adSpends.findById(input.adSpendId, tx)
		if (!entity) {
			throw new BaseError<MarketingApplicationErrors>('AD_SPEND_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			const startDate = input.startDate ? new Date(input.startDate) : undefined
			startDate?.setUTCHours(0, 0, 0, 0)
			const endDate = input.endDate ? new Date(input.endDate) : undefined
			endDate?.setUTCHours(23, 59, 59, 999)

			entity.updateManual({
				name: input.name,
				description: input.description,
				startDate,
				endDate,
				spend:
					input.amountCents !== undefined
						? {
								amountCents: input.amountCents,
								currency: input.currency ?? entity.currency,
							}
						: undefined,
			})
			await this.adSpends.save(entity, tx)

			await this.domainEventRepository.save(
				new ManualAdSpendUpdatedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					// toJSON() serialises Id instances to strings; z.instance(Id) accepts
					// both at runtime — the cast bridges the TS mismatch.
					payload: { adSpend: entity.toJSON() as unknown as Z.infer<typeof AdSpendManualSchema> },
				}),
				tx,
			)
		})

		return
	}
}

import { singleton } from 'tsyringe-neo'
import { BaseError } from '@bk-dash/core-typescript'
import type { HttpControllerRequest, HttpMiddlewareResponse, Middleware } from '@bk-dash/core-typescript'
import { StoreMembershipRepository } from '@tenancy/repositories/StoreMembershipRepository'
import type { ApplicationErrors } from '@tenancy/errors'
import { SessionSchema } from '@auth/schemas'

/**
 * Tenancy gate — foundation of the storeId-from-session convention. It:
 *   1. Parses `request.ctx` against `SessionSchema` (requires `user.id` and the
 *      active `session.storeId`).
 *   2. Asserts the user is a member of that store via `findByStoreAndUser`.
 *   3. On a miss (or any parse failure), throws `STORE_MEMBERSHIP_NOT_FOUND` (→ 404).
 *   4. On a hit, stamps `request.ctx.membership = { id, userId, role, storeIds }`
 *      for `RequireStoreRole` and any controller that still needs the role or the
 *      full list of stores the user belongs to.
 *
 * Store-scoped controllers no longer read `ctx.membership.storeId` — the active
 * store is `ctx.session.storeId`, which this middleware has already validated.
 *
 * Composition rule: `AuthAccountMiddleware` first (provides `user.id` +
 * `session.storeId`), then this; `RequireStoreRole` goes after to enforce the
 * role allow-list.
 */
@singleton()
export class RequireStoreMember implements Middleware {
	constructor(private readonly memberships: StoreMembershipRepository) {}

	async execute(request: HttpControllerRequest<unknown>): Promise<HttpMiddlewareResponse<void>> {
		const ctx = SessionSchema.safeParse(request.ctx)
		if (!ctx.success) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

		const userId = ctx.data.user.id
		const storeId = ctx.data.session.storeId
		if (!storeId) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

		const active = await this.memberships.findByStoreAndUser(storeId, userId)
		if (!active) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

		const all = await this.memberships.findByUserId(userId)
		const storeIds = all.map((m) => m.storeId)

		request.ctx = {
			...request.ctx,
			membership: { id: active.id, userId: active.userId, role: active.role, storeIds },
		}
		return {}
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, CredentialVault, Handler, Id, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Client } from '@bk-dash/client-typescript'
import { StoreIntegrationType, MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegrationRepository } from '../../integration/repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../../integration/repositories/IntegrationCredentialSecretRepository'
import { MarketingReconciliationRequestedEvent } from '../events'
import type { ApplicationErrors } from '../errors'

export const ReconcileMarketingAccountsInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	platform: z.enum(MarketingPlatform),
})

export const ReconcileMarketingAccountsOutputSchema = z.object({
	jobId: z.string(),
	estimatedCompletionAt: z.date(),
})

/**
 * C38 ReconcileMarketingAccounts. Per spec § Data Flow Outbound: TS
 * triggers a go-worker sync scoped to the MARKETING_METRICS pipeline
 * (POST /sync with pipelines:['MARKETING_METRICS']) using the
 * MarketingPlatform's stored credentials. Replaces the former bespoke
 * /marketing/reconcile route, removed in the Go sync restructure; the
 * marketing pull is now one sync kind among many. Go runs the same job
 * on cron (spec § Scheduled Flows); this is the merchant-triggered
 * manual path exposed in the dashboard's "Refresh data" button.
 *
 * Opens credentials → calls go-worker → emits a domain event for audit.
 */
@injectable()
export class ReconcileMarketingAccounts extends Handler<
	typeof ReconcileMarketingAccountsInputSchema,
	typeof ReconcileMarketingAccountsOutputSchema
> {
	readonly name = 'reconcile_marketing_accounts' as const
	readonly inputSchema = ReconcileMarketingAccountsInputSchema
	readonly outputSchema = ReconcileMarketingAccountsOutputSchema

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly credentialSecretRepo: IntegrationCredentialSecretRepository,
		private readonly vault: CredentialVault,
		private readonly client: Client,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const integration = await this.storeIntegrationRepo.findByStoreIdAndPlatform(
			input.storeId,
			{ type: StoreIntegrationType.MARKETING_PLATFORM, platform: input.platform },
			tx,
		)
		if (integration === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		if (!integration.active) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_INACTIVE')
		}

		const secret = await this.credentialSecretRepo.findByStoreIntegrationId(integration.id.value, tx)
		if (secret === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_CREDENTIAL_NOT_FOUND')
		}
		const credentials = await this.vault.open<Record<string, string>>({
			encryptionAlgorithm: secret.encryptionAlgorithm,
			encryptedPayload: secret.encryptedPayload,
		})

		// Pass an explicit empty config object as the second arg so the GoClient
		// correctly threads `baseURL` + `client` into the request config rather
		// than merging them into the data payload (GoClient uses args.slice(0,-1)
		// to separate data from config — without a second arg the data is treated
		// as the config and the stub fetch is never applied in tests).
		await this.client.go.sync(
			{
				platform: input.platform,
				storeId: input.storeId,
				storeIntegrationId: integration.id.value,
				credentials,
				pipelines: ['MARKETING_METRICS'],
			},
			{},
		)

		// Go's reconcile returns counters, not a job handle — synthesize a jobId
		// + ETA so the audit event + output preserve their existing contract.
		const jobId = Id.value()
		const estimatedCompletionAt = new Date(Date.now() + 30 * 60_000)

		return this.withTransaction(tx, async tx => {
			await this.domainEventRepository.save(
				new MarketingReconciliationRequestedEvent({
					entityId: integration.id.value,
					ownerId: input.userId,
					payload: {
						storeId: input.storeId,
						storeIntegrationId: integration.id.value,
						platform: input.platform,
						jobId,
						requestedByUserId: input.userId,
					},
				}),
				tx,
			)
			return { jobId, estimatedCompletionAt }
		})
	}
}

