import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Role as TenancyRole } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { StoreMemberRoleChangedEvent } from '../events'
import type { ApplicationErrors, DomainErrors } from '../errors'

export const ChangeMemberRoleInputSchema = z.object({
	storeId: z.uuid(),
	userId: z.uuid(),
	newRole: z.enum(TenancyRole),
})

export const ChangeMemberRoleOutputSchema = z.object({
	changed: z.boolean(),
})

@injectable()
export class ChangeMemberRole extends Handler<typeof ChangeMemberRoleInputSchema, typeof ChangeMemberRoleOutputSchema> {
	readonly name = 'change_member_role' as const
	readonly inputSchema = ChangeMemberRoleInputSchema
	readonly outputSchema = ChangeMemberRoleOutputSchema

	constructor(private readonly memberships: StoreMembershipRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const membership = await this.memberships.findByStoreAndUser(input.storeId, input.userId, tx)
		if (!membership) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

		// No-op: same role → no save, no event. Controller will translate `changed=false` to 204.
		if (membership.role === input.newRole) return { changed: false }

		// LAST_OWNER guard: demoting the only OWNER → block.
		if (membership.role === TenancyRole.OWNER && input.newRole !== TenancyRole.OWNER) {
			const owners = await this.memberships.countOwnersByStoreId(input.storeId, tx)
			if (owners <= 1) throw new BaseError<DomainErrors>('CANNOT_DEMOTE_LAST_OWNER')
		}

		const oldRole = membership.role
		membership.changeRole(input.newRole)

		return this.withTransaction(tx, async tx => {
			await this.memberships.save(membership, tx)
			await this.domainEventRepository.save(
				new StoreMemberRoleChangedEvent({
					entityId: input.storeId,
					ownerId: input.userId,
					payload: {
						storeId: input.storeId,
						storeMembershipId: membership.id.value,
						userId: input.userId,
						oldRole,
						newRole: input.newRole,
					},
				}),
				tx,
			)
			return { changed: true }
		})
	}
}

