import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { FxRateRepository } from '../repositories/FxRateRepository'
import type { FinanceApplicationErrors } from '../errors'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const ResolveFxRateInputSchema = z.object({
	fromCurrency: z.enum(CurrencyCode),
	toCurrency: z.enum(CurrencyCode),
	date: z.date(),
})

export const ResolveFxRateOutputSchema = z.object({
	fromCurrency: z.enum(CurrencyCode),
	toCurrency: z.enum(CurrencyCode),
	rate: z.string(),
	asOf: z.date(),
})

/**
 * C49 ResolveFxRate. Per spec § 1.2 FX Management: "Resolve the FX rate
 * effective on any historical date for any currency pair." Returns the
 * latest captured rate with `startDate <= date`. Identity pairs
 * (from == to) short-circuit to "1.0" without a repo lookup. Throws
 * FX_RATE_NOT_FOUND when no captured rate exists for the pair on/before
 * the requested date.
 */
@injectable()
export class ResolveFxRate extends Handler<typeof ResolveFxRateInputSchema, typeof ResolveFxRateOutputSchema> {
	readonly name = 'resolve_fx_rate' as const
	readonly inputSchema = ResolveFxRateInputSchema
	readonly outputSchema = ResolveFxRateOutputSchema

	constructor(private readonly fxRates: FxRateRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		if (input.fromCurrency === input.toCurrency) {
			return { fromCurrency: input.fromCurrency, toCurrency: input.toCurrency, rate: '1.0', asOf: input.date }
		}

		// Query at end-of-day on the requested date so a rate captured at
		// 00:00:00Z on that date counts as effective.
		const asOf = input.date
		const rate = await this.fxRates.findEffective(input.fromCurrency, input.toCurrency, asOf, tx)
		if (!rate) {
			throw new BaseError<FinanceApplicationErrors>('FX_RATE_NOT_FOUND')
		}

		return { fromCurrency: input.fromCurrency, toCurrency: input.toCurrency, rate: rate.rate, asOf: input.date }
	}
}
