import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { RecordManualAdSpend } from './RecordManualAdSpend'
import { UpdateManualAdSpend } from './UpdateManualAdSpend'
import { DeleteManualAdSpend } from './DeleteManualAdSpend'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { ManualAdSpendDeletedEvent, ManualAdSpendRecordedEvent, ManualAdSpendUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('Manual AdSpend (C33 + C34 + C35)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let record: RecordManualAdSpend
	let update: UpdateManualAdSpend
	let del: DeleteManualAdSpend
	let repo: AdSpendManualRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		record = testBed.resolve(RecordManualAdSpend)
		update = testBed.resolve(UpdateManualAdSpend)
		del = testBed.resolve(DeleteManualAdSpend)
		repo = testBed.resolve(AdSpendManualRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readRecordedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendRecordedEvent)
	}
	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendUpdatedEvent)
	}
	async function readDeletedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendDeletedEvent)
	}

	describe('RecordManualAdSpend (C33)', () => {
		it('persists a MANUAL AdSpendManual + emits ManualAdSpendRecordedEvent', async () => {
			const out = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 10_000,
				description: 'May spend',
			})

			expect(out.adSpendId).toMatch(/^[0-9a-f-]{36}$/)
			const saved = await repo.findById(out.adSpendId)
			expect(saved?.platform).toBeUndefined()
			expect(saved?.spend.amountCents).toBe(10_000)

			const emitted = await readRecordedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.spend.amountCents).toBe(10_000)
		})

		it('propagates INVALID_DATE_RANGE when startDate > endDate', async () => {
			await expect(
				record.execute({
					userId: USER,
					storeId: STORE,
					startDate: new Date('2026-06-30T00:00:00.000Z'),
					endDate: new Date('2026-06-01T00:00:00.000Z'),
					currency: CurrencyCode.USD,
					amountCents: 100,
				}),
			).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
		})
	})

	describe('UpdateManualAdSpend (C34)', () => {
		async function seedManual(): Promise<string> {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})
			return adSpendId
		}

		it('updates name + description + emits with changedFields', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, adSpendId, name: 'new', description: 'updated' })

			const saved = await repo.findById(adSpendId)
			expect(saved?.name).toBe('new')
			expect(saved?.description).toBe('updated')

			const emitted = await readUpdatedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.name).toBe('new')
		})

		it('updates spend (amountCents only — uses existing currency)', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, adSpendId, amountCents: 9_999 })

			const saved = await repo.findById(adSpendId)
			expect(saved?.spend.amountCents).toBe(9_999)
			expect(saved?.spend.currency).toBe(CurrencyCode.USD) // preserved
		})

		it('emits ManualAdSpendUpdatedEvent even when no fields supplied (always-publish)', async () => {
			const adSpendId = await seedManual()
			await update.execute({ userId: USER, adSpendId })
			const updated = await readUpdatedEvents()
			expect(updated).toHaveLength(1)
			expect(updated[0]!.payload.adSpend).toBeDefined()
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(update.execute({ userId: USER, adSpendId: testId(), name: 'x' })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})

	describe('DeleteManualAdSpend (C35)', () => {
		it('hard-deletes the MANUAL AdSpendManual + emits ManualAdSpendDeletedEvent', async () => {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})

			await del.execute({ userId: USER, adSpendId })

			expect(await repo.findById(adSpendId)).toBeUndefined()
			const emitted = await readDeletedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpendId).toBe(adSpendId)
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(del.execute({ userId: USER, adSpendId: testId() })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})
})

