import { HttpStatusCode, registerErrorCodes } from '@bk-dash/core-typescript'
import type { BaseDomainErrors, BaseApplicationErrors, BaseInterfaceErrors, BaseInfrastructureErrors } from '@bk-dash/core-typescript'

// Domain — invariant violations raised by entities / value objects
export type MarketingDomainErrors = 'INVALID_DATE_RANGE' | 'CANNOT_MUTATE_AUTOMATIC_AD_SPEND' | 'BINDING_ALREADY_EXISTS'

export type DomainErrors = BaseDomainErrors | MarketingDomainErrors

// Application — orchestration failures raised by use cases / handlers
export type MarketingApplicationErrors =
	| 'AD_SPEND_NOT_FOUND'
	| 'CAMPAIGN_NOT_FOUND'
	| 'BINDING_NOT_FOUND'
	| 'PRODUCT_NOT_FOUND'
	| 'VARIANT_NOT_FOUND'
	| 'STORE_INTEGRATION_NOT_FOUND'
	| 'STORE_INTEGRATION_INACTIVE'
	| 'STORE_INTEGRATION_CREDENTIAL_NOT_FOUND'

export type ApplicationErrors = BaseApplicationErrors | MarketingApplicationErrors

export type InterfaceErrors = BaseInterfaceErrors
export type InfrastructureErrors = BaseInfrastructureErrors
export type Errors = ApplicationErrors | DomainErrors | InfrastructureErrors | InterfaceErrors

registerErrorCodes({
	// Domain
	INVALID_DATE_RANGE: HttpStatusCode.UNPROCESSABLE_ENTITY,
	CANNOT_MUTATE_AUTOMATIC_AD_SPEND: HttpStatusCode.UNPROCESSABLE_ENTITY,
	BINDING_ALREADY_EXISTS: HttpStatusCode.CONFLICT,
	// Application
	AD_SPEND_NOT_FOUND: HttpStatusCode.NOT_FOUND,
	CAMPAIGN_NOT_FOUND: HttpStatusCode.NOT_FOUND,
	BINDING_NOT_FOUND: HttpStatusCode.NOT_FOUND,
	PRODUCT_NOT_FOUND: HttpStatusCode.NOT_FOUND,
	VARIANT_NOT_FOUND: HttpStatusCode.NOT_FOUND,
	STORE_INTEGRATION_NOT_FOUND: HttpStatusCode.NOT_FOUND,
	// STORE_INTEGRATION_INACTIVE + STORE_INTEGRATION_CREDENTIAL_NOT_FOUND
	// are registered by the Integration BC's errors module (loaded via its
	// registry.ts side-effect import). Marketing only declares the union
	// type so use cases can throw them; the status mapping is owned upstream.
})

