import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateProductCost } from './UpdateProductCost'
import { CreateProductCost } from './CreateProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostUpdatedEvent } from '../events'
import { ProductCost, type ProductCostOptionInput } from '../entities/ProductCost'

const STORE = testId('store', '1')
const STORE_INTEGRATION = testId('store-integration', '1')
const PRODUCT_A = testId('product', 'a')
const VARIANT_1 = testId('variant', '1')
const USER = testId('user', '1')

function singleOption(overrides: Partial<ProductCostOptionInput> = {}): ProductCostOptionInput {
	return {
		currency: CurrencyCode.USD,
		startDate: '2026-05-01',
		items: [
			{
				variantIds: [VARIANT_1],
				quantity: 1,
				quantityModifier: QuantityModifier.EQ,
				unitCost: { amountCents: 500, currency: CurrencyCode.USD },
			},
		],
		...overrides,
	}
}

describe('UpdateProductCost (C28)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateProductCost
	let createUseCase: CreateProductCost
	let repo: ProductCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateProductCost)
		createUseCase = testBed.resolve(CreateProductCost)
		repo = testBed.resolve(ProductCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedProductCost(): Promise<string> {
		const { productCostId } = await createUseCase.execute({
			userId: USER,
			storeId: STORE,
			storeIntegrationId: STORE_INTEGRATION,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})
		return productCostId
	}

	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ProductCostUpdatedEvent)
	}

	it('updates options + emits ProductCostUpdatedEvent', async () => {
		const productCostId = await seedProductCost()

		await useCase.execute({
			userId: USER,
			productCostId,
			options: [singleOption({ currency: CurrencyCode.EUR })],
		})

		const updated = await repo.findById(productCostId)
		expect(updated?.options[0]?.currency).toBe(CurrencyCode.EUR)

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
	})

	it('updates options + reports changedFields=[options]; items get fresh ids + variantsHash', async () => {
		const productCostId = await seedProductCost()
		const before = await repo.findById(productCostId)
		const originalOptionId = before!.options[0]!.id

		const newOption = singleOption({
			currency: CurrencyCode.BRL,
			startDate: '2026-06-01',
			items: [
				{
					variantIds: [VARIANT_1],
					quantity: 10,
					quantityModifier: QuantityModifier.GTE,
					unitCost: { amountCents: 400, currency: CurrencyCode.BRL },
				},
			],
		})

		await useCase.execute({
			userId: USER,
			productCostId,
			options: [newOption],
		})

		const updated = await repo.findById(productCostId)
		const opt = updated?.options[0]
		expect(updated?.options).toHaveLength(1)
		expect(opt?.currency).toBe(CurrencyCode.BRL)
		expect(opt?.items[0]?.quantity).toBe(10)
		expect(opt?.id).not.toBe(originalOptionId) // fresh id
		expect(opt?.items[0]?.variantsHash).toBe(VARIANT_1)

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
	})

	it('updates options together with a currency change', async () => {
		const productCostId = await seedProductCost()

		await useCase.execute({
			userId: USER,
			productCostId,
			options: [singleOption({ currency: CurrencyCode.EUR })],
		})

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
	})

	it('emits ProductCostUpdatedEvent even when no fields supplied (always-publish)', async () => {
		const productCostId = await seedProductCost()

		await useCase.execute({ userId: USER, productCostId })

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
	})

	it('throws PRODUCT_COST_NOT_FOUND when the row is missing', async () => {
		await expect(
			useCase.execute({
				userId: USER,
				productCostId: testId(),
				options: [singleOption()],
			}),
		).rejects.toMatchObject({ name: 'PRODUCT_COST_NOT_FOUND' })
	})

	it('throws PRODUCT_COST_NOT_FOUND when the row was soft-deleted', async () => {
		const productCostId = await seedProductCost()
		const entity = await repo.findById(productCostId)
		entity!.delete()
		await repo.save(entity as ProductCost)

		await expect(useCase.execute({ userId: USER, productCostId, options: [singleOption()] })).rejects.toMatchObject({
			name: 'PRODUCT_COST_NOT_FOUND',
		})
	})

	it('propagates INVALID_DATE_RANGE from entity.update when options carry bad dates', async () => {
		const productCostId = await seedProductCost()

		await expect(
			useCase.execute({
				userId: USER,
				productCostId,
				options: [singleOption({ startDate: '2026-12-01', endDate: '2026-11-01' })],
			}),
		).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
	})
})

