import { injectable } from 'tsyringe-neo'
import { BaseError, CredentialVault, Handler, Id, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Client } from '@bk-dash/client-typescript'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../repositories/IntegrationCredentialSecretRepository'
import { ReintegrationTriggeredEvent } from '../events'
import type { ApplicationErrors, DomainErrors } from '../errors'

export const TriggerReintegrationInputSchema = z.object({
	userId: z.uuid(),
	storeIntegrationId: z.uuid(),
})

export const TriggerReintegrationOutputSchema = z.object({
	jobId: z.string(),
	estimatedCompletionAt: z.date(),
})

/**
 * C23 TriggerReintegration. Per spec: "Rate-limited per integration (1/5min);
 * TS HTTP-calls go-worker with credentials." Rate-limit enforcement is
 * deferred to a Redis-backed middleware/service slice — the use case currently
 * trusts that the caller (typically the controller behind a rate-limit guard)
 * already gated. Opens the sealed credentials, hands them to the Go sync
 * worker, emits ReintegrationTriggered.
 */
@injectable()
export class TriggerReintegration extends Handler<typeof TriggerReintegrationInputSchema, typeof TriggerReintegrationOutputSchema> {
	readonly name = 'trigger_reintegration' as const
	readonly inputSchema = TriggerReintegrationInputSchema
	readonly outputSchema = TriggerReintegrationOutputSchema

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly credentialSecretRepo: IntegrationCredentialSecretRepository,
		private readonly vault: CredentialVault,
		private readonly client: Client,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const integration = await this.storeIntegrationRepo.findById(input.storeIntegrationId, tx)
		if (integration === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		if (!integration.active) {
			throw new BaseError<DomainErrors>('STORE_INTEGRATION_INACTIVE')
		}

		const secret = await this.credentialSecretRepo.findByStoreIntegrationId(integration.id.value, tx)
		if (secret === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_CREDENTIAL_NOT_FOUND')
		}

		const credentials = await this.vault.open<Record<string, string>>({
			encryptionAlgorithm: secret.encryptionAlgorithm,
			encryptedPayload: secret.encryptedPayload,
		})

		await this.client.go.sync(
			{
				platform: integration.platform,
				storeId: integration.storeId.value,
				storeIntegrationId: integration.id.value,
				storeIntegrationExternalId: integration.externalId,
				credentials,
			},
			{},
		)

		// Go's /sync returns per-pipeline counters, not a job handle —
		// synthesize a local jobId + ETA so the audit event + output preserve
		// their existing contract.
		const jobId = Id.value()
		const estimatedCompletionAt = new Date(Date.now() + 30 * 60_000)

		return this.withTransaction(tx, async tx => {
			await this.domainEventRepository.save(
				new ReintegrationTriggeredEvent({
					entityId: integration.id.value,
					ownerId: input.userId,
					payload: { storeIntegrationId: integration.id.value },
				}),
				tx,
			)
			return { jobId, estimatedCompletionAt }
		})
	}
}

