import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, givenStore } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateStorePreferences } from './UpdateStorePreferences'
import { StoreRepository } from '../repositories/StoreRepository'
import { OrderSamplingService } from '../services/OrderSamplingService'
import { StorePreferencesUpdatedEvent } from '../events'

class HasOrdersStub extends OrderSamplingService {
	constructor(private readonly v: boolean) {
		super()
	}
	async hasOrdersForStore(_storeId: string): Promise<boolean> {
		return this.v
	}
}

describe('UpdateStorePreferences use case (C14)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let storeRepo: StoreRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		storeRepo = testBed.resolve(StoreRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedStore(): Promise<string> {
		const s = await givenStore(testBed, { name: 'Acme', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })
		return s.id.value
	}

	async function readEvents() {
		return testBed.resolve(DomainEventRepository).findByType(StorePreferencesUpdatedEvent)
	}

	function useCaseWithOrders(hasOrders: boolean): UpdateStorePreferences {
		testContainer.register(OrderSamplingService as never, { useValue: new HasOrdersStub(hasOrders) })
		return testBed.resolve(UpdateStorePreferences)
	}

	it('timezone-only change succeeds even when hasOrders=true', async () => {
		const storeId = await seedStore()
		const uc = useCaseWithOrders(true)

		await uc.execute({
			storeId,
			timezone: 'America/Sao_Paulo',
		})

		const reloaded = await storeRepo.findById(storeId)
		expect(reloaded?.timezone).toBe('America/Sao_Paulo')
		const evts = await readEvents()
		expect(evts[0]!.payload.store.timezone).toBe('America/Sao_Paulo')
	})

	it('reportingCurrency change succeeds when hasOrders=false', async () => {
		const storeId = await seedStore()
		const uc = useCaseWithOrders(false)

		await uc.execute({
			storeId,
			reportingCurrency: CurrencyCode.BRL,
		})

		const reloaded = await storeRepo.findById(storeId)
		expect(reloaded?.reportingCurrency).toBe(CurrencyCode.BRL)
		const evts = await readEvents()
		expect(evts[0]!.payload.store.reportingCurrency).toBe(CurrencyCode.BRL)
	})

	it('reportingCurrency change throws REPORTING_CURRENCY_LOCKED when hasOrders=true', async () => {
		const storeId = await seedStore()
		const uc = useCaseWithOrders(true)

		await expect(
			uc.execute({
				storeId,
				reportingCurrency: CurrencyCode.BRL,
			}),
		).rejects.toMatchObject({ name: 'REPORTING_CURRENCY_LOCKED' })

		// Confirm the row wasn't mutated.
		const reloaded = await storeRepo.findById(storeId)
		expect(reloaded?.reportingCurrency).toBe(CurrencyCode.USD)
	})

	it('showStoreNameInNotifications flip emits changedFields=[showStoreNameInNotifications]', async () => {
		const storeId = await seedStore()
		const uc = useCaseWithOrders(false)

		await uc.execute({
			storeId,
			showStoreNameInNotifications: false,
		})

		const reloaded = await storeRepo.findById(storeId)
		expect(reloaded?.showStoreNameInNotifications).toBe(false)
		const evts = await readEvents()
		expect(evts[0]!.payload.store.showStoreNameInNotifications).toBe(false)
	})

	it('empty input → emits StorePreferencesUpdatedEvent (always-publish)', async () => {
		const storeId = await seedStore()
		const uc = useCaseWithOrders(false)
		await uc.execute({ storeId })

		const evts = await readEvents()
		expect(evts).toHaveLength(1)
		expect(evts[0]!.payload.store).toBeDefined()
	})

	it('throws STORE_NOT_FOUND for unknown storeId', async () => {
		const uc = useCaseWithOrders(false)
		await expect(
			uc.execute({
				storeId: '00000000-0000-7000-8000-000000000000',
				timezone: 'UTC',
			}),
		).rejects.toMatchObject({ name: 'STORE_NOT_FOUND' })
	})
})
