=== usecases/OperationalCost.test.ts ===
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import {
	CurrencyCode,
	OperationalCostCategory,
	OperationalCostFlow,
	OperationalCostPaymentStatus,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import { CreateOperationalCost } from './CreateOperationalCost'
import { UpdateOperationalCost } from './UpdateOperationalCost'
import { DeleteOperationalCost } from './DeleteOperationalCost'
import { SetOperationalCostStatusOverride } from './SetOperationalCostStatusOverride'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import {
	OperationalCostCreatedEvent,
	OperationalCostDeletedEvent,
	OperationalCostStatusOverriddenEvent,
	OperationalCostUpdatedEvent,
} from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('OperationalCost (C41/C42/C43/C44)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let create: CreateOperationalCost
	let update: UpdateOperationalCost
	let del: DeleteOperationalCost
	let setOverride: SetOperationalCostStatusOverride
	let repo: OperationalCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		create = testBed.resolve(CreateOperationalCost)
		update = testBed.resolve(UpdateOperationalCost)
		del = testBed.resolve(DeleteOperationalCost)
		setOverride = testBed.resolve(SetOperationalCostStatusOverride)
		repo = testBed.resolve(OperationalCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function eventRepo() {
		return testBed.resolve(DomainEventRepository)
	}

	async function seed(): Promise<string> {
		const { operationalCostId } = await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.RENT,
			description: 'Office rent',
			amount: { amountCents: 100_000, currency: CurrencyCode.BRL },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01'),
		})
		return operationalCostId
	}

	it('Create persists + emits OperationalCostCreatedEvent', async () => {
		const id = await seed()

		const saved = await repo.findById(id)
		expect(saved?.category).toBe(OperationalCostCategory.RENT)
		expect(saved?.amount.amountCents).toBe(100_000)
		expect(saved?.flow).toBe(OperationalCostFlow.DEBIT) // defaults to DEBIT when omitted

		const emitted = await eventRepo().findByType(OperationalCostCreatedEvent)
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.operationalCost).toBeDefined()
		expect(emitted[0]!.payload.operationalCost.storeId).toBe(STORE)
	})

	it('Create honors an explicit CREDIT flow', async () => {
		const { operationalCostId } = await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.TAKE_PROFIT,
			flow: OperationalCostFlow.CREDIT,
			description: 'Partner deposit',
			amount: { amountCents: 50_000, currency: CurrencyCode.BRL },
			recurrency: OperationalCostRecurrency.ONCE,
			startDate: new Date('2026-06-01'),
		})
		const saved = await repo.findById(operationalCostId)
		expect(saved?.flow).toBe(OperationalCostFlow.CREDIT)
	})

	it('Create propagates INVALID_DATE_RANGE on startDate > endDate', async () => {
		await expect(
			create.execute({
				userId: USER,
				storeId: STORE,
				category: OperationalCostCategory.RENT,
				description: 'x',
				amount: { amountCents: 100, currency: CurrencyCode.USD },
				recurrency: OperationalCostRecurrency.ONCE,
				startDate: new Date('2026-12-01'),
				endDate: new Date('2026-11-01'),
			}),
		).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
	})

	it('Update emits OperationalCostUpdatedEvent (idempotent re-publish on same value)', async () => {
		const id = await seed()
		await update.execute({
			userId: USER,
			operationalCostId: id,
			amount: { amountCents: 200_000, currency: CurrencyCode.BRL },
			description: 'New rent',
		})

		const saved = await repo.findById(id)
		expect(saved?.amount.amountCents).toBe(200_000)
		expect(saved?.description).toBe('New rent')
		const emitted = await eventRepo().findByType(OperationalCostUpdatedEvent)
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.operationalCost).toBeDefined()
		expect(emitted[0]!.payload.operationalCost.storeId).toBe(STORE)

		// Idempotent re-publish — still emits a second event
		await update.execute({ userId: USER, operationalCostId: id, amount: { amountCents: 200_000, currency: CurrencyCode.BRL } })
		const after = await eventRepo().findByType(OperationalCostUpdatedEvent)
		expect(after).toHaveLength(2) // second idempotent event
	})

	it('Update throws OPERATIONAL_COST_NOT_FOUND on missing id', async () => {
		await expect(
			update.execute({
				userId: USER,
				operationalCostId: testId('operational-cost', 'missing'),
				amount: { amountCents: 100, currency: CurrencyCode.USD },
			}),
		).rejects.toMatchObject({ name: 'OPERATIONAL_COST_NOT_FOUND' })
	})

	it('Delete soft-deletes + emits + second delete throws NOT_FOUND', async () => {
		const id = await seed()
		await del.execute({ userId: USER, operationalCostId: id })

		const saved = await repo.findById(id)
		expect(saved?.isDeleted).toBe(true)
		const emitted = await eventRepo().findByType(OperationalCostDeletedEvent)
		expect(emitted).toHaveLength(1)

		await expect(del.execute({ userId: USER, operationalCostId: id })).rejects.toMatchObject({ name: 'OPERATIONAL_COST_NOT_FOUND' })
	})

	it('Override records a non-default deviation, prunes back to default, + emits each time', async () => {
		const id = await seed()
		const occurrenceDate = new Date('2026-06-01T00:00:00.000Z')

		// Default is PAID — flip this occurrence to UNPAID (a real deviation).
		await setOverride.execute({ userId: USER, operationalCostId: id, occurrenceDate, status: OperationalCostPaymentStatus.UNPAID })

		let saved = await repo.findById(id)
		expect(saved?.statusOverrides).toHaveLength(1)
		expect(saved?.statusOverrides[0]).toEqual({ occurrenceDate, status: OperationalCostPaymentStatus.UNPAID })

		// Set back to the default (PAID) → override is pruned (exclusion stays minimal).
		await setOverride.execute({ userId: USER, operationalCostId: id, occurrenceDate, status: OperationalCostPaymentStatus.PAID })

		saved = await repo.findById(id)
		expect(saved?.statusOverrides).toHaveLength(0)

		const emitted = await eventRepo().findByType(OperationalCostStatusOverriddenEvent)
		expect(emitted).toHaveLength(2)
	})
})

