import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { MonetaryAmountSchema } from '../../shared/objects'
import { UpdateGoal } from '../usecases/UpdateGoal'

export const UpdateGoalControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), session: z.object({ storeId: z.uuid() }) }),
	body: z.object({
		ids: z.array(z.uuid()).min(1),
		targetAmount: MonetaryAmountSchema.input()
			.refine(m => m.amountCents > 0)
			.optional(),
		from: z.stringToDate().optional(),
		to: z.stringToDate().optional(),
	}),
})

export const UpdateGoalControllerOutputSchema = z.void()

@injectable()
export class UpdateGoalController extends Controller<typeof UpdateGoalControllerInputSchema, typeof UpdateGoalControllerOutputSchema> {
	readonly path = '/goals'
	readonly method = 'patch' as const
	readonly description = 'Update one or more goals (C50)'
	readonly inputSchema = UpdateGoalControllerInputSchema
	readonly outputSchema = UpdateGoalControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: UpdateGoal) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.cmd.execute({
			userId: request.ctx.user.id,
			ids: request.body.ids,
			targetAmount: request.body.targetAmount,
			from: request.body.from,
			to: request.body.to,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

