import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, Role } from '@bk-dash/contracts-typescript/wire/enums'
import { ChangeMemberRole } from './ChangeMemberRole'
import { Store } from '../entities/Store'
import { StoreMembership } from '../entities/StoreMembership'
import { StoreRepository } from '../repositories/StoreRepository'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { StoreMemberRoleChangedEvent } from '../events'

const OWNER_A = testId('user', '1')
const OWNER_B = testId('user', '2')
const MEMBER_C = testId('user', '3')
const ABSENT_D = testId('user', 'd')

describe('ChangeMemberRole use case (C18)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let changeRole: ChangeMemberRole
	let storeRepo: StoreRepository
	let memberships: StoreMembershipRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		changeRole = testBed.resolve(ChangeMemberRole)
		storeRepo = testBed.resolve(StoreRepository)
		memberships = testBed.resolve(StoreMembershipRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedStore(): Promise<string> {
		const s = Store.create({ name: 'Acme', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })
		await storeRepo.save(s)
		return s.id.value
	}

	// Typed event read straight from the repository — no DrizzleClient, no cast.
	async function readRoleChangedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(StoreMemberRoleChangedEvent)
	}

	it('promotes MEMBER → ADMIN: persists + emits StoreMemberRoleChanged{oldRole,newRole}', async () => {
		const storeId = await seedStore()
		await memberships.save(StoreMembership.forOwner({ storeId, userId: OWNER_A }))
		await memberships.save(StoreMembership.forInvitee({ storeId, userId: MEMBER_C, role: Role.MEMBER }))

		const out = await changeRole.execute({ storeId, userId: MEMBER_C, newRole: Role.ADMIN })
		expect(out.changed).toBe(true)

		const reloaded = await memberships.findByStoreAndUser(storeId, MEMBER_C)
		expect(reloaded?.role).toBe(Role.ADMIN)

		const evs = await readRoleChangedEvents()
		expect(evs).toHaveLength(1)
		const { payload } = evs[0]!
		expect(payload.oldRole).toBe(Role.MEMBER)
		expect(payload.newRole).toBe(Role.ADMIN)
		expect(payload.userId).toBe(MEMBER_C)
		expect(payload.storeId).toBe(storeId)
	})

	it('throws CANNOT_DEMOTE_LAST_OWNER when demoting the only OWNER', async () => {
		const storeId = await seedStore()
		await memberships.save(StoreMembership.forOwner({ storeId, userId: OWNER_A }))

		await expect(changeRole.execute({ storeId, userId: OWNER_A, newRole: Role.ADMIN })).rejects.toMatchObject({
			name: 'CANNOT_DEMOTE_LAST_OWNER',
		})

		const still = await memberships.findByStoreAndUser(storeId, OWNER_A)
		expect(still?.role).toBe(Role.OWNER)
		expect(await readRoleChangedEvents()).toHaveLength(0)
	})

	it('allows demoting one OWNER when another OWNER exists', async () => {
		const storeId = await seedStore()
		await memberships.save(StoreMembership.forOwner({ storeId, userId: OWNER_A }))
		await memberships.save(StoreMembership.forOwner({ storeId, userId: OWNER_B }))

		const out = await changeRole.execute({ storeId, userId: OWNER_A, newRole: Role.ADMIN })
		expect(out.changed).toBe(true)

		const reloaded = await memberships.findByStoreAndUser(storeId, OWNER_A)
		expect(reloaded?.role).toBe(Role.ADMIN)
		expect((await readRoleChangedEvents())[0]!.payload.oldRole).toBe(Role.OWNER)
	})

	it('no-op when newRole === currentRole: no save, no event, changed=false', async () => {
		const storeId = await seedStore()
		await memberships.save(StoreMembership.forOwner({ storeId, userId: OWNER_A }))
		await memberships.save(StoreMembership.forInvitee({ storeId, userId: MEMBER_C, role: Role.MEMBER }))

		const before = await memberships.findByStoreAndUser(storeId, MEMBER_C)
		const versionBefore = (before as any).version

		const out = await changeRole.execute({ storeId, userId: MEMBER_C, newRole: Role.MEMBER })
		expect(out.changed).toBe(false)

		// No event.
		expect(await readRoleChangedEvents()).toHaveLength(0)

		// Row not written: version unchanged (save() increments version).
		const after = await memberships.findByStoreAndUser(storeId, MEMBER_C)
		expect((after as any).version).toBe(versionBefore)
	})

	it('throws STORE_MEMBERSHIP_NOT_FOUND when the membership does not exist', async () => {
		const storeId = await seedStore()
		await memberships.save(StoreMembership.forOwner({ storeId, userId: OWNER_A }))

		await expect(changeRole.execute({ storeId, userId: ABSENT_D, newRole: Role.ADMIN })).rejects.toMatchObject({
			name: 'STORE_MEMBERSHIP_NOT_FOUND',
		})
		expect(await readRoleChangedEvents()).toHaveLength(0)
	})

	it('promotes OWNER → OWNER is a no-op (changed=false, no event)', async () => {
		// Edge: re-applying OWNER to an OWNER must not double-count or fire the LAST_OWNER guard.
		const storeId = await seedStore()
		await memberships.save(StoreMembership.forOwner({ storeId, userId: OWNER_A }))

		const out = await changeRole.execute({ storeId, userId: OWNER_A, newRole: Role.OWNER })
		expect(out.changed).toBe(false)
		expect(await readRoleChangedEvents()).toHaveLength(0)
	})
})
