const OWNER_A = testId('user', 'owner-a')
const OWNER_B = testId('user', 'owner-b')
const MEMBER_C = testId('user', 'member-c')
const ABSENT_D = testId('user', 'absent-d')

describe('RemoveMember use case (C17)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let remove: RemoveMember
	let memberships: StoreMembershipRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		remove = testBed.resolve(RemoveMember)
		memberships = testBed.resolve(StoreMembershipRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readRemovedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(StoreMemberRemovedEvent)
	}

	it('removes a non-OWNER member + emits StoreMemberRemoved', async () => {
		const store = await givenStore(testBed)
		const storeId = store.id.value
		await givenStoreMembership(testBed, { storeId, userId: OWNER_A, role: Role.OWNER })
		await givenStoreMembership(testBed, { storeId, userId: MEMBER_C, role: Role.MEMBER })

		const out = await remove.execute({ storeId, userId: MEMBER_C })
		expect(out.removed).toBe(true)

		// Row gone.
		const gone = await memberships.findByStoreAndUser(storeId, MEMBER_C)
		expect(gone).toBeUndefined()

		// OWNER still there.
		const owner = await memberships.findByStoreAndUser(storeId, OWNER_A)
		expect(owner?.role).toBe(Role.OWNER)

		// Event emitted.
		const removed = await readRemovedEvents()
		expect(removed).toHaveLength(1)
		expect(removed[0]!.payload.userId).toBe(MEMBER_C)
		expect(removed[0]!.payload.storeId).toBe(storeId)
	})

	it('throws CANNOT_REMOVE_LAST_OWNER when removing the only OWNER', async () => {
		const store = await givenStore(testBed)
		const storeId = store.id.value
		await givenStoreMembership(testBed, { storeId, userId: OWNER_A, role: Role.OWNER })

		await expect(remove.execute({ storeId, userId: OWNER_A })).rejects.toMatchObject({ name: 'CANNOT_REMOVE_LAST_OWNER' })

		// Row preserved + no event emitted.
		const still = await memberships.findByStoreAndUser(storeId, OWNER_A)
		expect(still?.role).toBe(Role.OWNER)
		expect(await readRemovedEvents()).toHaveLength(0)
	})

	it('allows removing one OWNER when another OWNER exists', async () => {
		const store = await givenStore(testBed)
		const storeId = store.id.value
		await givenStoreMembership(testBed, { storeId, userId: OWNER_A, role: Role.OWNER })
		await givenStoreMembership(testBed, { storeId, userId: OWNER_B, role: Role.OWNER })

		const out = await remove.execute({ storeId, userId: OWNER_A })
		expect(out.removed).toBe(true)

		const remaining = await memberships.findByStoreId(storeId)
		expect(remaining).toHaveLength(1)
		expect(remaining[0]!.userId.value).toBe(OWNER_B)
	})

	it('throws STORE_MEMBERSHIP_NOT_FOUND when the membership does not exist', async () => {
		const store = await givenStore(testBed)
		const storeId = store.id.value
		await givenStoreMembership(testBed, { storeId, userId: OWNER_A, role: Role.OWNER })

		await expect(remove.execute({ storeId, userId: ABSENT_D })).rejects.toMatchObject({ name: 'STORE_MEMBERSHIP_NOT_FOUND' })
		expect(await readRemovedEvents()).toHaveLength(0)
	})
})

