import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId, givenUserPreferences } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { UpdateUserSettings } from './UpdateUserSettings'
import { UserPreferencesRepository } from '../repositories/UserPreferencesRepository'
import { UserPreferencesUpdatedEvent } from '../events'
import { CurrencyCode, NotificationCurrencyMode } from '@bk-dash/contracts-typescript/wire/enums'

describe('UpdateUserPreferences use case (C11)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateUserPreferences
	let prefsRepo: UserPreferencesRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateUserPreferences)
		prefsRepo = testBed.resolve(UserPreferencesRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(UserPreferencesUpdatedEvent)
	}

	it('updates notificationCurrencyMode + emits changedFields=[notificationCurrencyMode]', async () => {
		const userId = (await givenUserPreferences(testBed)).userId.value
		await useCase.execute({
			userId,
			notificationCurrencyMode: NotificationCurrencyMode.SALE_CURRENCY,
		})

		const found = await prefsRepo.findByUserId(userId)
		expect(found?.notificationCurrencyMode).toBe(NotificationCurrencyMode.SALE_CURRENCY)

		const evts = await readUpdatedEvents()
		expect(evts).toHaveLength(1)
		expect(evts[0]!.payload.userPreferences).toBeDefined()
		expect(evts[0]!.payload.userPreferences.notificationCurrencyMode).toBe(NotificationCurrencyMode.SALE_CURRENCY)
	})

	it('updates customCurrency + dailyNotificationsEnabled + emits both in changedFields', async () => {
		const userId = (await givenUserPreferences(testBed)).userId.value
		await useCase.execute({
			userId,
			notificationCurrencyMode: NotificationCurrencyMode.CUSTOM_CURRENCY,
			customCurrency: CurrencyCode.BRL,
			dailyNotificationsEnabled: false,
		})

		const found = await prefsRepo.findByUserId(userId)
		expect(found?.customCurrency).toBe(CurrencyCode.BRL)
		expect(found?.dailyNotificationsEnabled).toBe(false)
		expect(found?.notificationCurrencyMode).toBe(NotificationCurrencyMode.CUSTOM_CURRENCY)

		const evts = await readUpdatedEvents()
		expect(evts[0]!.payload.userPreferences.notificationCurrencyMode).toBe(NotificationCurrencyMode.CUSTOM_CURRENCY)
		expect(evts[0]!.payload.userPreferences.customCurrency).toBe(CurrencyCode.BRL)
		expect(evts[0]!.payload.userPreferences.dailyNotificationsEnabled).toBe(false)
	})

	it('updates timezone + emits changedFields=[timezone]', async () => {
		const userId = (await givenUserPreferences(testBed)).userId.value
		await useCase.execute({ userId, timezone: 'America/Sao_Paulo' })

		const found = await prefsRepo.findByUserId(userId)
		expect(found?.timezone).toBe('America/Sao_Paulo')

		const evts = await readUpdatedEvents()
		expect(evts[0]!.payload.userPreferences.timezone).toBe('America/Sao_Paulo')
	})

	it('null customCurrency clears the override (CUSTOM_CURRENCY → STORE_CURRENCY scenario)', async () => {
		const userId = (await givenUserPreferences(testBed)).userId.value
		await useCase.execute({
			userId,
			notificationCurrencyMode: NotificationCurrencyMode.CUSTOM_CURRENCY,
			customCurrency: CurrencyCode.USD,
		})

		await useCase.execute({
			userId,
			notificationCurrencyMode: NotificationCurrencyMode.STORE_CURRENCY,
			customCurrency: null,
		})

		const reloaded = await prefsRepo.findByUserId(userId)
		expect(reloaded?.customCurrency).toBeUndefined()
		expect(reloaded?.notificationCurrencyMode).toBe(NotificationCurrencyMode.STORE_CURRENCY)
	})

	it('same value → emits UserPreferencesUpdatedEvent (idempotent re-publish)', async () => {
		const userId = (await givenUserPreferences(testBed)).userId.value
		await useCase.execute({ userId, dailyNotificationsEnabled: true })

		const evts = await readUpdatedEvents()
		expect(evts).toHaveLength(1)
		expect(evts[0]!.payload.userPreferences).toBeDefined()
	})

	it('empty input (no fields) → emits UserPreferencesUpdatedEvent (always-publish)', async () => {
		const userId = (await givenUserPreferences(testBed)).userId.value
		await useCase.execute({ userId })

		const evts = await readUpdatedEvents()
		expect(evts).toHaveLength(1)
		expect(evts[0]!.payload.userPreferences).toBeDefined()
	})

	it('throws USER_PREFERENCES_NOT_FOUND if no row for userId', async () => {
		await expect(
			useCase.execute({
				userId: testId('user', 'notfound'),
				dailyNotificationsEnabled: false,
			}),
		).rejects.toMatchObject({ name: 'USER_PREFERENCES_NOT_FOUND' })
	})

