// Integration given helpers — set up StoreIntegrations via repository directly.
import type { TestBed } from '../TestBed'
import { SalesPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegration } from '@integration/entities/StoreIntegration'
import { StoreIntegrationRepository } from '@integration/repositories/StoreIntegrationRepository'
import type { PlatformProps } from '@integration/services'
import { uniqueId } from './sequence'

export async function givenStoreIntegration(
	testBed: TestBed,
	data: {
		storeId: string
		ownerId: string
	} & Partial<{
		// pass a full PlatformProps to target a non-default platform/type;
		// defaults to a Shopify SALES_CHANNEL integration.
		platform: PlatformProps
		externalId: string
		displayName: string
	}>,
): Promise<StoreIntegration> {
	const repository = testBed.resolve(StoreIntegrationRepository)

	const integration = StoreIntegration.create({
		storeId: data.storeId,
		platform: data.platform ?? { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY },
		externalId: data.externalId ?? `acme-${uniqueId()}.myshopify.com`,
		displayName: data.displayName ?? `Acme Store ${uniqueId()}`,
		ownerId: data.ownerId,
	})

	await repository.save(integration)
	return integration
}
