		storeIntegrationExternalId: z.string().min(1),
		patch: OrderOverrideFieldsSchema,
	}),
})

export const UpdateOrderOverrideControllerOutputSchema = UpdateOrderOverrideOutputSchema

@injectable()
export class UpdateOrderOverrideController extends Controller<
	typeof UpdateOrderOverrideControllerInputSchema,
	typeof UpdateOrderOverrideControllerOutputSchema
> {
	readonly path = '/orders/override'
	readonly method = 'patch' as const
	readonly description = 'Batch-update typed override fields on one or more Orders (C26 UpdateOrderOverride)'
	readonly inputSchema = UpdateOrderOverrideControllerInputSchema
	readonly outputSchema = UpdateOrderOverrideControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: UpdateOrderOverride) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.membership.storeId,
