import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { PlatformRegistrySchema } from '@integration/services'

export const GetPlatformDescriptorsControllerInputSchema = z.object({})

// The platform-descriptor registry emitted as a JSON Schema document — one
// `anyOf` over every platform leaf (authMode as `const`, scopes as consts,
// inputTokens/outputTokens as object schemas). Dynamic shape → typed loosely.
export const GetPlatformDescriptorsControllerOutputSchema = z.record(z.string(), z.unknown())

/**
 * `GET /integrations/platforms` — exposes the `PlatformRegistrySchema` as JSON
 * Schema so the frontend can render per-platform connect forms dynamically
 * (the `anyOf` branches carry each platform's `inputTokens` object schema).
 * Public read; no auth required because the descriptors are configuration
 * shape, not secrets.
 */
@injectable()
export class GetPlatformDescriptorsController extends Controller<
	typeof GetPlatformDescriptorsControllerInputSchema,
	typeof GetPlatformDescriptorsControllerOutputSchema
> {
	readonly path = '/integrations/platforms'
	readonly method = 'get' as const
	readonly description = 'Read the platform-descriptor registry (per-platform authMode, scopes, input/output token schemas) as JSON Schema'
	readonly inputSchema = GetPlatformDescriptorsControllerInputSchema
	readonly outputSchema = GetPlatformDescriptorsControllerOutputSchema

	async handle(): Promise<this['output']> {
		return { status: HttpStatusCode.OK, data: z.toJSONSchema(PlatformRegistrySchema) as Record<string, unknown> }
	}
}

