		expect(await eventRepo.findByType(IntegrationDeactivatedEvent)).toHaveLength(1)
		expect(await eventRepo.findByType(StoreIntegrationDataWipeRequestedEvent)).toHaveLength(0)
	})

	it('wipeData=true additionally emits StoreIntegrationDataWipeRequested', async () => {
