import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { Role } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { RequireStoreRole } from '../middlewares/RequireStoreRole'
import { DisableStore, DisableStoreOutputSchema } from '../usecases/DisableStore'

export const DisableStoreControllerInputSchema = z
	.object({
		ctx: z.object({
			user: z.object({ id: z.string() }),
		}),
		params: z.object({
			storeId: z.uuid(),
		}),
		reason: z.string().trim().min(1).max(500).optional(),
	})
	.example([
		{
			ctx: { user: { id: 'user-123' } },
			params: { storeId: '019e4d24-6524-7041-9e1c-8108180cddae' },
			reason: 'closing for maintenance',
		},
	])

export const DisableStoreControllerOutputSchema = DisableStoreOutputSchema.example([
	{ storeId: '019e4d24-6524-7041-9e1c-8108180cddae', isDisabled: true },
])

@injectable()
export class DisableStoreController extends Controller<
	typeof DisableStoreControllerInputSchema,
	typeof DisableStoreControllerOutputSchema
> {
	readonly path = '/stores/:storeId/disable'
	readonly method = 'post' as const
	readonly description = 'Disable a store (C19 DisableStore; OWNER only)'
	readonly inputSchema = DisableStoreControllerInputSchema
	readonly outputSchema = DisableStoreControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER])]

	constructor(private disableStore: DisableStore) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.disableStore.execute({
			storeId: request.params.storeId,
			disabledByUserId: request.ctx.user.id,
			reason: request.reason,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

