import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { givenStoreIntegration } from '@test/support/given/integrations'
import { BaseError, DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, PaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import { UpdateOrderOverride } from './UpdateOrderOverride'
import { OrderOverrideRepository } from '../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderOverriddenEvent } from '../events'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')
const ORDER_A = testId('order', 'a')
const ORDER_B = testId('order', 'b')
// externalId is now derived from the store's integration, not passed in.
const EXT_A = 'shop-a.myshopify.com'
const EXT_B = 'shop-b.myshopify.com'
const USER_1 = testId('user', '1')
const USER_2 = testId('user', '2')

describe('UpdateOrderOverride (C26)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateOrderOverride
	let repo: OrderOverrideRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateOrderOverride)
		repo = testBed.resolve(OrderOverrideRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
		// STORE_A is integrated with EXT_A — the override pin externalId is
		// derived from this row, not from the request.
		await givenStoreIntegration(testBed, { storeId: STORE_A, ownerId: 'integration-tenant', externalId: EXT_A })
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readOverriddenEvents() {
		return testBed.resolve(DomainEventRepository).findByType(OrderOverriddenEvent)
	}

	it('creates a fresh override on first call + emits with all fields as changed', async () => {
		const out = await useCase.execute({
			userId: USER_1,
			storeId: STORE_A,
			orderIds: [ORDER_A],
			patch: {
				paymentStatus: PaymentStatus.PAID,
				revenue: new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }),
			},
		})

		expect(out.orderOverrideIds).toHaveLength(1)
		expect(out.orderOverrideIds[0]).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findByPin(ORDER_A, EXT_A)
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(saved?.fields.revenue).toEqual(new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }))

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.orderId).toBe(ORDER_A)
		expect(emitted[0]!.payload.storeIntegrationExternalId).toBe(EXT_A)
