import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { UpdateManualAdSpend } from '../usecases/UpdateManualAdSpend'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateManualAdSpendControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }) }),
	body: z.object({
		ids: z.array(z.uuid()).min(1),
		amountCents: z.number().int().positive().optional(),
		currency: z.enum(CurrencyCode).optional(),
		startDate: z.stringToDate().optional(),
		endDate: z.stringToDate().optional(),
		description: z.string().optional(),
	}),
})

export const UpdateManualAdSpendControllerOutputSchema = z.void()

@injectable()
export class UpdateManualAdSpendController extends Controller<
	typeof UpdateManualAdSpendControllerInputSchema,
	typeof UpdateManualAdSpendControllerOutputSchema
> {
	readonly path = '/manual-ad-spend'
	readonly method = 'patch' as const
	readonly description = 'Update one or more manual ad spend entries (C32)'
	readonly inputSchema = UpdateManualAdSpendControllerInputSchema
	readonly outputSchema = UpdateManualAdSpendControllerOutputSchema

	override middlewares = [AuthAccountMiddleware]

	constructor(private cmd: UpdateManualAdSpend) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.cmd.execute({
			userId: request.ctx.user.id,
			ids: request.body.ids,
			amountCents: request.body.amountCents,
			currency: request.body.currency,
			startDate: request.body.startDate,
			endDate: request.body.endDate,
			description: request.body.description,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

