import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { Role } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { RequireStoreRole } from '../middlewares/RequireStoreRole'
import { InviteMember, InviteMemberOutputSchema } from '../usecases/InviteMember'

export const InviteMemberControllerInputSchema = z
	.object({
		ctx: z.object({
			user: z.object({ id: z.string() }),
		}),
		params: z.object({
			storeId: z.uuid(),
		}),
		email: z.email(),
		role: z.enum(Role),
	})
	.example([
		{
			ctx: { user: { id: 'user-123' } },
			params: { storeId: '019e4d24-6524-7041-9e1c-8108180cddae' },
			email: 'newmember@example.com',
			role: Role.MEMBER,
		},
	])

export const InviteMemberControllerOutputSchema = InviteMemberOutputSchema.example([
	{ storeInvitationId: '019e4d25-7c1f-7041-9e1c-8108180cddae' },
])

@injectable()
export class InviteMemberController extends Controller<
	typeof InviteMemberControllerInputSchema,
	typeof InviteMemberControllerOutputSchema
> {
	readonly path = '/stores/:storeId/memberships'
	readonly method = 'post' as const
	readonly description = 'Issue a signed invitation envelope for a new store member (C15 InviteMember)'
	readonly inputSchema = InviteMemberControllerInputSchema
	readonly outputSchema = InviteMemberControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private inviteMember: InviteMember) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.inviteMember.execute({
			storeId: request.params.storeId,
			invitedByUserId: request.ctx.user.id,
			email: request.email,
			role: request.role,
		})
		return { status: HttpStatusCode.CREATED, data }
	}
}

