import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateKit, UpdateKitOutputSchema } from '../usecases/UpdateKit'

export const UpdateKitControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), session: z.object({ storeId: z.uuid() }) }),
	params: z.object({ id: z.uuid() }),
	body: z.object({
		name: z.string().optional(),
		shipping: z.number().optional(),
		cost: z.number().optional(),
		items: z
			.array(
				z.object({
					productId: z.uuid(),
					quantity: z.number(),
					quantityModifier: z.enum(QuantityModifier),
				}),
			)
			.optional(),
	}),
})

export const UpdateKitControllerOutputSchema = UpdateKitOutputSchema

@injectable()
export class UpdateKitController extends Controller<typeof UpdateKitControllerInputSchema, typeof UpdateKitControllerOutputSchema> {
	readonly path = '/catalog/kits/:id'
	readonly method = 'patch' as const
	readonly description = 'MOCK. Update an existing kit (wizard edit command).'
	readonly inputSchema = UpdateKitControllerInputSchema
	readonly outputSchema = UpdateKitControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private command: UpdateKit) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		return {
			status: HttpStatusCode.OK,
			data: await this.command.execute({
				storeId: request.ctx.session.storeId,
				id: request.params.id,
				...request.body,
			}),
		}
	}
}

