import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostDeletedEvent } from '../events'
import type { CatalogApplicationErrors } from '../errors'

export const DeleteProductCostInputSchema = z.object({
	userId: z.uuid(),
	productCostId: z.uuid(),
})

export const DeleteProductCostOutputSchema = z.void()

/**
 * C29 DeleteProductCost. Soft-delete via `entity.delete()` (preserves
 * the row for historical COGS attribution per spec). Emits
 * ProductCostDeletedEvent for downstream consumers (analytics
 * invalidations, reporting). Refuses a second delete with
 * PRODUCT_COST_NOT_FOUND — the entity rejects double-delete inside
 * delete(); this layer just translates that to the application
 * lookup-failure shape.
 */
@injectable()
export class DeleteProductCost extends Handler<typeof DeleteProductCostInputSchema, typeof DeleteProductCostOutputSchema> {
	readonly name = 'delete_product_cost' as const
	readonly inputSchema = DeleteProductCostInputSchema
	readonly outputSchema = DeleteProductCostOutputSchema

	constructor(private readonly productCosts: ProductCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const productCost = await this.productCosts.findById(input.productCostId, tx)
		if (!productCost || productCost.isDeleted) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			productCost.delete()
			await this.productCosts.save(productCost, tx)

			await this.domainEventRepository.save(
				new ProductCostDeletedEvent({
					entityId: productCost.id.value,
					ownerId: productCost.storeId.value,
					payload: {
						productCost: productCost.toJSON(),
					},
				}),
				tx,
			)
		})

		return
	}
}

it('round-trips gateway timeline with coerced Date windows (AC-9)', async () => {
	const fc = Fees.create({ storeId: STORE_A })
	fc.placeGatewayFee(gw(0.029, new Date('2026-01-01T00:00:00.000Z'), new Date('2026-06-01T00:00:00.000Z')))
	fc.placeGatewayFee(gw(0.031, new Date('2026-06-01T00:00:00.000Z'), null))
	await repo.save(fc)

	const fetched = await repo.findById(fc.id.value)
	expect(fetched?.gatewayFees).toHaveLength(2)
	// Dates must be coerced back from ISO strings to Date instances
	expect(fetched?.gatewayFees[0]?.startDate).toBeInstanceOf(Date)
	expect(fetched?.gatewayFees[0]?.endDate).toBeInstanceOf(Date)
	expect(fetched?.gatewayFees[1]?.endDate).toBeNull()
	expect(fetched?.gatewayFees[0]?.variable).toBe(0.029)
	expect(fetched?.gatewayFees[1]?.variable).toBe(0.031)
})

