import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CurrencyCode, PaymentGateway, PaymentMethod, CheckoutPlatform, ShippingCostMode } from '@bk-dash/contracts-typescript/wire/enums'
import { Fees } from '../../entities/Fees'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')

const gw = (variable: number, s: Date, e: Date | null) => ({
	platform: PaymentGateway.STRIPE,
	paymentMethod: PaymentMethod.CREDIT_CARD,
	variable,
	fixed: { amountCents: 30, currency: CurrencyCode.USD },
	startDate: s,
	endDate: e,
})

describe('DrizzleFeesConfigurationRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: FeesConfigurationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(FeesConfigurationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	describe('save + findById', () => {
		it('round-trips gateway timeline with coerced Date windows (AC-9)', async () => {
			const fc = Fees.create({ storeId: STORE_A })
			fc.placeGatewayFee(gw(0.029, new Date('2026-01-01T00:00:00.000Z'), new Date('2026-06-01T00:00:00.000Z')))
			fc.placeGatewayFee(gw(0.031, new Date('2026-06-01T00:00:00.000Z'), null))
			await repo.save(fc)

			const fetched = await repo.findById(fc.id.value)
			expect(fetched?.gatewayFees).toHaveLength(2)
			// Dates must be coerced back from ISO strings to Date instances
			expect(fetched?.gatewayFees[0]?.startDate).toBeInstanceOf(Date)
			expect(fetched?.gatewayFees[0]?.endDate).toBeInstanceOf(Date)
			expect(fetched?.gatewayFees[1]?.endDate).toBeNull()
			expect(fetched?.gatewayFees[0]?.variable).toBe(0.029)
			expect(fetched?.gatewayFees[1]?.variable).toBe(0.031)
		})

		it('round-trips empty fee arrays', async () => {
			const fc = Fees.create({ storeId: STORE_A })
			await repo.save(fc)

			const fetched = await repo.findById(fc.id.value)
			expect(fetched?.gatewayFees).toEqual([])
			expect(fetched?.checkoutFee).toEqual([])
			expect(fetched?.shippingFee).toEqual([])
		})

		it('round-trips checkout and shipping timelines', async () => {
			const fc = Fees.create({ storeId: STORE_A })
			fc.placeCheckoutFee({ platform: CheckoutPlatform.YAMPI, rate: 0.02, startDate: new Date('2026-01-01T00:00:00.000Z'), endDate: null })
			fc.placeShippingFee({ mode: ShippingCostMode.AVERAGE_PER_SALE, value: { amountCents: 1500, currency: CurrencyCode.BRL }, startDate: new Date('2026-01-01T00:00:00.000Z'), endDate: null })
			await repo.save(fc)

			const fetched = await repo.findById(fc.id.value)
			expect(fetched?.checkoutFee).toHaveLength(1)
			expect(fetched?.checkoutFee[0]?.startDate).toBeInstanceOf(Date)
			expect(fetched?.shippingFee).toHaveLength(1)
			expect(fetched?.shippingFee[0]?.mode).toBe(ShippingCostMode.AVERAGE_PER_SALE)
		})

		it('returns undefined when no row matches', async () => {
			expect(await repo.findById(testId())).toBeUndefined()
		})

		it('UPSERT on save bumps version', async () => {
			const fc = Fees.create({ storeId: STORE_A })
			await repo.save(fc)
			await repo.save(fc)

			const fetched = await repo.findById(fc.id.value)
			expect(fetched?.version).toBeGreaterThan(1)
		})
	})

	describe('findByStoreId', () => {
		it('returns undefined when no row exists for that store', async () => {
			expect(await repo.findByStoreId(STORE_A)).toBeUndefined()
		})

		it('returns the single row for the store', async () => {
			const fc = Fees.create({ storeId: STORE_A })
			fc.placeGatewayFee(gw(0.029, new Date('2026-01-01T00:00:00.000Z'), null))
			await repo.save(fc)

			const found = await repo.findByStoreId(STORE_A)
			expect(found?.id.value).toBe(fc.id.value)
			expect(found?.gatewayFees).toHaveLength(1)
		})

		it('isolates by storeId', async () => {
			const a = Fees.create({ storeId: STORE_A })
			const b = Fees.create({ storeId: STORE_B })
			await repo.save(a)
			await repo.save(b)

			const ra = await repo.findByStoreId(STORE_A)
			const rb = await repo.findByStoreId(STORE_B)
			expect(ra?.storeId.value).toBe(STORE_A)
			expect(rb?.storeId.value).toBe(STORE_B)
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
			const fc = Fees.create({ storeId: STORE_A })
			await repo.save(fc)
			await repo.delete(fc.id.value)
			expect(await repo.findById(fc.id.value)).toBeUndefined()
		})
	})
})

