import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { ProductCostOptionInputSchema } from '../entities/ProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostUpdatedEvent } from '../events'
import type { CatalogApplicationErrors } from '../errors'

export const UpdateProductCostInputSchema = z.object({
	userId: z.uuid(),
	productCostId: z.uuid(),
	options: z.array(ProductCostOptionInputSchema).optional(),
})

export const UpdateProductCostOutputSchema = z.void()

/**
 * C28 UpdateProductCost. Loads the existing aggregate, applies the
 * options patch via `entity.update()` — which re-validates
 * the date-range invariant on the new options — then persists + emits
 * ProductCostUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateProductCost extends Handler<typeof UpdateProductCostInputSchema, typeof UpdateProductCostOutputSchema> {
	readonly name = 'update_product_cost' as const
	readonly inputSchema = UpdateProductCostInputSchema
	readonly outputSchema = UpdateProductCostOutputSchema

	constructor(private readonly productCosts: ProductCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const productCost = await this.productCosts.findById(input.productCostId, tx)
		if (!productCost || productCost.isDeleted) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			productCost.update({ options: input.options })
			await this.productCosts.save(productCost, tx)

			await this.domainEventRepository.save(
				new ProductCostUpdatedEvent({
					entityId: productCost.id.value,
					ownerId: productCost.storeId.value,
					payload: { productCost: productCost.toJSON() },
				}),
				tx,
			)
		})

		return
	}
}

