import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { BaseDomainEvent, Transaction } from '@bk-dash/core-typescript'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationDeactivatedEvent, IntegrationDisconnectedEvent, StoreIntegrationDataWipeRequestedEvent } from '../events'
import type { ApplicationErrors } from '../errors'

export const DisconnectIntegrationInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	storeIntegrationId: z.uuid(),
	/** When true, cascades a StoreIntegrationDataWipeRequested event so Sales/Catalog/Marketing/Tracking can purge canonical rows (merchant-owned overrides stay). Defaults to false (keep canonical data for re-connect or compliance audits). */
	wipeData: z.boolean().default(false),
})

export const DisconnectIntegrationOutputSchema = z.void()

/**
 * C22 DisconnectIntegration. Marks the integration's disconnectedAt + emits
 * IntegrationDisconnected (terminal) + IntegrationDeactivated (mirrors the
 * inactive/active flip for cross-cutting handlers that don't care about the
 * disconnect/toggle distinction). Optionally emits StoreIntegrationDataWipeRequested
 * for downstream BCs to cascade-clean canonical rows.
 */
@injectable()
export class DisconnectIntegration extends Handler<typeof DisconnectIntegrationInputSchema, typeof DisconnectIntegrationOutputSchema> {
	readonly name = 'disconnect_integration' as const
	readonly inputSchema = DisconnectIntegrationInputSchema
	readonly outputSchema = DisconnectIntegrationOutputSchema

	constructor(private readonly storeIntegrationRepo: StoreIntegrationRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const integration = await this.storeIntegrationRepo.findById(input.storeIntegrationId, tx)
		if (integration === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}

		// Entity throws STORE_INTEGRATION_ALREADY_DISCONNECTED if disconnectedAt is set.
		integration.disconnect()

		return this.withTransaction(tx, async tx => {
			await this.storeIntegrationRepo.save(integration, tx)

			const eventsToSave: BaseDomainEvent[] = [
				new IntegrationDisconnectedEvent({
					entityId: integration.id.value,
					ownerId: input.userId,
					payload: {
						storeIntegrationId: integration.id.value,
						disconnectedAt: integration.disconnectedAt ?? new Date(),
					},
				}),
				new IntegrationDeactivatedEvent({
					entityId: integration.id.value,
					ownerId: input.userId,
					payload: { storeIntegrationId: integration.id.value },
				}),
			]
			if (input.wipeData) {
				eventsToSave.push(
					new StoreIntegrationDataWipeRequestedEvent({
						entityId: integration.id.value,
						ownerId: input.userId,
						payload: {
							storeIntegrationId: integration.id.value,
							requestedByUserId: input.userId,
						},
					}),
				)
			}
			await this.domainEventRepository.saveMany(eventsToSave, tx)
			return
		})
	}
}

