import { injectable } from 'tsyringe-neo'
import { BaseError, CredentialVault, Handler, Id, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Client } from '@bk-dash/client-typescript'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../repositories/IntegrationCredentialSecretRepository'
import { ReintegrationTriggeredEvent } from '../events'
import type { ApplicationErrors, DomainErrors } from '../errors'

export const TriggerReintegrationInputSchema = z.object({
	userId: z.uuid(),
	storeIntegrationId: z.uuid(),
})

export const TriggerReintegrationOutputSchema = z.object({
	jobId: z.string(),
	estimatedCompletionAt: z.date(),
})

/**
 * C23 TriggerReintegration. Per spec: "Rate-limited per integration (1/5min);
 * TS HTTP-calls go-worker with credentials." Rate-limit enforcement is
 * deferred to a Redis-backed middleware/service slice — the use case currently
 * trusts that the caller (typically the controller behind a rate-limit guard)
 * already gated. Opens the sealed credentials, hands them to the Go sync
 * worker, emits ReintegrationTriggered.
 */
@injectable()
export class TriggerReintegration extends Handler<typeof TriggerReintegrationInputSchema, typeof TriggerReintegrationOutputSchema> {
	readonly name = 'trigger_reintegration' as const
	readonly inputSchema = TriggerReintegrationInputSchema
	readonly outputSchema = TriggerReintegrationOutputSchema

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly credentialSecretRepo: IntegrationCredentialSecretRepository,
		private readonly vault: CredentialVault,
		private readonly client: Client,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const integration = await this.storeIntegrationRepo.findById(input.storeIntegrationId, tx)
		if (integration === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		if (!integration.active) {
			throw new BaseError<DomainErrors>('STORE_INTEGRATION_INACTIVE')
		}

		const secret = await this.credentialSecretRepo.findByStoreIntegrationId(integration.id.value, tx)
		if (secret === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_CREDENTIAL_NOT_FOUND')
		}

		const credentials = await this.vault.open<Record<string, string>>({
			encryptionAlgorithm: secret.encryptionAlgorithm,
			encryptedPayload: secret.encryptedPayload,
		})

		await this.client.go.sync(
			{
				platform: integration.platform,
				storeId: integration.storeId.value,
				storeIntegrationId: integration.id.value,
				storeIntegrationExternalId: integration.externalId,
				credentials,
			},
			{},
		)

		// Go's /sync returns per-pipeline counters, not a job handle —
		// synthesize a local jobId + ETA so the audit event + output preserve
		// their existing contract.
		const jobId = Id.value()
		const estimatedCompletionAt = new Date(Date.now() + 30 * 60_000)

		return this.withTransaction(tx, async tx => {
			await this.domainEventRepository.save(
				new ReintegrationTriggeredEvent({
					entityId: integration.id.value,
					ownerId: input.userId,
					payload: { storeIntegrationId: integration.id.value },
				}),
				tx,
			)
			return { jobId, estimatedCompletionAt }
		})
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { CreateManualAdSpend } from './CreateManualAdSpend'
import { UpdateManualAdSpend } from './UpdateManualAdSpend'
import { DeleteManualAdSpend } from './DeleteManualAdSpend'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { ManualAdSpendDeletedEvent, ManualAdSpendRecordedEvent, ManualAdSpendUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('Manual AdSpend (C33 + C34 + C35)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let record: CreateManualAdSpend
	let update: UpdateManualAdSpend
	let del: DeleteManualAdSpend
	let repo: AdSpendManualRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		record = testBed.resolve(CreateManualAdSpend)
		update = testBed.resolve(UpdateManualAdSpend)
		del = testBed.resolve(DeleteManualAdSpend)
		repo = testBed.resolve(AdSpendManualRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readRecordedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendRecordedEvent)
	}
	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendUpdatedEvent)
	}
	async function readDeletedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendDeletedEvent)
	}

	describe('CreateManualAdSpend (C33)', () => {
		it('persists a MANUAL AdSpendManual + emits ManualAdSpendRecordedEvent', async () => {
			const out = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 10_000,
				description: 'May spend',
			})

			expect(out.adSpendId).toMatch(/^[0-9a-f-]{36}$/)
			const saved = await repo.findById(out.adSpendId)
			expect(saved?.platform).toBeUndefined()
			expect(saved?.spend.amountCents).toBe(10_000)

			const emitted = await readRecordedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.spend.amountCents).toBe(10_000)
		})

		it('propagates INVALID_DATE_RANGE when startDate > endDate', async () => {
			await expect(
				record.execute({
					userId: USER,
					storeId: STORE,
					startDate: new Date('2026-06-30T00:00:00.000Z'),
					endDate: new Date('2026-06-01T00:00:00.000Z'),
					currency: CurrencyCode.USD,
					amountCents: 100,
				}),
			).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
		})
	})

	describe('UpdateManualAdSpend (C34)', () => {
		async function seedManual(): Promise<string> {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})
			return adSpendId
		}

		it('updates name + description + emits with changedFields', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, ids: [adSpendId], name: 'new', description: 'updated' })

			const saved = await repo.findById(adSpendId)
			expect(saved?.name).toBe('new')
			expect(saved?.description).toBe('updated')

			const emitted = await readUpdatedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.name).toBe('new')
		})

		it('updates spend (amountCents only — uses existing currency)', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, ids: [adSpendId], amountCents: 9_999 })

			const saved = await repo.findById(adSpendId)
			expect(saved?.spend.amountCents).toBe(9_999)
			expect(saved?.spend.currency).toBe(CurrencyCode.USD) // preserved
		})

		it('emits ManualAdSpendUpdatedEvent even when no fields supplied (always-publish)', async () => {
			const adSpendId = await seedManual()
			await update.execute({ userId: USER, ids: [adSpendId] })
			const updated = await readUpdatedEvents()
			expect(updated).toHaveLength(1)
			expect(updated[0]!.payload.adSpend).toBeDefined()
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(update.execute({ userId: USER, ids: [testId()], name: 'x' })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})

	describe('DeleteManualAdSpend (C35)', () => {
		it('hard-deletes the MANUAL AdSpendManual + emits ManualAdSpendDeletedEvent', async () => {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})

			await del.execute({ userId: USER, ids: [adSpendId] })

			expect(await repo.findById(adSpendId)).toBeUndefined()
			const emitted = await readDeletedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpendId).toBe(adSpendId)
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(del.execute({ userId: USER, adSpendId: testId() })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})
})

