import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreRepository } from '../repositories/StoreRepository'
import { OrderSamplingService } from '../services/OrderSamplingService'
import { StoreSettingsUpdatedEvent } from '../events'
import type { ApplicationErrors } from '../errors'

export const UpdateStoreSettingsInputSchema = z.object({
	storeId: z.uuid(),
	// Profile settings
	name: z.string().trim().min(1).max(120).optional(),
	pictureUrl: z.url().nullable().optional(),
	email: z.email().nullable().optional(),
	phoneNumber: z.string().min(5).max(40).nullable().optional(),
	// Reporting + notification settings (merged from the former
	// UpdateStorePreferences command — one Settings command).
	reportingCurrency: z.enum(CurrencyCode).optional(),
	timezone: z.string().min(1).optional(),
	showStoreNameInNotifications: z.boolean().optional(),
})

export const UpdateStoreSettingsOutputSchema = z.void()

@injectable()
export class UpdateStoreSettings extends Handler<typeof UpdateStoreSettingsInputSchema, typeof UpdateStoreSettingsOutputSchema> {
	readonly name = 'update_store_settings' as const
	readonly inputSchema = UpdateStoreSettingsInputSchema
	readonly outputSchema = UpdateStoreSettingsOutputSchema

	constructor(
		private readonly storeRepo: StoreRepository,
		private readonly orderSampling: OrderSamplingService,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		// REPORTING_CURRENCY_LOCKED invariant: sales-side sampling decides whether
		// the currency may change. Check lives here (not in the entity) because the
		// entity cannot reach into sales.* — see master-prompt requirement.
		const hasOrders = await this.orderSampling.hasOrdersForStore(input.storeId)

		return this.withTransaction(tx, async tx => {
			const store = await this.storeRepo.findById(input.storeId, tx)
			if (!store) throw new BaseError<ApplicationErrors>('STORE_NOT_FOUND')

			store.updateSettings({
				name: input.name,
				pictureUrl: input.pictureUrl ?? undefined,
				email: input.email ?? undefined,
				phoneNumber: input.phoneNumber ?? undefined,
			})

			store.updatePreferences(
				{
					reportingCurrency: input.reportingCurrency,
					timezone: input.timezone,
					showStoreNameInNotifications: input.showStoreNameInNotifications,
				},
				{ hasOrders },
			)

			await this.storeRepo.save(store, tx)
			await this.domainEventRepository.save(
				new StoreSettingsUpdatedEvent({
					entityId: input.storeId,
					ownerId: input.storeId,
					payload: {
						store: store.toJSON(),
					},
				}),
				tx,
			)
		})
	}
}

