		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const integration = await this.storeIntegrationRepo.findById(input.storeIntegrationId, tx)
		if (integration === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		if (!integration.active) {
			throw new BaseError<DomainErrors>('STORE_INTEGRATION_INACTIVE')
		}

		const secret = await this.credentialSecretRepo.findByStoreIntegrationId(integration.id.value, tx)
		if (secret === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_CREDENTIAL_NOT_FOUND')
		}

		const credentials = await this.vault.open<Record<string, string>>({
			encryptionAlgorithm: secret.encryptionAlgorithm,
			encryptedPayload: secret.encryptedPayload,
		})

		await this.client.go.sync(
			{
				platform: integration.platform,
				storeId: integration.storeId.value,
				storeIntegrationId: integration.id.value,
				storeIntegrationExternalId: integration.externalId,
				credentials,
			},
			{},
		)

		// Go's /sync returns per-pipeline counters, not a job handle —
		// synthesize a local jobId + ETA so the audit event + output preserve
		// their existing contract.
		const jobId = Id.value()
		const estimatedCompletionAt = new Date(Date.now() + 30 * 60_000)

		return this.withTransaction(tx, async tx => {
			await this.domainEventRepository.save(
				new ReintegrationTriggeredEvent({
					entityId: integration.id.value,
					ownerId: input.userId,
					payload: { storeIntegrationId: integration.id.value },
				}),
				tx,
			)
			return { jobId, estimatedCompletionAt }
		})
	}
}

