		})

		it('filters by currency pair', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.EUR, to: CurrencyCode.BRL, rate: '5.60', startDate: '2026-06-01T00:00:00.000Z' })

