import { describe, expect, it } from 'bun:test'
import { CurrencyCode, Role } from '@bk-dash/contracts-typescript/wire/enums'
import { testId } from '@test/support'
import {
	StoreCreatedEvent,
	StoreSettingsUpdatedEvent,
	StorePreferencesCreatedEvent,
	StorePreferencesUpdatedEvent,
	StoreDisabledEvent,
	StoreEnabledEvent,
	StoreMemberInvitedEvent,
	StoreMemberAddedEvent,
	StoreMemberRemovedEvent,
	StoreMemberRoleChangedEvent,
} from './index'

const STORE_ID = testId('store', '1')
const USER_ID = testId('user', '1')
const MEMBERSHIP_ID = testId('membership', '1')
const INVITATION_ID = testId('invitation', '1')
const NOW = new Date().toISOString()

describe('Tenancy domain events', () => {
	it('event names follow tenancy.<entity>.<verb> convention', () => {
		expect(StoreCreatedEvent.name).toBe('tenancy.store.created')
		expect(StoreSettingsUpdatedEvent.name).toBe('tenancy.store.settings_updated')
		expect(StorePreferencesCreatedEvent.name).toBe('tenancy.store_preferences.created')
		expect(StorePreferencesUpdatedEvent.name).toBe('tenancy.store_preferences.updated')
		expect(StoreDisabledEvent.name).toBe('tenancy.store.disabled')
		expect(StoreEnabledEvent.name).toBe('tenancy.store.enabled')
		expect(StoreMemberInvitedEvent.name).toBe('tenancy.store_member.invited')
		expect(StoreMemberAddedEvent.name).toBe('tenancy.store_member.added')
		expect(StoreMemberRemovedEvent.name).toBe('tenancy.store_member.removed')
		expect(StoreMemberRoleChangedEvent.name).toBe('tenancy.store_member.role_changed')
	})

	it('StoreCreatedEvent carries storeId + name', () => {
		const e = new StoreCreatedEvent({
			entityId: STORE_ID,
			ownerId: USER_ID,
			payload: { storeId: STORE_ID, name: 'Acme' },
		})
		expect(e.payload.storeId).toBe(STORE_ID)
		expect(e.payload.name).toBe('Acme')
	})

	it('StoreSettingsUpdatedEvent carries the full Store entity snapshot', () => {
		const e = new StoreSettingsUpdatedEvent({
			entityId: STORE_ID,
			ownerId: USER_ID,
			payload: {
				store: {
					name: 'Acme',
					pictureUrl: undefined,
					email: 'owner@acme.co',
					phoneNumber: undefined,
					reportingCurrency: CurrencyCode.USD,
					timezone: 'UTC',
					isDisabled: false,
					disabledReason: undefined,
					showStoreNameInNotifications: true,
				} as never,
			},
		})
		expect(e.payload.store).toBeDefined()
	})

	it('StorePreferencesCreatedEvent carries reportingCurrency + timezone', () => {
		const e = new StorePreferencesCreatedEvent({
			entityId: STORE_ID,
			ownerId: USER_ID,
			payload: { storeId: STORE_ID, reportingCurrency: CurrencyCode.BRL, timezone: 'America/Sao_Paulo' },
		})
		expect(e.payload.reportingCurrency).toBe(CurrencyCode.BRL)
		expect(e.payload.timezone).toBe('America/Sao_Paulo')
	})

	it('StorePreferencesUpdatedEvent carries the full Store entity snapshot', () => {
		const e = new StorePreferencesUpdatedEvent({
			entityId: STORE_ID,
			ownerId: USER_ID,
			payload: {
				store: {
					name: 'Acme',
					pictureUrl: undefined,
					email: undefined,
					phoneNumber: undefined,
					reportingCurrency: CurrencyCode.BRL,
					timezone: 'America/Sao_Paulo',
					isDisabled: false,
					disabledReason: undefined,
					showStoreNameInNotifications: true,
				} as never,
			},
		})
		expect(e.payload.store).toBeDefined()
	})

	it('StoreDisabledEvent + StoreEnabledEvent carry verb-specific ISO timestamps', () => {
		const disabled = new StoreDisabledEvent({
			entityId: STORE_ID,
			ownerId: USER_ID,
			payload: { storeId: STORE_ID, disabledAt: NOW, disabledReason: 'admin' },
		})
		const enabled = new StoreEnabledEvent({
			entityId: STORE_ID,
			ownerId: USER_ID,
			payload: { storeId: STORE_ID, enabledAt: NOW },
		})
		expect(disabled.payload.disabledReason).toBe('admin')
		expect(enabled.payload.enabledAt).toBe(NOW)
	})

	it('StoreMemberInvitedEvent carries the plain invitationToken on the payload', () => {
		const e = new StoreMemberInvitedEvent({
			entityId: INVITATION_ID,
			ownerId: USER_ID,
			payload: {
				storeId: STORE_ID,
				storeInvitationId: INVITATION_ID,
				email: 'invitee@b.com',
				role: Role.MEMBER,
				invitationToken: 'plain-secret-not-persisted',
			},
		})
		expect(e.payload.invitationToken).toBe('plain-secret-not-persisted')
		expect(e.payload.role).toBe(Role.MEMBER)
	})

	it('StoreMemberAddedEvent + StoreMemberRemovedEvent carry membership identifiers', () => {
		const added = new StoreMemberAddedEvent({
			entityId: MEMBERSHIP_ID,
			ownerId: USER_ID,
			payload: {
				storeId: STORE_ID,
				storeMembershipId: MEMBERSHIP_ID,
				userId: USER_ID,
				role: Role.ADMIN,
			},
		})
		const removed = new StoreMemberRemovedEvent({
			entityId: MEMBERSHIP_ID,
			ownerId: USER_ID,
			payload: { storeId: STORE_ID, storeMembershipId: MEMBERSHIP_ID, userId: USER_ID },
		})
		expect(added.payload.role).toBe(Role.ADMIN)
		expect(removed.payload.storeMembershipId).toBe(MEMBERSHIP_ID)
	})

