import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId, givenStoreIntegration } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { DisconnectIntegration } from './DisconnectIntegration'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationDisconnectedEvent, IntegrationDeactivatedEvent, StoreIntegrationDataWipeRequestedEvent } from '../events'

const STORE_ID = testId('store', '1')
const USER = testId('user', '1')

describe('DisconnectIntegration use case (C22)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: DisconnectIntegration
	let storeIntegrationRepo: StoreIntegrationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(DisconnectIntegration)
		storeIntegrationRepo = testBed.resolve(StoreIntegrationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('happy path: marks disconnectedAt + emits Disconnected + Deactivated (no wipe by default)', async () => {
		const integration = await givenStoreIntegration(testBed, { storeId: STORE_ID, ownerId: USER })
		const eventRepo = testBed.resolve(DomainEventRepository)

		await useCase.execute({ userId: USER, storeId: STORE_ID, storeIntegrationId: integration.id.value, wipeData: false })

		const persisted = await storeIntegrationRepo.findById(integration.id.value)
		expect(persisted!.disconnectedAt).not.toBeNull()

		expect(await eventRepo.findByType(IntegrationDisconnectedEvent)).toHaveLength(1)
		expect(await eventRepo.findByType(IntegrationDeactivatedEvent)).toHaveLength(1)
		expect(await eventRepo.findByType(StoreIntegrationDataWipeRequestedEvent)).toHaveLength(0)
	})

	it('wipeData=true additionally emits StoreIntegrationDataWipeRequested', async () => {
		const integration = await givenStoreIntegration(testBed, { storeId: STORE_ID, ownerId: USER })
		const eventRepo = testBed.resolve(DomainEventRepository)

		await useCase.execute({ userId: USER, storeId: STORE_ID, storeIntegrationId: integration.id.value, wipeData: true })

		expect(await eventRepo.findByType(StoreIntegrationDataWipeRequestedEvent)).toHaveLength(1)
	})

	it('unknown storeIntegrationId → STORE_INTEGRATION_NOT_FOUND', async () => {
		await expect(
			useCase.execute({
				userId: USER,
				storeIntegrationId: testId(),
				wipeData: false,
			}),
		).rejects.toMatchObject({ name: 'STORE_INTEGRATION_NOT_FOUND' })
	})

	it('re-disconnect → STORE_INTEGRATION_ALREADY_DISCONNECTED (entity invariant)', async () => {
		const integration = await givenStoreIntegration(testBed, { storeId: STORE_ID, ownerId: USER })
		await useCase.execute({ userId: USER, storeId: STORE_ID, storeIntegrationId: integration.id.value, wipeData: false })

		await expect(useCase.execute({ userId: USER, storeId: STORE_ID, storeIntegrationId: integration.id.value, wipeData: false })).rejects.toMatchObject({
			name: 'STORE_INTEGRATION_ALREADY_DISCONNECTED',
		})
	})
})

