	it('StoreSettingsUpdatedEvent carries the full Store entity snapshot', () => {
		const e = new StoreSettingsUpdatedEvent({
			entityId: STORE_ID,
			ownerId: USER_ID,
			payload: {
				store: {
					name: 'Acme',
					pictureUrl: undefined,
