export const DeleteOperationalCostInputSchema = z.object({
	userId: z.uuid(),
	operationalCostId: z.uuid(),
})

export const DeleteOperationalCostOutputSchema = z.void()

/** C43 DeleteOperationalCost. Soft-delete via entity.delete(). */
@injectable()
export class DeleteOperationalCost extends Handler<typeof DeleteOperationalCostInputSchema, typeof DeleteOperationalCostOutputSchema> {
	readonly name = 'delete_operational_cost' as const
	readonly inputSchema = DeleteOperationalCostInputSchema
	readonly outputSchema = DeleteOperationalCostOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const entity = await this.costs.findById(input.operationalCostId, tx)
		if (!entity || entity.isDeleted) {
			throw new BaseError<FinanceApplicationErrors>('OPERATIONAL_COST_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			entity.delete()
			await this.costs.save(entity, tx)
			await this.domainEventRepository.save(
				new OperationalCostDeletedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					payload: { operationalCostId: entity.id.value, storeId: entity.storeId.value },
				}),
				tx,
			)
		})

		return
	}
}

