import { StoreRepository } from '../repositories/StoreRepository'
import { OrderSamplingService } from '../services/OrderSamplingService'
import { StoreSettingsUpdatedEvent } from '../events'

class HasOrdersStub extends OrderSamplingService {
	constructor(private readonly v: boolean) {
		super()
	}
	async hasOrdersForStore(_storeId: string): Promise<boolean> {
		return this.v
	}
}

describe('UpdateStoreSettings use case (C13 — settings + merged preferences)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateStoreSettings
	let storeRepo: StoreRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateStoreSettings)
		storeRepo = testBed.resolve(StoreRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents() {
		return testBed.resolve(DomainEventRepository).findByType(StoreSettingsUpdatedEvent)
	}

	function useCaseWithOrders(hasOrders: boolean): UpdateStoreSettings {
		testContainer.register(OrderSamplingService as never, { useValue: new HasOrdersStub(hasOrders) })
		return testBed.resolve(UpdateStoreSettings)
	}

	it('partial profile update emits StoreSettingsUpdated', async () => {
