import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { WarrantyReserveRepository } from '../repositories/WarrantyReserveRepository'
import { WarrantyReserveUpdatedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'

export const UpdateWarrantyReserveInputSchema = z.object({
	userId: z.uuid(),
	warrantyReserveId: z.uuid(),
	/** Rate as a 0..100 percentage. */
	rate: z.number().min(0).max(100).optional(),
})

export const UpdateWarrantyReserveOutputSchema = z.void()

/** C46 UpdateWarrantyReserve. Mutates the active row's rate in place. */
@injectable()
export class UpdateWarrantyReserve extends Handler<typeof UpdateWarrantyReserveInputSchema, typeof UpdateWarrantyReserveOutputSchema> {
	readonly name = 'update_warranty_reserve' as const
	readonly inputSchema = UpdateWarrantyReserveInputSchema
	readonly outputSchema = UpdateWarrantyReserveOutputSchema

	constructor(private readonly warranties: WarrantyReserveRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const entity = await this.warranties.findById(input.warrantyReserveId, tx)
		if (!entity || entity.isDeleted) {
			throw new BaseError<FinanceApplicationErrors>('WARRANTY_RESERVE_NOT_FOUND')
		}
		entity.update({ rate: input.rate !== undefined ? input.rate / 100 : undefined })

		await this.withTransaction(tx, async tx => {
			await this.warranties.save(entity, tx)
			await this.domainEventRepository.save(
				new WarrantyReserveUpdatedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					payload: { warrantyReserve: entity.toJSON() },
				}),
				tx,
			)
		})

		return
	}
}

