		{ token: InvitationTokenService, instance: InvitationTokenService },
		{ token: PlanQuotaService, instance: PlanQuotaService },
		// Tenancy owns stores → provides the real StoreQueryService for billing.
		{ token: StoreQueryService, instance: TenancyStoreQueryService },
	],
	real: [
		{ token: StoreRepository, instance: DrizzleStoreRepository },
