import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { DeleteOperationalCost } from '../usecases/DeleteOperationalCost'

export const DeleteOperationalCostControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), session: z.object({ storeId: z.uuid() }) }),
	body: z.object({ ids: z.array(z.uuid()).min(1) }),
})

export const DeleteOperationalCostControllerOutputSchema = z.void()

@injectable()
export class DeleteOperationalCostController extends Controller<
	typeof DeleteOperationalCostControllerInputSchema,
	typeof DeleteOperationalCostControllerOutputSchema
> {
	readonly path = '/operational-costs'
	readonly method = 'delete' as const
	readonly description = 'Delete operational costs by ids (C43)'
	readonly inputSchema = DeleteOperationalCostControllerInputSchema
	readonly outputSchema = DeleteOperationalCostControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: DeleteOperationalCost) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.cmd.execute({
			userId: request.ctx.user.id,
			ids: request.body.ids,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

