import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { givenStoreIntegration } from '@test/support/given'
import { DomainEventRepository, DrizzleClient, type BaseDomainEvent, type DomainEventConstructor } from '@bk-dash/core-typescript'
import { CurrencyCode, ProductCostType } from '@bk-dash/contracts-typescript/wire/enums'
import { products, variants } from '@bk-dash/contracts/db'
import { ImportProductCostsFromCsv } from './ImportProductCostsFromCsv'
import { ProductCostCsvProvider } from '../enums'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostCreatedEvent, ProductCostUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const PRODUCT_A = testId('product', 'a')
const PRODUCT_B = testId('product', 'b')
const VARIANT_1 = testId('variant', '1')
const VARIANT_2 = testId('variant', '2')
const USER = testId('user', '1')

// Shopify describe constants
const PRODUCT_SHIRT = 'cccccccc-0002-4000-8000-000000000001'
const VARIANT_BM = 'dddddddd-0002-4000-8000-000000000001'
const VARIANT_BL = 'dddddddd-0002-4000-8000-000000000002'

const HEADER = [
	'productId',
	'currency',
	'country',
	'startDate',
	'endDate',
	'variantIds',
	'quantity',
	'quantityModifier',
	'unitCostAmountCents',
	'unitCostCurrency',
	'costType',
].join(',')

function row(opts: {
	productId: string | 'null'
	startDate?: string
	variantIds?: string
	quantity?: string
	quantityModifier?: string
	costType?: string
}): string {
	return [
		opts.productId,
		'USD',
		'',
		opts.startDate ?? '2026-05-01',
		'',
		opts.variantIds ?? VARIANT_1,
		opts.quantity ?? '1',
		opts.quantityModifier ?? 'EQ',
		'500',
		'USD',
		opts.costType ?? 'SINGLE',
	].join(',')
}

describe('ImportProductCostsFromCsv (C30) — MANUAL', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: ImportProductCostsFromCsv
	let repo: ProductCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(ImportProductCostsFromCsv)
		repo = testBed.resolve(ProductCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
		// The owning StoreIntegration is derived from storeId by the use case.
		await givenStoreIntegration(testBed, { storeId: STORE, ownerId: 'integration-tenant' })
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents<E extends BaseDomainEvent>(eventClass: DomainEventConstructor<E>) {
		return testBed.resolve(DomainEventRepository).findByType(eventClass)
	}

	const base = { userId: USER, storeId: STORE, provider: ProductCostCsvProvider.MANUAL as const }

	it('reports a typed code when required columns are missing', async () => {
		const result = await useCase.execute({ ...base, csvContent: 'productId,currency\nu,USD' })
		expect(result.skippedCount).toBe(1)
		expect(result.errors[0]).toEqual({ row: 0, code: 'CSV_MISSING_REQUIRED_COLUMN', value: 'startDate' })
	})

	it('reports a typed code for an empty CSV', async () => {
		const result = await useCase.execute({ ...base, csvContent: '   \n\n' })
		expect(result.skippedCount).toBe(1)
		expect(result.errors[0]!.code).toBe('CSV_EMPTY')
	})

	it('creates one ProductCost per distinct product, merging multiple rows into one aggregate', async () => {
		const csv = [
			HEADER,
			row({ productId: PRODUCT_A }),
			row({ productId: PRODUCT_A, startDate: '2026-06-01', quantity: '10', quantityModifier: 'GTE' }),
			row({ productId: PRODUCT_B, variantIds: VARIANT_2 }),
		].join('\n')

		const result = await useCase.execute({ ...base, csvContent: csv })
		expect(result.createdCount).toBe(2) // A (2 options) + B — one create each
		expect(result.updatedCount).toBe(0) // grouped: A is not created-then-updated
		expect(result.skippedCount).toBe(0)

		expect((await repo.findByStoreAndProduct(STORE, PRODUCT_A))?.options).toHaveLength(2)
		expect((await repo.findByStoreAndProduct(STORE, PRODUCT_B))?.options).toHaveLength(1)
		expect(await readEvents(ProductCostCreatedEvent)).toHaveLength(2)
		expect(await readEvents(ProductCostUpdatedEvent)).toHaveLength(0)
	})

	it('updates a pre-existing aggregate (append) with one Updated event', async () => {
		await useCase.execute({ ...base, csvContent: [HEADER, row({ productId: PRODUCT_A })].join('\n') })
		const result = await useCase.execute({
			...base,
			csvContent: [HEADER, row({ productId: PRODUCT_A, startDate: '2026-07-01' })].join('\n'),
		})
		expect(result.createdCount).toBe(0)
		expect(result.updatedCount).toBe(1)
		expect((await repo.findByStoreAndProduct(STORE, PRODUCT_A))?.options).toHaveLength(2)
		expect(await readEvents(ProductCostUpdatedEvent)).toHaveLength(1)
	})

	it('reports per-row validation errors without aborting the batch (partial-success)', async () => {
		const csv = [
			HEADER,
			row({ productId: PRODUCT_A }),
			row({ productId: 'not-a-uuid' }),
			row({ productId: PRODUCT_B, quantity: '0' }),
		].join('\n')

		const result = await useCase.execute({ ...base, csvContent: csv })
		expect(result.createdCount).toBe(1) // only A
		expect(result.skippedCount).toBe(2)
		expect(result.errors.find(e => e.row === 2)?.code).toBe('CSV_INVALID_PRODUCT_ID')
		expect(result.errors.find(e => e.row === 3)?.code).toBe('CSV_INVALID_QUANTITY')
	})

	it('handles kit-scoped rows (productId="null") as a distinct uniqueness slot', async () => {
		const result = await useCase.execute({ ...base, csvContent: [HEADER, row({ productId: 'null', costType: 'MULTIPLE' })].join('\n') })
		expect(result.createdCount).toBe(1)
		const kit = await repo.findByStoreAndProduct(STORE, null)
		expect(kit?.productId).toBeNull()
		expect(kit?.costType).toBe(ProductCostType.MULTIPLE)
	})
})

describe('ImportProductCostsFromCsv (C30) — SHOPIFY', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: ImportProductCostsFromCsv
	let repo: ProductCostRepository
	let db: ReturnType<typeof testBed.resolve<typeof DrizzleClient>>
	let storeIntegrationId: string

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer })
		useCase = testBed.resolve(ImportProductCostsFromCsv)
		repo = testBed.resolve(ProductCostRepository)
		db = testBed.resolve(DrizzleClient) as any
	})
	beforeEach(async () => {
		await testBed.reset()
		// Seed the StoreIntegration the use case derives, and stamp the products /
		// variants with its id so the Shopify processor can resolve them by handle.
		const integration = await givenStoreIntegration(testBed, { storeId: STORE, ownerId: testBed.ownerId() })
		storeIntegrationId = integration.id.value
		await db.insert(products).values({
			id: PRODUCT_SHIRT,
			storeId: STORE,
			storeIntegrationId,
			storeIntegrationExternalId: integration.externalId,
			platform: 'SHOPIFY',
			externalId: 'gid-shirt',
			title: 'The Shirt',
			handle: 'the-shirt',
			status: 'ACTIVE',
			externalCreatedAt: new Date('2026-01-01T00:00:00Z'),
		})
		await db.insert(variants).values([
			{
				id: VARIANT_BM,
				productId: PRODUCT_SHIRT,
				storeIntegrationId,
				storeIntegrationExternalId: integration.externalId,
				platform: 'SHOPIFY',
				externalId: 'v-bm',
				productExternalId: 'gid-shirt',
				title: 'Black / M',
				status: 'ACTIVE',
				externalCreatedAt: new Date('2026-01-01T00:00:00Z'),
			},
			{
				id: VARIANT_BL,
				productId: PRODUCT_SHIRT,
				storeIntegrationId,
				storeIntegrationExternalId: integration.externalId,
				platform: 'SHOPIFY',
				externalId: 'v-bl',
				productExternalId: 'gid-shirt',
				title: 'Black / L',
				status: 'ACTIVE',
				externalCreatedAt: new Date('2026-01-01T00:00:00Z'),
			},
		])
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents<E extends BaseDomainEvent>(eventClass: DomainEventConstructor<E>) {
		return testBed.resolve(DomainEventRepository).findByType(eventClass)
	}

	const base = {
		userId: USER,
		storeId: STORE,
		provider: ProductCostCsvProvider.SHOPIFY as const,
		currency: CurrencyCode.USD,
		effectiveDate: '2026-05-01',
	}

	const SHOPIFY_CSV = [
		'Handle,Title,Option1 Name,Option1 Value,Option2 Name,Option2 Value,Cost per item',
		'the-shirt,The Shirt,Color,Black,Size,M,12.50',
		'the-shirt,The Shirt,Color,Black,Size,L,13.00',
	].join('\n')

	it('imports a real Shopify export CSV → one ProductCost with a SINGLE item per resolved variant', async () => {
		const result = await useCase.execute({ ...base, csvContent: SHOPIFY_CSV })

		expect(result.createdCount).toBe(1)
		expect(result.skippedCount).toBe(0)
		expect(result.errors).toEqual([])

		const cost = await repo.findByStoreAndProduct(STORE, PRODUCT_SHIRT)
		expect(cost).not.toBeNull()
		expect(cost!.options).toHaveLength(1)

		const items = cost!.options[0]!.items
		expect(items).toHaveLength(2)

		const itemBm = items.find(i => i.variantIds.some(vid => vid.value === VARIANT_BM))
		const itemBl = items.find(i => i.variantIds.some(vid => vid.value === VARIANT_BL))
		expect(itemBm).not.toBeUndefined()
		expect(itemBl).not.toBeUndefined()
		expect(itemBm!.unitCost.amountCents).toBe(1250)
		expect(itemBl!.unitCost.amountCents).toBe(1300)

		expect(await readEvents(ProductCostCreatedEvent)).toHaveLength(1)
	})

	it('skips rows whose handle or variant title does not resolve, with typed codes', async () => {
		const csv = [
			'Handle,Title,Option1 Name,Option1 Value,Option2 Name,Option2 Value,Cost per item',
			'the-shirt,The Shirt,Color,Black,Size,M,12.50',
			'unknown-handle,Unknown,Color,Black,Size,M,10.00',
			'the-shirt,The Shirt,Color,Red,Size,XL,11.00',
		].join('\n')

		const result = await useCase.execute({ ...base, csvContent: csv })

		expect(result.createdCount).toBe(1)
		expect(result.skippedCount).toBe(2)

		const unknownHandle = result.errors.find(e => e.code === 'CSV_UNKNOWN_HANDLE')
		const unresolvedVariant = result.errors.find(e => e.code === 'CSV_UNRESOLVED_VARIANT')
		expect(unknownHandle).not.toBeUndefined()
		expect(unknownHandle!.value).toBe('unknown-handle')
		expect(unresolvedVariant).not.toBeUndefined()
		expect(unresolvedVariant!.value).toBe('Red / XL')
	})
})

