import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { feesConfiguration } from '@bk-dash/contracts/db'
import type Z from 'zod'
import { Fees, FeesSchema } from '../../entities/Fees'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

type FeesInput = Z.input<typeof FeesSchema>

/**
 * Drizzle-backed FeesConfigurationRepository.
 *
 * One row per Store (UNIQUE on store_id). The three fee collections are
 * embedded jsonb timeline arrays — `z.coerce.date()` in the entity
 * schema rehydrates stored ISO strings back to Date on read, so
 * `toDomain` passes raw jsonb straight through `new Fees`.
 *
 * `save` upserts on `id` (the aggregate's own PK) so a second call on
 * the same entity updates rather than inserts. The unique index on
 * `store_id` is the DB-level guard that enforces one-row-per-store.
 */
@injectable()
export class DrizzleFeesConfigurationRepository extends FeesConfigurationRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<Fees | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(feesConfiguration).where(eq(feesConfiguration.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreId(storeId: string, tx?: DrizzleClient): Promise<Fees | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(feesConfiguration).where(eq(feesConfiguration.storeId, storeId)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: Fees, tx?: DrizzleClient): Promise<Fees> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(feesConfiguration)
				.values(data)
				.onConflictDoUpdate({
					target: feesConfiguration.id,
					set: {
						storeId: data.storeId,
						gatewayFees: data.gatewayFees,
						checkoutFee: data.checkoutFee,
						shippingFee: data.shippingFee,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(feesConfiguration).where(eq(feesConfiguration.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof feesConfiguration.$inferSelect): Fees {
		// z.coerce.date() in GatewayFeeSchema / CheckoutFeeSchema / ShippingFeeSchema
		// converts stored ISO strings back to Date objects during entity validation.
		return new Fees({
			id: row.id,
			storeId: row.storeId,
			gatewayFees: (row.gatewayFees as unknown[]) ?? [],
			checkoutFee: (row.checkoutFee as unknown[]) ?? [],
			shippingFee: (row.shippingFee as unknown[]) ?? [],
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: Fees): typeof feesConfiguration.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			gatewayFees: entity.gatewayFees,
			checkoutFee: entity.checkoutFee,
			shippingFee: entity.shippingFee,
			version: entity.version,
		}
	}
}

import { AggregateRoot, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const FxRateSchema = z.object({
	fromCurrency: z.enum(CurrencyCode),
	toCurrency: z.enum(CurrencyCode),
	/** Rate carried as string to preserve provider-side decimal precision. */
	rate: z.string(),
	startDate: z.date(),
})

export type FxRateProps = Z.infer<typeof FxRateSchema>

/**
 * `FxRate` aggregate per spec § 1.2 FX Management. Captured rates form a
 * historical series; consumers (ResolveFxRate) pick the latest entry
 * with `startDate <= asOf` for a (from, to) pair.
 *
 * Identity rates (from == to) are derived in code (always "1.0"), not
 * persisted.
 */
export class FxRate extends AggregateRoot<typeof FxRateSchema> {
	static override schema = FxRateSchema

	static create(data: {
		fromCurrency: CurrencyCode
		toCurrency: CurrencyCode
		rate: string
		startDate: Date
	}): FxRate {
		return new FxRate({ ...data })
	}
}

export interface FxRate extends FxRateProps {}

