import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { CreateWarrantyReserve, CreateWarrantyReserveOutputSchema } from '../usecases/CreateWarrantyReserve'

export const CreateWarrantyReserveControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), session: z.object({ storeId: z.uuid() }) }),
	body: z.object({
		rate: z.number().min(0).max(100),
		effectiveFrom: z.stringToDate(),
	}),
})

export const CreateWarrantyReserveControllerOutputSchema = CreateWarrantyReserveOutputSchema

@injectable()
export class CreateWarrantyReserveController extends Controller<
	typeof CreateWarrantyReserveControllerInputSchema,
	typeof CreateWarrantyReserveControllerOutputSchema
> {
	readonly path = '/warranty-reserves'
	readonly method = 'post' as const
	readonly description = 'Create warranty reserve rule (C45)'
	readonly inputSchema = CreateWarrantyReserveControllerInputSchema
	readonly outputSchema = CreateWarrantyReserveControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: CreateWarrantyReserve) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.session.storeId,
			rate: request.body.rate,
			effectiveFrom: request.body.effectiveFrom,
		})
		return { status: HttpStatusCode.CREATED, data }
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { WarrantyReserve } from '../entities/WarrantyReserve'
import { WarrantyReserveRepository } from '../repositories/WarrantyReserveRepository'
import { WarrantyReserveCreatedEvent } from '../events'

export const CreateWarrantyReserveInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	/** Rate as a 0..100 percentage. */
	rate: z.number().min(0).max(100),
	effectiveFrom: z.date(),
})

export const CreateWarrantyReserveOutputSchema = z.object({
	warrantyReserveId: z.uuid(),
})

/**
 * C45 CreateWarrantyReserve. Opens a new time-effective row, superseding
 * the previously-active reserve by stamping its `effectiveTo`. Rate is
 * persisted as a 0..1 fraction.
 */
@injectable()
export class CreateWarrantyReserve extends Handler<typeof CreateWarrantyReserveInputSchema, typeof CreateWarrantyReserveOutputSchema> {
	readonly name = 'create_warranty_reserve' as const
	readonly inputSchema = CreateWarrantyReserveInputSchema
	readonly outputSchema = CreateWarrantyReserveOutputSchema

	constructor(private readonly warranties: WarrantyReserveRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const previous = await this.warranties.findActiveByStoreId(input.storeId, tx)
			if (previous) {
				previous.supersede(input.effectiveFrom)
				await this.warranties.save(previous, tx)
			}

			const fresh = WarrantyReserve.create({
				storeId: input.storeId,
				rate: input.rate / 100,
				effectiveFrom: input.effectiveFrom,
			})
			await this.warranties.save(fresh, tx)

			await this.domainEventRepository.save(
				new WarrantyReserveCreatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: {
						warrantyReserve: fresh.toJSON(),
						previousWarrantyReserveId: previous?.id.value ?? null,
					},
				}),
				tx,
			)

			return { warrantyReserveId: fresh.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { ProductCostCsvProvider } from '../enums'
import { ImportProductCostsFromCsv, ImportProductCostsFromCsvOutputSchema } from '../usecases/ImportProductCostsFromCsv'

const baseBody = { csvContent: z.string().min(1) }

export const ImportProductCostsFromCsvControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), session: z.object({ storeId: z.uuid() }) }),
	body: z.discriminatedUnion('provider', [
		z.object({ provider: z.literal(ProductCostCsvProvider.MANUAL), ...baseBody }),
		z.object({
			provider: z.literal(ProductCostCsvProvider.SHOPIFY),
			...baseBody,
			currency: z.enum(CurrencyCode),
			effectiveDate: z.iso.date(),
			endDate: z.iso.date().optional(),
		}),
	]),
})

export const ImportProductCostsFromCsvControllerOutputSchema = ImportProductCostsFromCsvOutputSchema

@injectable()
export class ImportProductCostsFromCsvController extends Controller<
	typeof ImportProductCostsFromCsvControllerInputSchema,
	typeof ImportProductCostsFromCsvControllerOutputSchema
> {
	readonly path = '/product-costs/import-csv'
	readonly method = 'post' as const
	readonly description = 'Import ProductCosts from CSV (C30)'
	readonly inputSchema = ImportProductCostsFromCsvControllerInputSchema
	readonly outputSchema = ImportProductCostsFromCsvControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: ImportProductCostsFromCsv) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			...request.body,
			userId: request.ctx.user.id,
			storeId: request.ctx.session.storeId,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

