import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { WarrantyReserveRepository } from '../repositories/WarrantyReserveRepository'
import { WarrantyReserveDeletedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'

export const DeleteWarrantyReserveInputSchema = z.object({
	userId: z.uuid(),
	ids: z.array(z.uuid()).min(1),
})

export const DeleteWarrantyReserveOutputSchema = z.void()

/** C47 DeleteWarrantyReserve. Soft-deletes each id; preserves historical reserve trail; emits one event per entity. */
@injectable()
export class DeleteWarrantyReserve extends Handler<typeof DeleteWarrantyReserveInputSchema, typeof DeleteWarrantyReserveOutputSchema> {
	readonly name = 'delete_warranty_reserve' as const
	readonly inputSchema = DeleteWarrantyReserveInputSchema
	readonly outputSchema = DeleteWarrantyReserveOutputSchema

	constructor(private readonly warranties: WarrantyReserveRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		await this.withTransaction(tx, async tx => {
			for (const id of input.ids) {
				const entity = await this.warranties.findById(id, tx)
				if (!entity || entity.isDeleted) {
					throw new BaseError<FinanceApplicationErrors>('WARRANTY_RESERVE_NOT_FOUND')
				}

				entity.delete()
				await this.warranties.save(entity, tx)
				await this.domainEventRepository.save(
					new WarrantyReserveDeletedEvent({
						entityId: entity.id.value,
						ownerId: entity.storeId.value,
						payload: { warrantyReserveId: entity.id.value, storeId: entity.storeId.value },
					}),
					tx,
				)
			}
		})

		return
	}
}

