import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const GetFxRatesInputSchema = z.object({
	fromCurrency: z.enum(CurrencyCode).optional(),
	toCurrency: z.enum(CurrencyCode).optional(),
	from: z.date().optional(),
	to: z.date().optional(),
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(500).default(100),
})

export const GetFxRatesOutputSchema = z.object({
	total: z.number().int().min(0),
	items: z.array(
		z.object({
			fromCurrency: z.enum(CurrencyCode),
			toCurrency: z.enum(CurrencyCode),
			rate: z.string(),
			startDate: z.date(),
		}),
	),
})

/** T28 GetFxRates. Paginated historical series across all (from, to) pairs. */
@injectable()
export class GetFxRates extends Handler<typeof GetFxRatesInputSchema, typeof GetFxRatesOutputSchema> {
	readonly name = 'get_fx_rates' as const
	readonly inputSchema = GetFxRatesInputSchema
	readonly outputSchema = GetFxRatesOutputSchema

	constructor(private readonly fxRates: FxRateRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const result = await this.fxRates.list(
			{
				fromCurrency: input.fromCurrency,
				toCurrency: input.toCurrency,
				from: input.from,
				to: input.to,
				page: input.page,
				limit: input.limit,
			},
			tx,
		)
		return {
			total: result.total,
			items: result.items.map(r => ({
				fromCurrency: r.fromCurrency,
				toCurrency: r.toCurrency,
				rate: r.rate,
				startDate: r.startDate,
			})),
		}
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { ProductOverride } from '../entities/ProductOverride'
import { ProductOverrideRepository } from '../repositories/ProductOverrideRepository'
import { ProductTagAddedEvent } from '../events'
import type { CatalogDomainErrors } from '../errors'

export const AddProductTagInputSchema = z.object({
	userId: z.uuid(),
	productId: z.uuid(),
	storeId: z.uuid(),
	tag: z.string().min(1).max(100),
})

export const AddProductTagOutputSchema = z.void()

/**
 * C31 AddProductTag. Tags live on a TS-owned ProductOverride overlay
 * (SPEC-10) — find-or-create the override for (productId, storeId) and
 * append the tag. Idempotent: re-adding an existing tag is a no-op and
 * does not emit a duplicate event.
 */
@injectable()
export class AddProductTag extends Handler<typeof AddProductTagInputSchema, typeof AddProductTagOutputSchema> {
	readonly name = 'add_product_tag' as const
	readonly inputSchema = AddProductTagInputSchema
	readonly outputSchema = AddProductTagOutputSchema

	constructor(private readonly overrides: ProductOverrideRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		if (input.tag.length > 100) {
			throw new BaseError<CatalogDomainErrors>('TAG_TOO_LONG')
		}

		await this.withTransaction(tx, async tx => {
			let override = await this.overrides.findByProductAndStore(input.productId, input.storeId, tx)
			if (!override) {
				override = ProductOverride.create({ productId: input.productId, storeId: input.storeId, tags: [] })
			}
			const added = override.addTag(input.tag)
			if (!added) return

			await this.overrides.save(override, tx)
			await this.domainEventRepository.save(
				new ProductTagAddedEvent({
					entityId: input.productId,
					ownerId: input.storeId,
					payload: {
						productId: input.productId,
						storeId: input.storeId,
						tag: input.tag,
					},
				}),
				tx,
			)
		})

		return
	}
}

