import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Role as TenancyRole } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreMembership } from '../entities/StoreMembership'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { StoreInvitationRepository } from '../repositories/StoreInvitationRepository'
import { InvitationTokenService } from '../services/InvitationTokenService'
import { StoreMemberAddedEvent } from '../events'
import type { ApplicationErrors } from '../errors'

export const AcceptInvitationInputSchema = z.object({
	// Fails closed when no session userId (controller layer enforces upstream;
	// use case still validates as non-empty).
	userId: z.uuid(),
	invitationToken: z.string().min(1),
})

export const AcceptInvitationOutputSchema = z.object({
	storeId: z.uuid(),
	role: z.enum(TenancyRole),
})

@injectable()
export class AcceptInvitation extends Handler<typeof AcceptInvitationInputSchema, typeof AcceptInvitationOutputSchema> {
	readonly name = 'accept_invitation' as const
	readonly inputSchema = AcceptInvitationInputSchema
	readonly outputSchema = AcceptInvitationOutputSchema

	constructor(
		private readonly invitations: StoreInvitationRepository,
		private readonly memberships: StoreMembershipRepository,
		private readonly tokens: InvitationTokenService,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		// Envelope decode — throws INVALID_INVITATION_TOKEN / INVITATION_EXPIRED.
		const payload = this.tokens.verify(input.invitationToken)

		const invitation = await this.invitations.findById(payload.sid, tx)
		// A non-existent sid is treated as INVALID — the envelope was signed
		// but no row matches (data drift / dev-env reset).
		if (!invitation) throw new BaseError<ApplicationErrors>('INVALID_INVITATION_TOKEN')

		// Entity-layer hash check + acceptedAt/expiresAt guards. Throws
		// INVALID_INVITATION_TOKEN / INVITATION_EXPIRED / INVITATION_ALREADY_USED.
		invitation.accept({ userId: input.userId, plainToken: payload.plainToken })

		return this.withTransaction(tx, async tx => {
			await this.invitations.save(invitation, tx)

			const membership = StoreMembership.forInvitee({
				storeId: invitation.storeId.value,
				userId: input.userId,
				role: invitation.role as TenancyRole,
			})
			await this.memberships.save(membership, tx)

			await this.domainEventRepository.save(
				new StoreMemberAddedEvent({
					entityId: invitation.storeId.value,
					ownerId: input.userId,
					payload: {
						storeId: invitation.storeId.value,
						storeMembershipId: membership.id.value,
						userId: input.userId,
						role: invitation.role as TenancyRole,
					},
				}),
				tx,
			)

			return { storeId: invitation.storeId.value, role: invitation.role as TenancyRole }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Role as TenancyRole } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { StoreMemberRoleChangedEvent } from '../events'
import type { ApplicationErrors, DomainErrors } from '../errors'

export const ChangeMemberRoleInputSchema = z.object({
	storeId: z.uuid(),
	// userIds of the members to re-role under `storeId`. Bulk: `newRole` applied
	// to all of them, one StoreMemberRoleChangedEvent emitted per actual change.
	ids: z.array(z.uuid()).min(1),
	newRole: z.enum(TenancyRole),
})

export const ChangeMemberRoleOutputSchema = z.void()

@injectable()
export class ChangeMemberRole extends Handler<typeof ChangeMemberRoleInputSchema, typeof ChangeMemberRoleOutputSchema> {
	readonly name = 'change_member_role' as const
	readonly inputSchema = ChangeMemberRoleInputSchema
	readonly outputSchema = ChangeMemberRoleOutputSchema

	constructor(private readonly memberships: StoreMembershipRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			// LAST_OWNER guard across the whole batch: track the live OWNER count
			// and block any demotion that would leave the store ownerless.
			let ownersRemaining = await this.memberships.countOwnersByStoreId(input.storeId, tx)

			for (const userId of input.ids) {
				const membership = await this.memberships.findByStoreAndUser(input.storeId, userId, tx)
				if (!membership) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

				// No-op: same role → no save, no event.
				if (membership.role === input.newRole) continue

				if (membership.role === TenancyRole.OWNER && input.newRole !== TenancyRole.OWNER) {
					if (ownersRemaining <= 1) throw new BaseError<DomainErrors>('CANNOT_DEMOTE_LAST_OWNER')
					ownersRemaining -= 1
				}

				const oldRole = membership.role
				membership.changeRole(input.newRole)

				await this.memberships.save(membership, tx)
				await this.domainEventRepository.save(
					new StoreMemberRoleChangedEvent({
						entityId: input.storeId,
						ownerId: userId,
						payload: {
							storeId: input.storeId,
							storeMembershipId: membership.id.value,
							userId,
							oldRole,
							newRole: input.newRole,
						},
					}),
					tx,
				)
			}
		})
	}
}

