	errors: z.array(
		z.object({
			row: z.number().int().min(0),
			/** A CatalogCsvImportErrors code (registered, i18n-able) — never a raw message. */
			code: z.string(),
			/** The offending raw cell value, for display/debug. */
			value: z.string().optional(),
		}),
	),
})

/**
 * C30 ImportProductCostsFromCsv. The owning StoreIntegration is derived from
 * the active storeId (the controller no longer accepts it). Routes on
 * `provider` through the ProductCostCsvParser facade (parser + processor per
 * provider), then persists the resulting per-product builds in one transaction
 * via saveMany + DomainEventRepository.saveMany — one Created/Updated event per
 * aggregate. Partial-success: per-row failures accumulate as typed `errors[]`
 * codes.
 */
@injectable()
export class ImportProductCostsFromCsv extends Handler<
	typeof ImportProductCostsFromCsvInputSchema,
	typeof ImportProductCostsFromCsvOutputSchema
> {
	readonly name = 'import_product_costs_from_csv' as const
	readonly inputSchema = ImportProductCostsFromCsvInputSchema
	readonly outputSchema = ImportProductCostsFromCsvOutputSchema

	constructor(
		private readonly productCosts: ProductCostRepository,
		private readonly csvParser: ProductCostCsvParser,
		private readonly storeIntegrations: StoreIntegrationRepository,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const integrations = await this.storeIntegrations.findByStoreId(input.storeId, tx)
		const integration = integrations[0]
		if (!integration) {
			throw new BaseError<CatalogApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		const storeIntegrationId = integration.id.value

		const { builds, errors } = await this.csvParser.parse({
			provider: input.provider,
			csvContent: input.csvContent,
			storeId: input.storeId,
			storeIntegrationId,
			currency: input.provider === ProductCostCsvProvider.SHOPIFY ? input.currency : undefined,
			effectiveDate: input.provider === ProductCostCsvProvider.SHOPIFY ? input.effectiveDate : undefined,
			endDate: input.provider === ProductCostCsvProvider.SHOPIFY ? input.endDate : undefined,
		})

		const rowErrors: { row: number; code: string; value?: string }[] = [...errors]
		const toSave: ProductCost[] = []
		const events: BaseDomainEvent[] = []
		let createdCount = 0
		let updatedCount = 0

		await this.withTransaction(tx, async tx => {
			const productIds = [...new Set(builds.map(b => b.productId))]
			const existingList = productIds.length > 0 ? await this.productCosts.findByStoreAndProducts(input.storeId, productIds, tx) : []
			const existingByProduct = new Map<string | null, ProductCost>(existingList.map(e => [e.productId?.value ?? null, e]))

			for (const build of builds) {
				const existing = existingByProduct.get(build.productId)
				if (existing) {
					const r = tryCatch(() =>
						existing.update({
							options: [
								...existing.options.map(o => {
									const json = o.toJSON()
									return {
										...json,
										startDate: new Date(json.startDate).toISOString().slice(0, 10),
										endDate: json.endDate != null ? new Date(json.endDate).toISOString().slice(0, 10) : undefined,
									}
								}),
								...build.options,
							],
						}),
					)
					if (!r.success) {
						rowErrors.push({ row: build.sourceRows[0]!, code: 'CSV_ROW_INVALID', value: errorMessage(r.error) })
						continue
					}
					toSave.push(existing)
					events.push(
						new ProductCostUpdatedEvent({
							entityId: existing.id.value,
							ownerId: existing.storeId.value,
							payload: { productCost: existing.toJSON() },
						}),
					)
					updatedCount++
				} else {
					const r = tryCatch(() =>
						ProductCost.create({
							storeId: input.storeId,
							storeIntegrationId,
							productId: build.productId,
							costType: build.costType,
							options: build.options,
						}),
					)
					if (!r.success) {
						rowErrors.push({ row: build.sourceRows[0]!, code: 'CSV_ROW_INVALID', value: errorMessage(r.error) })
						continue
					}
					toSave.push(r.data)
					events.push(
						new ProductCostCreatedEvent({
							entityId: r.data.id.value,
							ownerId: r.data.storeId.value,
							payload: { productCost: r.data.toJSON() },
						}),
					)
					createdCount++
				}
			}

			if (toSave.length > 0) await this.productCosts.saveMany(toSave, tx)
			if (events.length > 0) await this.domainEventRepository.saveMany(events, tx)
		})

		return { createdCount, updatedCount, skippedCount: rowErrors.length, errors: rowErrors }
	}
}

function errorMessage(e: unknown): string {
	if (e instanceof Error) return e.message || e.name
	return String(e)
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { PlanFeature, Role as TenancyRole } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreRepository } from '../repositories/StoreRepository'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { SubscriptionQueryService } from '../services/SubscriptionQueryService'
import { PlanQuotaService } from '../services/PlanQuotaService'
import { StoreSubscriptionChangedEvent } from '../events'
import type { ApplicationErrors } from '../errors'

export const ChangeStoreSubscriptionInputSchema = z.object({
	storeId: z.uuid(),
	targetSubscriptionId: z.uuid(),
	userId: z.uuid(),
})

export const ChangeStoreSubscriptionOutputSchema = z.object({ storeId: z.uuid() })

/**
 * Reassigns a store whose subscription has ended onto another active
 * subscription the user owns. Guard (old-backend parity): only when the
 * store's CURRENT subscription is inactive. Validates the target is active,
 * owned by the user, and has a free slot.
 */
@injectable()
export class ChangeStoreSubscription extends Handler<
	typeof ChangeStoreSubscriptionInputSchema,
	typeof ChangeStoreSubscriptionOutputSchema
> {
	readonly name = 'change_store_subscription' as const
	readonly inputSchema = ChangeStoreSubscriptionInputSchema
	readonly outputSchema = ChangeStoreSubscriptionOutputSchema

	constructor(
		private readonly storeRepo: StoreRepository,
		private readonly membershipRepo: StoreMembershipRepository,
		private readonly subscriptionQuery: SubscriptionQueryService,
		private readonly planQuota: PlanQuotaService,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const store = await this.storeRepo.findById(input.storeId)
		if (!store) throw new BaseError<ApplicationErrors>('STORE_NOT_FOUND')

		const membership = await this.membershipRepo.findByStoreAndUser(input.storeId, input.userId)
		if (!membership || membership.role !== TenancyRole.OWNER) {
			throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')
		}

		// Guard: only reassign when the current subscription is inactive.
		const fromSubscriptionId = store.subscriptionId
		if (fromSubscriptionId) {
			const current = await this.subscriptionQuery.getSubscriptionById(fromSubscriptionId)
			if (current?.isActive) throw new BaseError<ApplicationErrors>('STORE_SUBSCRIPTION_STILL_ACTIVE')
		}

		// Validate the target: exists → owned → active → has a free slot.
		const target = await this.subscriptionQuery.getSubscriptionById(input.targetSubscriptionId)
		if (!target?.isActive) throw new BaseError<ApplicationErrors>('SUBSCRIPTION_NOT_FOUND')
		if (target.userId !== input.userId) throw new BaseError<ApplicationErrors>('SUBSCRIPTION_NOT_OWNED')

		const counts = await this.storeRepo.countStoresBySubscriptionIds([input.targetSubscriptionId])
		if ((counts[input.targetSubscriptionId] ?? 0) >= this.planQuota.quotaFor(target.tier, PlanFeature.STORE_AMOUNT)) {
			throw new BaseError<ApplicationErrors>('TARGET_SUBSCRIPTION_FULL')
		}

		return this.withTransaction(tx, async tx => {
			store.changeSubscription(input.targetSubscriptionId)
			await this.storeRepo.save(store, tx)
			await this.domainEventRepository.save(
				new StoreSubscriptionChangedEvent({
					entityId: store.id.value,
					ownerId: input.userId,
					payload: {
						storeId: store.id.value,
						fromSubscriptionId,
						toSubscriptionId: input.targetSubscriptionId,
					},
				}),
				tx,
			)
			return { storeId: store.id.value }
		})
	}
}

