/**
 * C32 RemoveProductTag. Tags live on a TS-owned ProductOverride overlay
 * (SPEC-10). Idempotent: removing a tag that isn't present (or when no
 * override row exists at all) is a no-op.
 */
@injectable()
export class RemoveProductTag extends Handler<typeof RemoveProductTagInputSchema, typeof RemoveProductTagOutputSchema> {
	readonly name = 'remove_product_tag' as const
	readonly inputSchema = RemoveProductTagInputSchema
	readonly outputSchema = RemoveProductTagOutputSchema

	constructor(private readonly overrides: ProductOverrideRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		await this.withTransaction(tx, async tx => {
			const override = await this.overrides.findByProductAndStore(input.productId, input.storeId, tx)
			if (!override) return

			const removed = override.removeTag(input.tag)
			if (!removed) return

			await this.overrides.save(override, tx)
			await this.domainEventRepository.save(
				new ProductTagRemovedEvent({
					entityId: input.productId,
					ownerId: input.storeId,
					payload: {
						productId: input.productId,
						storeId: input.storeId,
						tag: input.tag,
					},
				}),
				tx,
			)
		})

		return
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Role as TenancyRole, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { Store } from '../entities/Store'
import { StoreMembership } from '../entities/StoreMembership'
import { StoreRepository } from '../repositories/StoreRepository'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { PlanQuotaService } from '../services/PlanQuotaService'
import { StoreCreatedEvent, StoreMemberAddedEvent, StorePreferencesCreatedEvent } from '../events'

export const CreateStoreInputSchema = z.object({
	userId: z.uuid(),
	name: z.string().trim().min(1).max(120),
	reportingCurrency: z.enum(CurrencyCode),
	timezone: z.string().min(1),
	pictureUrl: z.url().optional(),
})

export const CreateStoreOutputSchema = z.object({
	storeId: z.uuid(),
})

@injectable()
export class CreateStore extends Handler<typeof CreateStoreInputSchema, typeof CreateStoreOutputSchema> {
	readonly name = 'create_store' as const
	readonly inputSchema = CreateStoreInputSchema
	readonly outputSchema = CreateStoreOutputSchema

	constructor(
		private readonly storeRepo: StoreRepository,
		private readonly membershipRepo: StoreMembershipRepository,
		private readonly planQuota: PlanQuotaService,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const { subscriptionId } = await this.planQuota.resolveSubscriptionForNewStore(input.userId, tx)

			// Entity validates name/timezone/email at construction; INVALID_TIMEZONE
			// propagates as a DomainError from the schema refinement.
			const store = Store.create({
				name: input.name,
				reportingCurrency: input.reportingCurrency,
				timezone: input.timezone,
				pictureUrl: input.pictureUrl,
				subscriptionId,
			})
			await this.storeRepo.save(store, tx)

			const ownership = StoreMembership.forOwner({
				storeId: store.id.value,
				userId: input.userId,
			})
			await this.membershipRepo.save(ownership, tx)

			await this.domainEventRepository.saveMany(
				[
					new StoreCreatedEvent({
						entityId: store.id.value,
						ownerId: input.userId,
						payload: {
							storeId: store.id.value,
							name: store.name,
						},
					}),
					new StorePreferencesCreatedEvent({
						entityId: store.id.value,
						ownerId: input.userId,
						payload: {
							storeId: store.id.value,
							reportingCurrency: input.reportingCurrency,
							timezone: input.timezone,
						},
					}),
					new StoreMemberAddedEvent({
						entityId: store.id.value,
						ownerId: input.userId,
						payload: {
							storeId: store.id.value,
							storeMembershipId: ownership.id.value,
							userId: input.userId,
							role: TenancyRole.OWNER,
						},
					}),
				],
				tx,
			)

			return { storeId: store.id.value }
		})
	}
}

