import { injectable } from 'tsyringe-neo'
import { BaseError, CredentialVault, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { CredentialHandleStore } from '../services/CredentialHandleStore'
import { IntegrationCredentialSecretRepository } from '../repositories/IntegrationCredentialSecretRepository'
import type { ApplicationErrors } from '../errors'

export const ExchangeCredentialsInputSchema = z.object({
	handle: z.string().min(1),
})

export const ExchangeCredentialsOutputSchema = z.object({
	credentials: z.record(z.string(), z.string()),
})

/**
 * Resolves a capability handle to its StoreIntegration, opens that integration's
 * sealed vault secret, and returns the plaintext. Multi-use within TTL — redelivery
 * of the activation event re-exchanges the same handle. The endpoint exposing this
 * is S2S-gated (InternalServiceKey middleware); the use case trusts the gate.
 */
@injectable()
export class ExchangeCredentials extends Handler<typeof ExchangeCredentialsInputSchema, typeof ExchangeCredentialsOutputSchema> {
	readonly name = 'exchange_credentials' as const
	readonly inputSchema = ExchangeCredentialsInputSchema
	readonly outputSchema = ExchangeCredentialsOutputSchema

	constructor(
		private readonly handles: CredentialHandleStore,
		private readonly credentialSecretRepo: IntegrationCredentialSecretRepository,
		private readonly vault: CredentialVault,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const storeIntegrationId = await this.handles.resolve(input.handle)
		if (storeIntegrationId === undefined) {
			throw new BaseError<ApplicationErrors>('CREDENTIAL_HANDLE_INVALID')
		}
		const secret = await this.credentialSecretRepo.findByStoreIntegrationId(storeIntegrationId, tx)
		if (secret === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_CREDENTIAL_NOT_FOUND')
		}
		const credentials = await this.vault.open<Record<string, string>>({
			encryptionAlgorithm: secret.encryptionAlgorithm,
			encryptedPayload: secret.encryptedPayload,
		})
		return { credentials }
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Role as TenancyRole } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { StoreMemberRemovedEvent } from '../events'
import type { ApplicationErrors, DomainErrors } from '../errors'

export const RemoveMemberInputSchema = z.object({
	storeId: z.uuid(),
	// userIds of the members to remove under `storeId`. Bulk: all removed in one
	// call, one StoreMemberRemovedEvent emitted per member.
	ids: z.array(z.uuid()).min(1),
})

export const RemoveMemberOutputSchema = z.object({
	removed: z.boolean(),
})

@injectable()
export class RemoveMember extends Handler<typeof RemoveMemberInputSchema, typeof RemoveMemberOutputSchema> {
	readonly name = 'remove_member' as const
	readonly inputSchema = RemoveMemberInputSchema
	readonly outputSchema = RemoveMemberOutputSchema

	constructor(private readonly memberships: StoreMembershipRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			// LAST_OWNER guard across the whole batch: track the live OWNER count
			// and block any removal that would leave the store ownerless.
			let ownersRemaining = await this.memberships.countOwnersByStoreId(input.storeId, tx)

			for (const userId of input.ids) {
				const membership = await this.memberships.findByStoreAndUser(input.storeId, userId, tx)
				if (!membership) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

				if (membership.role === TenancyRole.OWNER) {
					if (ownersRemaining <= 1) throw new BaseError<DomainErrors>('CANNOT_REMOVE_LAST_OWNER')
					ownersRemaining -= 1
				}

				await this.memberships.removeByStoreAndUser(input.storeId, userId, tx)
				await this.domainEventRepository.save(
					new StoreMemberRemovedEvent({
						entityId: input.storeId,
						ownerId: userId,
						payload: {
							storeId: input.storeId,
							storeMembershipId: membership.id.value,
							userId,
						},
					}),
					tx,
				)
			}

			return { removed: true }
		})
	}
}

