export const SetActiveStoreInputSchema = z.object({
	storeId: z.string(),
	userId: z.uuid(),
	sessionId: z.string(),
})

export const SetActiveStoreOutputSchema = z.object({
	storeId: z.string(),
})

@injectable()
export class SetActiveStore extends Handler<typeof SetActiveStoreInputSchema, typeof SetActiveStoreOutputSchema> {
	readonly name = 'set_active_store' as const
	readonly inputSchema = SetActiveStoreInputSchema
	readonly outputSchema = SetActiveStoreOutputSchema

	constructor(private readonly membershipRepo: StoreMembershipRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		const { storeId, userId, sessionId } = input

		// Guard: user must be a member of the target store.
		const membership = await this.membershipRepo.findByStoreAndUser(storeId, userId)
		if (!membership) {
			throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')
		}

		// Targeted single-column update on authentication.sessions — no entity/UoW
		// needed for this session mutation (same targeted-update pattern as the
		// better-auth sign-in hook). No domain event is raised (no aggregate changes
		// state).
		const db = this.di.resolve(DrizzleClient as any) as DrizzleClient
		await db.update(sessions).set({ activeStoreId: storeId, updatedAt: new Date() }).where(eq(sessions.id, sessionId))

		// Bump lastAccess on the membership (spec: "may bump").
		membership.touchAccess(new Date())
		await this.membershipRepo.save(membership)

		return { storeId }
	}
}

