import { injectable } from 'tsyringe-neo'
import { Handler, Id, z } from '@bk-dash/core-typescript'
import { BillingPlatform, PlanTier } from '@bk-dash/contracts-typescript/wire/enums'
import { Subscription } from '../entities/Subscription'
import { SubscriptionRepository } from '../repositories/SubscriptionRepository'
import { SubscriptionCreatedEvent } from '../events'

export const GrantInternalSubscriptionInputSchema = z.object({
	userId: z.uuid(),
	tier: z.enum(PlanTier),
})

export const GrantInternalSubscriptionOutputSchema = z.object({
	subscriptionId: z.uuid(),
})

/**
 * Grants a subscription with no purchase. Each call mints a new bucket: a
 * fresh INTERNAL subscription with `internal:<uuid>` as external id, active
 * immediately. Reuses SubscriptionCreatedEvent so the quota publisher fires
 * exactly like the webhook CREATED path. Guarded by InternalSecretKeyMiddleware.
 */
@injectable()
export class GrantInternalSubscription extends Handler<
	typeof GrantInternalSubscriptionInputSchema,
	typeof GrantInternalSubscriptionOutputSchema
> {
	readonly name = 'grant_internal_subscription' as const
	readonly inputSchema = GrantInternalSubscriptionInputSchema
	readonly outputSchema = GrantInternalSubscriptionOutputSchema

	constructor(private readonly subscriptions: SubscriptionRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		return this.withTransaction(undefined, async tx => {
			const externalSubscriptionId = `internal:${Id.value()}`
			const subscription = Subscription.create({
				userId: input.userId,
				platform: BillingPlatform.INTERNAL,
				externalSubscriptionId,
				tier: input.tier,
				period: null,
			})
			await this.subscriptions.save(subscription, tx)
			await this.domainEventRepository.save(
				new SubscriptionCreatedEvent({
					entityId: subscription.id.value,
					ownerId: input.userId,
					payload: {
						externalId: externalSubscriptionId,
						platform: BillingPlatform.INTERNAL,
						tier: input.tier,
						userId: input.userId,
						period: null,
					},
				}),
				tx,
			)
			return { subscriptionId: subscription.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, Id, SerializedRequest, z, type Transaction } from '@bk-dash/core-typescript'
import { BillingWebhookReceivedEvent } from '../events'
import { BillingWebhookVerifierFactory } from '../services'
import type { InterfaceErrors } from '../errors'
import { BillingPlatform } from '@bk-dash/contracts-typescript/wire/enums'

export const HandleBillingWebhookInputSchema = z.object({
	platform: z.enum(BillingPlatform),
	// The whole inbound request. The verifier reads its own signature + signed
	// bytes off it; the use case snapshots it into the received event.
	rawRequest: z.instanceof(Request),
})

export const HandleBillingWebhookOutputSchema = z.void()

/**
 * Dumb ingest — the single billing-webhook entry point.
 *
 * Steps:
 *  1. Resolve the platform verifier via the factory → BILLING_WEBHOOK_UNKNOWN_PLATFORM
 *     when none is registered.
 *  2. Snapshot the request into a SerializedRequest and verify it →
 *     BILLING_WEBHOOK_SIGNATURE_INVALID. Verifying the rehydrated snapshot
 *     guarantees we verify exactly the bytes we persist.
 *  3. Build a deterministic externalEventId from a content hash of the raw body
 *     — re-deliveries of the same body dedupe without knowing the provider's
 *     delivery-id field.
 *  4. saveIfNotExists(BillingWebhookReceivedEvent) — duplicate delivery → ack.
 *
 * No mapper call. No derived events. The BillingWebhookReceivedHandler reads
 * BillingWebhookReceivedEvent from the outbox and invokes the mapper.
 */
@injectable()
export class HandleBillingWebhook extends Handler<typeof HandleBillingWebhookInputSchema, typeof HandleBillingWebhookOutputSchema> {
	readonly name = 'handle_billing_webhook' as const
	readonly inputSchema = HandleBillingWebhookInputSchema
	readonly outputSchema = HandleBillingWebhookOutputSchema

	constructor(private readonly verifierFactory: BillingWebhookVerifierFactory) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const { platform, rawRequest } = input

		const verifier = this.verifierFactory.get(platform)

		if (!verifier) {
			throw new BaseError<InterfaceErrors>('BILLING_WEBHOOK_UNKNOWN_PLATFORM')
		}

		// Snapshot first: fromRequest clones the request and reads the clone, so the
		// source body stays unconsumed for the verifier. Verifying after would
		// otherwise read (and exhaust) the body, leaving an empty snapshot to persist.
		const serializedRequest = await SerializedRequest.fromRequest(rawRequest)

		if (!(await verifier.verify(rawRequest))) {
			throw new BaseError<InterfaceErrors>('BILLING_WEBHOOK_SIGNATURE_INVALID')
		}

		// Deterministic delivery id: a content hash of the raw body, stable across
		// re-deliveries — no need to know the provider's delivery-id field.
		const externalEventId = Id.fromSeed('billing', 'webhook', platform, serializedRequest.body).value
		const entityId = Id.fromSeed('billing', 'webhook', platform, externalEventId).value

		await this.withTransaction(tx, async tx => {
			const received = new BillingWebhookReceivedEvent({
				entityId,
				payload: {
					platform,
					externalEventId,
					rawRequest: serializedRequest.toJSON(),
				},
			})

			await this.domainEventRepository.saveIfNotExists(received, tx)
			// Duplicate delivery → no-op (saveIfNotExists returns false; we still return void).
		})
		return
	}
}

