import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { AdSpendManual, AdSpendManualSchema } from '../entities/AdSpendManual'
import Z from 'zod'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { ManualAdSpendRecordedEvent } from '../events'

export const CreateManualAdSpendInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	startDate: z.date(),
	endDate: z.date(),
	currency: z.enum(CurrencyCode),
	amountCents: z.number().int().positive(),
	description: z.string().optional(),
	name: z.string().optional(),
})

export const CreateManualAdSpendOutputSchema = z.object({
	adSpendId: z.uuid(),
})

/**
 * C33 CreateManualAdSpend. Materialises a MANUAL AdSpendManual (no provider
 * connection, no Go-worker sync — merchant-entered expense for ROAS
 * attribution). The entity's `create()` validates the date range.
 */
@injectable()
export class CreateManualAdSpend extends Handler<typeof CreateManualAdSpendInputSchema, typeof CreateManualAdSpendOutputSchema> {
	readonly name = 'create_manual_ad_spend' as const
	readonly inputSchema = CreateManualAdSpendInputSchema
	readonly outputSchema = CreateManualAdSpendOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const startDate = new Date(input.startDate)
			startDate.setUTCHours(0, 0, 0, 0)
			const endDate = new Date(input.endDate)
			endDate.setUTCHours(23, 59, 59, 999)

			const entity = AdSpendManual.create({
				storeId: input.storeId,
				// MANUAL rows have no platform.
				currency: input.currency,
				startDate,
				endDate,
				spend: { amountCents: input.amountCents, currency: input.currency },
				name: input.name,
				description: input.description,
			})

			await this.adSpends.save(entity, tx)

			await this.domainEventRepository.save(
				new ManualAdSpendRecordedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					// toJSON() serialises Id instances to strings; z.instance(Id) accepts
					// both at runtime — the cast bridges the TS mismatch.
					payload: { adSpend: entity.toJSON() as unknown as Z.infer<typeof AdSpendManualSchema> },
				}),
				tx,
			)

			return { adSpendId: entity.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { FxRate } from '../entities/FxRate'
import { FxRateRepository } from '../repositories/FxRateRepository'
import { FxRateCapturedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateFxRatesInputSchema = z.object({
	startDate: z.date(),
	rates: z
		.array(
			z.object({
				fromCurrency: z.enum(CurrencyCode),
				toCurrency: z.enum(CurrencyCode),
				rate: z.string(),
			}),
		)
		.min(1),
})

export const UpdateFxRatesOutputSchema = z.object({
	captured: z.number().int().nonnegative(),
})

/**
 * C48 UpdateFxRates. Per spec § 1.2 FX Management + § Scheduled Flows:
 * "Hourly: UpdateFxRates (TS) → FxRateCaptured." Persists a batch of
 * captured rates as new FxRate aggregates; each emits a
 * FxRateCapturedEvent so Analytics can invalidate profit-margin caches
 * that fold in the rate. Identity rates (from == to) are filtered out —
 * those are always "1.0" by the resolver short-circuit.
 *
 * Input is the rate payload coming from the scheduled fetcher (provider
 * stubbed for offline use). Use case is the seam: the fetcher reads the
 * provider, batches the per-pair list, and calls execute() once per
 * tick.
 */
@injectable()
export class UpdateFxRates extends Handler<typeof UpdateFxRatesInputSchema, typeof UpdateFxRatesOutputSchema> {
	readonly name = 'update_fx_rates' as const
	readonly inputSchema = UpdateFxRatesInputSchema
	readonly outputSchema = UpdateFxRatesOutputSchema

	constructor(private readonly fxRates: FxRateRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const nonIdentity = input.rates.filter(r => r.fromCurrency !== r.toCurrency)
		if (nonIdentity.length === 0) {
			throw new BaseError<FinanceApplicationErrors>('FX_RATE_CAPTURE_EMPTY')
		}

		return this.withTransaction(tx, async tx => {
			let captured = 0
			for (const r of nonIdentity) {
				const entity = FxRate.create({
					fromCurrency: r.fromCurrency,
					toCurrency: r.toCurrency,
					rate: r.rate,
					startDate: input.startDate,
				})
				await this.fxRates.save(entity, tx)
				await this.domainEventRepository.save(
					new FxRateCapturedEvent({
						entityId: entity.id.value,
						payload: {
							fxRateId: entity.id.value,
							fromCurrency: r.fromCurrency,
							toCurrency: r.toCurrency,
							rate: r.rate,
							startDate: input.startDate,
						},
					}),
					tx,
				)
				captured++
			}
			return { captured }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { ManualAdSpendDeletedEvent } from '../events'
import type { MarketingApplicationErrors } from '../errors'

export const DeleteManualAdSpendInputSchema = z.object({
	userId: z.uuid(),
	ids: z.array(z.uuid()).min(1),
})

export const DeleteManualAdSpendOutputSchema = z.void()

/**
 * C35 DeleteManualAdSpend. Bulk hard delete (no historical attribution
 * requirement per spec, unlike ProductCost) of one or more MANUAL
 * AdSpendManual rows by id. Emits one ManualAdSpendDeletedEvent per row
 * before the actual delete so the row identity is still available for the
 * event payload. Throws AD_SPEND_NOT_FOUND if any id is missing.
 */
@injectable()
export class DeleteManualAdSpend extends Handler<typeof DeleteManualAdSpendInputSchema, typeof DeleteManualAdSpendOutputSchema> {
	readonly name = 'delete_manual_ad_spend' as const
	readonly inputSchema = DeleteManualAdSpendInputSchema
	readonly outputSchema = DeleteManualAdSpendOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		await this.withTransaction(tx, async tx => {
			for (const adSpendId of input.ids) {
				const entity = await this.adSpends.findById(adSpendId, tx)
				if (!entity) {
					throw new BaseError<MarketingApplicationErrors>('AD_SPEND_NOT_FOUND')
				}
				// All AdSpendManual rows are by definition MANUAL — guardManualOnly removed
				// in Spec β.2 D2 (AdSpend → AdSpendManual rename dropped the adSpendType discriminator).
				await this.domainEventRepository.save(
					new ManualAdSpendDeletedEvent({
						entityId: entity.id.value,
						ownerId: entity.storeId.value,
						payload: {
							adSpendId: entity.id.value,
							storeId: entity.storeId.value,
						},
					}),
					tx,
				)
				await this.adSpends.delete(entity.id.value, tx)
			}
		})

		return
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, CredentialVault, Handler, Id, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Client } from '@bk-dash/client-typescript'
import { StoreIntegrationType, MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegrationRepository } from '../../integration/repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../../integration/repositories/IntegrationCredentialSecretRepository'
import { MarketingReconciliationRequestedEvent } from '../events'
import type { ApplicationErrors } from '../errors'

export const ReconcileMarketingAccountsInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	platform: z.enum(MarketingPlatform),
})

export const ReconcileMarketingAccountsOutputSchema = z.object({
	jobId: z.string(),
	estimatedCompletionAt: z.date(),
})

/**
 * C38 ReconcileMarketingAccounts. Per spec § Data Flow Outbound: TS
 * triggers a go-worker sync scoped to the MARKETING_METRICS pipeline
 * (POST /sync with pipelines:['MARKETING_METRICS']) using the
 * MarketingPlatform's stored credentials. Replaces the former bespoke
 * /marketing/reconcile route, removed in the Go sync restructure; the
 * marketing pull is now one sync kind among many. Go runs the same job
 * on cron (spec § Scheduled Flows); this is the merchant-triggered
 * manual path exposed in the dashboard's "Refresh data" button.
 *
 * Opens credentials → calls go-worker → emits a domain event for audit.
 */
@injectable()
export class ReconcileMarketingAccounts extends Handler<
	typeof ReconcileMarketingAccountsInputSchema,
	typeof ReconcileMarketingAccountsOutputSchema
> {
	readonly name = 'reconcile_marketing_accounts' as const
	readonly inputSchema = ReconcileMarketingAccountsInputSchema
	readonly outputSchema = ReconcileMarketingAccountsOutputSchema

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly credentialSecretRepo: IntegrationCredentialSecretRepository,
		private readonly vault: CredentialVault,
		private readonly client: Client,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const integration = await this.storeIntegrationRepo.findByStoreIdAndPlatform(
			input.storeId,
			{ type: StoreIntegrationType.MARKETING_PLATFORM, platform: input.platform },
			tx,
		)
		if (integration === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		if (!integration.active) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_INACTIVE')
		}

		const secret = await this.credentialSecretRepo.findByStoreIntegrationId(integration.id.value, tx)
		if (secret === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_CREDENTIAL_NOT_FOUND')
		}
		const credentials = await this.vault.open<Record<string, string>>({
			encryptionAlgorithm: secret.encryptionAlgorithm,
			encryptedPayload: secret.encryptedPayload,
		})

		// Pass an explicit empty config object as the second arg so the GoClient
		// correctly threads `baseURL` + `client` into the request config rather
		// than merging them into the data payload (GoClient uses args.slice(0,-1)
		// to separate data from config — without a second arg the data is treated
		// as the config and the stub fetch is never applied in tests).
		await this.client.go.sync(
			{
				platform: input.platform,
				storeId: input.storeId,
				storeIntegrationId: integration.id.value,
				credentials,
				pipelines: ['MARKETING_METRICS'],
			},
			{},
		)

		// Go's reconcile returns counters, not a job handle — synthesize a jobId
		// + ETA so the audit event + output preserve their existing contract.
		const jobId = Id.value()
		const estimatedCompletionAt = new Date(Date.now() + 30 * 60_000)

		return this.withTransaction(tx, async tx => {
			await this.domainEventRepository.save(
				new MarketingReconciliationRequestedEvent({
					entityId: integration.id.value,
					ownerId: input.userId,
					payload: {
						storeId: input.storeId,
						storeIntegrationId: integration.id.value,
						platform: input.platform,
						jobId,
						requestedByUserId: input.userId,
					},
				}),
				tx,
			)
			return { jobId, estimatedCompletionAt }
		})
	}
}

