import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'

import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { AdSpendManualSchema } from '../entities/AdSpendManual'
import { ManualAdSpendUpdatedEvent } from '../events'
import Z from 'zod'
import type { MarketingApplicationErrors } from '../errors'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateManualAdSpendInputSchema = z.object({
	userId: z.uuid(),
	ids: z.array(z.uuid()).min(1),
	amountCents: z.number().int().positive().optional(),
	currency: z.enum(CurrencyCode).optional(),
	startDate: z.date().optional(),
	endDate: z.date().optional(),
	name: z.string().optional(),
	description: z.string().optional(),
})

export const UpdateManualAdSpendOutputSchema = z.void()

/**
 * C34 UpdateManualAdSpend. Bulk: loads each AdSpendManual by id, applies the
 * same patch, persists, and emits one ManualAdSpendUpdatedEvent per row.
 * Throws AD_SPEND_NOT_FOUND if any id is missing.
 */
@injectable()
export class UpdateManualAdSpend extends Handler<typeof UpdateManualAdSpendInputSchema, typeof UpdateManualAdSpendOutputSchema> {
	readonly name = 'update_manual_ad_spend' as const
	readonly inputSchema = UpdateManualAdSpendInputSchema
	readonly outputSchema = UpdateManualAdSpendOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		await this.withTransaction(tx, async tx => {
			const startDate = input.startDate ? new Date(input.startDate) : undefined
			startDate?.setUTCHours(0, 0, 0, 0)
			const endDate = input.endDate ? new Date(input.endDate) : undefined
			endDate?.setUTCHours(23, 59, 59, 999)

			for (const adSpendId of input.ids) {
				const entity = await this.adSpends.findById(adSpendId, tx)
				if (!entity) {
					throw new BaseError<MarketingApplicationErrors>('AD_SPEND_NOT_FOUND')
				}

				entity.updateManual({
					name: input.name,
					description: input.description,
					startDate,
					endDate,
					spend:
						input.amountCents !== undefined
							? {
									amountCents: input.amountCents,
									currency: input.currency ?? entity.currency,
								}
							: undefined,
				})
				await this.adSpends.save(entity, tx)

				await this.domainEventRepository.save(
					new ManualAdSpendUpdatedEvent({
						entityId: entity.id.value,
						ownerId: entity.storeId.value,
						// toJSON() serialises Id instances to strings; z.instance(Id) accepts
						// both at runtime — the cast bridges the TS mismatch.
						payload: { adSpend: entity.toJSON() as unknown as Z.infer<typeof AdSpendManualSchema> },
					}),
					tx,
				)
			}
		})

		return
	}
}

