import type { Transaction } from '@bk-dash/core-typescript'

import { FcmRegistrationToken } from '../entities/FcmRegistrationToken'
import { FcmRegistrationTokenRepository } from '../repositories/FcmRegistrationTokenRepository'
import { FcmTokenRegisteredEvent } from '../events'
import { FcmPlatform } from '@bk-dash/contracts-typescript/wire/enums'

export const RegisterFcmTokenInputSchema = z.object({
	userId: z.uuid(),
	token: z.string().min(1),
	platform: z.enum(FcmPlatform),
})

export const RegisterFcmTokenOutputSchema = z.void()

@injectable()
export class RegisterFcmToken extends Handler<typeof RegisterFcmTokenInputSchema, typeof RegisterFcmTokenOutputSchema> {
	readonly name = 'register_fcm_token' as const
	readonly inputSchema = RegisterFcmTokenInputSchema
	readonly outputSchema = RegisterFcmTokenOutputSchema

	constructor(private readonly repo: FcmRegistrationTokenRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const existing = await this.repo.findByToken(input.token, tx)
			if (existing) {
				// Spec C09 is idempotent on token value. Re-registering refreshes
				// liveness without emitting a second FcmTokenRegistered event.
				existing.touch()
				await this.repo.save(existing, tx)
				return
			}

			const fcm = FcmRegistrationToken.create({
				userId: input.userId,
				token: input.token,
				platform: input.platform,
			})
			await this.repo.save(fcm, tx)
			await this.domainEventRepository.save(
				new FcmTokenRegisteredEvent({
					entityId: fcm.id.value,
					ownerId: input.userId,
					payload: { userId: input.userId, tokenId: fcm.id.value, platform: input.platform },
				}),
				tx,
			)
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { FcmRegistrationTokenRepository } from '../repositories/FcmRegistrationTokenRepository'
import { FcmTokenUnregisteredEvent } from '../events'

export const UnregisterFcmTokenInputSchema = z.object({
	userId: z.uuid(),
	token: z.string().min(1),
})

export const UnregisterFcmTokenOutputSchema = z.void()

@injectable()
export class UnregisterFcmToken extends Handler<typeof UnregisterFcmTokenInputSchema, typeof UnregisterFcmTokenOutputSchema> {
	readonly name = 'unregister_fcm_token' as const
	readonly inputSchema = UnregisterFcmTokenInputSchema
	readonly outputSchema = UnregisterFcmTokenOutputSchema

	constructor(private readonly repo: FcmRegistrationTokenRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const existing = await this.repo.findByToken(input.token, tx)
			// Spec C10 is "no-op if absent". Also silently ignore cross-user
			// unregister attempts — the SDK input has no userId, so the
			// controller injects session.user.id; defense-in-depth here.
			if (!existing || existing.userId.value !== input.userId) return

			await this.repo.delete(existing.id.value, tx)
			await this.domainEventRepository.save(
				new FcmTokenUnregisteredEvent({
					entityId: existing.id.value,
					ownerId: input.userId,
					payload: { userId: input.userId, tokenId: existing.id.value },
				}),
				tx,
			)
		})
	}
}

