import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { BkdashNotificationDeliveryRepository } from '../repositories/BkdashNotificationDeliveryRepository'
import { NotificationDeliveryReadEvent } from '../events'
import type { NotificationsApplicationErrors } from '../errors'

export const MarkNotificationReadInputSchema = z.object({
	userId: z.uuid(),
	notificationDeliveryIds: z.array(z.uuid()).min(1),
})

export const MarkNotificationReadOutputSchema = z.void()

/**
 * C55 MarkNotificationRead. Marks every delivery in `notificationDeliveryIds`
 * read for the calling user. Idempotent — already-read deliveries are a no-op
 * (one read event emitted per delivery that actually transitions).
 */
@injectable()
export class MarkNotificationRead extends Handler<typeof MarkNotificationReadInputSchema, typeof MarkNotificationReadOutputSchema> {
	readonly name = 'mark_notification_read' as const
	readonly inputSchema = MarkNotificationReadInputSchema
	readonly outputSchema = MarkNotificationReadOutputSchema

	constructor(private readonly deliveries: BkdashNotificationDeliveryRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		await this.withTransaction(tx, async tx => {
			for (const notificationDeliveryId of input.notificationDeliveryIds) {
				const delivery = await this.deliveries.findById(notificationDeliveryId, tx)
				if (!delivery) {
					throw new BaseError<NotificationsApplicationErrors>('NOTIFICATION_DELIVERY_NOT_FOUND')
				}
				const changed = delivery.markRead(input.userId)
				if (!changed) continue // already-read, idempotent
				if (delivery.readAt === null) continue
				const readAt = delivery.readAt

				await this.deliveries.save(delivery, tx)
				await this.domainEventRepository.save(
					new NotificationDeliveryReadEvent({
						entityId: delivery.id.value,
						ownerId: delivery.userId.value,
						payload: {
							notificationDeliveryId: delivery.id.value,
							notificationId: delivery.notificationId.value,
							userId: delivery.userId.value,
							readAt,
						},
					}),
					tx,
				)
			}
		})

		return
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { NotificationChannel, NotificationOrigin, NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { BkdashNotification } from '../entities/BkdashNotification'
import { BkdashNotificationDelivery } from '../entities/BkdashNotificationDelivery'
import { BkdashNotificationRepository } from '../repositories/BkdashNotificationRepository'
import { BkdashNotificationDeliveryRepository } from '../repositories/BkdashNotificationDeliveryRepository'
import { NotificationSentEvent } from '../events'
import type { NotificationsDomainErrors } from '../errors'

export const SendNotificationInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid().optional(),
	targetUserIds: z.array(z.string()).optional(),
	title: z.string().min(1).max(200),
	content: z.string().min(1),
	category: z.enum(NotificationCategory),
	important: z.boolean().default(false),
	pushEnabled: z.boolean().default(true),
	emailEnabled: z.boolean().default(false),
	contentType: z.string().default('text/plain'),
	payload: z.record(z.string(), z.unknown()).optional(),
	scheduledAt: z.date().optional(),
})

export const SendNotificationOutputSchema = z.object({
	notificationId: z.uuid(),
	deliveriesCreated: z.number().int().min(0),
	deliveriesSkippedDuplicate: z.number().int().min(0),
})

/**
 * C53 SendNotification. Creates one BkdashNotification + N
 * BkdashNotificationDelivery rows (one per recipient × enabled channel).
 * Requires at least one targetUserId and at least one enabled channel.
 *
 * `scheduledAt` is accepted for SDK compatibility but not yet honored at
 * this layer — the scheduler integration that defers the persist to the
 * requested wall-clock lands in a follow-up iter; for now the rows are
 * created immediately with `deliveredAt = now`.
 */
@injectable()
export class SendNotification extends Handler<typeof SendNotificationInputSchema, typeof SendNotificationOutputSchema> {
	readonly name = 'send_notification' as const
	readonly inputSchema = SendNotificationInputSchema
	readonly outputSchema = SendNotificationOutputSchema

	constructor(
		private readonly notifications: BkdashNotificationRepository,
		private readonly deliveries: BkdashNotificationDeliveryRepository,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const targets = input.targetUserIds ?? []
		if (targets.length === 0) {
			throw new BaseError<NotificationsDomainErrors>('EMPTY_RECIPIENTS')
		}
		const channels: NotificationChannel[] = []
		if (input.pushEnabled) channels.push(NotificationChannel.PUSH)
		if (input.emailEnabled) channels.push(NotificationChannel.EMAIL)
		if (channels.length === 0) {
			throw new BaseError<NotificationsDomainErrors>('NO_CHANNEL_ENABLED')
		}

		return this.withTransaction(tx, async tx => {
			const notification = BkdashNotification.create({
				title: input.title,
				content: input.content,
				category: input.category as NotificationCategory,
				origin: NotificationOrigin.ADMIN,
				important: input.important,
				contentType: input.contentType,
				payload: input.payload,
				storeId: input.storeId ?? null,
			})
			await this.notifications.save(notification, tx)

			let deliveriesCreated = 0
			for (const recipient of targets) {
				for (const channel of channels) {
					const delivery = BkdashNotificationDelivery.create({
						notificationId: notification.id.value,
						userId: recipient,
						channel,
					})
					await this.deliveries.save(delivery, tx)
					deliveriesCreated++
				}
			}

			await this.domainEventRepository.save(
				new NotificationSentEvent({
					entityId: notification.id.value,
					ownerId: input.storeId ?? input.userId,
					payload: {
						notificationId: notification.id.value,
						storeId: input.storeId ?? null,
						category: input.category,
						channels,
						recipientCount: targets.length,
						deliveriesCreated,
					},
				}),
				tx,
			)

			return {
				notificationId: notification.id.value,
				deliveriesCreated,
				deliveriesSkippedDuplicate: 0,
			}
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import { SalesPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegrationRepository } from '@integration/repositories'
import type { ApplicationErrors } from '../errors'

export const GetPixelScriptSnippetInputSchema = z.object({
	storeId: z.uuid(),
})

export const GetPixelScriptSnippetOutputSchema = z.object({
	storeIntegrationId: z.uuid(),
	platform: z.enum(SalesPlatform),
	scriptUrl: z.url(),
	inlineScript: z.string(),
	installationInstructions: z.string(),
})

/**
 * T24 PixelScriptSnippet. Per spec: "Copy-pasteable pixel script —
 * Embed code per StoreIntegration." Shopify-only at launch (only
 * supported pixel platform); other SalesPlatforms throw
 * PIXEL_NOT_SUPPORTED_FOR_PLATFORM.
 *
 * scriptUrl is the CDN-hosted bundle the merchant pastes into their
 * storefront theme. inlineScript is the bootstrap snippet that wires
 * the merchant's storeIntegrationId into the bundle at load time.
 */
@injectable()
export class GetPixelScriptSnippet extends Handler<typeof GetPixelScriptSnippetInputSchema, typeof GetPixelScriptSnippetOutputSchema> {
	readonly name = 'get_pixel_script_snippet' as const
	readonly inputSchema = GetPixelScriptSnippetInputSchema
	readonly outputSchema = GetPixelScriptSnippetOutputSchema

	constructor(private readonly storeIntegrationRepo: StoreIntegrationRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		const integrations = await this.storeIntegrationRepo.findByStoreId(input.storeId)
		const integration = integrations.find((i) => i.type === StoreIntegrationType.SALES_CHANNEL)
		if (integration === undefined) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		if (integration.platform !== SalesPlatform.SHOPIFY) {
			throw new BaseError<ApplicationErrors>('PIXEL_NOT_SUPPORTED_FOR_PLATFORM')
		}

		const scriptUrl = `https://cdn.bkdash.local/pixel/v1/bkdash-pixel.js`
		const inlineScript = `<!-- BK Dash Pixel -->
<script>
  window.BKDASH_PIXEL_CONFIG = { storeIntegrationId: ${JSON.stringify(integration.id.value)} };
</script>
<script async src=${JSON.stringify(scriptUrl)}></script>`
		const installationInstructions = `Paste the snippet above into your Shopify theme.liquid file just before </head>. The pixel will fire on every page view, product view, cart change, and checkout step.`

		return {
			storeIntegrationId: integration.id.value,
			platform: SalesPlatform.SHOPIFY,
			scriptUrl,
			inlineScript,
			installationInstructions,
		}
	}
}

