import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { Role } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { RequireStoreRole } from '../middlewares/RequireStoreRole'
import { ChangeMemberRole } from '../usecases/ChangeMemberRole'

export const ChangeMemberRoleControllerInputSchema = z
	.object({
		ctx: z.object({
			session: z.object({ storeId: z.uuid() }),
		}),
		// `ids` are the userIds of the members to re-role under the active store.
		// Bulk: apply `newRole` to all of them in one call.
		body: z.object({
			ids: z.array(z.uuid()).min(1),
			newRole: z.enum(Role),
		}),
	})
	.example([
		{
			ctx: { session: { storeId: '019e4d24-6524-7041-9e1c-8108180cddae' } },
			body: {
				ids: ['019e4d25-7c1f-7041-9e1c-8108180cddae'],
				newRole: Role.ADMIN,
			},
		},
	])

export const ChangeMemberRoleControllerOutputSchema = z.void()

@injectable()
export class ChangeMemberRoleController extends Controller<
	typeof ChangeMemberRoleControllerInputSchema,
	typeof ChangeMemberRoleControllerOutputSchema
> {
	readonly path = '/stores/memberships/role'
	readonly method = 'patch' as const
	readonly description = "Change one or more store members' role (C18 ChangeMemberRole; LAST_OWNER guarded)"
	readonly inputSchema = ChangeMemberRoleControllerInputSchema
	readonly outputSchema = ChangeMemberRoleControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER])]

	constructor(private changeMemberRole: ChangeMemberRole) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.changeMemberRole.execute({
			storeId: request.ctx.session.storeId,
			ids: request.body.ids,
			newRole: request.body.newRole,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

