import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { Role } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { RequireStoreRole } from '@tenancy/middlewares/RequireStoreRole'
import { DisconnectIntegration } from '../usecases/DisconnectIntegration'

export const DisconnectIntegrationControllerInputSchema = z
	.object({
		ctx: z.object({
			user: z.object({ id: z.string() }),
			session: z.object({ storeId: z.uuid() }),
		}),
		params: z.object({
			integrationId: z.uuid(),
		}),
		body: z.object({
			wipeData: z.boolean().default(false),
		}),
	})
	.example([
		{
			ctx: { user: { id: 'user-123' }, session: { storeId: '019e4d24-6524-7041-9e1c-8108180cddae' } },
			params: {
				integrationId: '019e4d24-7000-7041-9e1c-8108180cddae',
			},
			body: {
				wipeData: true,
			},
		},
	])

export const DisconnectIntegrationControllerOutputSchema = z.void()

@injectable()
export class DisconnectIntegrationController extends Controller<
	typeof DisconnectIntegrationControllerInputSchema,
	typeof DisconnectIntegrationControllerOutputSchema
> {
	readonly path = '/integrations/:integrationId'
	readonly method = 'delete' as const
	readonly description = 'Disconnect a provider integration (C22 DisconnectIntegration; wipeData cascades canonical row cleanup)'
	readonly inputSchema = DisconnectIntegrationControllerInputSchema
	readonly outputSchema = DisconnectIntegrationControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private disconnect: DisconnectIntegration) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.disconnect.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.session.storeId,
			storeIntegrationId: request.params.integrationId,
			wipeData: request.body.wipeData,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

