			estimatedCompletionAt: new Date('2026-05-23T00:00:00.000Z'),
		},
	])

@injectable()
export class TriggerReintegrationController extends Controller<
	typeof TriggerReintegrationControllerInputSchema,
	typeof TriggerReintegrationControllerOutputSchema
> {
	readonly path = '/integrations/:integrationId/reintegrate'
	readonly method = 'post' as const
	readonly description = 'Trigger a full re-sync for an integration (C23 TriggerReintegration; rate-limited 1/5min per integration)'
	readonly inputSchema = TriggerReintegrationControllerInputSchema
	readonly outputSchema = TriggerReintegrationControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private trigger: TriggerReintegration) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.trigger.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.session.storeId,
			storeIntegrationId: request.params.integrationId,
		})
		return { status: HttpStatusCode.ACCEPTED, data }
	}
}

