import { RequireStoreRole } from '@tenancy/middlewares/RequireStoreRole'
import { TriggerReintegrationAll, TriggerReintegrationAllOutputSchema } from '../usecases/TriggerReintegrationAll'

export const TriggerReintegrationAllControllerInputSchema = z
	.object({
		ctx: z.object({
			user: z.object({ id: 'user-123' },
			session: z.object({ storeId: z.uuid() }),
		}),
	})
	.example([
		{
			ctx: {
				user: { id: 'user-123' },
				session: { storeId: '019e4d24-6524-7041-9e1c-8108180cddae' },
			},
		},
	])

// userId/storeId both come from ctx — no body to compose.
// OutputSchema is imported from the use case as the single source of truth.
export const TriggerReintegrationAllControllerOutputSchema = TriggerReintegrationAllOutputSchema.example([
	{
		triggeredIntegrationIds: ['019e4d24-7000-7041-9e1c-8108180cddae', '019e4d24-7001-7041-9e1c-8108180cddae'],
	},
])

@injectable()
export class TriggerReintegrationAllController extends Controller<
	typeof TriggerReintegrationAllControllerInputSchema,
	typeof TriggerReintegrationAllControllerOutputSchema
> {
	readonly path = '/integrations/reintegrate-all'
	readonly method = 'post' as const
	readonly description = 'Trigger a full re-sync for every active integration on this store (C24 TriggerReintegrationAll)'
	readonly inputSchema = TriggerReintegrationAllControllerInputSchema
	readonly outputSchema = TriggerReintegrationAllControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private trigger: TriggerReintegrationAll) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.trigger.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.session.storeId,
		})
		return { status: HttpStatusCode.ACCEPTED, data }
	}
}

