	readonly description = 'Remove one or more store members (C17 RemoveMember; LAST_OWNER guarded)'
	readonly inputSchema = RemoveMemberControllerInputSchema
	readonly outputSchema = RemoveMemberControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

