import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { UpdateOperationalCost } from '../usecases/UpdateOperationalCost'
import { OperationalCostCategory, OperationalCostFlow, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateOperationalCostControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), session: z.object({ storeId: z.uuid() }) }),
	body: z.object({
		ids: z.array(z.uuid()).min(1),
		category: z.enum(OperationalCostCategory).optional(),
		flow: z.enum(OperationalCostFlow).optional(),
		description: z.string().min(1).max(500).optional(),
		amount: MonetaryAmountSchema.refine(m => m.amountCents > 0).optional(),
		recurrency: z.enum(OperationalCostRecurrency).optional(),
		startDate: z.stringToDate().optional(),
		endDate: z.stringToDate().nullable().optional(),
	}),
})

export const UpdateOperationalCostControllerOutputSchema = z.void()

@injectable()
export class UpdateOperationalCostController extends Controller<
	typeof UpdateOperationalCostControllerInputSchema,
	typeof UpdateOperationalCostControllerOutputSchema
> {
	readonly path = '/operational-costs'
	readonly method = 'patch' as const
	readonly description = 'Update recurring operational costs by ids (C42)'
	readonly inputSchema = UpdateOperationalCostControllerInputSchema
	readonly outputSchema = UpdateOperationalCostControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: UpdateOperationalCost) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.cmd.execute({
			userId: request.ctx.user.id,
			ids: request.body.ids,
			category: request.body.category,
			flow: request.body.flow,
