export const RemoveMemberControllerInputSchema = z
	.object({
		ctx: z.object({
			session: z.object({ storeId: z.uuid() }),
		}),
		// `ids` are the userIds of the members to remove — StoreMembership has no
		// separate id; a membership is uniquely identified by (storeId, userId).
		// Bulk: remove all of them under the active store in one call.
		// storeId is supplied from ctx.session.storeId — omitted from the HTTP surface.
		body: RemoveMemberInputSchema.omit({ storeId: true }),
	})
	.example([
		{
			ctx: { session: { storeId: '019e4d24-6524-7041-9e1c-8108180cddae' } },
			body: { ids: ['019e4d25-7c1f-7041-9e1c-8108180cddae'] },
