			showStoreNameInNotifications: true,
		},
	])

export const UpdateStoreSettingsControllerOutputSchema = z.void()

@injectable()
export class UpdateStoreSettingsController extends Controller<
	typeof UpdateStoreSettingsControllerInputSchema,
	typeof UpdateStoreSettingsControllerOutputSchema
> {
	readonly path = '/stores/settings'
	readonly method = 'patch' as const
	readonly description = 'Update store profile + reporting/notification settings (C13 UpdateStoreSettings)'
	readonly inputSchema = UpdateStoreSettingsControllerInputSchema
	readonly outputSchema = UpdateStoreSettingsControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private updateStoreSettings: UpdateStoreSettings) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.updateStoreSettings.execute({
			storeId: request.ctx.session.storeId,
			name: request.name,
			pictureUrl: request.pictureUrl,
			email: request.email,
			phoneNumber: request.phoneNumber,
			reportingCurrency: request.reportingCurrency,
			timezone: request.timezone,
			showStoreNameInNotifications: request.showStoreNameInNotifications,
