=== RequireStoreMember ctx stamp ===
import { singleton } from 'tsyringe-neo'
import { BaseError } from '@bk-dash/core-typescript'
import type { HttpControllerRequest, HttpMiddlewareResponse, Middleware } from '@bk-dash/core-typescript'
import { StoreMembershipRepository } from '@tenancy/repositories/StoreMembershipRepository'
import type { ApplicationErrors } from '@tenancy/errors'
import { SessionSchema } from '@auth/schemas'

/**
 * Tenancy gate — foundation of the storeId-from-session convention. It:
 *   1. Parses `request.ctx` against `SessionSchema` (requires `user.id` and the
 *      active `session.storeId`).
 *   2. Asserts the user is a member of that store via `findByStoreAndUser`.
 *   3. On a miss (or any parse failure), throws `STORE_MEMBERSHIP_NOT_FOUND` (→ 404).
 *   4. On a hit, stamps `request.ctx.membership = { id, userId, role, storeIds }`
 *      for `RequireStoreRole` and any controller that still needs the role or the
 *      full list of stores the user belongs to.
 *
 * Store-scoped controllers no longer read `ctx.membership.storeId` — the active
 * store is `ctx.session.storeId`, which this middleware has already validated.
 *
 * Composition rule: `AuthAccountMiddleware` first (provides `user.id` +
 * `session.storeId`), then this; `RequireStoreRole` goes after to enforce the
 * role allow-list.
 */
@singleton()
export class RequireStoreMember implements Middleware {
	constructor(private readonly memberships: StoreMembershipRepository) {}

	async execute(request: HttpControllerRequest<unknown>): Promise<HttpMiddlewareResponse<void>> {
		const ctx = SessionSchema.safeParse(request.ctx)
		if (!ctx.success) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

		const userId = ctx.data.user.id
		const storeId = ctx.data.session.storeId
		if (!storeId) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

		const active = await this.memberships.findByStoreAndUser(storeId, userId)
		if (!active) throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')

		const all = await this.memberships.findByUserId(userId)
		const storeIds = all.map((m) => m.storeId)

		request.ctx = {
			...request.ctx,
			membership: { id: active.id, userId: active.userId, role: active.role, storeIds },
		}
		return {}
	}
}
