=== Goal entity ===
import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { type CurrencyCode, GoalType } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { AnalyticsDomainErrors } from '../errors'

export const GoalSchema = z.object({
	storeId: z.instance(Id),
	type: z.enum(GoalType),
	targetAmount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as AnalyticsDomainErrors,
	}),
	from: z.date(),
	to: z.date(),
})

export type GoalProps = Z.infer<typeof GoalSchema>

/**
 * `Goal` aggregate per spec § BC11 Analytics. Per-user, per-Store
 * revenue or profit target over a date window. Immutable scoping keys
 * after creation; only the target amount is mutable.
 */
export class Goal extends AggregateRoot<typeof GoalSchema> {
	static override schema = GoalSchema

	static create(data: {
		storeId: string
		type: GoalType
		targetAmount: { amountCents: number; currency: CurrencyCode }
		from: Date
		to: Date
	}): Goal {
		if (data.from > data.to) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		return new Goal(data)
	}

	updateTarget(patch: { targetAmount?: { amountCents: number; currency: CurrencyCode }; from?: Date; to?: Date }): void {
		const effFrom = patch.from ?? this.from
		const effTo = patch.to ?? this.to
		if (effFrom > effTo) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		if (patch.targetAmount !== undefined) {
			this.targetAmount = new MonetaryAmount(patch.targetAmount)
		}
		if (patch.from !== undefined) {
			this.from = patch.from
		}
		if (patch.to !== undefined) {
			this.to = patch.to
		}
		this.validate()
	}
}

export interface Goal extends GoalProps {}
