import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { type CurrencyCode, GoalType } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { AnalyticsDomainErrors } from '../errors'

export const GoalSchema = z.object({
	storeId: z.instance(Id),
	type: z.enum(GoalType),
	targetAmount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as AnalyticsDomainErrors,
	}),
	from: z.date(),
	to: z.date(),
})

export type GoalProps = Z.infer<typeof GoalSchema>

/**
 * `Goal` aggregate per spec § BC11 Analytics. Per-user, per-Store
 * revenue or profit target over a date window. Immutable scoping keys
 * after creation; only the target amount is mutable.
 */
export class Goal extends AggregateRoot<typeof GoalSchema> {
	static override schema = GoalSchema

	static create(data: {
		storeId: string
		type: GoalType
		targetAmount: { amountCents: number; currency: CurrencyCode }
		from: Date
		to: Date
	}): Goal {
		if (data.from > data.to) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		return new Goal(data)
	}

	updateTarget(patch: { targetAmount?: { amountCents: number; currency: CurrencyCode }; from?: Date; to?: Date }): void {
		const effFrom = patch.from ?? this.from
		const effTo = patch.to ?? this.to
		if (effFrom > effTo) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		if (patch.targetAmount !== undefined) {
			this.targetAmount = new MonetaryAmount(patch.targetAmount)
		}
		if (patch.from !== undefined) {
			this.from = patch.from
		}
		if (patch.to !== undefined) {
			this.to = patch.to
		}
		this.validate()
	}
}

export interface Goal extends GoalProps {}

import { Repository } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Goal } from '../../entities/Goal'

export abstract class GoalRepository extends Repository<Goal> {
	abstract findById(id: string, tx?: Transaction): Promise<Goal | undefined>
	/** All Goals for a store, newest first (by `to`). */
	abstract listByStoreId(storeId: string, tx?: Transaction): Promise<Goal[]>
	/** Last Goal for a (user, store) pair — backs DuplicateLastGoal. */
	abstract findLastByUserAndStore(storeId: string, tx?: Transaction): Promise<Goal | undefined>
}

import { injectable } from 'tsyringe-neo'
import { desc, eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { bkdashGoals } from '@bk-dash/contracts/db'
import { Goal, GoalSchema } from '../../entities/Goal'
import { GoalRepository } from './GoalRepository'

/**
 * Drizzle-backed real impl of GoalRepository (iter 301 — closes the
 * iter-300 known-gap #1: GoalRepository was Mock-only). UPSERT on save
 * via deterministic id; `incrementVersion` bumps the optimistic-
 * concurrency counter on every write.
 *
 * The `goals.goals` Drizzle table got a `user_id` column added in
 * migration 0020 (iter 301) so `findLastByUserAndStore` works against
 * the canonical row shape the Goal entity carries.
 */
@injectable()
export class DrizzleGoalRepository extends GoalRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<Goal | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(bkdashGoals).where(eq(bkdashGoals.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async listByStoreId(storeId: string, tx?: DrizzleClient): Promise<Goal[]> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			return await dbc.select().from(bkdashGoals).where(eq(bkdashGoals.storeId, storeId)).orderBy(desc(bkdashGoals.endDate))
		})
		if (!result.success) throw result.error
		return (result.data ?? []).map(row => this.toDomain(row))
	}

	async findLastByUserAndStore(storeId: string, tx?: DrizzleClient): Promise<Goal | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(bkdashGoals).where(eq(bkdashGoals.storeId, storeId)).orderBy(desc(bkdashGoals.endDate)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: Goal, tx?: DrizzleClient): Promise<Goal> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(bkdashGoals)
				.values(data)
				.onConflictDoUpdate({
					target: bkdashGoals.id,
					set: {
						storeId: data.storeId,
						type: data.type,
						targetAmountCents: data.targetAmountCents,
						targetCurrency: data.targetCurrency,
						startDate: data.startDate,
						endDate: data.endDate,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(bkdashGoals).where(eq(bkdashGoals.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof bkdashGoals.$inferSelect): Goal {
		const parsed = GoalSchema.parse({
			storeId: row.storeId,
			type: row.type,
			targetAmount: { amountCents: Number(row.targetAmountCents), currency: row.targetCurrency },
			from: row.startDate,
			to: row.endDate,
		})
		return new Goal({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: Goal): typeof bkdashGoals.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			type: entity.type,
			targetAmountCents: BigInt(entity.targetAmount.amountCents),
			targetCurrency: entity.targetAmount.currency,
			startDate: entity.from,
			endDate: entity.to,
			version: entity.version,
		}
	}
}

import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import { Goal } from '../../entities/Goal'
import { GoalRepository } from './GoalRepository'

@injectable()
export class MockGoalRepository extends GoalRepository {
	private rows = new Map<string, Goal>()

	async findById(id: string, _tx?: Transaction): Promise<Goal | undefined> {
		return this.rows.get(id)
	}

	async listByStoreId(storeId: string, _tx?: Transaction): Promise<Goal[]> {
		return [...this.rows.values()].filter(g => g.storeId.value === storeId).sort((a, b) => (a.to < b.to ? 1 : -1))
	}

	async findLastByUserAndStore(storeId: string, _tx?: Transaction): Promise<Goal | undefined> {
		const candidates = [...this.rows.values()].filter(g => g.storeId.value === storeId).sort((a, b) => (a.to < b.to ? 1 : -1))
		return candidates[0]
	}

	async save(entity: Goal, _tx?: Transaction): Promise<Goal> {
		entity.incrementVersion()
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(entity: Goal): void {
		this.rows.set(entity.id.value, entity)
	}

	clear(): void {
		this.rows.clear()
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
