import { GoalRepository } from './GoalRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')

describe('DrizzleGoalRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: GoalRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(GoalRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: { storeId?: string; amountCents?: number; from?: Date; to?: Date }): Goal {
		return Goal.create({
			storeId: opts.storeId ?? STORE_A,
			type: GoalType.REVENUE,
			targetAmount: { amountCents: opts.amountCents ?? 100_000, currency: CurrencyCode.USD },
			from: opts.from ?? new Date('2026-05-01T00:00:00.000Z'),
			to: opts.to ?? new Date('2026-05-31T00:00:00.000Z'),
		})
	}

	describe('save + findById', () => {
		it('round-trips through Drizzle', async () => {
			const entity = build({ amountCents: 250_000 })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.storeId.value).toBe(STORE_A)
			expect(fetched?.type).toBe(GoalType.REVENUE)
			expect(fetched?.targetAmount.amountCents).toBe(250_000)
			expect(fetched?.targetAmount.currency).toBe(CurrencyCode.USD)
			expect(fetched?.from).toBeInstanceOf(Date)
			expect(fetched?.to).toBeInstanceOf(Date)
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId())
			expect(r).toBeUndefined()
		})

		it('UPSERT persists updateTarget() — target bumped + version up', async () => {
			const entity = build({ amountCents: 100_000 })
			await repo.save(entity)

			entity.updateTarget({ targetAmount: { amountCents: 200_000, currency: CurrencyCode.USD } })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.targetAmount.amountCents).toBe(200_000)
			expect(fetched?.version).toBeGreaterThan(1)
		})
	})

	describe('listByStoreId', () => {
		it('returns empty list when none exist', async () => {
			const r = await repo.listByStoreId(STORE_A)
			expect(r).toEqual([])
		})

		it('returns goals newest-first by endDate (entity exposes as `to`)', async () => {
			await repo.save(build({ from: new Date('2026-05-01T00:00:00.000Z'), to: new Date('2026-05-31T00:00:00.000Z') }))
			await repo.save(build({ from: new Date('2026-06-01T00:00:00.000Z'), to: new Date('2026-06-30T00:00:00.000Z') }))
			await repo.save(build({ from: new Date('2026-04-01T00:00:00.000Z'), to: new Date('2026-04-30T00:00:00.000Z') }))

			const list = await repo.listByStoreId(STORE_A)
			expect(list).toHaveLength(3)
			// newest first: June, May, April
			expect(list[0]!.to).toBeInstanceOf(Date)
			const toStrings = list.map(g => g.to.toISOString().slice(0, 10))
			expect(toStrings).toEqual(['2026-06-30', '2026-05-31', '2026-04-30'])
		})

		it('isolates by storeId', async () => {
			await repo.save(build({ storeId: STORE_A }))
			await repo.save(build({ storeId: STORE_B }))

			const a = await repo.listByStoreId(STORE_A)
			expect(a).toHaveLength(1)
			expect(a[0]?.storeId.value).toBe(STORE_A)
		})
	})

	describe('findLastByUserAndStore (DuplicateLastGoal backing)', () => {
		it('returns undefined when no row matches', async () => {
			const r = await repo.findLastByUserAndStore(STORE_A)
			expect(r).toBeUndefined()
		})

		it('filters by store — separate stores isolated', async () => {
			await repo.save(build({ storeId: STORE_A, to: new Date('2026-05-31T00:00:00.000Z') }))
			await repo.save(build({ storeId: STORE_B, to: new Date('2026-06-30T00:00:00.000Z') }))

			const r = await repo.findLastByUserAndStore(STORE_A)
			expect(r?.storeId.value).toBe(STORE_A)
			expect(r?.to.toISOString().slice(0, 10)).toBe('2026-05-31')
		})

		it('returns the newest by `to` when multiple exist', async () => {
			await repo.save(build({ storeId: STORE_A, from: new Date('2026-04-01T00:00:00.000Z'), to: new Date('2026-04-30T00:00:00.000Z') }))
			await repo.save(build({ storeId: STORE_A, from: new Date('2026-06-01T00:00:00.000Z'), to: new Date('2026-06-30T00:00:00.000Z') }))
			await repo.save(build({ storeId: STORE_A, from: new Date('2026-05-01T00:00:00.000Z'), to: new Date('2026-05-31T00:00:00.000Z') }))

			const r = await repo.findLastByUserAndStore(STORE_A)
			expect(r?.to.toISOString().slice(0, 10)).toBe('2026-06-30')
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
			const entity = build({})
			await repo.save(entity)
			await repo.delete(entity.id.value)
			expect(await repo.findById(entity.id.value)).toBeUndefined()
		})
	})
})

import { pgSchema, uuid, text, timestamp, integer, bigint, index } from 'drizzle-orm/pg-core'

/**
 * `goals` is BK Dash's BC9 Analytics goals schema.
 *
 * Distinct from polyglot's `analytics` pgSchema (video watch / daily
 * stats — unrelated). The Analytics BC's READ side has no tables of
 * its own (all reads JOIN existing canonical projections in sales /
 * catalog / marketing / etc.). The WRITE side has just one aggregate:
 * `Goal` — a merchant-defined target on revenue or profit for a window.
 *
 * Per spec §4 BC9 line 868: a Goal belongs to a Store (not a User —
 * authorization is delegated to Tenancy's store-membership rule). T34
 * GoalsList takes `storeIds: string[]` and returns goals per-store.
 *
 * **File + TS-export naming:** `bkdash_analytics.ts` filename avoids
 * the polyglot `analytics.ts` collision. PG schema `goals` is short
 * + unambiguous.
 *
 * **Shape locked to spec by iter-43.6c migrations 0015 (pass 1, ADD)
 * + 0016 (pass 2, DROP).** Previous iterations carried four invented
 * columns (`user_id`, `frequency`, `is_active`, `progress_fraction`)
 * and dropped two spec-required ones (`store_integration_id`,
 * `disabled_at`). Pass 1 added the omissions + tightened nullables;
 * pass 2 drops the inventions.
 */
export const goalsSchema = pgSchema('goals')

export const bkdashGoals = goalsSchema.table(
	'goals',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		// Owning Store. Per spec §4 BC9 + §7.9 C49 input + T34 output, a
		// Goal is store-scoped (multistore views aggregate many Goals via
		// `storeIds: string[]`, not a NULL marker on a single row).
		storeId: uuid('store_id').notNull(),

		// Optional integration-level scope (e.g. "Shopify only"). Per spec
		// C49 + C52 inputs and T34 output. NULL = goal applies across all
		// integrations for the Store.
		storeIntegrationId: uuid('store_integration_id'),

		// GoalType enum (REVENUE | PROFIT). REVENUE = gross; PROFIT applies
		// all cost deductions per FeesConfiguration + Taxes + ProductCost.
		type: text('type').notNull(),

		// Target amount stored as cents + currency (the canonical
		// MonetaryAmount split). T34 converts to the Store's reporting
		// currency via FxRate joined at read time.
		targetAmountCents: bigint('target_amount_cents', { mode: 'bigint' }).notNull(),
		targetCurrency: text('target_currency').notNull(),

		// Effective window. Both required per spec aggregate + C49 input —
		// goals are date-ranged, never open-ended (DuplicateLastGoal shifts
		// `startDate` to `previous.endDate + 1 day`, so an open-ended row
		// would break that semantic).
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		endDate: timestamp('end_date', { withTimezone: true }).notNull(),

		// Soft-delete marker (spec C51). NULL = active, non-NULL = the
		// timestamp at which the merchant deleted the goal. T34's `active?`
		// input toggles `disabledAt IS NULL` / `IS NOT NULL` predicates.
		disabledAt: timestamp('disabled_at', { withTimezone: true }),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('goals_store_id_idx').on(t.storeId),
		// T34 `active?` filter: `WHERE store_id = ANY(?) AND disabled_at IS NULL`.
		storeDisabledIdx: index('goals_store_disabled_idx').on(t.storeId, t.disabledAt),
		// C52 DuplicateLastGoal lookup scoped by integration.
		storeIntegrationIdx: index('goals_store_integration_id_idx').on(t.storeIntegrationId),
		// Effective-window scans.
		startDateIdx: index('goals_start_date_idx').on(t.startDate),
	}),
)

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { Goal } from '../entities/Goal'
import { GoalRepository } from '../repositories/GoalRepository'
import { GoalCreatedEvent } from '../events'
import { GoalType } from '@bk-dash/contracts-typescript/wire/enums'

export const CreateGoalInputSchema = z.object({
	storeId: z.uuid(),
	from: z.date(),
	to: z.date(),
	type: z.enum(GoalType),
	targetAmount: MonetaryAmountSchema.input(),
})

export const CreateGoalOutputSchema = z.object({
	goalId: z.uuid(),
})

@injectable()
export class CreateGoal extends Handler<typeof CreateGoalInputSchema, typeof CreateGoalOutputSchema> {
	readonly name = 'create_goal' as const
	readonly inputSchema = CreateGoalInputSchema
	readonly outputSchema = CreateGoalOutputSchema

	constructor(private readonly goals: GoalRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const entity = Goal.create({
				storeId: input.storeId,
				type: input.type,
				targetAmount: input.targetAmount,
				from: input.from,
				to: input.to,
			})
			await this.goals.save(entity, tx)
			await this.domainEventRepository.save(
				new GoalCreatedEvent({
					entityId: entity.id.value,
					ownerId: input.storeId,
					payload: { goal: entity.toJSON() },
				}),
				tx,
			)
			return { goalId: entity.id.value }
		})
	}
}

