import { pgSchema, uuid, text, timestamp, integer, uniqueIndex } from 'drizzle-orm/pg-core'

/**
 * `ui` is BK Dash's UI-preference / BFF-read schema.
 *
 * Owns per-store UI settings that are persisted server-side and read
 * back by GetDashboard to pick the correct response variant.
 *
 * Tables:
 *   - `store_visualizations` — one row per Store holding the dashboardMode
 *     preference (GLOBAL | NATIONAL). Keyed by storeId (unique).
 */
export const uiSchema = pgSchema('ui')

/**
 * `store_visualizations` — persisted dashboard visualization mode per store.
 * Upserted by SetStoreVisualization; read by GetDashboard.
 * dashboardMode is stored as text (values: GLOBAL | NATIONAL from DashboardMode enum).
 */
export const storeVisualizations = uiSchema.table(
	'store_visualizations',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		// Owning store — unique so there is exactly one mode row per store.
		storeId: uuid('store_id').notNull(),

		// DashboardMode enum value (GLOBAL | NATIONAL). Text storage avoids
		// pgEnum migration coupling; validated at the application layer.
		dashboardMode: text('dashboard_mode').notNull().default('GLOBAL'),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: uniqueIndex('store_visualizations_store_id_idx').on(t.storeId),
	}),
)

