import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { storeVisualizations } from '@bk-dash/contracts/db'
import { StoreVisualization, StoreVisualizationSchema } from '../../entities/StoreVisualization'
import { StoreVisualizationRepository } from './StoreVisualizationRepository'
import { DashboardMode } from '@bk-dash/contracts-typescript/wire/enums'

@injectable()
export class DrizzleStoreVisualizationRepository extends StoreVisualizationRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findByStoreId(storeId: string, tx?: DrizzleClient): Promise<StoreVisualization | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(storeVisualizations)
				.where(eq(storeVisualizations.storeId, storeId))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: StoreVisualization, tx?: DrizzleClient): Promise<StoreVisualization> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(storeVisualizations)
				.values(data)
				.onConflictDoUpdate({
					target: storeVisualizations.storeId,
					set: {
						dashboardMode: data.dashboardMode,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(storeVisualizations).where(eq(storeVisualizations.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof storeVisualizations.$inferSelect): StoreVisualization {
		const parsed = StoreVisualizationSchema.parse({
			storeId: row.storeId,
			dashboardMode: row.dashboardMode,
		})
		return new StoreVisualization({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: StoreVisualization): typeof storeVisualizations.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			dashboardMode: entity.dashboardMode as DashboardMode,
			version: entity.version,
		}
	}
}

