const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')

describe('DrizzleStoreVisualizationRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: StoreVisualizationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(StoreVisualizationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: { storeId?: string; dashboardMode?: DashboardMode }): StoreVisualization {
		return StoreVisualization.create({
			storeId: opts.storeId ?? STORE_A,
			dashboardMode: opts.dashboardMode ?? DashboardMode.GLOBAL,
		})
	}

	describe('save + findByStoreId', () => {
		it('round-trips through Drizzle', async () => {
			const entity = build({ dashboardMode: DashboardMode.NATIONAL })
			await repo.save(entity)

			const fetched = await repo.findByStoreId(STORE_A)
			expect(fetched?.storeId.value).toBe(STORE_A)
			expect(fetched?.dashboardMode).toBe(DashboardMode.NATIONAL)
		})

		it('returns undefined when no row exists for the store', async () => {
			const result = await repo.findByStoreId(testId())
			expect(result).toBeUndefined()
		})

		it('UPSERT persists changeMode() — mode bumped + version up', async () => {
			const entity = build({ dashboardMode: DashboardMode.GLOBAL })
			await repo.save(entity)

			entity.changeMode(DashboardMode.NATIONAL)
			await repo.save(entity)

			const fetched = await repo.findByStoreId(STORE_A)
			expect(fetched?.dashboardMode).toBe(DashboardMode.NATIONAL)
			expect(fetched?.version).toBeGreaterThan(1)
		})

		it('upsert on storeId — second save does not create a new row', async () => {
			await repo.save(build({ storeId: STORE_A, dashboardMode: DashboardMode.GLOBAL }))
			// Create a second entity for the same store and save — should upsert, not insert
