import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { Goal } from '../entities/Goal'
import { GoalRepository } from '../repositories/GoalRepository'
import { GoalCreatedEvent } from '../events'
import { GoalType } from '@bk-dash/contracts-typescript/wire/enums'

export const CreateGoalInputSchema = z.object({
	storeId: z.uuid(),
	from: z.date(),
	to: z.date(),
	type: z.enum(GoalType),
	targetAmount: MonetaryAmountSchema.input(),
})

export const CreateGoalOutputSchema = z.object({
	goalId: z.uuid(),
})

@injectable()
export class CreateGoal extends Handler<typeof CreateGoalInputSchema, typeof CreateGoalOutputSchema> {
	readonly name = 'create_goal' as const
	readonly inputSchema = CreateGoalInputSchema
	readonly outputSchema = CreateGoalOutputSchema

	constructor(private readonly goals: GoalRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const entity = Goal.create({
				storeId: input.storeId,
				type: input.type,
				targetAmount: input.targetAmount,
				from: input.from,
				to: input.to,
			})
			await this.goals.save(entity, tx)
			await this.domainEventRepository.save(
				new GoalCreatedEvent({
					entityId: entity.id.value,
					ownerId: input.storeId,
					payload: { goal: entity.toJSON() },
				}),
				tx,
			)
			return { goalId: entity.id.value }
		})
	}
}
