import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'

import { CreateGoal, CreateGoalInputSchema, CreateGoalOutputSchema } from '../usecases/CreateGoal'

export const CreateGoalControllerInputSchema = z.object({
	ctx: z.object({ session: z.object({ storeId: z.uuid() }) }),
	body: CreateGoalInputSchema.omit({ storeId: true }).extend({
		// Body arrives as JSON strings — coerce to Date before use case receives them
		from: z.stringToDate(),
		to: z.stringToDate(),
	}),
})

export const CreateGoalControllerOutputSchema = CreateGoalOutputSchema

@injectable()
export class CreateGoalController extends Controller<typeof CreateGoalControllerInputSchema, typeof CreateGoalControllerOutputSchema> {
	readonly path = '/goals'
	readonly method = 'post' as const
	readonly description = 'Create a revenue or profit goal'
	readonly inputSchema = CreateGoalControllerInputSchema
	readonly outputSchema = CreateGoalControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: CreateGoal) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			storeId: request.ctx.session.storeId,
			type: request.body.type,
			targetAmount: request.body.targetAmount,
			from: request.body.from,
			to: request.body.to,
		})
		return { status: HttpStatusCode.CREATED, data }
	}
}
