import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { DashboardMode } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreVisualization } from '../entities/StoreVisualization'
import { StoreVisualizationRepository } from '../repositories/StoreVisualizationRepository'

export const SetStoreVisualizationInputSchema = z.object({
	storeId: z.uuid(),
	dashboardMode: z.enum(DashboardMode),
})

export const SetStoreVisualizationOutputSchema = z.object({
	id: z.uuid(),
})

/**
 * `SetStoreVisualization` — upserts the per-store dashboard mode. No domain
 * event (trivial UI-preference state). `GetDashboard` reads it back to pick
 * the response variant.
 */
@injectable()
export class SetStoreVisualization extends Handler<typeof SetStoreVisualizationInputSchema, typeof SetStoreVisualizationOutputSchema> {
	readonly name = 'set_store_visualization' as const
	readonly inputSchema = SetStoreVisualizationInputSchema
	readonly outputSchema = SetStoreVisualizationOutputSchema

	constructor(private readonly visualizations: StoreVisualizationRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const existing = await this.visualizations.findByStoreId(input.storeId, tx)
			if (existing) {
				existing.changeMode(input.dashboardMode)
				await this.visualizations.save(existing, tx)
				return { id: existing.id.value }
			}
			const entity = StoreVisualization.create({ storeId: input.storeId, dashboardMode: input.dashboardMode })
			await this.visualizations.save(entity, tx)
			return { id: entity.id.value }
		})
	}
}

