import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import {
	TenancyScope,
	DashboardMode,
	CurrencyCode,
	CostKind,
	MarketingPlatform,
	AdAttribution,
	DisputeStatus,
	PaymentMethod,
	PaymentStatus,
	OperationalCostFlow,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import {
	StatSchema,
	ConsolidatedStatSchema,
	PerStoreStatSchema,
	DashboardDetailsSchema,
	ConsolidatedDashboardDetailsSchema,
	PaymentMethodBreakdownSchema,
	MetricSchema,
	CurrencyMetricSchema,
	CurrencyAmountSchema,
	TallySchema,
	ConsolidatedTallySchema,
	OperationalCostItemSchema,
} from '../../shared/schemas/ui'
import { faker, mockId, mockMoney, mockMetric, mockSeries, pick } from '../../shared/testing/mock'
import { StoreVisualizationRepository } from '../repositories/StoreVisualizationRepository'

// ---------------------------------------------------------------------------
// Input — `tenancyScope` selects the store set; `dashboardMode` is NOT a query
// param (read from the persisted StoreVisualization). storeId/storeIds come
// from ctx. productIds is an optional filter.
// ---------------------------------------------------------------------------
export const GetDashboardInputSchema = z.object({
	tenancyScope: z.enum(TenancyScope),
	storeId: z.uuid(), // ← ctx.session.storeId      (SINGLE_STORE)
	storeIds: z.array(z.uuid()), // ← ctx.membership.storeIds  (MULTI_STORE)
	startDate: z.date(),
	endDate: z.date(),
	productIds: z.array(z.uuid()).optional(),
})

// ---------------------------------------------------------------------------
// Output — composition-first discriminated union. Section shape fragments +
// a `variant()` composer + a single `z.discriminatedUnion('kind', …)`.
// Both real enums are echoed for the frontend.
// ---------------------------------------------------------------------------
const STORE = { store: z.object({ id: z.uuid(), currency: z.enum(CurrencyCode) }) }
const STAT = { stat: StatSchema }
const STAT_CONSOLIDATED = { stat: ConsolidatedStatSchema, perStore: PerStoreStatSchema }
const DETAILS = { details: DashboardDetailsSchema }
const DETAILS_CONS = { details: ConsolidatedDashboardDetailsSchema }
const PAYMENT_METHODS = { paymentMethods: PaymentMethodBreakdownSchema }

const variant = (
	kind: string,
	tenancyScope: TenancyScope,
	dashboardMode: DashboardMode,
	...shapes: Array<Record<string, z.ZodTypeAny>>
) =>
	z.object({
		kind: z.literal(kind),
		tenancyScope: z.literal(tenancyScope),
		dashboardMode: z.literal(dashboardMode),
		...Object.assign({}, ...shapes),
	})

const SINGLE_GLOBAL = variant('SINGLE_GLOBAL', TenancyScope.SINGLE_STORE, DashboardMode.GLOBAL, STORE, STAT, DETAILS)
const SINGLE_NATIONAL = variant('SINGLE_NATIONAL', TenancyScope.SINGLE_STORE, DashboardMode.NATIONAL, STORE, STAT, DETAILS, PAYMENT_METHODS)
const MULTI_GLOBAL = variant('MULTI_GLOBAL', TenancyScope.MULTI_STORE, DashboardMode.GLOBAL, STAT_CONSOLIDATED, DETAILS_CONS)
const MULTI_NATIONAL = variant('MULTI_NATIONAL', TenancyScope.MULTI_STORE, DashboardMode.NATIONAL, STAT_CONSOLIDATED, DETAILS_CONS, PAYMENT_METHODS)

export const GetDashboardOutputSchema = z.discriminatedUnion('kind', [SINGLE_GLOBAL, SINGLE_NATIONAL, MULTI_GLOBAL, MULTI_NATIONAL])

// ---------------------------------------------------------------------------
// Faker builders (each typed by its schema so tsc verifies the shape).
// Swap the use-case body for a real cross-context aggregation later; the
// contract above is final.
// ---------------------------------------------------------------------------
type Metric = z.infer<typeof MetricSchema>
type CurrencyMetric = z.infer<typeof CurrencyMetricSchema>

const fakeMetric = (): Metric => mockMetric()
const fakeCurrencyAmount = (): z.infer<typeof CurrencyAmountSchema> => {
	const currencies = faker.helpers.arrayElements(Object.values(CurrencyCode), 2)
	return Object.fromEntries(currencies.map(c => [c, mockMoney()]))
}
const fakeCurrencyMetric = (): CurrencyMetric => ({
	value: fakeCurrencyAmount(),
	deltaPct: faker.datatype.boolean() ? faker.number.float({ min: -1, max: 1, fractionDigits: 2 }) : null,
})

const recordOf = <V>(enumObject: Record<string, string>, fn: () => V): Record<string, V> =>
	Object.fromEntries(Object.values(enumObject).map(v => [v, fn()]))

const segmentedMetric = (enumObject: Record<string, string>) => ({ total: fakeMetric(), segments: recordOf(enumObject, fakeMetric) })
const segmentedCurrency = (enumObject: Record<string, string>) => ({ total: fakeCurrencyMetric(), segments: recordOf(enumObject, fakeCurrencyMetric) })

const fakeTally = (): z.infer<typeof TallySchema> => ({ count: fakeMetric(), value: fakeMetric() })
const fakeConsolidatedTally = (): z.infer<typeof ConsolidatedTallySchema> => ({ count: fakeMetric(), value: fakeCurrencyMetric() })

const fakeOperationalItem = (): z.infer<typeof OperationalCostItemSchema> => ({
	id: mockId(),
	name: faker.commerce.productName(),
	flow: pick(Object.values(OperationalCostFlow)),
	frequency: pick(Object.values(OperationalCostRecurrency)),
	amount: mockMoney(),
	currency: pick(Object.values(CurrencyCode)),
	startDate: faker.date.recent({ days: 30 }).toISOString(),
	endDate: null,
})

const fakeStat = (): z.infer<typeof StatSchema> => ({
	revenue: fakeMetric(),
	profit: fakeMetric(),
	margin: fakeMetric(),
	averageTicket: fakeMetric(),
	unitsSold: fakeMetric(),
	costs: segmentedMetric(CostKind),
})

const fakeConsolidatedStat = (): z.infer<typeof ConsolidatedStatSchema> => ({
	revenue: fakeCurrencyMetric(),
	profit: fakeCurrencyMetric(),
	margin: fakeMetric(),
	averageTicket: fakeCurrencyMetric(),
	unitsSold: fakeMetric(),
	costs: { total: fakeCurrencyMetric(), segments: recordOf(CostKind, fakeCurrencyMetric) },
})

const fakeDetails = (): z.infer<typeof DashboardDetailsSchema> => ({
	orders: { generated: fakeTally(), paid: fakeTally() },
	fees: { gateway: fakeMetric(), checkout: fakeMetric(), chargeback: fakeMetric() },
	ads: {
		total: fakeMetric(),
		byPlatform: segmentedMetric(MarketingPlatform),
		byType: segmentedMetric(AdAttribution),
		tax: fakeMetric(),
		cpa: fakeMetric(),
		roi: fakeMetric(),
		roas: fakeMetric(),
	},
	productCost: { product: fakeMetric(), shipping: fakeMetric() },
	chargeback: { byStatus: segmentedMetric(DisputeStatus), fees: fakeMetric() },
	refund: fakeMetric(),
	taxes: { ads: fakeMetric(), others: fakeMetric() },
	operational: { total: fakeMetric(), items: mockSeries(3, fakeOperationalItem) },
})

const fakeConsolidatedDetails = (): z.infer<typeof ConsolidatedDashboardDetailsSchema> => ({
	orders: { generated: fakeConsolidatedTally(), paid: fakeConsolidatedTally() },
	fees: { gateway: fakeCurrencyMetric(), checkout: fakeCurrencyMetric(), chargeback: fakeCurrencyMetric() },
	ads: {
		total: fakeCurrencyMetric(),
		byPlatform: segmentedCurrency(MarketingPlatform),
		byType: segmentedCurrency(AdAttribution),
		tax: fakeCurrencyMetric(),
		cpa: fakeMetric(),
		roi: fakeMetric(),
		roas: fakeMetric(),
	},
	productCost: { product: fakeCurrencyMetric(), shipping: fakeCurrencyMetric() },
	chargeback: { byStatus: segmentedCurrency(DisputeStatus), fees: fakeCurrencyMetric() },
	refund: fakeCurrencyMetric(),
	taxes: { ads: fakeCurrencyMetric(), others: fakeCurrencyMetric() },
	operational: { total: fakeCurrencyMetric(), items: mockSeries(3, fakeOperationalItem) },
})

const fakePaymentMethods = (): z.infer<typeof PaymentMethodBreakdownSchema> => ({
	total: fakeTally(),
	byMethod: recordOf(PaymentMethod, () => ({ total: fakeTally(), byStatus: recordOf(PaymentStatus, fakeTally) })),
})

const fakePerStore = (storeIds: string[]): z.infer<typeof PerStoreStatSchema> =>
	Object.fromEntries(storeIds.map(id => [id, fakeStat()]))

/** Deterministic seed from the request so refetches return stable fixtures. */
const seedFrom = (parts: string[]): number => {
	const s = parts.join('|')
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h) || 1
}

/**
 * `GetDashboard` — composition-first discriminated dashboard read.
 *
 * FAKER body, REAL contract: `tenancyScope` (query) selects SINGLE vs MULTI
 * store shape; `dashboardMode` is read from the persisted `StoreVisualization`
 * (default GLOBAL) and toggles the `paymentMethods` section. Real cross-context
 * aggregation is a later swap behind this interface.
 */
@injectable()
export class GetDashboard extends Handler<typeof GetDashboardInputSchema, typeof GetDashboardOutputSchema> {
	readonly name = 'get_dashboard' as const
	readonly inputSchema = GetDashboardInputSchema
	readonly outputSchema = GetDashboardOutputSchema

	constructor(private readonly visualizations: StoreVisualizationRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		faker.seed(seedFrom([input.storeId, input.startDate.toISOString(), input.endDate.toISOString(), ...(input.productIds ?? [])]))

		const visualization = await this.visualizations.findByStoreId(input.storeId)
		const dashboardMode = visualization?.dashboardMode ?? DashboardMode.GLOBAL
		const isMulti = input.tenancyScope === TenancyScope.MULTI_STORE
		const isNational = dashboardMode === DashboardMode.NATIONAL
		const kind = `${isMulti ? 'MULTI' : 'SINGLE'}_${dashboardMode}`

		const result = isMulti
			? {
					kind,
					tenancyScope: TenancyScope.MULTI_STORE,
					dashboardMode,
					stat: fakeConsolidatedStat(),
					perStore: fakePerStore(input.storeIds),
					details: fakeConsolidatedDetails(),
					...(isNational ? { paymentMethods: fakePaymentMethods() } : {}),
				}
			: {
					kind,
					tenancyScope: TenancyScope.SINGLE_STORE,
					dashboardMode,
					store: { id: input.storeId, currency: pick(Object.values(CurrencyCode)) },
					stat: fakeStat(),
					details: fakeDetails(),
					...(isNational ? { paymentMethods: fakePaymentMethods() } : {}),
				}

		return result as this['output']
	}
}

