	ads: ConsolidatedAdsBreakdownSchema,
	productCost: ConsolidatedProductCostBreakdownSchema,
	chargeback: ConsolidatedChargebackBreakdownSchema,
	refund: CurrencyMetricSchema,
	taxes: ConsolidatedTaxesBreakdownSchema,
	operational: ConsolidatedOperationalCostsSchema,
})

// ---------------------------------------------------------------------------
// Legacy KPIs aliases (kept for backward-compat — use Stat* instead)
// ---------------------------------------------------------------------------

/** @deprecated Use StatSchema instead. */
export const KpisSchema = StatSchema
/** @deprecated Use PerStoreStatSchema instead. */
export const PerStoreKpisSchema = PerStoreStatSchema
/** @deprecated Use ConsolidatedStatSchema instead. */
export const ConsolidatedKpisSchema = ConsolidatedStatSchema

// ---------------------------------------------------------------------------
// Profile alerts (discriminated union by `kind`)
// ---------------------------------------------------------------------------

const ProfileAlertBase = z.object({
	id: z.string(),
	platform: z.enum(MarketingPlatform),
	profileId: z.string(),
	displayName: z.string(),
})

export const ReconnectProfileAlertSchema = ProfileAlertBase.extend({
	kind: z.literal('reconnectProfile'),
})

export const SyncErrorAlertSchema = ProfileAlertBase.extend({
	kind: z.literal('syncError'),
	lastSyncedAt: z.iso.datetime({ offset: true }).nullable(),
