import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import { StoreVisualization } from '../../entities/StoreVisualization'
import { StoreVisualizationRepository } from './StoreVisualizationRepository'

@injectable()
export class MockStoreVisualizationRepository extends StoreVisualizationRepository {
	private byId = new Map<string, StoreVisualization>()
	private byStoreId = new Map<string, StoreVisualization>()

	async findByStoreId(storeId: string, _tx?: Transaction): Promise<StoreVisualization | undefined> {
		return this.byStoreId.get(storeId)
	}

	async save(entity: StoreVisualization, _tx?: Transaction): Promise<StoreVisualization> {
		entity.incrementVersion()
		this.byId.set(entity.id.value, entity)
		this.byStoreId.set(entity.storeId.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		const entity = this.byId.get(id)
		if (entity) {
			this.byStoreId.delete(entity.storeId.value)
			this.byId.delete(id)
		}
	}

	seed(entity: StoreVisualization): void {
		this.byId.set(entity.id.value, entity)
		this.byStoreId.set(entity.storeId.value, entity)
	}

	clear(): void {
		this.byId.clear()
		this.byStoreId.clear()
	}
}

