import { describe, it, expect } from 'bun:test'
import { TenancyScope, DashboardMode } from '@bk-dash/contracts-typescript/wire/enums'
import { GetDashboard, GetDashboardOutputSchema } from './GetDashboard'
import { MockStoreVisualizationRepository } from '../repositories/StoreVisualizationRepository/MockStoreVisualizationRepository'
import { StoreVisualization } from '../entities/StoreVisualization'

const STORE_ID = '11111111-1111-4111-8111-111111111111'
const STORE_IDS = ['11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222222']
const RANGE = { startDate: new Date('2026-05-01T00:00:00Z'), endDate: new Date('2026-05-31T00:00:00Z') }

function useCase(persistedMode?: DashboardMode): GetDashboard {
	const repo = new MockStoreVisualizationRepository()
	if (persistedMode) repo.seed(StoreVisualization.create({ storeId: STORE_ID, dashboardMode: persistedMode }))
	return new GetDashboard(repo)
}

function run(tenancyScope: TenancyScope, persistedMode?: DashboardMode) {
	return useCase(persistedMode).execute({ tenancyScope, storeId: STORE_ID, storeIds: STORE_IDS, ...RANGE })
}

describe('GetDashboard', () => {
	it('SINGLE + default (no persisted row) → SINGLE_GLOBAL: store + stat + details, no paymentMethods/perStore', async () => {
		const out = await run(TenancyScope.SINGLE_STORE)
		expect(out.kind).toBe('SINGLE_GLOBAL')
		expect(out.tenancyScope).toBe(TenancyScope.SINGLE_STORE)
		expect(out.dashboardMode).toBe(DashboardMode.GLOBAL)
		expect('store' in out).toBe(true)
		expect('stat' in out).toBe(true)
		expect('details' in out).toBe(true)
		expect('paymentMethods' in out).toBe(false)
		expect('perStore' in out).toBe(false)
	})

	it('SINGLE + persisted NATIONAL → SINGLE_NATIONAL: adds paymentMethods', async () => {
		const out = await run(TenancyScope.SINGLE_STORE, DashboardMode.NATIONAL)
		expect(out.kind).toBe('SINGLE_NATIONAL')
		expect(out.dashboardMode).toBe(DashboardMode.NATIONAL)
		expect('paymentMethods' in out).toBe(true)
	})

	it('MULTI + default → MULTI_GLOBAL: perStore (keyed by storeIds) + no store, no paymentMethods', async () => {
		const out = await run(TenancyScope.MULTI_STORE)
		expect(out.kind).toBe('MULTI_GLOBAL')
		expect('perStore' in out).toBe(true)
		expect('store' in out).toBe(false)
		expect('paymentMethods' in out).toBe(false)
		expect(Object.keys((out as { perStore: Record<string, unknown> }).perStore).sort()).toEqual([...STORE_IDS].sort())
	})

	it('MULTI + persisted NATIONAL → MULTI_NATIONAL: perStore + paymentMethods', async () => {
		const out = await run(TenancyScope.MULTI_STORE, DashboardMode.NATIONAL)
		expect(out.kind).toBe('MULTI_NATIONAL')
		expect('perStore' in out).toBe(true)
		expect('paymentMethods' in out).toBe(true)
	})

	it('faker output conforms to the discriminated-union schema', async () => {
		for (const scope of [TenancyScope.SINGLE_STORE, TenancyScope.MULTI_STORE]) {
			for (const mode of [DashboardMode.GLOBAL, DashboardMode.NATIONAL]) {
				const out = await run(scope, mode)
				expect(() => GetDashboardOutputSchema.parse(out)).not.toThrow()
			}
		}
	})

	it('is deterministic for the same inputs (seeded faker)', async () => {
		const a = await run(TenancyScope.SINGLE_STORE)
		const b = await run(TenancyScope.SINGLE_STORE)
		expect(a).toEqual(b)
	})
})

