import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DashboardMode } from '@bk-dash/contracts-typescript/wire/enums'
import { SetStoreVisualization } from './SetStoreVisualization'
import { StoreVisualizationRepository } from '../repositories/StoreVisualizationRepository'

const STORE = testId('store', '1')

describe('SetStoreVisualization', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let cmd: SetStoreVisualization
	let repo: StoreVisualizationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		cmd = testBed.resolve(SetStoreVisualization)
		repo = testBed.resolve(StoreVisualizationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('creates a row when none exists for the store', async () => {
		const { id } = await cmd.execute({ storeId: STORE, dashboardMode: DashboardMode.NATIONAL })
		expect(id).toBeTruthy()
		const saved = await repo.findByStoreId(STORE)
		expect(saved?.dashboardMode).toBe(DashboardMode.NATIONAL)
	})

	it('upserts the same row on repeat (no duplicate, mode changes)', async () => {
		const first = await cmd.execute({ storeId: STORE, dashboardMode: DashboardMode.GLOBAL })
		const second = await cmd.execute({ storeId: STORE, dashboardMode: DashboardMode.NATIONAL })
		expect(second.id).toBe(first.id)
		const saved = await repo.findByStoreId(STORE)
		expect(saved?.dashboardMode).toBe(DashboardMode.NATIONAL)
	})
})

