/**
 * Dashboard read vocabulary — section schemas composed by GetDashboard.
 * Generic atoms (Metric/CurrencyMetric/Tally/segmented) come from @shared/schemas.
 */
import { z } from '@bk-dash/core-typescript'
import {
	CurrencyCode,
	CostKind,
	MarketingPlatform,
	AdAttribution,
	DisputeStatus,
	PaymentMethod,
	PaymentStatus,
	OperationalCostFlow,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import {
	MetricSchema,
	CurrencyMetricSchema,
	TallySchema,
	ConsolidatedTallySchema,
	segmented,
} from '../../shared/schemas'

// ---------------------------------------------------------------------------
// Segmented breakdowns (mono-currency)
// ---------------------------------------------------------------------------
export const CostBreakdownSchema = segmented(CostKind)
export const AdsByPlatformSchema = segmented(MarketingPlatform)
export const AdsByTypeSchema = segmented(AdAttribution)
export const ChargebackByStatusSchema = segmented(DisputeStatus)

// ---------------------------------------------------------------------------
// Named breakdowns (tooltip data — mono-currency)
// ---------------------------------------------------------------------------
export const FeesBreakdownSchema = z.object({
	gateway: MetricSchema,
	checkout: MetricSchema,
	chargeback: MetricSchema,
})

export const AdsBreakdownSchema = z.object({
	total: MetricSchema,
	byPlatform: AdsByPlatformSchema,
	byType: AdsByTypeSchema,
	tax: MetricSchema,
	cpa: MetricSchema,
	roi: MetricSchema,
	roas: MetricSchema,
})

export const ChargebackBreakdownSchema = z.object({
	byStatus: ChargebackByStatusSchema,
	fees: MetricSchema,
})

export const TaxesBreakdownSchema = z.object({
	ads: MetricSchema,
	others: MetricSchema,
})

export const ProductCostBreakdownSchema = z.object({
	product: MetricSchema,
	shipping: MetricSchema,
})

// ---------------------------------------------------------------------------
// Consolidated breakdown variants (money leaves → CurrencyMetric; ratios stay Metric)
// ---------------------------------------------------------------------------
export const ConsolidatedFeesBreakdownSchema = z.object({
	gateway: CurrencyMetricSchema,
	checkout: CurrencyMetricSchema,
	chargeback: CurrencyMetricSchema,
})

export const ConsolidatedAdsBreakdownSchema = z.object({
	total: CurrencyMetricSchema,
	byPlatform: z.object({
		total: CurrencyMetricSchema,
		segments: z.record(z.enum(MarketingPlatform), CurrencyMetricSchema),
	}),
	byType: z.object({
		total: CurrencyMetricSchema,
		segments: z.record(z.enum(AdAttribution), CurrencyMetricSchema),
	}),
	tax: CurrencyMetricSchema,
	cpa: MetricSchema,
	roi: MetricSchema,
	roas: MetricSchema,
})

export const ConsolidatedProductCostBreakdownSchema = z.object({
	product: CurrencyMetricSchema,
	shipping: CurrencyMetricSchema,
})

export const ConsolidatedChargebackBreakdownSchema = z.object({
	byStatus: z.object({
		total: CurrencyMetricSchema,
		segments: z.record(z.enum(DisputeStatus), CurrencyMetricSchema),
	}),
	fees: CurrencyMetricSchema,
})

export const ConsolidatedTaxesBreakdownSchema = z.object({
	ads: CurrencyMetricSchema,
	others: CurrencyMetricSchema,
})

// ---------------------------------------------------------------------------
// Operational costs
// ---------------------------------------------------------------------------
export const OperationalCostItemSchema = z.object({
	id: z.string(),
	name: z.string(),
	flow: z.enum(OperationalCostFlow),
	frequency: z.enum(OperationalCostRecurrency),
	amount: z.number(),
	currency: z.enum(CurrencyCode),
	startDate: z.iso.datetime({ offset: true }),
	endDate: z.iso.datetime({ offset: true }).nullable(),
})

export const OperationalCostsSchema = z.object({
	total: MetricSchema,
	items: z.array(OperationalCostItemSchema),
