import { injectable } from 'tsyringe-neo'
import { desc, eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { bkdashGoals } from '@bk-dash/contracts/db'
import { Goal, GoalSchema } from '../../entities/Goal'
import { GoalRepository } from './GoalRepository'

/**
 * Drizzle-backed real impl of GoalRepository (iter 301 — closes the
 * iter-300 known-gap #1: GoalRepository was Mock-only). UPSERT on save
 * via deterministic id; `incrementVersion` bumps the optimistic-
 * concurrency counter on every write.
 *
 * The `goals.goals` Drizzle table got a `user_id` column added in
 * migration 0020 (iter 301) so `findLastByUserAndStore` works against
 * the canonical row shape the Goal entity carries.
 */
@injectable()
export class DrizzleGoalRepository extends GoalRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<Goal | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(bkdashGoals).where(eq(bkdashGoals.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async listByStoreId(storeId: string, tx?: DrizzleClient): Promise<Goal[]> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			return await dbc.select().from(bkdashGoals).where(eq(bkdashGoals.storeId, storeId)).orderBy(desc(bkdashGoals.endDate))
		})
		if (!result.success) throw result.error
		return (result.data ?? []).map(row => this.toDomain(row))
	}

	async findLastByUserAndStore(storeId: string, tx?: DrizzleClient): Promise<Goal | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(bkdashGoals).where(eq(bkdashGoals.storeId, storeId)).orderBy(desc(bkdashGoals.endDate)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: Goal, tx?: DrizzleClient): Promise<Goal> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(bkdashGoals)
				.values(data)
				.onConflictDoUpdate({
					target: bkdashGoals.id,
					set: {
						storeId: data.storeId,
						type: data.type,
						targetAmountCents: data.targetAmountCents,
						targetCurrency: data.targetCurrency,
						startDate: data.startDate,
						endDate: data.endDate,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(bkdashGoals).where(eq(bkdashGoals.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof bkdashGoals.$inferSelect): Goal {
		const parsed = GoalSchema.parse({
			storeId: row.storeId,
			type: row.type,
			targetAmount: { amountCents: Number(row.targetAmountCents), currency: row.targetCurrency },
			from: row.startDate,
			to: row.endDate,
		})
		return new Goal({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: Goal): typeof bkdashGoals.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			type: entity.type,
			targetAmountCents: BigInt(entity.targetAmount.amountCents),
			targetCurrency: entity.targetAmount.currency,
			startDate: entity.from,
			endDate: entity.to,
			version: entity.version,
		}
	}
}

