import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { GoalType, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { GoalRepository } from '../repositories/GoalRepository'

export const GetGoalInputSchema = z.object({
	storeId: z.uuid(),
})

export const GetGoalOutputSchema = z.object({
	goal: z
		.object({
			id: z.uuid(),
			storeId: z.uuid(),
			type: z.enum(GoalType),
			targetAmount: z.object({ amountCents: z.number(), currency: z.enum(CurrencyCode) }),
			from: z.date(),
			to: z.date(),
		})
		.nullable(),
})

/**
 * `GetGoal` — the current active goal for the session store (the goal whose
 * window contains now), or `null`. Real read over the Goal aggregate.
 */
@injectable()
export class GetGoal extends Handler<typeof GetGoalInputSchema, typeof GetGoalOutputSchema> {
	readonly name = 'get_goal' as const
	readonly inputSchema = GetGoalInputSchema
	readonly outputSchema = GetGoalOutputSchema

	constructor(private readonly goals: GoalRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		const goal = await this.goals.findActiveByStoreId(input.storeId, new Date())
		if (!goal) return { goal: null }
		return {
			goal: {
				id: goal.id.value,
				storeId: goal.storeId.value,
				type: goal.type,
				targetAmount: { amountCents: goal.targetAmount.amountCents, currency: goal.targetAmount.currency },
				from: goal.from,
				to: goal.to,
			},
		}
	}
}

