import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { GoalType, TenancyScope } from '@bk-dash/contracts-typescript/wire/enums'
import { faker } from '../../shared/testing/mock'
import { Goal } from '../entities/Goal'
import { GoalRepository } from '../repositories/GoalRepository'

// ---------------------------------------------------------------------------
// Input — `tenancyScope` input-only (selects store set; output shape identical).
// ---------------------------------------------------------------------------
export const GetGoalProgressInputSchema = z.object({
	tenancyScope: z.enum(TenancyScope),
	storeId: z.uuid(), // ← ctx.session.storeId      (SINGLE_STORE)
	storeIds: z.array(z.uuid()), // ← ctx.membership.storeIds  (MULTI_STORE)
	startDate: z.date(),
	endDate: z.date(),
})

// ---------------------------------------------------------------------------
// Output — per goal type (REVENUE/PROFIT), with per-store composition.
// Money is a plain normalized number (MULTI crosses currencies; faker normalizes).
// `progress` (achieved / target) is derived frontend-side.
// ---------------------------------------------------------------------------
export const GoalStoreProgressSchema = z.object({
	storeId: z.uuid(),
	storeName: z.string(),
	target: z.number(),
	achieved: z.number(),
})

export const GoalTypeProgressSchema = z.object({
	target: z.number(),
	achieved: z.number(),
	stores: z.array(GoalStoreProgressSchema),
})

export const GetGoalProgressOutputSchema = z.object({
	byType: z.partialRecord(z.enum(GoalType), GoalTypeProgressSchema),
})

const DAY = 86_400_000
const round2 = (n: number): number => Math.round(n * 100) / 100
const hash = (s: string): number => {
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h)
}

/** Deterministic fake store name (real tenancy lookup is the later swap). */
const fakeStoreName = (storeId: string): string => {
	faker.seed(hash(storeId) || 1)
	return faker.company.name()
}

/** Deterministic actual-vs-target factor (0.3..1.2) — stands in for real revenue/profit. */
const achievedFactor = (key: string): number => 0.3 + (hash(key) % 90) / 100

/** Overlapping slice of a goal's target that falls inside [from,to] — no averaging. */
const proratedSlice = (goal: Goal, from: Date, to: Date): number => {
	const goalDays = Math.max(1, Math.round((goal.to.getTime() - goal.from.getTime()) / DAY) + 1)
	const overlapStart = Math.max(goal.from.getTime(), from.getTime())
	const overlapEnd = Math.min(goal.to.getTime(), to.getTime())
	if (overlapEnd < overlapStart) return 0
	const overlapDays = Math.round((overlapEnd - overlapStart) / DAY) + 1
	const dailyTarget = goal.targetAmount.amountCents / 100 / goalDays
	return dailyTarget * overlapDays
}

/**
 * `GetGoalProgress` — REAL goals + FAKER actuals. Goals intersecting the window
 * are prorated to their overlapping slice, grouped by type, with per-store
 * composition (name + target + achieved). `tenancyScope` selects the store set.
 */
@injectable()
export class GetGoalProgress extends Handler<typeof GetGoalProgressInputSchema, typeof GetGoalProgressOutputSchema> {
	readonly name = 'get_goal_progress' as const
	readonly inputSchema = GetGoalProgressInputSchema
	readonly outputSchema = GetGoalProgressOutputSchema

	constructor(private readonly goals: GoalRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		const storeIds = input.tenancyScope === TenancyScope.MULTI_STORE ? input.storeIds : [input.storeId]
		const goals = await this.goals.listIntersecting(storeIds, input.startDate, input.endDate)

		// Accumulate prorated target per (type, storeId).
		const targets = new Map<GoalType, Map<string, number>>()
		for (const goal of goals) {
			const slice = proratedSlice(goal, input.startDate, input.endDate)
			if (slice <= 0) continue
			const perStore = targets.get(goal.type) ?? new Map<string, number>()
			perStore.set(goal.storeId.value, (perStore.get(goal.storeId.value) ?? 0) + slice)
			targets.set(goal.type, perStore)
		}

		const byType: Partial<Record<GoalType, z.infer<typeof GoalTypeProgressSchema>>> = {}
		for (const [type, perStore] of targets) {
			const stores = [...perStore.entries()].map(([storeId, target]) => ({
				storeId,
				storeName: fakeStoreName(storeId),
				target: round2(target),
				achieved: round2(target * achievedFactor(`${type}:${storeId}`)),
			}))
			byType[type] = {
				target: round2(stores.reduce((sum, s) => sum + s.target, 0)),
				achieved: round2(stores.reduce((sum, s) => sum + s.achieved, 0)),
				stores,
			}
		}

		return { byType }
	}
}

