import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { GetGoal, GetGoalOutputSchema } from '../usecases/GetGoal'

export const GetGoalControllerInputSchema = z.object({
	ctx: z.object({ session: z.object({ storeId: z.uuid() }) }),
})

export const GetGoalControllerOutputSchema = GetGoalOutputSchema

@injectable()
export class GetGoalController extends Controller<typeof GetGoalControllerInputSchema, typeof GetGoalControllerOutputSchema> {
	readonly path = '/goals/current'
	readonly method = 'get' as const
	readonly description = 'The current active revenue/profit goal for the session store (or null)'
	readonly inputSchema = GetGoalControllerInputSchema
	readonly outputSchema = GetGoalControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private query: GetGoal) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.query.execute({ storeId: request.ctx.session.storeId })
		return { status: HttpStatusCode.OK, data }
	}
}

