import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CurrencyCode, GoalType, TenancyScope } from '@bk-dash/contracts-typescript/wire/enums'
import { CreateGoal } from './CreateGoal'
import { GetGoal } from './GetGoal'
import { GetGoalProgress } from './GetGoalProgress'

const DAY = 86_400_000
const STORE = testId('store', 'g1')
const STORE2 = testId('store', 'g2')

describe('GetGoal + GetGoalProgress', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let create: CreateGoal
	let getGoal: GetGoal
	let getProgress: GetGoalProgress

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		create = testBed.resolve(CreateGoal)
		getGoal = testBed.resolve(GetGoal)
		getProgress = testBed.resolve(GetGoalProgress)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('GetGoal returns the goal whose window contains now', async () => {
		const now = Date.now()
		await create.execute({
			storeId: STORE,
			type: GoalType.REVENUE,
			targetAmount: { amountCents: 100_000, currency: CurrencyCode.USD },
			from: new Date(now - 5 * DAY),
			to: new Date(now + 5 * DAY),
		})
		const out = await getGoal.execute({ storeId: STORE })
		expect(out.goal).not.toBeNull()
		expect(out.goal?.type).toBe(GoalType.REVENUE)
		expect(out.goal?.targetAmount.amountCents).toBe(100_000)
	})

	it('GetGoal returns null when no goal is active', async () => {
		await create.execute({
			storeId: STORE,
			type: GoalType.REVENUE,
			targetAmount: { amountCents: 100_000, currency: CurrencyCode.USD },
			from: new Date('2020-01-01T00:00:00Z'),
			to: new Date('2020-02-01T00:00:00Z'),
		})
		const out = await getGoal.execute({ storeId: STORE })
		expect(out.goal).toBeNull()
	})

	it('GetGoalProgress prorates intersecting goals per type with per-store composition (MULTI)', async () => {
		const from = new Date('2026-06-01T00:00:00Z')
		const to = new Date('2026-06-30T00:00:00Z')
		await create.execute({ storeId: STORE, type: GoalType.REVENUE, targetAmount: { amountCents: 300_000, currency: CurrencyCode.USD }, from, to })
		await create.execute({ storeId: STORE2, type: GoalType.PROFIT, targetAmount: { amountCents: 100_000, currency: CurrencyCode.USD }, from, to })

		const out = await getProgress.execute({ tenancyScope: TenancyScope.MULTI_STORE, storeId: STORE, storeIds: [STORE, STORE2], startDate: from, endDate: to })

		expect(out.byType.REVENUE).toBeDefined()
		expect(out.byType.PROFIT).toBeDefined()
		// full window → prorated slice = full amount ($3000)
		expect(out.byType.REVENUE?.target).toBeCloseTo(3000, 0)
		const revStore = out.byType.REVENUE?.stores[0]
		expect(revStore?.storeId).toBe(STORE)
		expect(revStore?.storeName).toBeTruthy()
		expect(typeof revStore?.achieved).toBe('number')
	})

	it('GetGoalProgress (SINGLE) only counts the session store', async () => {
		const from = new Date('2026-06-01T00:00:00Z')
		const to = new Date('2026-06-30T00:00:00Z')
		await create.execute({ storeId: STORE, type: GoalType.REVENUE, targetAmount: { amountCents: 300_000, currency: CurrencyCode.USD }, from, to })
		await create.execute({ storeId: STORE2, type: GoalType.REVENUE, targetAmount: { amountCents: 999_000, currency: CurrencyCode.USD }, from, to })

		const out = await getProgress.execute({ tenancyScope: TenancyScope.SINGLE_STORE, storeId: STORE, storeIds: [STORE, STORE2], startDate: from, endDate: to })

		expect(out.byType.REVENUE?.stores).toHaveLength(1)
		expect(out.byType.REVENUE?.stores[0]?.storeId).toBe(STORE)
	})
})

