import { Repository } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { Store } from '../../entities/Store'

export abstract class StoreRepository extends Repository<Store> {
	abstract findById(id: string, tx?: Transaction): Promise<Store | undefined>
	// Counts stores the user is a member of AND that are NOT disabled.
	// Used by the STORE_AMOUNT quota gate (CreateStore) and MyStores.storeCredits.
	abstract countActiveStoresByUserId(userId: string, tx?: Transaction): Promise<number>
	// Count of non-disabled stores bound to each subscription id. Drives the
	// per-subscription quota gate (T8) and GetMySubscriptions usage (T4).
	abstract countStoresBySubscriptionIds(subscriptionIds: string[], tx?: Transaction): Promise<Record<string, number>>
}

