import { injectable } from 'tsyringe-neo'
import Z from 'zod'
import { Handler, z } from '@bk-dash/core-typescript'
import { CurrencyCode, Role, MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreMembershipRepository, StoreRepository } from '@tenancy/repositories'
import { faker, mockId, mockSeries, pick } from '../../shared/testing/mock'

// ---------------------------------------------------------------------------
// Profile alerts (redefined here — was an orphan in the schema reorg). Derived
// FE-side into text/action; faker-generated until integration sync state is real.
// ---------------------------------------------------------------------------
const ProfileAlertBase = z.object({
	id: z.string(),
	platform: z.enum(MarketingPlatform),
	profileId: z.string(),
	displayName: z.string(),
})
export const ReconnectProfileAlertSchema = ProfileAlertBase.extend({ kind: z.literal('reconnectProfile') })
export const SyncErrorAlertSchema = ProfileAlertBase.extend({
	kind: z.literal('syncError'),
	lastSyncedAt: z.iso.datetime({ offset: true }).nullable(),
})
export const ProfileAlertSchema = z.discriminatedUnion('kind', [ReconnectProfileAlertSchema, SyncErrorAlertSchema])

const StoreRefSchema = z.object({
	id: z.uuid(),
	name: z.string(),
	currency: z.enum(CurrencyCode),
	role: z.enum(Role),
})

// ---------------------------------------------------------------------------
// Input — user identity from ctx.user; storeId = the active store (nullable).
// ---------------------------------------------------------------------------
export const GetUserInfoInputSchema = z.object({
	user: z.object({ id: z.uuid(), name: z.string(), email: z.string() }),
	storeId: z.uuid().nullable(),
})

export const GetUserInfoOutputSchema = z.object({
	user: z.object({ id: z.uuid(), name: z.string(), email: z.email(), avatarUrl: z.url().nullable() }),
	current: StoreRefSchema.nullable(),
	stores: z.array(StoreRefSchema),
	alerts: z.array(ProfileAlertSchema),
})

const hash = (s: string): number => {
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h) || 1
}

const fakeAlert = (): Z.infer<typeof ProfileAlertSchema> => {
	const base = { id: mockId(), platform: pick(Object.values(MarketingPlatform)), profileId: mockId(), displayName: faker.company.name() }
	return faker.datatype.boolean()
		? { ...base, kind: 'reconnectProfile' }
		: { ...base, kind: 'syncError', lastSyncedAt: faker.datatype.boolean() ? faker.date.recent({ days: 7 }).toISOString() : null }
}

/**
 * `GetUserInfo` — the Header's contextual read: user identity + all of the
 * user's stores (with role + currency) + the active store + profile alerts.
 * REAL user (ctx) + REAL stores (tenancy); alerts faked until integration sync
 * state is wired. No store scope required (Header loads before a store is picked).
 */
@injectable()
export class GetUserInfo extends Handler<typeof GetUserInfoInputSchema, typeof GetUserInfoOutputSchema> {
	readonly name = 'get_user_info' as const
	readonly inputSchema = GetUserInfoInputSchema
	readonly outputSchema = GetUserInfoOutputSchema

	constructor(
		private readonly memberships: StoreMembershipRepository,
		private readonly stores: StoreRepository,
	) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		const memberships = await this.memberships.findByUserId(input.user.id)
		const stores = (
			await Promise.all(
				memberships.map(async membership => {
					const store = await this.stores.findById(membership.storeId.value)
					if (!store) return null
					return { id: membership.storeId.value, name: store.name, currency: store.reportingCurrency, role: membership.role }
				}),
			)
		).filter((s): s is Z.infer<typeof StoreRefSchema> => s !== null)

		const current = input.storeId ? (stores.find(s => s.id === input.storeId) ?? null) : null

		faker.seed(hash(input.user.id))
		const alerts = mockSeries(faker.number.int({ min: 0, max: 2 }), fakeAlert)

		return {
			user: { id: input.user.id, name: input.user.name, email: input.user.email, avatarUrl: null },
			current,
			stores,
			alerts,
		}
	}
}

