import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CurrencyCode, Role } from '@bk-dash/contracts-typescript/wire/enums'
import { GetUserInfo } from './GetUserInfo'
import { StoreRepository, StoreMembershipRepository } from '@tenancy/repositories'
import { Store } from '@tenancy/entities/Store'
import { StoreMembership } from '@tenancy/entities/StoreMembership'

const USER = testId('user', 'u1')

describe('GetUserInfo', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let getUserInfo: GetUserInfo
	let storeRepo: StoreRepository
	let membershipRepo: StoreMembershipRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		getUserInfo = testBed.resolve(GetUserInfo)
		storeRepo = testBed.resolve(StoreRepository)
		membershipRepo = testBed.resolve(StoreMembershipRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedStore(name: string, currency: CurrencyCode): Promise<string> {
		const store = Store.create({ name, reportingCurrency: currency, timezone: 'UTC' })
		await storeRepo.save(store)
		await membershipRepo.save(StoreMembership.forOwner({ storeId: store.id.value, userId: USER }))
		return store.id.value
	}

	it('returns user identity + real stores (role + currency) + active store + alerts', async () => {
		const storeId = await seedStore('Acme', CurrencyCode.USD)
		const out = await getUserInfo.execute({ user: { id: USER, name: 'Gabriel', email: 'g@bk.app' }, storeId })

		expect(out.user.name).toBe('Gabriel')
		expect(out.user.avatarUrl).toBeNull()
		expect(out.stores).toHaveLength(1)
		expect(out.stores[0]?.name).toBe('Acme')
		expect(out.stores[0]?.currency).toBe(CurrencyCode.USD)
		expect(out.stores[0]?.role).toBe(Role.OWNER)
		expect(out.current?.id).toBe(storeId)
		expect(Array.isArray(out.alerts)).toBe(true)
	})

	it('current is null when no active store is selected', async () => {
		await seedStore('Acme', CurrencyCode.BRL)
		const out = await getUserInfo.execute({ user: { id: USER, name: 'G', email: 'g@bk.app' }, storeId: null })
		expect(out.current).toBeNull()
		expect(out.stores).toHaveLength(1)
	})
})

