### Reset Store When Needed

```typescript
const initialState = {
  selectedIds: [],
  isModalOpen: false,
}

export const useProductsStore = create<ProductsStore>((set) => ({
  ...initialState,
  // Actions...
  reset: () => set(initialState),
}))

// Usage - reset on unmount
useEffect(() => {
  return () => useProductsStore.getState().reset()
}, [])
```

