/**
 * Like `z.record(z.enum(E), value)` but emits EXPLICIT per-member properties to
 * OpenAPI, so the generated SDK is keyed by the enum members
 * (`{ marketing: V, product: V, … }`) instead of a string-indexed map
 * (`{ [k: string]: V }`). All members are required — segments always carry every
 * key (0/empty when there's no data).
 */
export function enumRecord<T extends Record<string, string>, V extends Z.ZodTypeAny>(
	enumObject: T,
	valueSchema: V,
): Z.ZodObject<{ [K in T[keyof T]]: V }> {
	const shape = {} as { [K in T[keyof T]]: V }
	for (const key of Object.values(enumObject) as T[keyof T][]) shape[key] = valueSchema
	return z.object(shape) as unknown as Z.ZodObject<{ [K in T[keyof T]]: V }>
}

