import type { Meta, StoryObj } from '@storybook/react'
import { Gauge } from '../gauge'

const meta: Meta<typeof Gauge> = {
	title: 'UI/Gauge',
	component: Gauge,
	argTypes: {
		value: {
			control: { type: 'range', min: 0, max: 1.2, step: 0.05 },
		},
	},
}

export default meta
type Story = StoryObj<typeof Gauge>

export const Default: Story = {
	args: {
		value: 0.65,
	},
}

export const WithLabel: Story = {
	args: {
		value: 0.72,
	},
	render: args => (
		<div className="w-48">
			<Gauge {...args}>
				<span className="text-2xl font-bold">72%</span>
			</Gauge>
		</div>
	),
}

export const Empty: Story = {
	args: { value: 0 },
	render: args => (
		<div className="w-48">
			<Gauge {...args}>
				<span className="text-2xl font-bold text-muted-foreground">0%</span>
			</Gauge>
		</div>
	),
}

export const Complete: Story = {
	args: { value: 1 },
	render: args => (
		<div className="w-48">
			<Gauge {...args}>
				<span className="text-2xl font-bold text-success">100%</span>
			</Gauge>
		</div>
	),
}

export const Exceeded: Story = {
	args: { value: 1.15 },
	render: args => (
		<div className="w-48">
			<Gauge {...args}>
				<span className="text-2xl font-bold text-success">115%</span>
			</Gauge>
		</div>
	),
}

export const AllStates: Story = {
	render: () => (
		<div className="flex flex-wrap gap-8 items-end">
			{[0, 0.25, 0.5, 0.75, 1, 1.1].map(v => (
				<div key={v} className="w-36 flex flex-col items-center gap-1">
					<Gauge value={v}>
