import * as React from 'react'
import type { Meta, StoryObj } from '@storybook/react'
import { MoneyInput } from '../money-input'

const meta: Meta<typeof MoneyInput> = {
	title: 'UI/MoneyInput',
	component: MoneyInput,
	argTypes: {
		amountCents: {
			control: { type: 'number' },
			description: 'Amount in integer cents (e.g. 150050 = 1500.50)',
		},
		currency: {
			control: 'select',
			options: ['BRL', 'USD', 'EUR', 'GBP', 'ARS'],
		},
	},
}

export default meta
type Story = StoryObj<typeof MoneyInput>

function Controlled(props: Partial<React.ComponentProps<typeof MoneyInput>>) {
	const [amountCents, setAmountCents] = React.useState(props.amountCents ?? 0)
	const [currency, setCurrency] = React.useState(props.currency ?? 'BRL')
	return (
		<div className="w-64 flex flex-col gap-2">
			<MoneyInput
				amountCents={amountCents}
				onAmountCentsChange={setAmountCents}
				currency={currency}
				onCurrencyChange={setCurrency}
				currencies={props.currencies}
				placeholder={props.placeholder}
			/>
			<p className="text-xs text-muted-foreground">
				{amountCents} cents · {currency}
			</p>
		</div>
	)
}

export const Default: Story = {
	render: () => <Controlled />,
}

export const WithValue: Story = {
	render: () => <Controlled amountCents={150050} currency="BRL" />,
}

export const USD: Story = {
	render: () => <Controlled amountCents={9999} currency="USD" />,
}

export const CustomCurrencies: Story = {
	render: () => (
		<Controlled
			amountCents={0}
			currency="EUR"
			currencies={['EUR', 'GBP', 'CHF']}
		/>
	),
}

export const Disabled: Story = {
	render: () => (
		<div className="w-64">
			<MoneyInput
				amountCents={100000}
				onAmountCentsChange={() => {}}
				currency="BRL"
				onCurrencyChange={() => {}}
				disabled
			/>
		</div>
	),
}

