import * as React from 'react'
import { useMaskito } from '@maskito/react'

import { cn } from '@/lib/utils'
import {
	currencyAmountMaskOptions,
	currencyAmountToDisplayString,
	displayStringToCurrencyCents,
} from '@/lib/masks'
import {
	InputGroup,
	InputGroupSelectTrigger,
	InputGroupInput,
} from '@/components/ui/input-group'
import {
	Select,
	SelectContent,
	SelectItem,
	SelectValue,
} from '@/components/ui/select'

const DEFAULT_CURRENCIES = ['BRL', 'USD', 'EUR', 'GBP', 'ARS', 'CLP', 'MXN']

export interface MoneyInputProps {
	/** Current amount in integer cents (e.g. 150050 = R$ 1.500,50) */
	amountCents: number
	onAmountCentsChange: (cents: number) => void
	/** ISO 4217 currency code (e.g. "BRL") */
	currency: string
	onCurrencyChange: (currency: string) => void
	/** Override the available currency options */
	currencies?: string[]
	placeholder?: string
	className?: string
	disabled?: boolean
	id?: string
}

/**
 * Controlled currency selector + masked decimal amount input.
 * Emits integer cents via `onAmountCentsChange`.
 * Layout: InputGroup [ Select(currency) | masked number input ]
 */
function MoneyInput({
	amountCents,
	onAmountCentsChange,
	currency,
	onCurrencyChange,
	currencies = DEFAULT_CURRENCIES,
	placeholder = '0,00',
	className,
	disabled,
	id,
}: MoneyInputProps) {
	const maskRef = useMaskito({ options: currencyAmountMaskOptions })

	// Sync the input's display value when `amountCents` changes from outside
	const displayValue = amountCents > 0 ? currencyAmountToDisplayString(amountCents) : ''

	const handleInput = React.useCallback(
		(e: React.FormEvent<HTMLInputElement>) => {
			const cents = displayStringToCurrencyCents(e.currentTarget.value)
			onAmountCentsChange(cents)
		},
		[onAmountCentsChange],
	)

	return (
		<InputGroup data-slot="money-input" className={cn(className)} aria-disabled={disabled}>
			<Select value={currency} onValueChange={v => { if (v !== null) onCurrencyChange(v) }} disabled={disabled}>
				<InputGroupSelectTrigger className="min-w-[4.5rem]">
					<SelectValue placeholder="BRL" />
				</InputGroupSelectTrigger>
				<SelectContent align="start">
					{currencies.map(c => (
						<SelectItem key={c} value={c}>
							{c}
						</SelectItem>
					))}
				</SelectContent>
			</Select>

			<InputGroupInput
				ref={maskRef}
				id={id}
				inputMode="decimal"
				placeholder={placeholder}
				defaultValue={displayValue}
				key={displayValue}
				onInput={handleInput}
				disabled={disabled}
			/>
		</InputGroup>
	)
}

export { MoneyInput }

import * as React from 'react'
import { Dialog as SheetPrimitive } from '@base-ui/react/dialog'

import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { surface } from './surfaces'
import { IconX } from '@tabler/icons-react'

function Sheet({ ...props }: SheetPrimitive.Root.Props) {
	return <SheetPrimitive.Root data-slot="sheet" {...props} />
}

function SheetTrigger({ ...props }: SheetPrimitive.Trigger.Props) {
	return <SheetPrimitive.Trigger data-slot="sheet-trigger" {...props} />
}

function SheetClose({ ...props }: SheetPrimitive.Close.Props) {
	return <SheetPrimitive.Close data-slot="sheet-close" {...props} />
}

function SheetPortal({ ...props }: SheetPrimitive.Portal.Props) {
	return <SheetPrimitive.Portal data-slot="sheet-portal" {...props} />
}

function SheetOverlay({ className, ...props }: SheetPrimitive.Backdrop.Props) {
	return (
		<SheetPrimitive.Backdrop
			data-slot="sheet-overlay"
			className={cn(
				'data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 bg-black/10 duration-100 data-ending-style:opacity-0 data-starting-style:opacity-0 supports-backdrop-filter:backdrop-blur-xs fixed inset-0 z-50',
				className,
			)}
			{...props}
		/>
	)
}

function SheetContent({
	className,
	children,
	side = 'right',
	showCloseButton = true,
	...props
}: SheetPrimitive.Popup.Props & {
	side?: 'top' | 'right' | 'bottom' | 'left'
	showCloseButton?: boolean
}) {
	return (
		<SheetPortal>
			<SheetOverlay />
			<SheetPrimitive.Popup
				data-slot="sheet-content"
				data-side={side}
