import * as React from 'react'
import { cn } from '@/lib/utils'

export interface GaugeProps {
	/** Progress value between 0 and 1 */
	value: number
	className?: string
	trackClassName?: string
	indicatorClassName?: string
	children?: React.ReactNode
}

/**
 * 180° semicircle SVG progress arc.
 * - Track: the full half-circle background
 * - Indicator: fills `value` of the half-circle (green at value>=1, brand/primary otherwise)
 * - children: centered content (e.g. big % label)
 */
function Gauge({ value, className, trackClassName, indicatorClassName, children }: GaugeProps) {
	const clampedValue = Math.min(1, Math.max(0, value))
	const isComplete = value >= 1

	// SVG geometry for a 180° semicircle
	// viewBox: 0 0 200 110 (extra 10px below centre for children clearance)
	const cx = 100
	const cy = 100
	const r = 80
	const strokeWidth = 14

	// The half-circle arc: from left (180°) to right (0°)
	// start = left point, end = right point
	const startX = cx - r
	const startY = cy
	const endX = cx + r
	const endY = cy

	// Total arc length of the semicircle
	const circumference = Math.PI * r // = π * r (half the full circumference 2πr)

	// Stroke-dashoffset: 0 = fully filled, circumference = empty
	const dashOffset = circumference * (1 - clampedValue)

	return (
		<div
			data-slot="gauge"
			className={cn('relative flex flex-col items-center', className)}
		>
			<svg
				viewBox="0 0 200 110"
				fill="none"
				aria-valuenow={Math.round(clampedValue * 100)}
				aria-valuemin={0}
				aria-valuemax={100}
				role="progressbar"
				className="w-full"
			>
				{/* Track */}
				<path
					d={`M ${startX} ${startY} A ${r} ${r} 0 0 1 ${endX} ${endY}`}
					stroke="currentColor"
					strokeWidth={strokeWidth}
					strokeLinecap="round"
					className={cn('text-muted/50', trackClassName)}
				/>
				{/* Indicator */}
				<path
					d={`M ${startX} ${startY} A ${r} ${r} 0 0 1 ${endX} ${endY}`}
					stroke="currentColor"
					strokeWidth={strokeWidth}
					strokeLinecap="round"
					strokeDasharray={`${circumference} ${circumference}`}
					strokeDashoffset={dashOffset}
					style={{ transition: 'stroke-dashoffset 0.5s ease' }}
					className={cn(
						isComplete ? 'text-success' : 'text-primary',
						indicatorClassName,
					)}
				/>
			</svg>

			{children != null && (
				<div
					data-slot="gauge-content"
					className="absolute bottom-0 left-0 right-0 flex items-center justify-center"
				>
					{children}
				</div>
			)}
		</div>
	)
}

export { Gauge }

import * as React from 'react'
import { useMaskito } from '@maskito/react'

import { cn } from '@/lib/utils'
import {
	currencyAmountMaskOptions,
	currencyAmountToDisplayString,
	displayStringToCurrencyCents,
} from '@/lib/masks'
import {
	InputGroup,
	InputGroupSelectTrigger,
	InputGroupInput,
} from '@/components/ui/input-group'
import {
	Select,
	SelectContent,
	SelectItem,
	SelectValue,
} from '@/components/ui/select'

const DEFAULT_CURRENCIES = ['BRL', 'USD', 'EUR', 'GBP', 'ARS', 'CLP', 'MXN']

export interface MoneyInputProps {
	/** Current amount in integer cents (e.g. 150050 = R$ 1.500,50) */
	amountCents: number
	onAmountCentsChange: (cents: number) => void
	/** ISO 4217 currency code (e.g. "BRL") */
	currency: string
	onCurrencyChange: (currency: string) => void
	/** Override the available currency options */
	currencies?: string[]
	placeholder?: string
	className?: string
	disabled?: boolean
	id?: string
}

/**
 * Controlled currency selector + masked decimal amount input.
 * Emits integer cents via `onAmountCentsChange`.
 * Layout: InputGroup [ Select(currency) | masked number input ]
 */
function MoneyInput({
	amountCents,
	onAmountCentsChange,
	currency,
	onCurrencyChange,
	currencies = DEFAULT_CURRENCIES,
	placeholder = '0,00',
	className,
	disabled,
	id,
}: MoneyInputProps) {
	const maskRef = useMaskito({ options: currencyAmountMaskOptions })

	// Sync the input's display value when `amountCents` changes from outside
	const displayValue = amountCents > 0 ? currencyAmountToDisplayString(amountCents) : ''

	const handleInput = React.useCallback(
		(e: React.FormEvent<HTMLInputElement>) => {
			const cents = displayStringToCurrencyCents(e.currentTarget.value)
			onAmountCentsChange(cents)
		},
		[onAmountCentsChange],
	)

	return (
		<InputGroup data-slot="money-input" className={cn(className)} aria-disabled={disabled}>
			<Select value={currency} onValueChange={v => { if (v !== null) onCurrencyChange(v) }} disabled={disabled}>
				<InputGroupSelectTrigger className="min-w-[4.5rem]">
					<SelectValue placeholder="BRL" />
				</InputGroupSelectTrigger>
				<SelectContent align="start">
					{currencies.map(c => (
						<SelectItem key={c} value={c}>
							{c}
						</SelectItem>
					))}
				</SelectContent>
			</Select>

			<InputGroupInput
				ref={maskRef}
				id={id}
				inputMode="decimal"
				placeholder={placeholder}
				defaultValue={displayValue}
				key={displayValue}
				onInput={handleInput}
				disabled={disabled}
			/>
		</InputGroup>
	)
}

export { MoneyInput }

