			data-slot="field-separator"
			data-content={!!children}
			className={cn('-my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2 relative', className)}
			{...props}
		>
			<Separator className="absolute inset-0 top-1/2" />
			{children && (
				<span className="text-muted-foreground px-2 bg-background relative mx-auto block w-fit" data-slot="field-separator-content">
					{children}
				</span>
			)}
		</div>
	)
}

// Map Zod's default messages to our error codes
// Translates error message if it's an error code or a Zod default message
function translateErrorMessage(message: string | undefined): string | undefined {
	if (!message) return message
	return translateError(message)
}

function FieldError({
	className,
	children,
	errors,
	...props
}: React.ComponentProps<'div'> & {
	errors?: Array<string | { message?: string } | undefined>
}) {
	const content = useMemo(() => {
		if (children) {
			return children
		}

		if (!errors?.length) {
			return null
		}

		// Translate error codes in messages (handles both string and object errors)
		const translatedErrors = errors.map(error => {
			if (typeof error === 'string') return { message: translateErrorMessage(error) }
			return {
				...error,
				message: translateErrorMessage(error?.message),
			}
		})

		const uniqueErrors = [...new Map(translatedErrors.map(error => [error?.message, error])).values()]

		if (uniqueErrors?.length === 1) {
			return uniqueErrors[0]?.message
		}

		return (
			<ul className="ml-4 flex list-disc flex-col gap-1">
				{uniqueErrors.map((error, index) => error?.message && <li key={index}>{error.message}</li>)}
			</ul>
		)
	}, [children, errors])

	if (!content) {
		return null
	}

	return (
		<div role="alert" data-slot="field-error" className={cn('text-destructive text-sm font-normal', className)} {...props}>
			{content}
		</div>
	)
}

export { Field, FieldLabel, FieldDescription, FieldError, FieldGroup, FieldLegend, FieldSeparator, FieldSet, FieldContent, FieldTitle }

