import { IconUsers } from '@tabler/icons-react'
import { useTranslation } from 'react-i18next'

import { cn } from '@/lib/utils'

export interface FunnelStepProps {
	label: string
	/** Step count (unique sessions at this stage). */
	count: number
	/** Base count (total sessions entering the funnel). */
	base: number
	/** Fraction 0..1 representing this step relative to base. */
	pct: number
	/** Whether this step is the last in the sequence. */
	isLast?: boolean
	className?: string
}

/**
 * FunnelStep — a single column in the pixel funnel:
 * big % at top, a purple trapezoid whose height ∝ pct, then "{count} de {base}" with a users icon.
 */
export function FunnelStep({ label, count, base, pct, isLast = false, className }: FunnelStepProps) {
	const { t } = useTranslation()

	const displayPct = Math.round(pct * 100)
	// Bar height: maps pct (0..1) to a visual range of 12px..88px
	const barHeight = Math.max(12, Math.round(pct * 88))

	return (
		<div
			className={cn('flex flex-1 flex-col items-center gap-2', className)}
			role="listitem"
			aria-label={label}
		>
			{/* Label */}
			<span className="text-muted-foreground text-xs font-medium text-center leading-tight">{label}</span>

			{/* Big percentage */}
			<span className="text-foreground text-2xl font-bold tabular-nums">{displayPct}%</span>

			{/* Purple trapezoid bar — simple SVG that slopes down to the next step */}
			<div className="w-full flex items-end" style={{ minHeight: 96 }}>
				<svg
					width="100%"
					height={96}
					viewBox="0 0 80 96"
					preserveAspectRatio="none"
					aria-hidden
					className="w-full"
				>
					{isLast ? (
						/* Last step: full rectangle (no right slope) */
						<rect
							x={0}
							y={96 - barHeight}
							width={80}
							height={barHeight}
							rx={4}
							className="fill-bkdash-purple/80"
						/>
					) : (
						/* Trapezoid: wide at top-left, narrows toward next step */
						<path
							d={`M0,${96 - barHeight} L80,${96 - Math.max(4, barHeight - 16)} L80,96 L0,96 Z`}
							className="fill-bkdash-purple/80"
						/>
					)}
				</svg>
			</div>

			{/* "{count} de {base}" with users icon */}
			<span className="inline-flex items-center gap-1 text-muted-foreground text-xs">
				<IconUsers className="size-3 shrink-0" aria-hidden />
				<span>
					{count.toLocaleString('pt-BR')}{' '}
					{t('dashboard.funnel.pageView', { defaultValue: 'de' }).replace(/[^de]/gi, '')
						? ''
						: ''}
					{'de'}{' '}
					{base.toLocaleString('pt-BR')}
				</span>
			</span>
		</div>
	)
}

