 * and `displayStringToCurrencyCents` to parse the display string back to integer cents.
 *
 * Decimal separator: `,`  Thousand separator: `.`  (pt-BR / common for BRL/USD display)
 */
export const currencyAmountMaskOptions: MaskitoOptions = maskitoNumberOptionsGenerator({
	decimalSeparator: ',',
	thousandSeparator: '.',
	decimalPseudoSeparators: ['.', ','],
	minimumFractionDigits: 2,
	maximumFractionDigits: 2,
	min: 0,
})

/** Convert integer cents (e.g. 150050) → display string ("1.500,50") */
export function currencyAmountToDisplayString(amountCents: number): string {
	if (!Number.isFinite(amountCents) || amountCents < 0) return '0,00'
	const major = Math.floor(amountCents / 100)
	const minor = amountCents % 100
	const majorStr = major.toLocaleString('pt-BR')
	return `${majorStr},${String(minor).padStart(2, '0')}`
}

/** Parse display string ("1.500,50") → integer cents (150050). Returns 0 on invalid input. */
export function displayStringToCurrencyCents(display: string): number {
	// Remove thousand separators (.) then replace decimal separator (,) with .
	const normalized = display.replace(/\./g, '').replace(',', '.')
	const parsed = parseFloat(normalized)
	if (!Number.isFinite(parsed) || parsed < 0) return 0
	return Math.round(parsed * 100)
}

