import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'
import { Card } from '@/components/ui/card'
import { MetricDelta } from '@/components/ui/metric-delta'
import { InfoHint } from '@/components/ui/info-hint'

export interface FunnelHighlightCardProps {
	/** Custom icon element rendered at top-left. */
	icon: ReactNode
	/** Card label, e.g. "Taxa de Conversão". */
	label: string
	/** Tooltip hint text for the info (i) icon. */
	hint: string
	/** Formatted value string, e.g. "4,2%" or "R$ 1.234,56". */
	value: string
	/** Period-over-period change as a fraction: 0.52 → +52%, null when unavailable. */
	deltaPct: number | null
	className?: string
}

/**
 * FunnelHighlightCard — compact metric card used in the funnel right rail.
 * Renders: icon + label + (i) hint | big value | MetricDelta.
 */
export function FunnelHighlightCard({
	icon,
	label,
	hint,
	value,
	deltaPct,
	className,
}: FunnelHighlightCardProps) {
	return (
		<Card className={cn('flex flex-col gap-2 p-4', className)}>
			{/* Header row: icon + label + info hint */}
			<div className="flex items-center gap-2">
				<span className="text-bkdash-purple shrink-0" aria-hidden>
					{icon}
				</span>
				<span className="text-muted-foreground text-xs font-medium">{label}</span>
				<InfoHint label={label}>{hint}</InfoHint>
			</div>

			{/* Big value */}
			<span className="text-foreground text-xl font-bold tabular-nums">{value}</span>

			{/* Delta */}
			{deltaPct !== null && <MetricDelta pct={deltaPct} />}
		</Card>
	)
}

