import { Gauge } from '@/components/ui/gauge'
import { cn } from '@/lib/utils'
import { currencyAmountToDisplayString } from '@/lib/masks'

export interface GoalGaugeCardProps {
	/** Fraction 0..1 (achieved / target, capped at 1) */
	pct: number
	/** Achieved amount in integer cents */
	achieved: number
	/** Target amount in integer cents */
	target: number
	/** ISO 4217 currency code */
	currency: string
}

/**
 * Displays a semicircle gauge with the achieved/target money amounts below.
 * Props-driven leaf — no data fetching.
 */
function GoalGaugeCard({ pct, achieved, target, currency }: GoalGaugeCardProps) {
	const clamped = Math.min(1, Math.max(0, pct))
	const pctLabel = `${Math.round(clamped * 100)}%`
	const achievedDisplay = `${currency} ${currencyAmountToDisplayString(achieved)}`
	const targetDisplay = `${currency} ${currencyAmountToDisplayString(target)}`

	return (
		<div className="flex flex-col items-center gap-3 w-full">
			<Gauge value={clamped} className="w-full max-w-[240px]">
				<span className={cn('text-2xl font-bold tabular-nums', clamped >= 1 ? 'text-success' : 'text-foreground')}>
					{pctLabel}
				</span>
			</Gauge>

			<p className="text-sm text-center leading-snug">
				<span className="font-semibold text-success">{achievedDisplay}</span>
				<span className="text-muted-foreground"> de {targetDisplay}</span>
			</p>
		</div>
	)
}

