import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { cn } from '@/lib/utils'
import { currencyAmountToDisplayString } from '@/lib/masks'

export interface RankingProductRowProps {
	name: string
	imageUrl: string | null
	/** Revenue in cents (sales.value.value). */
	value: number
	/** Units sold (sales.count.value). */
	count: number
	soldLabel: string
	className?: string
}

/**
 * RankingProductRow — a single row in the product ranking list.
 * Leaf component: receives one item by prop, never re-fetches.
 */
export function RankingProductRow({
	name,
	imageUrl,
	value,
	count,
	soldLabel,
	className,
}: RankingProductRowProps) {
	return (
		<div
			className={cn('flex items-center gap-3 py-2', className)}
			role="listitem"
		>
			{/* Square product image or placeholder */}
			<Avatar
				className="size-10 rounded-lg shrink-0"
				style={{ ['--size' as string]: undefined }}
			>
				{imageUrl ? (
					<AvatarImage
						src={imageUrl}
						alt={name}
						className="rounded-lg object-cover aspect-square"
					/>
				) : null}
				<AvatarFallback className="rounded-lg text-xs font-semibold bg-muted text-muted-foreground">
					{name.slice(0, 2).toUpperCase()}
				</AvatarFallback>
			</Avatar>

			{/* Name — truncate */}
			<span className="flex-1 min-w-0 text-sm font-medium text-foreground truncate">
				{name}
			</span>

			{/* Revenue + units — right-aligned */}
			<div className="flex flex-col items-end shrink-0">
				<span className="text-sm font-semibold text-foreground tabular-nums">
					R$&nbsp;{currencyAmountToDisplayString(value)}
				</span>
				<span className="text-xs text-muted-foreground tabular-nums">
					{count.toLocaleString('pt-BR')}&nbsp;{soldLabel}
				</span>
			</div>
		</div>
	)
}

