import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { IconPlus } from '@tabler/icons-react'

export interface AdditionalCostRowProps {
	label: string
	/** Display value string — already formatted by caller (e.g. "R$ 1.200,00" or "Sem Garantia") */
	value: string
	/** Controls text colour of the value. 'red' = destructive, 'green' = success, 'muted' = default */
	tone?: 'red' | 'green' | 'muted'
	/** When provided, renders a small + button at the end of the row */
	onAdd?: () => void
	/** aria-label for the + button */
	addLabel?: string
}

/**
 * A single additional-cost row: label on the left, value on the right, optional + button.
 * Leaf component — props-driven, no queries.
 */
export function AdditionalCostRow({ label, value, tone = 'muted', onAdd, addLabel }: AdditionalCostRowProps) {
	return (
		<div className="flex items-center justify-between gap-2 py-1.5">
			<span className="text-sm text-muted-foreground">{label}</span>

			<div className="flex items-center gap-2">
				<span
					className={cn(
						'text-sm font-medium tabular-nums',
						tone === 'red' && 'text-destructive',
						tone === 'green' && 'text-success',
						tone === 'muted' && 'text-foreground',
					)}
				>
					{value}
				</span>

				{onAdd && (
					<Button
						variant="outline"
						size="icon-xs"
						aria-label={addLabel ?? label}
						className="text-bkdash-purple border-bkdash-purple/30 hover:bg-bkdash-purple/10 size-5 rounded-md"
						onClick={onAdd}
					>
						<IconPlus className="size-3" />
					</Button>
				)}
			</div>
		</div>
	)
}

