							onOpenChange(false)
						},
					},
				)
			}
		},
	})

	const isPending = createGoal.isPending || updateGoal.isPending

	return (
		<Sheet open={open} onOpenChange={onOpenChange}>
			<SheetContent side="right">
				<SheetHeader>
					<SheetTitle>{t('dashboard.goal.drawerTitle')}</SheetTitle>
				</SheetHeader>

				<form
					className="flex flex-col gap-4 flex-1 overflow-y-auto px-4 pb-4"
					onSubmit={e => {
						e.preventDefault()
						void form.handleSubmit()
					}}
				>
					<FieldGroup>
						{/* Meta (MoneyInput) */}
						<form.Field name="amountCents">
							{field => (
								<Field>
									<FieldLabel htmlFor={field.name}>{t('dashboard.goal.goalAmount')}</FieldLabel>
									<form.Subscribe selector={s => s.values.currency}>
										{currency => (
											<MoneyInput
												id={field.name}
												amountCents={field.state.value}
												onAmountCentsChange={v => field.handleChange(v)}
												currency={currency}
												onCurrencyChange={v => form.setFieldValue('currency', v)}
											/>
										)}
									</form.Subscribe>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>

						{/* Data de Início da Meta */}
						<form.Field name="from">
							{field => (
								<Field>
									<FieldLabel>{t('dashboard.goal.startDate')}</FieldLabel>
									<DatePicker
										date={field.state.value}
										onDateChange={d => field.handleChange(d)}
										placeholder={t('dashboard.goal.startDate')}
									/>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>

						{/* Data de Fim da Meta */}
						<form.Field name="to">
							{field => (
								<Field>
									<FieldLabel>{t('dashboard.goal.endDate')}</FieldLabel>
									<DatePicker
										date={field.state.value}
										onDateChange={d => field.handleChange(d)}
										placeholder={t('dashboard.goal.endDate')}
									/>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>

						{/* Tipo: Faturamento / Lucro */}
						<form.Field name="type">
							{field => (
								<Field>
									<FieldLabel>{t('dashboard.goal.goalType')}</FieldLabel>
									<div className="flex flex-col gap-2 mt-1">
										<label className="flex items-center gap-2 cursor-pointer select-none">
											<Checkbox
												checked={field.state.value === 'REVENUE'}
												onCheckedChange={checked => {
													if (checked) field.handleChange('REVENUE')
												}}
											/>
											<Label className="cursor-pointer">{t('dashboard.goal.typeRevenue')}</Label>
										</label>
										<label className="flex items-center gap-2 cursor-pointer select-none">
											<Checkbox
												checked={field.state.value === 'PROFIT'}
												onCheckedChange={checked => {
													if (checked) field.handleChange('PROFIT')
												}}
											/>
											<Label className="cursor-pointer">{t('dashboard.goal.typeProfit')}</Label>
										</label>
									</div>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>
					</FieldGroup>
				</form>

				<SheetFooter className="px-4 pb-4 pt-2 border-t border-border">
					<form.Subscribe selector={s => s.canSubmit}>
						{canSubmit => (
							<Button
								type="submit"
								disabled={!canSubmit || isPending}
								className="w-full"
								onClick={() => void form.handleSubmit()}
							>
								{isPending && <Spinner className="mr-2 size-4" />}
								{isEditing ? t('dashboard.goal.submit') : t('dashboard.goal.submitCreate')}
							</Button>
						)}
					</form.Subscribe>
					<SheetClose
						render={<Button variant="outline" className="w-full" />}
					>
						{t('common.cancel') ?? 'Cancelar'}
					</SheetClose>
				</SheetFooter>
			</SheetContent>
		</Sheet>
	)
}

export { GoalDrawer }

