						<p className="text-muted-foreground text-xs font-medium uppercase tracking-wide">
							{t('dashboard.ranking.title')}
						</p>
						{data ? (
							<p className="text-foreground text-2xl font-bold tabular-nums leading-tight">
								{data.totalProducts.toLocaleString('pt-BR')}
							</p>
						) : (
							<Skeleton className="mt-1 h-7 w-16" />
						)}
					</div>
					<Button variant="outline" size="sm" asChild>
						<Link to="/app/products">{t('dashboard.ranking.viewAll')}</Link>
					</Button>
				</div>
			</CardHeader>

			<Separator />

			<CardContent className="pt-0 pb-2">
				{data ? (
					/* ~3.5 rows visible; each row is ~56px (py-2 = 8px × 2 + 40px avatar) */
					<div
						className="overflow-y-auto divide-y divide-border/40"
						style={{ maxHeight: '14rem' }}
						role="list"
						aria-label={t('dashboard.ranking.title')}
					>
						{data.items.map((item) => (
							<RankingProductRow
								key={item.productId}
								name={item.name}
								imageUrl={item.imageUrl}
								value={item.sales.value.value}
								count={item.sales.count.value}
								soldLabel={t('dashboard.ranking.soldUnits')}
							/>
						))}
					</div>
				) : (
					<div className="flex flex-col gap-2 pt-2" aria-busy="true">
						{Array.from({ length: 4 }, (_, i) => (
							<div key={i} className="flex items-center gap-3 py-2">
								<Skeleton className="size-10 rounded-lg shrink-0" />
								<Skeleton className="h-4 flex-1" />
								<Skeleton className="h-8 w-20" />
							</div>
						))}
					</div>
				)}
			</CardContent>
		</Card>
	)
}

