import * as React from 'react'
import { useForm } from '@tanstack/react-form'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { useTranslation } from 'react-i18next'
import {
	useCreateOperationalCost,
	getDashboardQueryKey,
	createOperationalCostMutationRequestSchema,
} from '@bk-dash/client-typescript/typescript'
import {
	Sheet,
	SheetContent,
	SheetHeader,
	SheetTitle,
	SheetFooter,
	SheetClose,
} from '@/components/ui/sheet'
import { Field, FieldError, FieldGroup, FieldLabel } from '@/components/ui/field'
import { MoneyInput } from '@/components/ui/money-input'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from '@/components/ui/select'
import { DatePicker } from '@/components/ui/date-picker'
import { subDays } from 'date-fns'

type Flow = 'CREDIT' | 'DEBIT'
type Recurrency =
	| 'ONCE'
	| 'DAILY'
	| 'WEEKLY'
	| 'MONTHLY'
	| 'BIMESTER'
	| 'TRIMESTER'
	| 'SEMESTER'
	| 'YEARLY'
	| 'NONE'
type Category =
	| 'EMPLOYEE'
	| 'APP'
	| 'FOOD'
	| 'RENT'
	| 'ACCOUNTANT'
	| 'REFUND'
	| 'SHIPPING'
	| 'TAKE_PROFIT'
	| 'OTHER'

interface OperationalCostDrawerProps {
	open: boolean
	onOpenChange: (open: boolean) => void
	/** Dashboard query params to invalidate on success */
	dashboardParams: { tenancyScope: 'SINGLE_STORE'; startDate: string; endDate: string }
}

const RECURRENCY_LABELS: Record<Recurrency, string> = {
	ONCE: 'Uma vez',
	DAILY: 'Diário',
	WEEKLY: 'Semanal',
	MONTHLY: 'Mensal',
	BIMESTER: 'Bimestral',
	TRIMESTER: 'Trimestral',
	SEMESTER: 'Semestral',
	YEARLY: 'Anual',
	NONE: 'Nenhum',
}

const CATEGORY_LABELS: Record<Category, string> = {
	EMPLOYEE: 'Funcionário',
	APP: 'Aplicativo',
	FOOD: 'Alimentação',
	RENT: 'Aluguel',
	ACCOUNTANT: 'Contador',
	REFUND: 'Reembolso',
	SHIPPING: 'Frete',
	TAKE_PROFIT: 'Retirada',
	OTHER: 'Outro',
}

interface FormValues {
	flow: Flow
	amountCents: number
	currency: string
	description: string
	recurrency: Recurrency
	startDate: Date | undefined
	endDate: Date | undefined
	category: Category
}

export function OperationalCostDrawer({
	open,
	onOpenChange,
	dashboardParams,
}: OperationalCostDrawerProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const mutation = useCreateOperationalCost()

	const form = useForm<FormValues>({
		defaultValues: {
			flow: 'DEBIT',
