													id="flow-credit"
													checked={field.state.value === 'CREDIT'}
													onCheckedChange={checked => {
														if (checked) field.handleChange('CREDIT')
													}}
												/>
												<Label htmlFor="flow-credit" className="text-sm cursor-pointer">
													{t('dashboard.additionalCosts.flowCredit')}
												</Label>
											</div>
										</div>
									</Field>
								)}
							</form.Field>

							{/* Amount */}
							<form.Subscribe selector={s => [s.values.amountCents, s.values.currency] as const}>
								{([amountCents, currency]) => (
									<form.Field name="amountCents">
										{field => (
											<Field>
												<FieldLabel htmlFor={field.name}>
													{t('dashboard.additionalCosts.value')}
												</FieldLabel>
												<MoneyInput
													id={field.name}
													amountCents={amountCents}
													onAmountCentsChange={cents => field.handleChange(cents)}
													currency={currency}
													onCurrencyChange={c =>
														form.setFieldValue('currency', c)
													}
												/>
											</Field>
										)}
									</form.Field>
								)}
							</form.Subscribe>

							{/* Description */}
							<form.Field name="description">
								{field => {
									const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
									return (
										<Field>
											<FieldLabel htmlFor={field.name}>
												{t('dashboard.additionalCosts.description')}
											</FieldLabel>
											<Input
												id={field.name}
												type="text"
												value={field.state.value}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
												aria-invalid={isInvalid}
											/>
											{isInvalid && <FieldError errors={field.state.meta.errors} />}
										</Field>
									)
								}}
							</form.Field>

							{/* Recurrency */}
							<form.Field name="recurrency">
								{field => (
									<Field>
										<FieldLabel htmlFor={field.name}>
											{t('dashboard.additionalCosts.frequency')}
										</FieldLabel>
										<Select
											value={field.state.value}
											onValueChange={v => field.handleChange(v as Recurrency)}
										>
											<SelectTrigger id={field.name} className="w-full">
												<SelectValue />
											</SelectTrigger>
											<SelectContent>
												{(Object.keys(RECURRENCY_LABELS) as Recurrency[]).map(key => (
													<SelectItem key={key} value={key}>
														{RECURRENCY_LABELS[key]}
													</SelectItem>
												))}
											</SelectContent>
										</Select>
									</Field>
								)}
							</form.Field>

							{/* Start Date */}
							<form.Field name="startDate">
								{field => (
									<Field>
										<FieldLabel>{t('dashboard.additionalCosts.startDate')}</FieldLabel>
										<DatePicker
											date={field.state.value}
											onDateChange={d => field.handleChange(d)}
											className="w-full"
										/>
									</Field>
								)}
							</form.Field>

							{/* End Date */}
							<form.Field name="endDate">
								{field => (
									<Field>
										<FieldLabel>{t('dashboard.additionalCosts.endDate')}</FieldLabel>
										<DatePicker
											date={field.state.value}
											onDateChange={d => field.handleChange(d)}
											className="w-full"
										/>
									</Field>
								)}
							</form.Field>

							{/* Category */}
							<form.Field name="category">
								{field => (
									<Field>
										<FieldLabel htmlFor={field.name}>
											{t('dashboard.additionalCosts.category')}
										</FieldLabel>
										<Select
											value={field.state.value}
											onValueChange={v => field.handleChange(v as Category)}
										>
											<SelectTrigger id={field.name} className="w-full">
												<SelectValue />
											</SelectTrigger>
											<SelectContent>
												{(Object.keys(CATEGORY_LABELS) as Category[]).map(key => (
													<SelectItem key={key} value={key}>
														{CATEGORY_LABELS[key]}
													</SelectItem>
												))}
											</SelectContent>
										</Select>
									</Field>
								)}
							</form.Field>
						</FieldGroup>
					</form>
				</div>

				<SheetFooter>
					<form.Subscribe selector={s => [s.canSubmit, s.isSubmitting] as const}>
						{([canSubmit, isSubmitting]) => (
							<Button
								type="submit"
								disabled={!canSubmit}
								className="w-full"
								onClick={() => form.handleSubmit()}
							>
								{isSubmitting && <Spinner className="mr-2" />}
								{t('dashboard.additionalCosts.addOperationalCost')}
							</Button>
						)}
					</form.Subscribe>
					<SheetClose render={<Button variant="outline" className="w-full" />}>
						Cancelar
					</SheetClose>
				</SheetFooter>
			</SheetContent>
		</Sheet>
	)
}

