import * as React from 'react'
import { useTranslation } from 'react-i18next'
import { IconPencil, IconPlus } from '@tabler/icons-react'
import { useGetGoal, useGetGoalProgress } from '@bk-dash/client-typescript/typescript'

import { Card, CardHeader, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'

import { GoalGaugeCard } from './GoalGaugeCard'
import { GoalDrawer } from '../GoalDrawer'

function getLastNDaysRange(n: number): { startDate: string; endDate: string } {
	const end = new Date()
	const start = new Date()
	start.setDate(start.getDate() - n)
	return {
		startDate: start.toISOString(),
		endDate: end.toISOString(),
	}
}

/**
 * GoalSection — owns useGetGoal + useGetGoalProgress.
 * Displays a Gauge with achieved/target amounts for the active goal.
 * Opens GoalDrawer for create/edit.
 */
export function GoalSection() {
	const { t } = useTranslation()
	const [drawerOpen, setDrawerOpen] = React.useState(false)
	const { startDate, endDate } = getLastNDaysRange(30)

	const { data: goalData } = useGetGoal()
	const { data: progressData } = useGetGoalProgress({
		tenancyScope: 'SINGLE_STORE',
		startDate,
		endDate,
	})

	const goal = goalData?.goal ?? null
	const progress = goal ? progressData?.byType[goal.type] : undefined

	const achieved = progress?.achieved ?? 0
	const target = progress?.target ?? 0
	const pct = target > 0 ? achieved / target : 0
	const currency = goal?.targetAmount.currency ?? 'BRL'

	// We're loading when we haven't received goal data yet
	const isLoading = goalData === undefined

	return (
		<>
			<Card>
				<CardHeader>
					<div className="flex items-center justify-between">
						<p className="text-muted-foreground text-xs font-medium uppercase tracking-wide">
							{t('dashboard.goal.title')}
						</p>
						<Button
							variant="ghost"
							size="icon-sm"
							aria-label={t('dashboard.goal.editGoal')}
							onClick={() => setDrawerOpen(true)}
						>
							<IconPencil className="size-4" />
						</Button>
					</div>
				</CardHeader>

				<CardContent className="pb-4 flex flex-col items-center">
					{isLoading ? (
						<div className="flex flex-col items-center gap-3 w-full">
							<Skeleton className="h-[120px] w-full max-w-[240px] rounded-xl" />
							<Skeleton className="h-4 w-40" />
						</div>
					) : goal === null ? (
						<div className="flex flex-col items-center gap-3 py-4">
							<p className="text-muted-foreground text-sm">{t('dashboard.goal.noGoal')}</p>
							<Button
								variant="outline"
								size="sm"
								onClick={() => setDrawerOpen(true)}
							>
								<IconPlus className="mr-1.5 size-4" />
								{t('dashboard.goal.createGoal')}
							</Button>
						</div>
					) : (
						<GoalGaugeCard
							pct={pct}
							achieved={achieved}
							target={target}
							currency={currency}
						/>
					)}
				</CardContent>
			</Card>

			<GoalDrawer
				open={drawerOpen}
				onOpenChange={setDrawerOpen}
				currentGoal={goal ?? undefined}
			/>
		</>
	)
}

