import { IconChartFunnel, IconShoppingCart } from '@tabler/icons-react'
import { useTranslation } from 'react-i18next'

import { useGetPixelFunnel } from '@bk-dash/client-typescript/typescript'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'

import { FunnelStep } from './FunnelStep'
import { FunnelHighlightCard } from './FunnelHighlightCard'

// ─── helpers ────────────────────────────────────────────────────────────────

function getDateRange() {
	const end = new Date()
	const start = new Date()
	start.setDate(end.getDate() - 30)
	const fmt = (d: Date) => d.toISOString().slice(0, 10)
	return { startDate: fmt(start), endDate: fmt(end) }
}

function formatMoney(cents: number) {
	return (cents / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
}

// ─── inline skeletons (never exported) ──────────────────────────────────────

function StepsSkeleton() {
	return (
		<div className="flex gap-3 px-4">
			{[0, 1, 2, 3, 4].map((i) => (
				<div key={i} className="flex flex-1 flex-col items-center gap-2">
					<Skeleton className="h-3 w-16" />
					<Skeleton className="h-7 w-10" />
					<Skeleton className="h-16 w-full" />
					<Skeleton className="h-3 w-20" />
				</div>
			))}
		</div>
	)
}

function HighlightsSkeleton() {
	return (
		<div className="flex flex-col gap-3">
			{[0, 1].map((i) => (
				<Card key={i} className="flex flex-col gap-2 p-4">
					<Skeleton className="h-3 w-28" />
					<Skeleton className="h-6 w-20" />
					<Skeleton className="h-3 w-12" />
				</Card>
			))}
		</div>
	)
}

// ─── step config (SDK field names, in display order) ─────────────────────────

type StepKey =
	| 'PAGE_VIEWED'
	| 'PRODUCT_VIEWED'
	| 'PRODUCT_ADDED_TO_CART'
	| 'CHECKOUT_STARTED'
	| 'CHECKOUT_COMPLETED'

const STEP_ORDER: StepKey[] = [
	'PAGE_VIEWED',
	'PRODUCT_VIEWED',
	'PRODUCT_ADDED_TO_CART',
	'CHECKOUT_STARTED',
	'CHECKOUT_COMPLETED',
]

// ─── component ───────────────────────────────────────────────────────────────

export function FunnelSection() {
	const { t } = useTranslation()
	const { startDate, endDate } = getDateRange()

	const stepLabels: Record<StepKey, string> = {
		PAGE_VIEWED: t('dashboard.funnel.pageView'),
		PRODUCT_VIEWED: t('dashboard.funnel.viewContent'),
		PRODUCT_ADDED_TO_CART: t('dashboard.funnel.addToCart'),
		CHECKOUT_STARTED: t('dashboard.funnel.initiateCheckout'),
		CHECKOUT_COMPLETED: t('dashboard.funnel.purchase'),
	}

	const { data } = useGetPixelFunnel({
		tenancyScope: 'SINGLE_STORE',
		startDate,
		endDate,
	})

	return (
		<Card aria-label={t('dashboard.funnel.pageView')}>
			<CardHeader>
				<CardTitle>{t('dashboard.funnel.pageView')}</CardTitle>
			</CardHeader>

			<CardContent className="pb-4">
				{/* ── no-pixel CTA ── */}
				{data?.hasPixel === false && (
					<div className="flex flex-col items-center gap-3 py-8 text-center">
						<IconChartFunnel className="size-10 text-muted-foreground/50" aria-hidden />
						<p className="text-sm text-muted-foreground">
							{t('dashboard.funnel.installPixelCta')}
						</p>
						<Button size="sm" variant="outline">
							{t('dashboard.funnel.installPixelCta')}
						</Button>
					</div>
				)}

				{/* ── main layout: steps + right-rail highlights ── */}
				{(data === undefined || data.hasPixel) && (
					<div className="flex gap-4">
						{/* Steps */}
						<div className="flex-1">
							{data === undefined ? (
								<StepsSkeleton />
							) : (
								<div className="flex gap-3" role="list" aria-label="Funil de conversão">
									{STEP_ORDER.map((key, idx) => {
										const step = data.steps[key]
										const baseValue = data.base.value
										const pct = baseValue > 0 ? step.value / baseValue : 0
										return (
											<FunnelStep
												key={key}
												label={stepLabels[key]}
												count={step.value}
												base={baseValue}
												pct={pct}
												isLast={idx === STEP_ORDER.length - 1}
											/>
										)
									})}
								</div>
							)}
						</div>

						{/* Right-rail highlights */}
						<div className="flex w-44 shrink-0 flex-col gap-3">
							{data === undefined ? (
								<HighlightsSkeleton />
							) : (
								<>
									<FunnelHighlightCard
										icon={<IconChartFunnel className="size-4" />}
										label={t('dashboard.funnel.conversionRate')}
										hint={t('dashboard.funnel.conversionRate')}
										value={`${Math.round(data.conversionRate.value * 100)}%`}
										deltaPct={data.conversionRate.deltaPct}
									/>
									<FunnelHighlightCard
										icon={<IconShoppingCart className="size-4" />}
										label={t('dashboard.funnel.carts')}
										hint={t('dashboard.funnel.carts')}
										value={formatMoney(data.carts.value.value)}
										deltaPct={data.carts.value.deltaPct}
									/>
								</>
							)}
						</div>
					</div>
				)}
			</CardContent>
		</Card>
	)
}

import { useTranslation } from 'react-i18next'
import { Link } from '@tanstack/react-router'
import { useListQuickProductRanking } from '@bk-dash/client-typescript/typescript'

import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Separator } from '@/components/ui/separator'
import { GradientIconBadge } from '@/components/ui/gradient-icon-badge'
import { BoxIcon } from '@/components/ui/icons'

import { RankingProductRow } from './RankingProductRow'

function getLastNDaysRange(n: number): { startDate: string; endDate: string } {
	const end = new Date()
	const start = new Date()
	start.setDate(start.getDate() - n)
	return {
		startDate: start.toISOString(),
		endDate: end.toISOString(),
	}
}

/**
 * RankingSection — owns the useListQuickProductRanking query.
 * Displays a scrollable top-10 product revenue ranking.
 */
export function RankingSection() {
	const { t } = useTranslation()
	const { startDate, endDate } = getLastNDaysRange(30)

	const { data } = useListQuickProductRanking({
		tenancyScope: 'SINGLE_STORE',
		startDate,
		endDate,
	})

	return (
		<Card>
			<CardHeader>
				<div className="flex items-center gap-3">
					<GradientIconBadge icon={BoxIcon} />
					<div className="flex-1 min-w-0">
						<p className="text-muted-foreground text-xs font-medium uppercase tracking-wide">
							{t('dashboard.ranking.title')}
						</p>
						{data ? (
							<p className="text-foreground text-2xl font-bold tabular-nums leading-tight">
								{data.totalProducts.toLocaleString('pt-BR')}
							</p>
						) : (
							<Skeleton className="mt-1 h-7 w-16" />
						)}
					</div>
					<Button variant="outline" size="sm" asChild>
						<Link to="/app/products">{t('dashboard.ranking.viewAll')}</Link>
					</Button>
				</div>
			</CardHeader>

			<Separator />

			<CardContent className="pt-0 pb-2">
				{data ? (
					/* ~3.5 rows visible; each row is ~56px (py-2 = 8px × 2 + 40px avatar) */
					<div
						className="overflow-y-auto divide-y divide-border/40"
						style={{ maxHeight: '14rem' }}
						role="list"
						aria-label={t('dashboard.ranking.title')}
					>
						{data.items.map((item) => (
							<RankingProductRow
