	SheetFooter,
	SheetClose,
} from '@/components/ui/sheet'
import { Field, FieldError, FieldGroup, FieldLabel } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from '@/components/ui/select'
import { DatePicker } from '@/components/ui/date-picker'

type WarrantyPeriod =
	| 'DAYS_30'
	| 'DAYS_45'
	| 'DAYS_60'
	| 'DAYS_90'
	| 'DAYS_180'
	| 'DAYS_240'
	| 'DAYS_360'

const PERIOD_LABELS: Record<WarrantyPeriod, string> = {
	DAYS_30: '30 dias',
	DAYS_45: '45 dias',
	DAYS_60: '60 dias',
	DAYS_90: '90 dias',
	DAYS_180: '180 dias',
	DAYS_240: '240 dias',
	DAYS_360: '360 dias',
}

interface FormValues {
	percentage: string
	startDate: Date | undefined
	period: WarrantyPeriod
}

interface WarrantyDrawerProps {
	open: boolean
	onOpenChange: (open: boolean) => void
	/** Dashboard query params to invalidate on success */
	dashboardParams: { tenancyScope: 'SINGLE_STORE'; startDate: string; endDate: string }
}

export function WarrantyDrawer({ open, onOpenChange, dashboardParams }: WarrantyDrawerProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const mutation = useUpsertWarranty()

	const form = useForm<FormValues>({
		defaultValues: {
			percentage: '',
			startDate: undefined,
			period: 'DAYS_30',
		},
		validators: {
			onChange: upsertWarrantyMutationRequestSchema,
		},
		onSubmit: async ({ value }) => {
			const startDate = value.startDate
			if (!startDate) return

			const pct = parseFloat(value.percentage)
			if (isNaN(pct)) return

			const data = {
				percentage: pct / 100,
				startDate: startDate.toISOString(),
				period: value.period,
			}

			await mutation.mutateAsync(
				{ data },
				{
					onSuccess: () => {
						toast.success(t('dashboard.additionalCosts.editWarranty'))
						queryClient.invalidateQueries({ queryKey: getDashboardQueryKey(dashboardParams) })
						onOpenChange(false)
					},
				},
			)
		},
	})

	return (
		<Sheet open={open} onOpenChange={onOpenChange}>
			<SheetContent side="right">
				<SheetHeader>
					<SheetTitle>{t('dashboard.additionalCosts.editWarranty')}</SheetTitle>
				</SheetHeader>

				<div className="flex-1 overflow-y-auto px-4 pb-2">
					<form
						noValidate
						onSubmit={e => {
							e.preventDefault()
							form.handleSubmit()
						}}
					>
						<FieldGroup>
							{/* Percentage */}
							<form.Field name="percentage">
								{field => {
									const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
									return (
										<Field>
											<FieldLabel htmlFor={field.name}>
												{t('dashboard.additionalCosts.warrantyPercentage')}
											</FieldLabel>
											<div className="relative">
												<Input
													id={field.name}
													type="number"
													min={0}
													max={100}
													step={0.01}
													placeholder="0.00"
													value={field.state.value}
													onBlur={field.handleBlur}
													onChange={e => field.handleChange(e.target.value)}
													aria-invalid={isInvalid}
													className="pr-7"
												/>
												<span className="pointer-events-none absolute right-2.5 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">
													%
												</span>
											</div>
											{isInvalid && <FieldError errors={field.state.meta.errors} />}
										</Field>
									)
								}}
							</form.Field>

							{/* Start Date */}
							<form.Field name="startDate">
								{field => (
									<Field>
										<FieldLabel>{t('dashboard.additionalCosts.startDate')}</FieldLabel>
										<DatePicker
											date={field.state.value}
											onDateChange={d => field.handleChange(d)}
											className="w-full"
										/>
									</Field>
								)}
							</form.Field>

							{/* Period */}
							<form.Field name="period">
								{field => (
									<Field>
										<FieldLabel htmlFor={field.name}>
											{t('dashboard.additionalCosts.period')}
										</FieldLabel>
										<Select
											value={field.state.value}
											onValueChange={v => field.handleChange(v as WarrantyPeriod)}
										>
											<SelectTrigger id={field.name} className="w-full">
												<SelectValue />
											</SelectTrigger>
											<SelectContent>
												{(Object.keys(PERIOD_LABELS) as WarrantyPeriod[]).map(key => (
													<SelectItem key={key} value={key}>
														{PERIOD_LABELS[key]}
													</SelectItem>
												))}
											</SelectContent>
										</Select>
									</Field>
								)}
							</form.Field>
						</FieldGroup>
					</form>
				</div>

				<SheetFooter>
					<form.Subscribe selector={s => [s.canSubmit, s.isSubmitting] as const}>
						{([canSubmit, isSubmitting]) => (
							<Button
								type="submit"
								disabled={!canSubmit}
								className="w-full"
								onClick={() => form.handleSubmit()}
							>
								{isSubmitting && <Spinner className="mr-2" />}
								{t('dashboard.additionalCosts.editWarranty')}
							</Button>
						)}
					</form.Subscribe>
					<SheetClose render={<Button variant="outline" className="w-full" />}>
						Cancelar
					</SheetClose>
				</SheetFooter>
			</SheetContent>
		</Sheet>
	)
}

