import * as React from 'react'
import { useForm } from '@tanstack/react-form'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { useTranslation } from 'react-i18next'
import {
	useCreateGoal,
	useUpdateGoal,
	createGoalMutationRequestSchema,
	getGoalQueryKey,
	getGoalProgressQueryKey,
} from '@bk-dash/client-typescript/typescript'
import type { GetGoal200 } from '@bk-dash/client-typescript/typescript'
import {
	Sheet,
	SheetContent,
	SheetHeader,
	SheetTitle,
	SheetFooter,
	SheetClose,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { MoneyInput } from '@/components/ui/money-input'
import { DatePicker } from '@/components/ui/date-picker'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import { Field, FieldGroup, FieldLabel, FieldError } from '@/components/ui/field'
import { Spinner } from '@/components/ui/spinner'

interface GoalDrawerProps {
	open: boolean
	onOpenChange: (open: boolean) => void
	/** When provided the drawer is in edit mode and prefills the form */
	currentGoal?: GetGoal200['goal']
}

type GoalType = 'REVENUE' | 'PROFIT'

interface FormValues {
	amountCents: number
	currency: string
	from: Date | undefined
	to: Date | undefined
	type: GoalType
}

function GoalDrawer({ open, onOpenChange, currentGoal }: GoalDrawerProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const createGoal = useCreateGoal()
	const updateGoal = useUpdateGoal()

	const isEditing = currentGoal != null

	const defaultValues: FormValues = React.useMemo(() => {
		if (currentGoal) {
			return {
				amountCents: currentGoal.targetAmount.amountCents,
				currency: currentGoal.targetAmount.currency,
				from: new Date(currentGoal.from),
				to: new Date(currentGoal.to),
				type: currentGoal.type,
			}
		}
		return {
			amountCents: 0,
			currency: 'BRL',
			from: undefined,
			to: undefined,
			type: 'REVENUE' as GoalType,
		}
	}, [currentGoal])

	const form = useForm<FormValues>({
		defaultValues,
		onSubmit: async ({ value }) => {
			// Build validated request body
			const requestBody = {
				from: value.from?.toISOString() ?? '',
				to: value.to?.toISOString() ?? '',
				type: value.type,
				targetAmount: {
					amountCents: value.amountCents,
					currency: value.currency,
				},
			}

			const parsed = createGoalMutationRequestSchema.safeParse(requestBody)
			if (!parsed.success) return

			const invalidate = () => {
				void queryClient.invalidateQueries({ queryKey: getGoalQueryKey() })
				void queryClient.invalidateQueries({
					predicate: query =>
						Array.isArray(query.queryKey) &&
						typeof query.queryKey[0] === 'object' &&
						(query.queryKey[0] as { url?: string }).url === '/v1/analytics/goals/progress',
				})
			}

			if (isEditing && currentGoal) {
				await updateGoal.mutateAsync(
					{
						data: {
							ids: [currentGoal.id],
							targetAmount: {
								amountCents: parsed.data.targetAmount.amountCents,
								currency: parsed.data.targetAmount.currency,
							},
							from: parsed.data.from,
							to: parsed.data.to,
						},
					},
					{
						onSuccess: () => {
							toast.success(t('dashboard.goal.editGoal'))
							invalidate()
							onOpenChange(false)
						},
					},
				)
			} else {
				await createGoal.mutateAsync(
					{ data: parsed.data },
					{
						onSuccess: () => {
							toast.success(t('dashboard.goal.submitCreate'))
							invalidate()
							onOpenChange(false)
						},
					},
				)
			}
		},
	})

	const isPending = createGoal.isPending || updateGoal.isPending

	return (
		<Sheet open={open} onOpenChange={onOpenChange}>
			<SheetContent side="right">
				<SheetHeader>
					<SheetTitle>{t('dashboard.goal.drawerTitle')}</SheetTitle>
				</SheetHeader>

				<form
					className="flex flex-col gap-4 flex-1 overflow-y-auto px-4 pb-4"
					onSubmit={e => {
						e.preventDefault()
						void form.handleSubmit()
					}}
				>
					<FieldGroup>
						{/* Meta (MoneyInput) */}
						<form.Field name="amountCents">
							{field => (
								<Field>
									<FieldLabel htmlFor={field.name}>{t('dashboard.goal.goalAmount')}</FieldLabel>
									<form.Subscribe selector={s => s.values.currency}>
										{currency => (
											<MoneyInput
												id={field.name}
												amountCents={field.state.value}
												onAmountCentsChange={v => field.handleChange(v)}
												currency={currency}
												onCurrencyChange={v => form.setFieldValue('currency', v)}
											/>
										)}
									</form.Subscribe>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>

						{/* Data de Início da Meta */}
						<form.Field name="from">
							{field => (
								<Field>
									<FieldLabel>{t('dashboard.goal.startDate')}</FieldLabel>
									<DatePicker
										date={field.state.value}
										onDateChange={d => field.handleChange(d)}
										placeholder={t('dashboard.goal.startDate')}
									/>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>

						{/* Data de Fim da Meta */}
						<form.Field name="to">
							{field => (
								<Field>
									<FieldLabel>{t('dashboard.goal.endDate')}</FieldLabel>
									<DatePicker
										date={field.state.value}
										onDateChange={d => field.handleChange(d)}
										placeholder={t('dashboard.goal.endDate')}
									/>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>

						{/* Tipo: Faturamento / Lucro */}
						<form.Field name="type">
							{field => (
								<Field>
									<FieldLabel>{t('dashboard.goal.goalType')}</FieldLabel>
									<div className="flex flex-col gap-2 mt-1">
										<label className="flex items-center gap-2 cursor-pointer select-none">
											<Checkbox
												checked={field.state.value === 'REVENUE'}
												onCheckedChange={checked => {
													if (checked) field.handleChange('REVENUE')
												}}
											/>
											<Label className="cursor-pointer">{t('dashboard.goal.typeRevenue')}</Label>
										</label>
										<label className="flex items-center gap-2 cursor-pointer select-none">
											<Checkbox
												checked={field.state.value === 'PROFIT'}
												onCheckedChange={checked => {
													if (checked) field.handleChange('PROFIT')
												}}
											/>
											<Label className="cursor-pointer">{t('dashboard.goal.typeProfit')}</Label>
										</label>
									</div>
									<FieldError>{field.state.meta.errors[0]?.toString()}</FieldError>
								</Field>
							)}
						</form.Field>
					</FieldGroup>
				</form>

				<SheetFooter className="px-4 pb-4 pt-2 border-t border-border">
					<form.Subscribe selector={s => s.canSubmit}>
						{canSubmit => (
							<Button
								type="submit"
								disabled={!canSubmit || isPending}
								className="w-full"
								onClick={() => void form.handleSubmit()}
							>
								{isPending && <Spinner className="mr-2 size-4" />}
								{isEditing ? t('dashboard.goal.submit') : t('dashboard.goal.submitCreate')}
							</Button>
						)}
					</form.Subscribe>
					<SheetClose
						render={<Button variant="outline" className="w-full" />}
					>
						{t('common.cancel') ?? 'Cancelar'}
					</SheetClose>
				</SheetFooter>
			</SheetContent>
		</Sheet>
	)
}

