import * as React from 'react'
import { useTranslation } from 'react-i18next'
import { useNavigate } from '@tanstack/react-router'
import { useGetDashboard, getDashboardQueryKey } from '@bk-dash/client-typescript/typescript'
import { Card, CardContent, CardHeader, CardTitle, CardAction } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Separator } from '@/components/ui/separator'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import { GradientIconBadge } from '@/components/ui/gradient-icon-badge'
import { MoneyIcon } from '@/components/ui/icons'
import { useDashboardStore } from '../-stores/useDashboardStore'
import { AdditionalCostRow } from '../AdditionalCostRow'
import { OperationalCostDrawer } from '../OperationalCostDrawer'
import { WarrantyDrawer } from '../WarrantyDrawer'

// ─── helpers ────────────────────────────────────────────────────────────────

function getDateRange() {
	const end = new Date()
	const start = new Date()
	start.setDate(end.getDate() - 30)
	const fmt = (d: Date) => d.toISOString().slice(0, 10)
	return { startDate: fmt(start), endDate: fmt(end) }
}

function formatMoney(cents: number, currency = 'BRL') {
	return (cents / 100).toLocaleString('pt-BR', { style: 'currency', currency })
}

// ─── inline skeleton ─────────────────────────────────────────────────────────

function CostsSkeleton() {
	return (
		<div className="flex flex-col gap-3 px-4">
			{[0, 1, 2, 3, 4].map(i => (
				<div key={i} className="flex items-center justify-between">
					<Skeleton className="h-3 w-24" />
					<Skeleton className="h-3 w-16" />
				</div>
			))}
		</div>
	)
}

// ─── component ───────────────────────────────────────────────────────────────

export function AdditionalCostsSection() {
	const { t } = useTranslation()
	const navigate = useNavigate()
	const { startDate, endDate } = getDateRange()

	const discountAdditionalCosts = useDashboardStore(s => s.discountAdditionalCosts)
	const toggleDiscountAdditionalCosts = useDashboardStore(s => s.toggleDiscountAdditionalCosts)

	const [operationalOpen, setOperationalOpen] = React.useState(false)
	const [warrantyOpen, setWarrantyOpen] = React.useState(false)

	const dashboardParams = {
		tenancyScope: 'SINGLE_STORE' as const,
		startDate,
		endDate,
	}

	const { data: rawData } = useGetDashboard(dashboardParams)

	// Narrow to a SINGLE_* kind before reading `details`
	const data =
		rawData?.kind === 'SINGLE_GLOBAL' || rawData?.kind === 'SINGLE_NATIONAL'
			? rawData
			: undefined

	const currency = data?.store.currency ?? 'BRL'

	// Row values (SDK field is in cents / fractional — dashboard returns raw numbers)
	const chargebackValue = data?.details.chargeback.byStatus.total.value ?? 0
	const refundValue = data?.details.refund.value ?? 0
	const taxesValue =
		(data?.details.taxes.ads.value ?? 0) + (data?.details.taxes.others.value ?? 0)
	const operationalValue = data?.details.operational.total.value ?? 0

	// Total displayed in the header
	const total = chargebackValue + refundValue + taxesValue + operationalValue

	return (
		<>
			<Card aria-label={t('dashboard.additionalCosts.title')}>
				<CardHeader>
					<div className="flex items-center gap-3">
						<GradientIconBadge icon={MoneyIcon} className="size-10" />
						<div className="flex flex-col gap-0.5">
							<CardTitle>{t('dashboard.additionalCosts.title')}</CardTitle>
							{data ? (
								<span className="text-base font-semibold tabular-nums text-foreground">
									{formatMoney(total, currency)}
								</span>
							) : (
								<Skeleton className="h-5 w-24" />
							)}
						</div>
					</div>
					<CardAction>
						<div className="flex items-center gap-2">
							<Checkbox
								id="discount-additional-costs"
								checked={discountAdditionalCosts}
								onCheckedChange={toggleDiscountAdditionalCosts}
							/>
							<Label
								htmlFor="discount-additional-costs"
								className="cursor-pointer text-sm font-normal text-muted-foreground"
							>
								{t('dashboard.additionalCosts.discountToggle')}
							</Label>
						</div>
					</CardAction>
				</CardHeader>

				<Separator className="mx-4 w-auto" />

				<CardContent className="pb-4">
					{data === undefined ? (
						<CostsSkeleton />
					) : (
						<div className="flex flex-col">
							<AdditionalCostRow
								label={t('dashboard.additionalCosts.chargeback')}
								value={formatMoney(chargebackValue, currency)}
								tone="red"
							/>
							<AdditionalCostRow
								label={t('dashboard.additionalCosts.refund')}
								value={formatMoney(refundValue, currency)}
								tone="red"
							/>
							<AdditionalCostRow
								label={t('dashboard.additionalCosts.taxes')}
								value={formatMoney(taxesValue, currency)}
								tone="red"
								onAdd={() => navigate({ to: '/app/settings/taxesAndFees' })}
								addLabel={t('dashboard.additionalCosts.taxes')}
							/>
							<AdditionalCostRow
								label={t('dashboard.additionalCosts.operational')}
								value={formatMoney(operationalValue, currency)}
								tone="red"
								onAdd={() => setOperationalOpen(true)}
								addLabel={t('dashboard.additionalCosts.addOperationalCost')}
							/>
							{/* Warranty — no read hook yet: always shows "Sem Garantia" in green */}
							<AdditionalCostRow
								label={t('dashboard.additionalCosts.warranty')}
								value={t('dashboard.additionalCosts.noWarranty')}
								tone="green"
								onAdd={() => setWarrantyOpen(true)}
								addLabel={t('dashboard.additionalCosts.editWarranty')}
							/>
						</div>
					)}
				</CardContent>
			</Card>

			<OperationalCostDrawer
				open={operationalOpen}
				onOpenChange={setOperationalOpen}
				dashboardParams={dashboardParams}
			/>
			<WarrantyDrawer
				open={warrantyOpen}
				onOpenChange={setWarrantyOpen}
				dashboardParams={dashboardParams}
			/>
		</>
	)
}

